'use client';

import { useState, Suspense } from 'react';
import { useRouter, useSearchParams } from 'next/navigation';
import { User, Lock, Loader2, ArrowLeft, CheckCircle, Eye, EyeOff } from 'lucide-react';
import Link from 'next/link';
import Image from 'next/image';
import { login } from '@/features/auth/actions';

function LoginForm() {
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [error, setError] = useState('');
    const [loading, setLoading] = useState(false);
    const router = useRouter();
    const searchParams = useSearchParams();
    const [showPassword, setShowPassword] = useState(false);

    // Check if user just registered
    const justRegistered = searchParams.get('registered') === 'true';
    const callbackUrl = searchParams.get('callbackUrl');

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setLoading(true);
        setError('');

        try {
            const res = await login({ email, password });
            if (res?.error) {
                setError(res.error);
            } else {
                // Redirect to callback URL if provided, otherwise to dashboard
                router.push(callbackUrl || '/dashboard');
            }
        } catch (err: any) {
            setError('Login gagal. Periksa kembali kredensial Anda.');
        } finally {
            setLoading(false);
        }
    };

    return (
        // Background Utama: #F3F4F6
        <div className="min-h-screen flex items-center justify-center bg-[#F3F4F6] p-4 font-sans">

            {/* Card Container: #FFFFFF */}
            <div className="max-w-md w-full bg-white rounded-2xl shadow-xl border border-gray-100 overflow-hidden">

                {/* Header Section */}
                <div className="p-8 pb-0 text-center">
                    {/* Logo Box (Branding) */}
                    <div className="mx-auto w-fit rounded-xl overflow-hidden shadow-md mb-4">
                        <Image
                            src="/fst-icon.png"
                            alt="Logo Lab Informatika"
                            width={120}
                            height={120}
                            className="object-contain w-auto h-auto max-w-[120px] max-h-[120px]"
                        />
                    </div>

                    {/* Text Utama: #0F4C81 */}
                    <h1 className="text-2xl font-bold text-[#0F4C81] mb-2 tracking-tight">
                        Selamat Datang
                    </h1>
                    {/* Text Sekunder: #6B7280 */}
                    <p className="text-[#6B7280] text-sm">
                        Portal Lab Industri<br />Universitas Al Azhar Indonesia
                    </p>
                </div>

                <div className="p-8 pt-6">
                    {/* Success Registration Notice */}
                    {justRegistered && (
                        <div className="mb-6 flex items-start gap-3 bg-green-50 border border-green-200 p-4 rounded-lg">
                            <CheckCircle className="w-5 h-5 text-green-600 flex-shrink-0 mt-0.5" />
                            <div className="text-green-800 text-sm">
                                <p className="font-semibold">Pendaftaran Berhasil!</p>
                                <p className="mt-1">Akun Anda sedang menunggu validasi dari Admin. Silakan coba login kembali setelah akun diverifikasi.</p>
                            </div>
                        </div>
                    )}

                    {/* Error State: Danger Red #EF4444 */}
                    {error && (
                        <div className="mb-6 flex items-start gap-3 bg-red-50 border border-red-100 p-4 rounded-lg">
                            <div className="text-[#EF4444] text-sm font-medium">
                                {error}
                            </div>
                        </div>
                    )}

                    <form onSubmit={handleSubmit} className="space-y-5">
                        {/* Input Email/NIM */}
                        <div>
                            <label className="block text-sm font-semibold text-[#1F2937] mb-2">
                                Email Universitas atau NIM
                            </label>
                            <div className="relative group">
                                <div className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 group-focus-within:text-[#0F4C81] transition-colors">
                                    <User className="w-5 h-5" />
                                </div>
                                <input
                                    type="text"
                                    value={email}
                                    onChange={(e) => setEmail(e.target.value)}
                                    className="w-full pl-10 pr-4 py-3 rounded-lg border border-gray-200 text-[#1F2937] placeholder-gray-400 focus:border-[#0F4C81] focus:ring-2 focus:ring-[#0F4C81]/20 outline-none transition-all"
                                    placeholder="nama@uai.ac.id atau NIM"
                                    required
                                />
                            </div>
                        </div>

                        {/* Input Password */}
                        <div>
                            <div className="flex items-center justify-between mb-2">
                                <label className="block text-sm font-semibold text-[#1F2937]">
                                    Password
                                </label>
                            </div>
                            <div className="relative group">
                                <div className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 group-focus-within:text-[#0F4C81] transition-colors">
                                    <Lock className="w-5 h-5" />
                                </div>
                                <input
                                    type={showPassword ? "text" : "password"}
                                    value={password}
                                    onChange={(e) => setPassword(e.target.value)}
                                    className="w-full pl-10 pr-12 py-3 rounded-lg border border-gray-200 text-[#1F2937] placeholder-gray-400 focus:border-[#0F4C81] focus:ring-2 focus:ring-[#0F4C81]/20 outline-none transition-all"
                                    placeholder="••••••••"
                                    required
                                />
                                <button
                                    type="button"
                                    onClick={() => setShowPassword(!showPassword)}
                                    className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-[#0F4C81] transition-colors"
                                >
                                    {showPassword ? <EyeOff className="w-5 h-5" /> : <Eye className="w-5 h-5" />}
                                </button>
                            </div>
                        </div>

                        {/* Submit Button: Primary #0F4C81 */}
                        <button
                            type="submit"
                            disabled={loading}
                            className="w-full bg-[#0F4C81] hover:bg-[#1A365D] text-white font-bold py-3.5 rounded-lg transition-all shadow-md hover:shadow-lg flex items-center justify-center disabled:opacity-70 disabled:cursor-not-allowed mt-2"
                        >
                            {loading ? (
                                <Loader2 className="w-5 h-5 animate-spin" />
                            ) : (
                                'Masuk ke Portal'
                            )}
                        </button>
                    </form>

                    <div className="mt-6 text-center text-sm">
                        <div className="text-gray-500 mb-2">
                            Belum punya akun?{' '}
                            <Link href="/register" className="text-[#0F4C81] font-medium hover:underline">
                                Ajukan Pembuatan Akun
                            </Link>
                        </div>
                        <p className="text-gray-400 text-xs">
                            Lupa password? Hubungi admin untuk reset password manual
                        </p>
                    </div>
                </div>

                {/* Footer Card */}
                <div className="px-8 py-4 bg-gray-50 border-t border-gray-100 flex justify-center">
                    <Link
                        href="/"
                        className="flex items-center gap-2 text-sm text-[#6B7280] hover:text-[#0F4C81] font-medium transition-colors"
                    >
                        <ArrowLeft className="w-4 h-4" />
                        Kembali ke Beranda
                    </Link>
                </div>
            </div>
        </div>
    );
}

export default function LoginPage() {
    return (
        <Suspense fallback={
            <div className="min-h-screen flex items-center justify-center bg-[#F3F4F6]">
                <Loader2 className="w-8 h-8 animate-spin text-[#0F4C81]" />
            </div>
        }>
            <LoginForm />
        </Suspense>
    );
}

'use client';

import { useState } from 'react';
import { useRouter } from 'next/navigation';
import { register } from '@/features/users/register';
import { checkPreRegisteredUser } from '@/features/users/enrollment';
import Link from 'next/link';
import { Loader2, Eye, EyeOff, CheckCircle } from 'lucide-react';

interface Lecturer {
    identifier: string;
    fullName: string;
}

interface RegisterFormProps {
    lecturers: Lecturer[];
}

interface PreRegisteredData {
    fullName: string;
    batch: number | null;
    studyType: 'Reguler' | 'Hybrid' | null;
    programStudi: string | null;
    dosenPembimbing: string | null;
}

export default function RegisterForm({ lecturers }: RegisterFormProps) {
    const router = useRouter();
    const [isLoading, setIsLoading] = useState(false);
    const [isCheckingNIM, setIsCheckingNIM] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [showPassword, setShowPassword] = useState(false);
    const [showConfirmPassword, setShowConfirmPassword] = useState(false);
    const [preRegistered, setPreRegistered] = useState<PreRegisteredData | null>(null);

    // State-controlled form values for auto-fill
    const [fullName, setFullName] = useState('');
    const [batch, setBatch] = useState('');
    const [studyType, setStudyType] = useState('');
    const [programStudi, setProgramStudi] = useState('Informatika');
    const [dosenPembimbing, setDosenPembimbing] = useState('');

    // Check NIM when user finishes typing
    const handleNIMChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const nim = e.target.value.trim();

        if (nim.length < 5) {
            setPreRegistered(null);
            return;
        }

        setIsCheckingNIM(true);
        try {
            const data = await checkPreRegisteredUser(nim);
            if (data) {
                setPreRegistered(data);
                // Auto-fill form fields using state
                setFullName(data.fullName);
                if (data.batch) setBatch(data.batch.toString());
                if (data.studyType) setStudyType(data.studyType);
                if (data.programStudi) setProgramStudi(data.programStudi);
                if (data.dosenPembimbing) setDosenPembimbing(data.dosenPembimbing);
            } else {
                setPreRegistered(null);
            }
        } catch (err) {
            console.error('Error checking NIM:', err);
        } finally {
            setIsCheckingNIM(false);
        }
    };

    async function handleSubmit(formData: FormData) {
        setIsLoading(true);
        setError(null);

        const result = await register(formData);

        if (result.success) {
            router.push('/login?registered=true');
        } else {
            setError(result.error);
            setIsLoading(false);
        }
    }

    return (
        <div className="min-h-screen flex items-center justify-center bg-gray-50 p-4">
            <div className="max-w-md w-full bg-white rounded-2xl shadow-xl p-8 border border-gray-100">
                <div className="text-center mb-8">
                    <h1 className="text-2xl font-bold text-gray-900">Pendaftaran Akun</h1>
                    <p className="text-gray-500 mt-2">Buat akun baru untuk mengakses laboratorium</p>
                </div>

                {error && (
                    <div className="bg-red-50 text-red-600 p-3 rounded-lg text-sm mb-6">
                        {error}
                    </div>
                )}

                {preRegistered && (
                    <div className="bg-green-50 text-green-700 p-3 rounded-lg text-sm mb-6 flex items-center gap-2">
                        <CheckCircle className="w-4 h-4" />
                        <span>Data ditemukan! Form sudah terisi otomatis.</span>
                    </div>
                )}

                <form action={handleSubmit} className="space-y-4">
                    {/* NIM - First field to enable auto-fill */}
                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">NIM</label>
                        <div className="relative">
                            <input
                                name="identifier"
                                type="text"
                                required
                                onChange={handleNIMChange}
                                className="w-full px-4 py-2 border border-gray-200 rounded-lg focus:ring-2 focus:ring-[#0F4C81] focus:border-transparent outline-none transition-all"
                                placeholder="Contoh: 0102521001"
                            />
                            {isCheckingNIM && (
                                <div className="absolute right-3 top-1/2 -translate-y-1/2">
                                    <Loader2 className="w-4 h-4 animate-spin text-gray-400" />
                                </div>
                            )}
                        </div>
                        <p className="text-xs text-gray-500 mt-1">Masukkan NIM untuk mengecek data pre-registrasi</p>
                    </div>

                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">Nama Lengkap</label>
                        <input
                            name="fullName"
                            type="text"
                            required
                            value={fullName}
                            onChange={(e) => !preRegistered && setFullName(e.target.value)}
                            readOnly={!!preRegistered}
                            className={`w-full px-4 py-2 border border-gray-200 rounded-lg focus:ring-2 focus:ring-[#0F4C81] focus:border-transparent outline-none transition-all ${preRegistered ? 'bg-gray-50 text-gray-600' : ''}`}
                            placeholder="Contoh: Budi Santoso"
                        />
                        {preRegistered && (
                            <p className="text-xs text-green-600 mt-1">Nama sesuai data pre-registrasi</p>
                        )}
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Angkatan</label>
                            <select
                                name="batch"
                                required
                                value={batch}
                                onChange={(e) => setBatch(e.target.value)}
                                className="w-full px-4 py-2 border border-gray-200 rounded-lg focus:ring-2 focus:ring-[#0F4C81] focus:border-transparent outline-none transition-all bg-white"
                            >
                                <option value="">Pilih Tahun</option>
                                {Array.from({ length: 10 }, (_, i) => new Date().getFullYear() - i).map(year => (
                                    <option key={year} value={String(year)}>{year}</option>
                                ))}
                            </select>
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Tipe</label>
                            <select
                                name="studyType"
                                required
                                value={studyType}
                                onChange={(e) => setStudyType(e.target.value)}
                                className="w-full px-4 py-2 border border-gray-200 rounded-lg focus:ring-2 focus:ring-[#0F4C81] focus:border-transparent outline-none transition-all bg-white"
                            >
                                <option value="">Pilih Tipe</option>
                                <option value="Reguler">Reguler</option>
                                <option value="Hybrid">Hybrid</option>
                            </select>
                        </div>
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Program Studi</label>
                            <input
                                name="programStudi"
                                type="text"
                                required
                                value={programStudi}
                                onChange={(e) => setProgramStudi(e.target.value)}
                                className="w-full px-4 py-2 border border-gray-200 rounded-lg focus:ring-2 focus:ring-[#0F4C81] focus:border-transparent outline-none transition-all"
                                placeholder="Contoh: Informatika"
                            />
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Dosen Pembimbing <span className="text-red-500">*</span></label>
                            <select
                                name="dosenPembimbing"
                                required
                                value={dosenPembimbing}
                                onChange={(e) => setDosenPembimbing(e.target.value)}
                                className="w-full px-4 py-2 border border-gray-200 rounded-lg focus:ring-2 focus:ring-[#0F4C81] focus:border-transparent outline-none transition-all bg-white"
                            >
                                <option value="">Pilih Dosen</option>
                                {lecturers.map(lecturer => (
                                    <option key={lecturer.identifier} value={lecturer.fullName}>
                                        {lecturer.fullName}
                                    </option>
                                ))}
                            </select>
                        </div>
                    </div>

                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">Email</label>
                        <input
                            name="email"
                            type="email"
                            required
                            className="w-full px-4 py-2 border border-gray-200 rounded-lg focus:ring-2 focus:ring-[#0F4C81] focus:border-transparent outline-none transition-all"
                            placeholder="nama@student.uai.ac.id"
                        />
                    </div>

                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">Password</label>
                        <div className="relative">
                            <input
                                name="password"
                                type={showPassword ? "text" : "password"}
                                required
                                className="w-full px-4 py-2 pr-12 border border-gray-200 rounded-lg focus:ring-2 focus:ring-[#0F4C81] focus:border-transparent outline-none transition-all"
                                placeholder="••••••••"
                            />
                            <button
                                type="button"
                                onClick={() => setShowPassword(!showPassword)}
                                className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-[#0F4C81] transition-colors"
                            >
                                {showPassword ? <EyeOff className="w-5 h-5" /> : <Eye className="w-5 h-5" />}
                            </button>
                        </div>
                    </div>

                    <div>
                        <label className="block text-sm font-medium text-gray-700 mb-1">Konfirmasi Password</label>
                        <div className="relative">
                            <input
                                name="confirmPassword"
                                type={showConfirmPassword ? "text" : "password"}
                                required
                                className="w-full px-4 py-2 pr-12 border border-gray-200 rounded-lg focus:ring-2 focus:ring-[#0F4C81] focus:border-transparent outline-none transition-all"
                                placeholder="••••••••"
                            />
                            <button
                                type="button"
                                onClick={() => setShowConfirmPassword(!showConfirmPassword)}
                                className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-[#0F4C81] transition-colors"
                            >
                                {showConfirmPassword ? <EyeOff className="w-5 h-5" /> : <Eye className="w-5 h-5" />}
                            </button>
                        </div>
                    </div>

                    <button
                        type="submit"
                        disabled={isLoading}
                        className="w-full bg-[#0F4C81] text-white py-2.5 rounded-lg font-medium hover:bg-[#0F4C81]/90 transition-colors flex items-center justify-center disabled:opacity-50 disabled:cursor-not-allowed mt-6"
                    >
                        {isLoading ? (
                            <>
                                <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                                Mendaftar...
                            </>
                        ) : (
                            'Daftar'
                        )}
                    </button>
                </form>

                <div className="mt-6 text-center text-sm text-gray-500">
                    Sudah punya akun?{' '}
                    <Link href="/login" className="text-[#0F4C81] font-medium hover:underline">
                        Masuk disini
                    </Link>
                </div>
            </div>
        </div>
    );
}

import { getLecturers } from '@/features/users/actions';
import RegisterForm from './RegisterForm';

export default async function RegisterPage() {
    const lecturers = await getLecturers();

    return <RegisterForm lecturers={lecturers} />;
}

'use client';

interface AnnouncementSectionProps {
    maintenanceRooms: any[];
    maintenanceItems: any[];
}

export default function AnnouncementSection({ maintenanceRooms, maintenanceItems }: AnnouncementSectionProps) {
    const hasAnnouncements = maintenanceRooms.length > 0 || maintenanceItems.length > 0;

    return (
        <div className="bg-white p-4 sm:p-6 h-auto max-h-[15.625rem] overflow-y-auto rounded-lg shadow-sm border border-gray-100">
            <h3 className="text-lg font-bold mb-4 flex items-center gap-2">
                <span className="w-1 h-6 bg-[#0F4C81] rounded-full"></span>
                Pengumuman
            </h3>

            {!hasAnnouncements ? (
                <div className="flex items-center justify-center min-h-[8rem] text-gray-400 italic">
                    Tidak ada pengumuman
                </div>
            ) : (
                <div className="space-y-3">
                    {maintenanceRooms.map((room) => (
                        <div key={`room-${room.id}`} className="bg-orange-50 p-3 rounded-md border border-orange-100">
                            <p className="font-semibold text-orange-800">Ruangan Maintenance</p>
                            <p className="text-sm text-gray-600">
                                Ruangan <span className="font-medium">{room.name}</span> ({room.location}) sedang dalam pemeliharaan.
                            </p>
                        </div>
                    ))}

                    {maintenanceItems.map((item) => (
                        <div key={`item-${item.id}`} className="bg-orange-50 p-3 rounded-md border border-orange-100">
                            <p className="font-semibold text-orange-800">Alat Maintenance</p>
                            <p className="text-sm text-gray-600">
                                Alat <span className="font-medium">{item.name}</span> di {item.room.name} sedang dalam pemeliharaan.
                            </p>
                        </div>
                    ))}
                </div>
            )}
        </div>
    );
}

import { Package, ArrowRight, CheckCircle } from 'lucide-react';
import Link from 'next/link';

interface Item {
    id: number;
    name: string;
    qrCode: string;
    status: string | null;
    category: {
        name: string | null;
    } | null;
}

interface AvailableItemsSectionProps {
    items: Item[];
}

export default function AvailableItemsSection({ items }: AvailableItemsSectionProps) {
    // Group by category
    const byCategory = items.reduce((acc, item) => {
        const cat = item.category?.name || 'Lainnya';
        if (!acc[cat]) acc[cat] = [];
        acc[cat].push(item);
        return acc;
    }, {} as Record<string, Item[]>);

    const categories = Object.entries(byCategory).slice(0, 4);

    return (
        <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-5">
            <div className="flex items-center justify-between mb-4">
                <div className="flex items-center gap-2">
                    <Package className="w-5 h-5 text-green-600" />
                    <h2 className="text-lg font-semibold text-gray-800">Alat Tersedia</h2>
                </div>
                <Link
                    href="/login"
                    className="text-sm text-[#0F4C81] hover:underline flex items-center gap-1"
                >
                    Pinjam alat <ArrowRight className="w-4 h-4" />
                </Link>
            </div>

            {items.length === 0 ? (
                <div className="text-center py-6 text-gray-400">
                    <Package className="w-10 h-10 mx-auto mb-2 opacity-50" />
                    <p className="text-sm">Semua alat sedang dipinjam</p>
                </div>
            ) : (
                <div className="space-y-3">
                    {categories.map(([category, categoryItems]) => (
                        <div key={category}>
                            <p className="text-xs font-medium text-gray-500 uppercase tracking-wider mb-2">
                                {category}
                            </p>
                            <div className="flex flex-wrap gap-2">
                                {categoryItems.slice(0, 3).map((item) => (
                                    <div
                                        key={item.id}
                                        className="flex items-center gap-2 px-3 py-2 bg-green-50 text-green-700 rounded-lg text-sm"
                                    >
                                        <CheckCircle className="w-4 h-4" />
                                        <span className="font-medium">{item.name}</span>
                                    </div>
                                ))}
                                {categoryItems.length > 3 && (
                                    <span className="px-3 py-2 text-gray-400 text-sm">
                                        +{categoryItems.length - 3} lainnya
                                    </span>
                                )}
                            </div>
                        </div>
                    ))}
                </div>
            )}
        </div>
    );
}

'use client';

import { useState, useEffect } from 'react';
import Image from 'next/image';
import { ChevronLeft, ChevronRight, Image as ImageIcon } from 'lucide-react';

interface HeroPhoto {
    id: number;
    title: string;
    description: string | null;
    imageUrl: string;
    focalX: number;
    focalY: number;
    link: string | null;
}

export default function HeroCarousel({ photos }: { photos: HeroPhoto[] }) {
    const [currentSlide, setCurrentSlide] = useState(0);

    // Auto-advance slides
    useEffect(() => {
        if (photos.length <= 1) return;

        const interval = setInterval(() => {
            setCurrentSlide((prev) => (prev + 1) % photos.length);
        }, 5000);

        return () => clearInterval(interval);
    }, [photos.length]);

    const nextSlide = () => {
        setCurrentSlide((prev) => (prev + 1) % photos.length);
    };

    const prevSlide = () => {
        setCurrentSlide((prev) => (prev - 1 + photos.length) % photos.length);
    };

    if (photos.length === 0) {
        return (
            <div className="w-full aspect-[16/9] sm:aspect-[21/9] relative bg-gray-900 flex flex-col items-center justify-center overflow-hidden rounded-2xl shadow-lg">
                {/* Gradient Overlay similar to actual slides */}
                <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-black/20 to-transparent z-10" />

                <div className="z-20 flex flex-col items-center text-center p-4 sm:p-8">
                    <div className="p-3 sm:p-4 bg-white/10 backdrop-blur-sm rounded-full mb-3 sm:mb-4 shadow-sm border border-white/20">
                        <ImageIcon className="w-6 h-6 sm:w-8 sm:h-8 text-white/80" />
                    </div>
                    <h2 className="text-base sm:text-xl font-semibold text-white">Belum ada foto kegiatan</h2>
                    <p className="text-white/80 mt-2">Foto kegiatan akan muncul di sini</p>
                </div>
            </div>
        );
    }

    return (
        <div className="w-full aspect-[16/9] sm:aspect-[21/9] relative bg-gray-900 flex items-center justify-center overflow-hidden rounded-2xl shadow-lg group">
            {photos.map((photo, index) => {
                const contentNode = (
                    <>
                        <Image
                            src={photo.imageUrl}
                            alt={photo.title}
                            fill
                            unoptimized
                            priority={index === 0}
                            className="object-cover z-0"
                            style={{ objectPosition: `${photo.focalX || 50}% ${photo.focalY || 50}%` }}
                            sizes="100vw"
                        />
                        {/* Gradient Overlay */}
                        <div className="absolute inset-0 bg-gradient-to-t from-gray-900 via-gray-900/40 to-transparent z-10 pointer-events-none" />

                        {/* Content */}
                        <div className="absolute bottom-0 left-0 right-0 p-4 sm:p-6 lg:p-8 z-20 pointer-events-none">
                            <h2 className="text-lg sm:text-2xl lg:text-3xl font-bold text-white mb-1 sm:mb-2 drop-shadow-md">{photo.title}</h2>
                            {photo.description && (
                                <p className="text-white/90 text-sm sm:text-base lg:text-lg max-w-2xl drop-shadow-sm line-clamp-2">{photo.description}</p>
                            )}
                        </div>
                    </>
                );

                return (
                    <div
                        key={photo.id}
                        className={`absolute inset-0 transition-opacity duration-700 ease-in-out ${index === currentSlide ? 'opacity-100 z-10' : 'opacity-0 z-0'
                            }`}
                    >
                        {photo.link ? (
                            <a href={photo.link} target="_blank" rel="noopener noreferrer" className="block w-full h-full cursor-pointer">
                                {contentNode}
                            </a>
                        ) : (
                            <div className="w-full h-full relative">
                                {contentNode}
                            </div>
                        )}
                    </div>
                );
            })}

            {photos.length > 1 && (
                <>
                    <button
                        onClick={prevSlide}
                        className="absolute left-4 top-1/2 -translate-y-1/2 p-3 bg-white/10 hover:bg-white/30 backdrop-blur-md rounded-full transition-all text-white z-30 opacity-0 group-hover:opacity-100"
                    >
                        <ChevronLeft className="w-6 h-6" />
                    </button>

                    <button
                        onClick={nextSlide}
                        className="absolute right-4 top-1/2 -translate-y-1/2 p-3 bg-white/10 hover:bg-white/30 backdrop-blur-md rounded-full transition-all text-white z-30 opacity-0 group-hover:opacity-100"
                    >
                        <ChevronRight className="w-6 h-6" />
                    </button>

                    {/* Indicators */}
                    <div className="absolute bottom-4 right-8 z-30 flex gap-2">
                        {photos.map((_, index) => (
                            <button
                                key={index}
                                onClick={() => setCurrentSlide(index)}
                                className={`w-2.5 h-2.5 rounded-full transition-all ${index === currentSlide ? 'bg-white w-8' : 'bg-white/50 hover:bg-white/80'
                                    }`}
                            />
                        ))}
                    </div>
                </>
            )}
        </div>
    );
}

