export default function SOPSection({ sops }: SOPSectionProps) {
    return (
        <div className="bg-white p-4 rounded-lg shadow-sm h-auto max-h-[24rem] sm:max-h-[37.5rem] overflow-y-auto border border-gray-100 custom-scrollbar">
