import { useEffect, useState } from 'react';
import { getTodayAttendanceAction } from '@/features/attendance/actions';
import { formatTimeWIB } from '@/lib/timezone';
import { Users, MapPin, Clock } from 'lucide-react';

interface AttendanceRecord {
    id: number;
    purpose: string;
    checkInTime: Date | null;
    dosenPenanggungJawab: string | null;
    user: {
        id: number;
        fullName: string;
        identifier: string;
    };
    room: {
        id: number;
        name: string;
    };
}

export default function TodayAttendance() {
    const [attendance, setAttendance] = useState<AttendanceRecord[]>([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        async function fetchAttendance() {
            try {
                const data = await getTodayAttendanceAction();
                setAttendance(data as AttendanceRecord[]);
            } catch (error) {
                console.error('Failed to fetch attendance:', error);
            } finally {
                setLoading(false);
            }
        }

        fetchAttendance();
    }, []);

    if (loading) {
        return (
            <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
                <div className="animate-pulse">
                    <div className="h-6 w-48 bg-gray-200 rounded mb-4"></div>
                    <div className="space-y-3">
                        <div className="h-16 bg-gray-100 rounded"></div>
                        <div className="h-16 bg-gray-100 rounded"></div>
                    </div>
                </div>
            </div>
        );
    }

    return (
        <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
            <div className="flex items-center gap-2 mb-4">
                <Users className="w-5 h-5 text-[#0F4C81]" />
                <h2 className="text-lg font-semibold text-gray-800">Kehadiran Lab Hari Ini</h2>
                <span className="bg-[#0F4C81] text-white text-xs px-2 py-0.5 rounded-full">{attendance.length}</span>
            </div>

            {attendance.length === 0 ? (
                <div className="text-center py-8 text-gray-400">
                    <Users className="w-12 h-12 mx-auto mb-2 opacity-50" />
                    <p>Belum ada kehadiran hari ini</p>
                </div>
            ) : (
                <div className="space-y-2 max-h-64 overflow-y-auto">
                    {attendance.map((record) => (
                        <div key={record.id} className="flex items-center justify-between p-3 bg-gray-50 rounded-lg hover:bg-gray-100 transition-colors">
                            <div className="flex items-center gap-3">
                                <div className="w-10 h-10 rounded-full bg-[#0F4C81]/10 flex items-center justify-center">
                                    <span className="text-[#0F4C81] font-semibold text-sm">
                                        {record.user.fullName.split(' ').map(n => n[0]).slice(0, 2).join('')}
                                    </span>
                                </div>
                                <div>
                                    <p className="font-medium text-gray-900 text-sm">{record.user.fullName}</p>
                                    <p className="text-xs text-gray-500">{record.user.identifier}</p>
                                </div>
                            </div>
                            <div className="text-right">
                                <div className="flex items-center gap-1 text-xs text-[#0F4C81] font-medium">
                                    <MapPin className="w-3 h-3" />
                                    {record.room.name}
                                </div>
                                <div className="flex items-center gap-1 text-xs text-gray-400 mt-1">
                                    <Clock className="w-3 h-3" />
                                    {formatTimeWIB(record.checkInTime)}
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            )}
        </div>
    );
}

import { getAdminStats } from '@/features/dashboard/actions';
import { getRoomAttendanceStatsAction } from '@/features/attendance/actions';
import { UserService } from '@/features/users/service';
import { TrendingUp, Package, Clock, Calendar, ArrowRight } from 'lucide-react';
import Link from 'next/link';
import DashboardAnalytics from './_components/DashboardAnalytics';
import TodayAttendance from './_components/TodayAttendance';
import RoomAttendanceChart from './_components/RoomAttendanceChart';
import DashboardNotifications from './_components/DashboardNotifications';
import AttendanceButton from '@/features/attendance/components/AttendanceButton';
import { getSession } from '@/lib/auth';

export default async function AdminDashboard() {
    const [stats, roomAttendanceStats, pendingUsers] = await Promise.all([
        getAdminStats(),
        getRoomAttendanceStatsAction(),
        UserService.getPending()
    ]);

    const session = await getSession();

    return (
        <div>
            <div className="flex justify-between items-center mb-6">
                <h1 className="text-2xl font-bold text-gray-900">Dashboard Overview</h1>
                {session && (
                    <AttendanceButton userData={{ identifier: session.user.identifier, role: session.user.role }} />
                )}
            </div>

            {/* Unified Notifications Section */}
            <DashboardNotifications
                pendingUsers={pendingUsers.length}
                pendingLoans={stats.pendingLoans}
                pendingBookings={stats.pendingBookings}
                autoApprovedLoans={stats.autoApprovedLoans}
                autoApprovedBookings={stats.autoApprovedBookings}
                autoReturnedLoans={stats.autoReturnedLoans}
            />

            {/* Smart Analytics Section */}
            <DashboardAnalytics />

            {/* Attendance Section - Grid layout */}
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 mb-6">
                <TodayAttendance />
                <RoomAttendanceChart data={roomAttendanceStats} />
            </div>

            {/* Stats Cards */}
            <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-8">
                <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
                    <div className="flex items-center justify-between mb-2">
                        <h3 className="text-gray-500 text-sm font-medium">Total Alat</h3>
                        <Package className="w-5 h-5 text-primary" />
                    </div>
                    <p className="text-3xl font-bold text-primary">{stats.totalItems}</p>
                </div>

                <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
                    <div className="flex items-center justify-between mb-2">
                        <h3 className="text-gray-500 text-sm font-medium">Peminjaman Aktif</h3>
                        <TrendingUp className="w-5 h-5 text-green-600" />
                    </div>
                    <p className="text-3xl font-bold text-green-600">{stats.activeLoans}</p>
                </div>

                <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
                    <div className="flex items-center justify-between mb-2">
                        <h3 className="text-gray-500 text-sm font-medium">Pending Peminjaman</h3>
                        <Clock className="w-5 h-5 text-orange-500" />
                    </div>
                    <p className="text-3xl font-bold text-orange-500">{stats.pendingLoans}</p>
                    {stats.pendingLoans > 0 && (
                        <Link href="/admin/validations?tab=loans" className="text-xs text-primary hover:underline mt-2 inline-block">
                            Lihat semua →
                        </Link>
                    )}
                </div>

                <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
                    <div className="flex items-center justify-between mb-2">
                        <h3 className="text-gray-500 text-sm font-medium">Pending Booking</h3>
                        <Calendar className="w-5 h-5 text-orange-500" />
                    </div>
                    <p className="text-3xl font-bold text-orange-500">{stats.pendingBookings}</p>
                    {stats.pendingBookings > 0 && (
                        <Link href="/admin/validations?tab=rooms" className="text-xs text-primary hover:underline mt-2 inline-block">
                            Lihat semua →
                        </Link>
                    )}
                </div>
            </div>

            {/* Item Status Distribution */}
            <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100 mb-8">
                <h2 className="text-lg font-semibold mb-4">Status Alat</h2>
                <div className="space-y-3">
                    {stats.itemStats.map((stat) => {
                        const total = stats.totalItems;
                        const percentage = ((stat.count / total) * 100).toFixed(1);
                        const color = stat.status === 'Tersedia' ? 'bg-green-500' :
                            stat.status === 'Dipinjam' ? 'bg-orange-500' : 'bg-gray-500';

                        return (
                            <div key={stat.status}>
                                <div className="flex justify-between text-sm mb-1">
                                    <span className="font-medium text-gray-700">{stat.status}</span>
                                    <span className="text-gray-500">{stat.count} ({percentage}%)</span>
                                </div>
                                <div className="w-full bg-gray-200 rounded-full h-2">
                                    <div className={`${color} h-2 rounded-full`} style={{ width: `${percentage}%` }}></div>
                                </div>
                            </div>
                        );
                    })}
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                {/* Active Loans */}
                <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
                    <div className="flex justify-between items-center mb-4">
                        <h2 className="text-lg font-semibold">Peminjaman Aktif</h2>
                        <Link href="/admin/validations?tab=loans" className="text-sm text-primary hover:underline flex items-center gap-1">
                            Lihat semua <ArrowRight className="w-4 h-4" />
                        </Link>
                    </div>
                    <div className="space-y-3">
                        {stats.recentLoans.filter(loan => loan.status === 'Disetujui').slice(0, 5).map((loan) => (
                            <div key={loan.id} className="flex items-center justify-between p-3 bg-gray-50 rounded-lg">
                                <div className="flex-1">
                                    <p className="font-medium text-gray-900 text-sm">{loan.student.fullName}</p>
                                    <p className="text-xs text-gray-500">{loan.item.name}</p>
                                </div>
                                <span className="text-xs px-2 py-1 rounded bg-green-100 text-green-700">
                                    Aktif
                                </span>
                            </div>
                        ))}
                        {stats.recentLoans.filter(loan => loan.status === 'Disetujui').length === 0 && (
                            <p className="text-center text-gray-500 py-4 text-sm">Tidak ada peminjaman aktif</p>
                        )}
                    </div>
                </div>

                {/* Active Room Bookings */}
                <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
                    <div className="flex justify-between items-center mb-4">
                        <h2 className="text-lg font-semibold">Booking Ruangan Aktif</h2>
                        <Link href="/admin/validations?tab=rooms" className="text-sm text-primary hover:underline flex items-center gap-1">
                            Lihat semua <ArrowRight className="w-4 h-4" />
                        </Link>
                    </div>
                    <div className="space-y-3">
                        {stats.recentBookings.filter(booking => booking.status === 'Disetujui').slice(0, 5).map((booking) => (
                            <div key={booking.id} className="flex items-center justify-between p-3 bg-gray-50 rounded-lg">
                                <div className="flex-1">
                                    <p className="font-medium text-gray-900 text-sm">{booking.user.fullName}</p>
                                    <p className="text-xs text-gray-500" suppressHydrationWarning>
                                        {booking.room.name} • {new Date(booking.startTime).toLocaleDateString('id-ID')}
                                    </p>
                                </div>
                                <span className="text-xs px-2 py-1 rounded bg-green-100 text-green-700">
                                    Aktif
                                </span>
                            </div>
                        ))}
                        {stats.recentBookings.filter(booking => booking.status === 'Disetujui').length === 0 && (
                            <p className="text-center text-gray-500 py-4 text-sm">Tidak ada booking aktif</p>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
}

import { getAllGovernanceDocsForDownload } from '@/features/governance/actions';
import DownloadCenter from '@/features/governance/components/DownloadCenter';
import { getSession, hasPermission } from '@/lib/auth';
import { redirect } from 'next/navigation';

export default async function AdminDownloadCenterPage() {
    const session = await getSession();
    if (!session || !hasPermission(session, 'dashboard.admin')) {
        redirect('/login');
    }

    const documents = await getAllGovernanceDocsForDownload();

    return <DownloadCenter documents={documents} />;
}

import { getGovernanceDocs } from '@/features/governance/actions';
import { getUsers, getRoles, getLecturers } from '@/features/users/actions';
import { getHeroPhotos } from '@/features/hero-photos/actions';
import { getAllPermissions, getRolePermissionMap } from '@/features/permissions/actions';
import GovernanceManager from '@/features/governance/components/GovernanceManager';
import { getSession, hasPermission } from '@/lib/auth';

export default async function GovernancePage() {
    const session = await getSession();

    const canManageGovernance = hasPermission(session, 'governance.manage');
    const canManageUsers = hasPermission(session, 'users.manage');
    const canManageHero = hasPermission(session, 'hero.manage');

    const [sops, lpjs, templateSurats, users, roles, lecturers, heroPhotos, allPermissions, rolePermissionMap] = await Promise.all([
        canManageGovernance ? getGovernanceDocs('SOP') : Promise.resolve([]),
        canManageGovernance ? getGovernanceDocs('LPJ Bulanan') : Promise.resolve([]),
        canManageGovernance ? getGovernanceDocs('Template Surat') : Promise.resolve([]),
        canManageUsers ? getUsers() : Promise.resolve([]),
        canManageUsers ? getRoles() : Promise.resolve([]),
        getLecturers(),
        canManageHero ? getHeroPhotos() : Promise.resolve([]),
        canManageUsers ? getAllPermissions() : Promise.resolve([]),
        canManageUsers ? getRolePermissionMap() : Promise.resolve({}),
    ]);

    return (
        <GovernanceManager
            sops={sops}
            lpjs={lpjs}
            templateSurats={templateSurats}
            users={users}
            roles={roles}
            lecturers={lecturers}
            heroPhotos={heroPhotos}
            adminId={session?.user.identifier || ''}
            allPermissions={allPermissions}
            rolePermissionMap={rolePermissionMap}
            permissions={{ canManageGovernance, canManageUsers, canManageHero }}
        />
    );
}

'use client';

import { useState, useRef, useEffect, useCallback } from 'react';
import { MousePointerClick } from 'lucide-react';

interface HeroFocalPickerProps {
    imageUrl: string;
    initialFocalX?: number;
    initialFocalY?: number;
    onChange: (x: number, y: number) => void;
}

export default function HeroFocalPicker({ imageUrl, initialFocalX = 50, initialFocalY = 50, onChange }: HeroFocalPickerProps) {
    const [focalX, setFocalX] = useState(initialFocalX);
    const [focalY, setFocalY] = useState(initialFocalY);
    const [isDragging, setIsDragging] = useState(false);
    const containerRef = useRef<HTMLDivElement>(null);
    const imgRef = useRef<HTMLImageElement>(null);

    // Update parent when local state changes (debounced/throttled conceptually by drag end, but we'll just fire on change)
    useEffect(() => {
        onChange(focalX, focalY);
    }, [focalX, focalY, onChange]);

    const handleInteractionStart = useCallback((e: React.MouseEvent | React.TouchEvent) => {
        setIsDragging(true);
        updateFocalPoint(e);
    }, []);

    const handleInteractionMove = useCallback((e: MouseEvent | TouchEvent) => {
        if (!isDragging) return;
        updateFocalPoint(e);
    }, [isDragging]);

    const handleInteractionEnd = useCallback(() => {
        setIsDragging(false);
    }, []);

    useEffect(() => {
        if (isDragging) {
            window.addEventListener('mousemove', handleInteractionMove);
            window.addEventListener('mouseup', handleInteractionEnd);
            window.addEventListener('touchmove', handleInteractionMove, { passive: false });
            window.addEventListener('touchend', handleInteractionEnd);
        } else {
            window.removeEventListener('mousemove', handleInteractionMove);
            window.removeEventListener('mouseup', handleInteractionEnd);
            window.removeEventListener('touchmove', handleInteractionMove);
            window.removeEventListener('touchend', handleInteractionEnd);
        }

        return () => {
            window.removeEventListener('mousemove', handleInteractionMove);
            window.removeEventListener('mouseup', handleInteractionEnd);
            window.removeEventListener('touchmove', handleInteractionMove);
            window.removeEventListener('touchend', handleInteractionEnd);
        };
    }, [isDragging, handleInteractionMove, handleInteractionEnd]);

    const updateFocalPoint = (e: React.MouseEvent | React.TouchEvent | MouseEvent | TouchEvent) => {
        if (!containerRef.current || !imgRef.current) return;

        // Prevent scrolling when dragging on touch devices
        if (e.type === 'touchmove') {
            e.preventDefault();
        }

        const containerRect = containerRef.current.getBoundingClientRect();

        let clientX, clientY;
        if ('touches' in e) {
            clientX = e.touches[0].clientX;
            clientY = e.touches[0].clientY;
        } else {
            clientX = (e as React.MouseEvent | MouseEvent).clientX;
            clientY = (e as React.MouseEvent | MouseEvent).clientY;
        }

        // Calculate click position relative to container
        const x = clientX - containerRect.left;
        const y = clientY - containerRect.top;

        // Convert to percentage (0-100)
        let percentX = Math.round((x / containerRect.width) * 100);
        let percentY = Math.round((y / containerRect.height) * 100);

        // Clamp to 0-100
        percentX = Math.max(0, Math.min(100, percentX));
        percentY = Math.max(0, Math.min(100, percentY));

        setFocalX(percentX);
        setFocalY(percentY);
    };

    return (
        <div className="space-y-4">
            <div className="flex items-center justify-between text-sm text-gray-600">
                <p className="flex items-center gap-1.5">
                    <MousePointerClick className="w-4 h-4 text-[#0F4C81]" />
                    Klik dan geser pada gambar untuk menentukan area fokus.
                </p>
                <div className="font-mono bg-gray-100 px-2 py-1 rounded">
                    X: {focalX}% | Y: {focalY}%
                </div>
            </div>

            <div
                className="relative overflow-hidden rounded-xl border-2 border-dashed border-gray-300 bg-gray-50 cursor-crosshair select-none touch-none aspect-video md:aspect-[21/9] w-full"
                ref={containerRef}
                onMouseDown={handleInteractionStart}
                onTouchStart={handleInteractionStart}
            >
                {/* 
                    The image itself is rendered using object-fit: cover 
                    and its object-position is updated in real-time based on focalX and focalY. 
                */}
                <img
                    ref={imgRef}
                    src={imageUrl}
                    alt="Focal point preview"
                    className="w-full h-full object-cover transition-none select-none pointer-events-none"
                    style={{ objectPosition: `${focalX}% ${focalY}%` }}
                    draggable={false}
                />

                {/* Crosshair indicator */}
                <div
                    className="absolute w-6 h-6 -ml-3 -mt-3 pointer-events-none z-10"
                    style={{ left: `${focalX}%`, top: `${focalY}%` }}
                >
                    <div className="absolute inset-0 border-2 border-white rounded-full shadow-[0_0_0_2px_rgba(0,0,0,0.5)]"></div>
                    <div className="absolute top-1/2 left-1/2 w-1.5 h-1.5 -translate-x-1/2 -translate-y-1/2 bg-white rounded-full shadow-[0_0_2px_rgba(0,0,0,0.5)]"></div>
                    {/* Cross lines */}
                    <div className="absolute top-1/2 -left-2 w-10 h-px bg-white/50 -translate-y-1/2 hidden"></div>
                    <div className="absolute left-1/2 -top-2 w-px h-10 bg-white/50 -translate-x-1/2 hidden"></div>
                </div>
            </div>

            <p className="text-xs text-gray-500">
                Area gambar yang tampil di dalam kotak ini merepresentasikan potongan gambar yang akan dilihat pengguna di homepage (rasio layar lebar).
            </p>
        </div>
    );
}

'use client';

import { useState } from 'react';
import { Plus, Pencil, Trash2, Image as ImageIcon, X, Loader2, Upload } from 'lucide-react';
import { addHeroPhoto, updateHeroPhoto, deleteHeroPhoto } from '@/features/hero-photos/actions';
import { useAlert } from '@/components/providers/AlertProvider';
import { translateError } from '@/lib/error';

interface HeroPhoto {
    id: number;
    title: string;
    description: string | null;
    imageUrl: string;
    focalX: number;
    focalY: number;
    link: string | null;
}

import HeroFocalPicker from './HeroFocalPicker';

export default function HeroPhotoManager({ initialPhotos }: { initialPhotos: HeroPhoto[] }) {
    const { showAlert, showConfirm } = useAlert();
    const [photos, setPhotos] = useState(initialPhotos);
    const [editingPhoto, setEditingPhoto] = useState<HeroPhoto | null>(null);
    const [isLoading, setIsLoading] = useState(false);

    const [formData, setFormData] = useState({
        title: '',
        description: '',
        link: '',
        focalX: 50,
        focalY: 50
    });
    const [selectedFile, setSelectedFile] = useState<File | null>(null);
    const [previewUrl, setPreviewUrl] = useState<string>('');
    const [isFocalPickerOpen, setIsFocalPickerOpen] = useState(false);

    const handleEdit = (photo: HeroPhoto) => {
        setEditingPhoto(photo);
        setFormData({
            title: photo.title,
            description: photo.description || '',
            link: photo.link || '',
            focalX: photo.focalX || 50,
            focalY: photo.focalY || 50
        });
        setPreviewUrl(photo.imageUrl);
        setSelectedFile(null);
        setIsFocalPickerOpen(false);
        window.scrollTo({ top: 0, behavior: 'smooth' });
    };

    const handleCancelEdit = () => {
        setEditingPhoto(null);
        setFormData({ title: '', description: '', link: '', focalX: 50, focalY: 50 });
        setPreviewUrl('');
        setSelectedFile(null);
        setIsFocalPickerOpen(false);
    };

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            if (file.size > 2 * 1024 * 1024) {
                showAlert({ title: 'Ukuran Terlalu Besar', message: 'Ukuran file maksimal 2MB', type: 'error' });
                e.target.value = '';
                return;
            }
            setSelectedFile(file);
            const url = URL.createObjectURL(file);
            setPreviewUrl(url);
            setIsFocalPickerOpen(true); // Auto-open for new files
        }
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setIsLoading(true);

        try {
            const data = new FormData();
            data.append('title', formData.title);
            data.append('description', formData.description);
            data.append('link', formData.link);
            data.append('focalX', formData.focalX.toString());
            data.append('focalY', formData.focalY.toString());

            if (selectedFile) {
                data.append('file', selectedFile);
            }

            if (editingPhoto) {
                await updateHeroPhoto(editingPhoto.id, data);
            } else {
                if (!selectedFile) {
                    showAlert({ title: 'Peringatan', message: 'Mohon pilih foto terlebih dahulu', type: 'warning' });
                    setIsLoading(false);
                    return;
                }
                await addHeroPhoto(data);
            }
            window.location.reload();
        } catch (error: any) {
            console.error('Failed to save photo:', error);
            const { title, message } = translateError(error, 'Gagal menyimpan foto');
            showAlert({ title, message, type: 'error' });
        } finally {
            setIsLoading(false);
        }
    };

    const handleDelete = async (id: number) => {
        const confirmed = await showConfirm({
            title: 'Hapus Foto',
            message: 'Apakah Anda yakin ingin menghapus foto ini?',
            type: 'danger',
            confirmText: 'Hapus'
        });
        if (!confirmed) return;
        
        try {
            await deleteHeroPhoto(id);
            setPhotos(photos.filter(p => p.id !== id));
            await showAlert({ title: 'Berhasil', message: 'Foto berhasil dihapus', type: 'success' });
        } catch (error: any) {
            console.error('Failed to delete photo:', error);
            const { title, message } = translateError(error, 'Gagal menghapus foto');
            showAlert({ title, message, type: 'error' });
        }
    };

    return (
        <div>
            {/* Upload Form - Styled like GovernanceUploadForm */}
            <div className="bg-white p-4 md:p-6 rounded-xl shadow-sm border border-gray-100 mb-8">
                <h2 className="text-lg font-semibold mb-4 flex items-center gap-2">
                    <Upload className="w-5 h-5 text-primary" />
                    {editingPhoto ? 'Edit Foto Hero' : 'Upload Foto Hero Baru'}
                </h2>
                <form onSubmit={handleSubmit} className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div className="md:col-span-2">
                        <label className="block text-sm font-medium text-gray-700 mb-1">Judul Foto</label>
                        <input
                            type="text"
                            required
                            value={formData.title}
                            onChange={e => setFormData({ ...formData, title: e.target.value })}
                            className="w-full px-4 py-2 rounded-lg border border-gray-200 focus:outline-none focus:ring-2 focus:ring-primary/20"
                            placeholder="Contoh: Kegiatan Workshop"
                        />
                    </div>

                    <div className="md:col-span-2">
                        <label className="block text-sm font-medium text-gray-700 mb-1">
                            {editingPhoto ? 'Foto (Opsional) - Biarkan kosong jika tidak ingin mengubah' : 'Foto'}
                        </label>
                        <div className="border-2 border-dashed border-gray-300 rounded-lg p-4 text-center hover:bg-gray-50 transition-colors cursor-pointer relative">
                            <input
                                type="file"
                                accept="image/*"
                                onChange={handleFileChange}
                                className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10"
                                required={!editingPhoto}
                            />
                            {previewUrl ? (
                                <div className="relative h-40 w-full">
                                    <img
                                        src={previewUrl}
                                        alt="Preview"
                                        className="w-full h-full object-cover rounded-lg"
                                        style={{ objectPosition: `${formData.focalX}% ${formData.focalY}%` }}
                                    />
                                    <div className="absolute inset-0 flex items-center justify-center bg-black/50 opacity-0 hover:opacity-100 transition-opacity rounded-lg text-white text-sm font-medium">
                                        Ganti Foto
                                    </div>
                                </div>
                            ) : (
                                <div className="py-8">
                                    <ImageIcon className="w-12 h-12 text-gray-400 mx-auto mb-2" />
                                    <p className="text-sm text-gray-500">Klik atau drag foto ke sini</p>
                                    <p className="text-xs text-gray-400 mt-1">Maksimal 2MB</p>
                                </div>
                            )}
                        </div>
                    </div>

                    {/* Focal Picker Section */}
                    {previewUrl && !isFocalPickerOpen && (
                        <div className="md:col-span-2">
                            <button
                                type="button"
                                onClick={() => setIsFocalPickerOpen(true)}
                                className="flex items-center justify-center gap-2 w-full py-3 border-2 border-dashed border-primary/30 text-primary hover:bg-primary/5 rounded-lg font-medium transition-colors"
                            >
                                <span className="text-xl">⛶</span> Atur Area Fokus Gambar
                            </button>
                        </div>
                    )}

                    {previewUrl && isFocalPickerOpen && (
                        <div className="md:col-span-2 bg-gray-50 p-4 rounded-lg border border-gray-200">
                            <div className="flex justify-between items-center mb-3">
                                <label className="block text-sm font-semibold text-gray-800">Menyesuaikan Titik Fokus</label>
                                <button
                                    type="button"
                                    onClick={() => setIsFocalPickerOpen(false)}
                                    className="text-xs bg-white border border-gray-300 px-3 py-1.5 rounded-md shadow-sm hover:bg-gray-100 font-medium"
                                >
                                    Selesai Atur Fokus
                                </button>
                            </div>
                            <HeroFocalPicker
                                imageUrl={previewUrl}
                                initialFocalX={formData.focalX}
                                initialFocalY={formData.focalY}
                                onChange={(x, y) => setFormData(prev => ({ ...prev, focalX: x, focalY: y }))}
                            />
                        </div>
                    )}

                    <div className="md:col-span-2">
                        <label className="block text-sm font-medium text-gray-700 mb-1">Link / URL (Opsional)</label>
                        <input
                            type="url"
                            value={formData.link}
                            onChange={e => setFormData({ ...formData, link: e.target.value })}
                            className="w-full px-4 py-2 rounded-lg border border-gray-200 focus:outline-none focus:ring-2 focus:ring-primary/20"
                            placeholder="https://example.com/detail-kegiatan"
                        />
                        <p className="text-xs text-gray-500 mt-1">Jika diisi, foto akan mengarah ke link ini saat diklik.</p>
                    </div>

                    <div className="md:col-span-2">
                        <label className="block text-sm font-medium text-gray-700 mb-1">Deskripsi</label>
                        <textarea
                            value={formData.description}
                            onChange={e => setFormData({ ...formData, description: e.target.value })}
                            className="w-full px-4 py-2 rounded-lg border border-gray-200 focus:outline-none focus:ring-2 focus:ring-primary/20 h-24 resize-none"
                            placeholder="Deskripsi singkat kegiatan..."
                        />
                    </div>

                    <div className="md:col-span-2 flex gap-2">
                        <button
                            type="submit"
                            disabled={isLoading}
                            className="bg-[#0F4C81] text-white px-4 py-2 rounded-lg text-sm font-medium hover:bg-[#0F4C81]/90 transition-colors disabled:opacity-50 w-full md:w-auto flex items-center justify-center gap-2"
                        >
                            {isLoading && <Loader2 className="w-4 h-4 animate-spin" />}
                            {editingPhoto ? 'Simpan Perubahan' : 'Upload Foto'}
                        </button>
                        {editingPhoto && (
                            <button
                                type="button"
                                onClick={handleCancelEdit}
                                className="bg-gray-100 text-gray-700 px-6 py-2 rounded-lg hover:bg-gray-200 transition-colors font-medium w-full md:w-auto"
                            >
                                Batal
                            </button>
                        )}
                    </div>
                </form>
            </div>

            {/* Photo List */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {photos.map((photo) => (
                    <div key={photo.id} className="bg-white rounded-xl border border-gray-100 shadow-sm overflow-hidden group">
                        <div className="relative h-48 w-full bg-gray-100">
                            {photo.imageUrl ? (
                                <img
                                    src={photo.imageUrl}
                                    alt={photo.title}
                                    className="w-full h-full object-cover"
                                    style={{ objectPosition: `${photo.focalX}% ${photo.focalY}%` }}
                                />
                            ) : (
                                <div className="flex items-center justify-center h-full text-gray-400">
                                    <ImageIcon className="w-8 h-8" />
                                </div>
                            )}
                            <div className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center gap-2">
                                <button
                                    onClick={() => handleEdit(photo)}
                                    className="p-2 bg-white/20 hover:bg-white/40 text-white rounded-lg backdrop-blur-sm transition-colors"
                                >
                                    <Pencil className="w-4 h-4" />
                                </button>
                                <button
                                    onClick={() => handleDelete(photo.id)}
                                    className="p-2 bg-red-500/20 hover:bg-red-500/40 text-red-500 hover:text-red-100 rounded-lg backdrop-blur-sm transition-colors"
                                >
                                    <Trash2 className="w-4 h-4" />
                                </button>
                            </div>
                        </div>
                        <div className="p-4">
                            <h3 className="font-semibold text-gray-900 mb-1">{photo.title}</h3>
                            <p className="text-sm text-gray-500 line-clamp-2">{photo.description}</p>
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
}

