'use client';

import { useState, useTransition } from 'react';
import { MapPin, User, CheckCircle, XCircle, Eye, X, ExternalLink, LayoutGrid, List, Trash2 } from 'lucide-react';
import { updateBookingStatus, deleteBooking } from '@/features/bookings/actions';
import { useAlert } from '@/components/providers/AlertProvider';
import { translateError } from '@/lib/error';
import RejectReasonModal from '@/components/ui/RejectReasonModal';

interface Booking {
    id: number;
    status: string | null;
    startTime: Date;
    endTime: Date;
    purpose: string;
    organisasi?: string | null;
    jumlahPeserta?: number | null;
    dosenPembimbing?: string | null;
    suratPermohonan?: string | null;
    user: { fullName: string; identifier: string; phoneNumber?: string | null; };
    room: { name: string; };
}

interface ActiveBookingsTableProps {
    bookings: Booking[];
    sessionUserId: string;
}

export default function ActiveBookingsTable({ bookings, sessionUserId }: ActiveBookingsTableProps) {
    const { showAlert, showConfirm } = useAlert();
    const [isPending, startTransition] = useTransition();
    const [selectedBooking, setSelectedBooking] = useState<Booking | null>(null);
    const [rejectModalOpen, setRejectModalOpen] = useState(false);
    const [rejectingBookingId, setRejectingBookingId] = useState<number | null>(null);

    const [viewMode, setViewMode] = useState<'grid' | 'list'>(() => {
        if (typeof window !== 'undefined') {
            return window.innerWidth >= 768 ? 'list' : 'grid';
        }
        return 'list';
    });

    const handleApprove = (bookingId: number) => {
        startTransition(async () => {
            await updateBookingStatus(bookingId, 'Disetujui', sessionUserId);
        });
    };

    const handleReject = (bookingId: number) => {
        setRejectingBookingId(bookingId);
        setRejectModalOpen(true);
    };

    const handleRejectConfirm = (reason: string) => {
        if (rejectingBookingId === null) return;
        const bookingId = rejectingBookingId;
        setRejectModalOpen(false);
        setRejectingBookingId(null);
        startTransition(async () => {
            try {
                await updateBookingStatus(bookingId, 'Ditolak', sessionUserId, reason || undefined);
                showAlert({ title: 'Berhasil', message: 'Permintaan booking ditolak', type: 'success' });
            } catch (error: any) {
                const { title, message } = translateError(error, 'Gagal menolak booking');
                showAlert({ title, message, type: 'error' });
            }
        });
    };

    const handleDelete = async (bookingId: number) => {
        const confirmed = await showConfirm({
            title: 'Hapus Booking',
            message: 'Apakah Anda yakin ingin menghapus booking ini? Data tidak dapat dikembalikan.',
            type: 'danger',
            confirmText: 'Hapus'
        });
        if (confirmed) {
            startTransition(async () => {
                try {
                    await deleteBooking(bookingId);
                    showAlert({ title: 'Berhasil', message: 'Booking berhasil dihapus', type: 'success' });
                } catch (error: any) {
                    const { title, message } = translateError(error, 'Gagal menghapus booking');
                    showAlert({ title, message, type: 'error' });
                }
            });
        }
    };

    return (
        <>
            <div className="flex justify-end mb-4">
                <div className="hidden md:flex items-center bg-gray-100 rounded-lg p-0.5">
                    <button
                        onClick={() => setViewMode('grid')}
                        className={`p-1.5 rounded ${viewMode === 'grid' ? 'bg-white shadow-sm text-[#0F4C81]' : 'text-gray-500 hover:text-gray-700'}`} title="Tampilan Grid">
                        <LayoutGrid className="w-4 h-4" />
                    </button>
                    <button
                        onClick={() => setViewMode('list')}
                        className={`p-1.5 rounded ${viewMode === 'list' ? 'bg-white shadow-sm text-[#0F4C81]' : 'text-gray-500 hover:text-gray-700'}`} title="Tampilan List">
                        <List className="w-4 h-4" />
                    </button>
                </div>
            </div>
            {/* Users List */}
            <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
                {/* Table View (Hidden on mobile, toggled on desktop) */}
                {viewMode === 'list' && (
                <div className="overflow-x-auto hidden md:block">
                    <table className="w-full text-left">
                    <thead className="bg-gray-50 border-b border-gray-100">
                        <tr>
                            <th className="px-6 py-4 font-semibold text-gray-700">Pemohon</th>
                            <th className="px-6 py-4 font-semibold text-gray-700">Ruangan</th>
                            <th className="px-6 py-4 font-semibold text-gray-700">Tanggal & Waktu</th>
                            <th className="px-6 py-4 font-semibold text-gray-700">Keperluan</th>
                            <th className="px-6 py-4 font-semibold text-gray-700">Status</th>
                            <th className="px-6 py-4 font-semibold text-gray-700 text-center">Aksi</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-100">
                        {bookings.map((booking) => (
                            <tr key={booking.id} className={`hover:bg-gray-50 transition-colors ${isPending ? 'opacity-50' : ''}`}>
                                <td className="px-6 py-4">
                                    <div className="flex items-center gap-2">
                                        <User className="w-4 h-4 text-gray-400" />
                                        <div>
                                            <p className="font-medium text-gray-900">{booking.user.fullName}</p>
                                            <p className="text-xs text-gray-500">{booking.user.identifier}</p>
                                        </div>
                                    </div>
                                </td>
                                <td className="px-6 py-4">
                                    <div className="flex items-center gap-2">
                                        <MapPin className="w-4 h-4 text-[#0F4C81]" />
                                        <span className="font-medium text-gray-900">{booking.room.name}</span>
                                    </div>
                                </td>
                                <td className="px-6 py-4 text-gray-600 text-sm">
                                    <div>{new Date(booking.startTime).toLocaleDateString('id-ID')}</div>
                                    <div className="text-xs text-gray-500">
                                        {new Date(booking.startTime).toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' })} -
                                        {new Date(booking.endTime).toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' })}
                                    </div>
                                </td>
                                <td className="px-6 py-4 text-gray-600 text-sm max-w-xs truncate">
                                    {booking.purpose}
                                </td>
                                <td className="px-6 py-4">
                                    <span className={`inline-flex px-2 py-1 rounded text-xs font-medium ${booking.status === 'Pending' ? 'bg-yellow-50 text-yellow-700' :
                                        booking.status === 'Disetujui' ? 'bg-green-50 text-green-700' :
                                            'bg-red-50 text-red-700'
                                        }`}>
                                        {booking.status}
                                    </span>
                                </td>
                                <td className="px-6 py-4">
                                    <div className="flex items-center justify-center gap-1">
                                        {/* View Details Button */}
                                        <button
                                            onClick={() => setSelectedBooking(booking)}
                                            className="text-[#0F4C81] hover:text-blue-700 p-1.5 hover:bg-blue-50 rounded-lg transition-colors"
                                            title="Lihat Detail"
                                        >
                                            <Eye className="w-4 h-4" />
                                        </button>

                                        {booking.status === 'Pending' && (
                                            <>
                                                <button
                                                    onClick={() => handleApprove(booking.id)}
                                                    disabled={isPending}
                                                    className="text-green-600 hover:text-green-700 p-1.5 hover:bg-green-50 rounded-lg transition-colors disabled:opacity-50"
                                                    title="Setujui"
                                                >
                                                    <CheckCircle className="w-4 h-4" />
                                                </button>
                                                <button
                                                    onClick={() => handleReject(booking.id)}
                                                    disabled={isPending}
                                                    className="text-red-600 hover:text-red-700 p-1.5 hover:bg-red-50 rounded-lg transition-colors disabled:opacity-50"
                                                    title="Tolak"
                                                >
                                                    <XCircle className="w-4 h-4" />
                                                </button>
                                            </>
                                        )}
                                        <button
                                            onClick={() => handleDelete(booking.id)}
                                            disabled={isPending}
                                            className="text-red-500 hover:text-red-700 p-1.5 hover:bg-red-50 rounded-lg transition-colors disabled:opacity-50"
                                            title="Hapus"
                                        >
                                            <Trash2 className="w-4 h-4" />
                                        </button>
                                    </div>
                                </td>
                            </tr>
                        ))}
                        {bookings.length === 0 && (
                            <tr>
                                <td colSpan={6} className="px-6 py-12 text-center text-gray-500">
                                    Belum ada permintaan booking.
                                </td>
                            </tr>
                        )}
                    </tbody>
                </table>
            </div>
                )}

                {/* Grid/Card View — always on mobile, desktop only in grid mode */}
                <div className={`p-4 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 ${viewMode === 'grid' ? 'grid' : 'grid md:hidden'}`}>
                        {bookings.map((booking) => (
                            <div key={booking.id} className={`bg-white border rounded-xl p-4 flex flex-col gap-3 shadow-sm hover:shadow-md transition-shadow ${isPending ? 'opacity-50' : ''}`}>
                                <div className="flex justify-between items-start">
                                    <div className="flex items-center gap-3">
                                        <div className="w-10 h-10 rounded-full bg-blue-50 flex items-center justify-center text-blue-600 shrink-0">
                                            <MapPin className="w-5 h-5" />
                                        </div>
                                        <div className="min-w-0">
                                            <p className="font-semibold text-gray-900 break-words" title={booking.room.name}>{booking.room.name}</p>
                                            <p className="text-xs text-gray-500 break-words" title={booking.purpose}>{booking.purpose}</p>
                                        </div>
                                    </div>
                                    <span className={`inline-flex px-2 py-1 rounded text-[10px] font-bold uppercase tracking-wider ${
                                        booking.status === 'Pending' ? 'bg-yellow-100 text-yellow-700' :
                                        booking.status === 'Disetujui' ? 'bg-green-100 text-green-700' :
                                        'bg-red-100 text-red-700'
                                    }`}>
                                        {booking.status}
                                    </span>
                                </div>
                                
                                <div className="bg-gray-50 rounded-lg p-3 space-y-2 text-sm">
                                    <div className="flex items-center gap-2 text-gray-700">
                                        <User className="w-4 h-4 text-gray-400 shrink-0" />
                                        <span className="break-words" title={booking.user.fullName}>{booking.user.fullName} ({booking.user.identifier})</span>
                                    </div>
                                    <div className="flex justify-between items-center text-xs text-gray-600 pt-1 border-t border-gray-200">
                                        <span>{new Date(booking.startTime).toLocaleDateString('id-ID')}</span>
                                        <span>
                                            {new Date(booking.startTime).toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' })}
                                            {' - '}
                                            {new Date(booking.endTime).toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' })}
                                        </span>
                                    </div>
                                </div>
                                
                                <div className="flex justify-end gap-2 mt-auto pt-2">
                                    <button
                                        onClick={() => setSelectedBooking(booking)}
                                        className="flex-1 flex justify-center items-center gap-1 text-[#0F4C81] bg-blue-50 hover:bg-blue-100 py-2 rounded-lg text-xs font-semibold transition-colors"
                                    >
                                        <Eye className="w-3.5 h-3.5" /> Detail
                                    </button>
                                    
                                    {booking.status === 'Pending' && (
                                        <>
                                            <button
                                                onClick={() => handleApprove(booking.id)}
                                                disabled={isPending}
                                                className="flex-1 flex justify-center items-center gap-1 text-green-700 bg-green-50 hover:bg-green-100 py-2 rounded-lg text-xs font-semibold transition-colors disabled:opacity-50"
                                            >
                                                <CheckCircle className="w-3.5 h-3.5" /> Setuju
                                            </button>
                                            <button
                                                onClick={() => handleReject(booking.id)}
                                                disabled={isPending}
                                                className="flex-1 flex justify-center items-center gap-1 text-red-700 bg-red-50 hover:bg-red-100 py-2 rounded-lg text-xs font-semibold transition-colors disabled:opacity-50"
                                            >
                                                <XCircle className="w-3.5 h-3.5" /> Tolak
                                            </button>
                                        </>
                                    )}
                                    <button
                                        onClick={() => handleDelete(booking.id)}
                                        disabled={isPending}
                                        className="flex justify-center items-center gap-1 text-red-500 bg-red-50 hover:bg-red-100 py-2 px-3 rounded-lg text-xs font-semibold transition-colors disabled:opacity-50"
                                    >
                                        <Trash2 className="w-3.5 h-3.5" />
                                    </button>
                                </div>
                            </div>
                        ))}
                        {bookings.length === 0 && (
                            <div className="col-span-full py-12 text-center text-gray-500 border rounded-xl border-dashed">
                                Belum ada permintaan booking.
                            </div>
                        )}
                </div>
            </div>

            {/* Modal Detail Booking */}
            {selectedBooking && (
                <div className="fixed inset-0 bg-black/50 flex flex-col items-center justify-center z-50 p-4">
                    <div className="bg-white rounded-xl shadow-xl max-w-2xl w-full max-h-[90vh] overflow-y-auto">
                        <div className="p-6 border-b border-gray-100 flex items-center justify-between sticky top-0 bg-white z-10">
                            <h3 className="text-lg font-semibold text-gray-900 flex items-center gap-2">
                                <MapPin className="w-5 h-5 text-[#0F4C81]" />
                                Detail Booking Ruangan
                            </h3>
                            <button
                                onClick={() => setSelectedBooking(null)}
                                className="text-gray-400 hover:text-gray-600"
                            >
                                <X className="w-5 h-5" />
                            </button>
                        </div>
                        <div className="p-6 space-y-6">
                            {/* Data Pemohon */}
                            <div>
                                <h4 className="font-medium text-gray-900 border-b pb-2 mb-3">Data Pemesan</h4>
                                <div className="grid grid-cols-2 gap-4 text-sm">
                                    <div>
                                        <p className="text-gray-500">Nama Lengkap</p>
                                        <p className="font-medium text-gray-900">{selectedBooking.user.fullName}</p>
                                    </div>
                                    <div>
                                        <p className="text-gray-500">NIM / Identifier</p>
                                        <p className="font-medium text-gray-900">{selectedBooking.user.identifier}</p>
                                    </div>
                                    <div>
                                        <p className="text-gray-500">Nomor HP</p>
                                        <p className="font-medium text-gray-900">{selectedBooking.user.phoneNumber || '-'}</p>
                                    </div>
                                    <div>
                                        <p className="text-gray-500">Dosen Pembimbing</p>
                                        <p className="font-medium text-gray-900">{selectedBooking.dosenPembimbing || '-'}</p>
                                    </div>
                                </div>
                            </div>

                            {/* Detail Booking */}
                            <div>
                                <h4 className="font-medium text-gray-900 border-b pb-2 mb-3">Detail Booking</h4>
                                <div className="grid grid-cols-2 gap-4 text-sm">
                                    <div>
                                        <p className="text-gray-500">Ruangan</p>
                                        <p className="font-medium text-gray-900">{selectedBooking.room.name}</p>
                                    </div>
                                    <div>
                                        <p className="text-gray-500">Tanggal</p>
                                        <p className="font-medium text-gray-900">
                                            {new Date(selectedBooking.startTime).toLocaleDateString('id-ID')}
                                        </p>
                                    </div>
                                    <div>
                                        <p className="text-gray-500">Waktu</p>
                                        <p className="font-medium text-gray-900">
                                            {new Date(selectedBooking.startTime).toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' })}
                                            {' s.d '}
                                            {new Date(selectedBooking.endTime).toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' })}
                                        </p>
                                    </div>
                                    <div>
                                        <p className="text-gray-500">Jumlah Peserta</p>
                                        <p className="font-medium text-gray-900">{selectedBooking.jumlahPeserta || '-'} Orang</p>
                                    </div>
                                    <div>
                                        <p className="text-gray-500">Organisasi / Unit</p>
                                        <p className="font-medium text-gray-900">{selectedBooking.organisasi || '-'}</p>
                                    </div>
                                    <div className="col-span-2">
                                        <p className="text-gray-500">Keperluan</p>
                                        <p className="font-medium text-gray-900 mt-1 bg-gray-50 p-3 rounded-lg border border-gray-100">{selectedBooking.purpose}</p>
                                    </div>
                                </div>
                            </div>

                            {/* Dokumen */}
                            {selectedBooking.suratPermohonan && (
                                <div>
                                    <h4 className="font-medium text-gray-900 border-b pb-2 mb-3">Dokumen Tambahan</h4>
                                    <div className="text-sm border border-gray-100 p-4 rounded-xl bg-gray-50 flex items-center justify-between">
                                        <div className="flex items-center gap-2">
                                            <ExternalLink className="w-5 h-5 text-gray-400" />
                                            <span className="font-medium text-gray-900">Surat Permohonan / Izin</span>
                                        </div>
                                        <a href={selectedBooking.suratPermohonan} target="_blank" rel="noopener noreferrer" className="text-[#0F4C81] hover:underline font-medium">Buka File</a>
                                    </div>
                                </div>
                            )}

                        </div>
                        <div className="p-6 border-t border-gray-100 flex justify-end">
                            <button
                                onClick={() => setSelectedBooking(null)}
                                className="bg-gray-100 text-gray-700 px-6 py-2 rounded-lg text-sm font-medium hover:bg-gray-200 transition-colors"
                            >
                                Tutup
                            </button>
                        </div>
                    </div>
                </div>
            )}
            <RejectReasonModal
                isOpen={rejectModalOpen}
                onClose={() => { setRejectModalOpen(false); setRejectingBookingId(null); }}
                onConfirm={handleRejectConfirm}
                title="Tolak Booking Ruangan"
                isPending={isPending}
            />
        </>
    );
}

'use client';

import { useState, useTransition } from 'react';
import { Box, User, CheckCircle, XCircle, Eye, X, ExternalLink, LayoutGrid, List } from 'lucide-react';
import { updateLoanStatus, adminDirectReturn } from '@/features/loans/actions';
import { useAlert } from '@/components/providers/AlertProvider';
import { translateError } from '@/lib/error';
import RejectReasonModal from '@/components/ui/RejectReasonModal';

interface Loan {
    id: number;
    status: string | null;
    requestDate: Date | null;
    returnPlanDate: Date;
    returnStatus: string | null;
    organisasi?: string | null;
    purpose?: string | null;
    dosenPembimbing?: string | null;
    suratIzin?: string | null;
    startTime?: Date | null;
    endTime?: Date | null;
    software?: string | null;
    student: { fullName: string; identifier: string; phoneNumber?: string | null };
    item: { name: string; category: { name: string; }; };
}

interface ActiveLoansTableProps {
    loans: Loan[];
    sessionUserId: string;
}

export default function ActiveLoansTable({ loans, sessionUserId }: ActiveLoansTableProps) {
    const { showConfirm, showAlert } = useAlert();
    const [isPending, startTransition] = useTransition();
    const [selectedLoan, setSelectedLoan] = useState<Loan | null>(null);
    const [rejectModalOpen, setRejectModalOpen] = useState(false);
    const [rejectingLoanId, setRejectingLoanId] = useState<number | null>(null);

    // View Mode State
    const [viewMode, setViewMode] = useState<'grid' | 'list'>(() => {
        if (typeof window !== 'undefined') {
            return window.innerWidth >= 768 ? 'list' : 'grid';
        }
        return 'list';
    });

    const handleApprove = (loanId: number) => {
        startTransition(async () => {
            await updateLoanStatus(loanId, 'Disetujui', sessionUserId);
        });
    };

    const handleReject = (loanId: number) => {
        setRejectingLoanId(loanId);
        setRejectModalOpen(true);
    };

    const handleRejectConfirm = (reason: string) => {
        if (rejectingLoanId === null) return;
        const loanId = rejectingLoanId;
        setRejectModalOpen(false);
        setRejectingLoanId(null);
        startTransition(async () => {
            try {
                await updateLoanStatus(loanId, 'Ditolak', sessionUserId, reason || undefined);
                showAlert({ title: 'Berhasil', message: 'Permintaan pinjaman ditolak', type: 'success' });
            } catch (error: any) {
                const { title, message } = translateError(error, 'Gagal menolak peminjaman');
                showAlert({ title, message, type: 'error' });
            }
        });
    };

    const handleReturn = async (loanId: number) => {
        const confirmed = await showConfirm({
            title: 'Konfirmasi Pengembalian',
            message: 'Konfirmasi pengembalian alat?',
            type: 'warning',
            confirmText: 'Konfirmasi'
        });
        if (!confirmed) return;
        startTransition(async () => {
            try {
                await adminDirectReturn(loanId, sessionUserId);
                showAlert({ title: 'Berhasil', message: 'Alat berhasil dikembalikan', type: 'success' });
            } catch (error: any) {
                const { title, message } = translateError(error, 'Gagal memproses pengembalian');
                showAlert({ title, message, type: 'error' });
            }
        });
    };

    return (
        <>
            <div className="flex justify-end mb-4">
                <div className="hidden md:flex items-center bg-gray-100 rounded-lg p-0.5">
                    <button
                        onClick={() => setViewMode('grid')}
                        className={`p-1.5 rounded ${viewMode === 'grid' ? 'bg-white shadow-sm text-[#0F4C81]' : 'text-gray-500 hover:text-gray-700'}`} title="Tampilan Grid">
                        <LayoutGrid className="w-4 h-4" />
                    </button>
                    <button
                        onClick={() => setViewMode('list')}
                        className={`p-1.5 rounded ${viewMode === 'list' ? 'bg-white shadow-sm text-[#0F4C81]' : 'text-gray-500 hover:text-gray-700'}`} title="Tampilan List">
                        <List className="w-4 h-4" />
                    </button>
                </div>
            </div>

            {/* Users List */}
            <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
                {/* Table View (Hidden on mobile, toggled on desktop) */}
                {viewMode === 'list' && (
                <div className="overflow-x-auto hidden md:block">
                    <table className="w-full text-left">
                    <thead className="bg-gray-50 border-b border-gray-100">
                        <tr>
                            <th className="px-6 py-4 font-semibold text-gray-700">Mahasiswa</th>
                            <th className="px-6 py-4 font-semibold text-gray-700">Alat</th>
                            <th className="px-6 py-4 font-semibold text-gray-700">Tanggal Pinjam</th>
                            <th className="px-6 py-4 font-semibold text-gray-700">Rencana Kembali</th>
                            <th className="px-6 py-4 font-semibold text-gray-700">Status</th>
                            <th className="px-6 py-4 font-semibold text-gray-700 text-center">Aksi</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-100">
                        {loans.map((loan) => (
                            <tr key={loan.id} className={`hover:bg-gray-50 transition-colors ${isPending ? 'opacity-50' : ''}`}>
                                <td className="px-6 py-4">
                                    <div className="flex items-center gap-2">
                                        <User className="w-4 h-4 text-gray-400" />
                                        <div>
                                            <p className="font-medium text-gray-900">{loan.student.fullName}</p>
                                            <p className="text-xs text-gray-500">{loan.student.identifier}</p>
                                        </div>
                                    </div>
                                </td>
                                <td className="px-6 py-4">
                                    <div className="flex items-center gap-2">
                                        <Box className="w-4 h-4 text-[#0F4C81]" />
                                        <div>
                                            <p className="font-medium text-gray-900">{loan.item.name}</p>
                                            <p className="text-xs text-gray-500">{loan.item.category.name}</p>
                                        </div>
                                    </div>
                                </td>
                                <td className="px-6 py-4 text-gray-600 text-sm">
                                    {new Date(loan.requestDate!).toLocaleDateString('id-ID')}
                                </td>
                                <td className="px-6 py-4 text-gray-600 text-sm">
                                    {new Date(loan.returnPlanDate).toLocaleDateString('id-ID')}
                                </td>
                                <td className="px-6 py-4">
                                    <span className={`inline-flex px-2 py-1 rounded text-xs font-medium ${loan.status === 'Pending' ? 'bg-yellow-50 text-yellow-700' :
                                        loan.status === 'Disetujui' ? 'bg-green-50 text-green-700' :
                                            'bg-red-50 text-red-700'
                                        }`}>
                                        {loan.status}
                                    </span>
                                </td>
                                <td className="px-6 py-4">
                                    <div className="flex items-center justify-center gap-1">
                                        {/* View Details Button */}
                                        <button
                                            onClick={() => setSelectedLoan(loan)}
                                            className="text-[#0F4C81] hover:text-blue-700 p-1.5 hover:bg-blue-50 rounded-lg transition-colors"
                                            title="Lihat Detail"
                                        >
                                            <Eye className="w-4 h-4" />
                                        </button>

                                        {loan.status === 'Pending' && (
                                            <>
                                                <button
                                                    onClick={() => handleApprove(loan.id)}
                                                    disabled={isPending}
                                                    className="text-green-600 hover:text-green-700 p-1.5 hover:bg-green-50 rounded-lg transition-colors disabled:opacity-50"
                                                    title="Setujui"
                                                >
                                                    <CheckCircle className="w-4 h-4" />
                                                </button>
                                                <button
                                                    onClick={() => handleReject(loan.id)}
                                                    disabled={isPending}
                                                    className="text-red-600 hover:text-red-700 p-1.5 hover:bg-red-50 rounded-lg transition-colors disabled:opacity-50"
                                                    title="Tolak"
                                                >
                                                    <XCircle className="w-4 h-4" />
                                                </button>
                                            </>
                                        )}
                                        {loan.status === 'Disetujui' && (
                                            <button
                                                onClick={() => handleReturn(loan.id)}
                                                disabled={isPending}
                                                className="flex items-center gap-1 ml-2 px-3 py-1.5 bg-[#0F4C81] text-white rounded-lg text-sm hover:bg-[#0F4C81]/90 transition-colors disabled:opacity-50"
                                                title="Konfirmasi Pengembalian"
                                            >
                                                <CheckCircle className="w-4 h-4" />
                                                Kembalikan
                                            </button>
                                        )}
                                    </div>
                                </td>
                            </tr>
                        ))}
                        {loans.length === 0 && (
                            <tr>
                                <td colSpan={6} className="px-6 py-12 text-center text-gray-500">
                                    Belum ada permintaan peminjaman.
                                </td>
                            </tr>
                        )}
                    </tbody>
                </table>
                </div>
                )}

                {/* Grid/Card View — always on mobile, desktop only in grid mode */}
                <div className={`p-4 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 ${viewMode === 'grid' ? 'grid' : 'grid md:hidden'}`}>
                        {loans.map((loan) => (
                            <div key={loan.id} className={`bg-white border rounded-xl p-4 flex flex-col gap-3 shadow-sm hover:shadow-md transition-shadow ${isPending ? 'opacity-50' : ''}`}>
                                <div className="flex justify-between items-start">
                                    <div className="flex items-center gap-3">
                                        <div className="w-10 h-10 rounded-full bg-blue-50 flex items-center justify-center text-blue-600 shrink-0">
                                            <Box className="w-5 h-5" />
                                        </div>
                                        <div className="min-w-0">
                                            <p className="font-semibold text-gray-900 break-words" title={loan.item.name}>{loan.item.name}</p>
                                            <p className="text-xs text-gray-500 break-words">{loan.item.category.name}</p>
                                        </div>
                                    </div>
                                    <span className={`inline-flex px-2 py-1 rounded text-[10px] font-bold uppercase tracking-wider ${
                                        loan.status === 'Pending' ? 'bg-yellow-100 text-yellow-700' :
                                        loan.status === 'Disetujui' ? 'bg-green-100 text-green-700' :
                                        'bg-red-100 text-red-700'
                                    }`}>
                                        {loan.status}
                                    </span>
                                </div>
                                
                                <div className="bg-gray-50 rounded-lg p-3 space-y-2 text-sm">
                                    <div className="flex items-center gap-2 text-gray-700">
                                        <User className="w-4 h-4 text-gray-400 shrink-0" />
                                        <span className="break-words" title={loan.student.fullName}>{loan.student.fullName} ({loan.student.identifier})</span>
                                    </div>
                                    <div className="flex justify-between items-center text-xs text-gray-600 pt-1 border-t border-gray-200">
                                        <span>Pinjam: {new Date(loan.requestDate!).toLocaleDateString('id-ID')}</span>
                                        <span>Kembali: {new Date(loan.returnPlanDate).toLocaleDateString('id-ID')}</span>
                                    </div>
                                </div>
                                
                                <div className="flex justify-end gap-2 mt-auto pt-2">
                                    <button
                                        onClick={() => setSelectedLoan(loan)}
                                        className="flex-1 flex justify-center items-center gap-1 text-[#0F4C81] bg-blue-50 hover:bg-blue-100 py-2 rounded-lg text-xs font-semibold transition-colors"
                                    >
                                        <Eye className="w-3.5 h-3.5" /> Detail
                                    </button>
                                    
                                    {loan.status === 'Pending' && (
                                        <>
                                            <button
                                                onClick={() => handleApprove(loan.id)}
                                                disabled={isPending}
                                                className="flex-1 flex justify-center items-center gap-1 text-green-700 bg-green-50 hover:bg-green-100 py-2 rounded-lg text-xs font-semibold transition-colors disabled:opacity-50"
                                            >
                                                <CheckCircle className="w-3.5 h-3.5" /> Setuju
                                            </button>
                                            <button
                                                onClick={() => handleReject(loan.id)}
                                                disabled={isPending}
                                                className="flex-1 flex justify-center items-center gap-1 text-red-700 bg-red-50 hover:bg-red-100 py-2 rounded-lg text-xs font-semibold transition-colors disabled:opacity-50"
                                            >
                                                <XCircle className="w-3.5 h-3.5" /> Tolak
                                            </button>
                                        </>
                                    )}
                                    {loan.status === 'Disetujui' && (
                                        <button
                                            onClick={() => handleReturn(loan.id)}
                                            disabled={isPending}
                                            className="flex-2 flex justify-center items-center gap-1 text-white bg-[#0F4C81] hover:bg-[#0F4C81]/90 py-2 px-3 rounded-lg text-xs font-semibold transition-colors disabled:opacity-50"
                                        >
                                            <CheckCircle className="w-3.5 h-3.5" /> Kembalikan
                                        </button>
                                    )}
                                </div>
                            </div>
                        ))}
                        {loans.length === 0 && (
                            <div className="col-span-full py-12 text-center text-gray-500 border rounded-xl border-dashed">
                                Belum ada permintaan peminjaman.
                            </div>
                        )}
                </div>
            </div>

            {/* Modal Detail Peminjaman */}
            {selectedLoan && (
                <div className="fixed inset-0 bg-black/50 flex flex-col items-center justify-center z-50 p-4">
                    <div className="bg-white rounded-xl shadow-xl max-w-2xl w-full max-h-[90vh] overflow-y-auto">
                        <div className="p-6 border-b border-gray-100 flex items-center justify-between sticky top-0 bg-white z-10">
                            <h3 className="text-lg font-semibold text-gray-900 flex items-center gap-2">
                                <Box className="w-5 h-5 text-[#0F4C81]" />
                                Detail Peminjaman
                            </h3>
                            <button
                                onClick={() => setSelectedLoan(null)}
                                className="text-gray-400 hover:text-gray-600"
                            >
                                <X className="w-5 h-5" />
                            </button>
                        </div>
                        <div className="p-6 space-y-6">
                            {/* Data Pemohon */}
                            <div>
                                <h4 className="font-medium text-gray-900 border-b pb-2 mb-3">Data Pemohon</h4>
                                <div className="grid grid-cols-2 gap-4 text-sm">
                                    <div>
                                        <p className="text-gray-500">Nama Lengkap</p>
                                        <p className="font-medium text-gray-900">{selectedLoan.student.fullName}</p>
                                    </div>
                                    <div>
                                        <p className="text-gray-500">NIM / Identifier</p>
                                        <p className="font-medium text-gray-900">{selectedLoan.student.identifier}</p>
                                    </div>
                                    <div>
                                        <p className="text-gray-500">Nomor HP</p>
                                        <p className="font-medium text-gray-900">{selectedLoan.student.phoneNumber || '-'}</p>
                                    </div>
                                    <div>
                                        <p className="text-gray-500">Dosen Pembimbing</p>
                                        <p className="font-medium text-gray-900">{selectedLoan.dosenPembimbing || '-'}</p>
                                    </div>
                                </div>
                            </div>

                            {/* Detail Peminjaman */}
                            <div>
                                <h4 className="font-medium text-gray-900 border-b pb-2 mb-3">Data Alat & Waktu</h4>
                                <div className="grid grid-cols-2 gap-4 text-sm">
                                    <div>
                                        <p className="text-gray-500">Alat (Kategori)</p>
                                        <p className="font-medium text-gray-900">{selectedLoan.item.name} ({selectedLoan.item.category.name})</p>
                                    </div>
                                    <div>
                                        <p className="text-gray-500">Organisasi / Unit</p>
                                        <p className="font-medium text-gray-900">{selectedLoan.organisasi || '-'}</p>
                                    </div>
                                    <div>
                                        <p className="text-gray-500">Rentang Peminjaman</p>
                                        <p className="font-medium text-gray-900">
                                            {selectedLoan.startTime ? new Date(selectedLoan.startTime).toLocaleDateString('id-ID') : new Date(selectedLoan.requestDate!).toLocaleDateString('id-ID')}
                                            {' - '}
                                            {new Date(selectedLoan.returnPlanDate).toLocaleDateString('id-ID')}
                                        </p>
                                    </div>
                                    <div>
                                        <p className="text-gray-500">Jam Peminjaman</p>
                                        <p className="font-medium text-gray-900">
                                            {selectedLoan.startTime ? new Date(selectedLoan.startTime).toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' }) : '-'}
                                            {' s.d '}
                                            {selectedLoan.endTime ? new Date(selectedLoan.endTime).toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' }) : '-'}
                                        </p>
                                    </div>
                                    <div className="col-span-2">
                                        <p className="text-gray-500">Keperluan</p>
                                        <p className="font-medium text-gray-900 bg-gray-50 p-3 rounded-lg mt-1 border border-gray-100">{selectedLoan.purpose || '-'}</p>
                                    </div>
                                    {selectedLoan.software && (
                                        <div className="col-span-2">
                                            <p className="text-gray-500">Software yang dipesan</p>
                                            <div className="flex flex-wrap gap-1 mt-1">
                                                {(() => {
                                                    try {
                                                        const sw = JSON.parse(selectedLoan.software);
                                                        return Array.isArray(sw) ? sw.map((s, idx) => (
                                                            <span key={idx} className="inline-flex px-2 py-0.5 rounded text-xs font-medium bg-blue-50 text-blue-700 border border-blue-100">{s}</span>
                                                        )) : <span className="text-gray-900">{selectedLoan.software}</span>;
                                                    } catch {
                                                        return <span className="text-gray-900">{selectedLoan.software}</span>;
                                                    }
                                                })()}
                                            </div>
                                        </div>
                                    )}
                                </div>
                            </div>

                            {/* Dokumen */}
                            {selectedLoan.suratIzin && (
                                <div>
                                    <h4 className="font-medium text-gray-900 border-b pb-2 mb-3">Dokumen Tambahan</h4>
                                    <div className="text-sm border border-gray-100 p-4 rounded-xl bg-gray-50 flex items-center justify-between">
                                        <div className="flex items-center gap-2">
                                            <ExternalLink className="w-5 h-5 text-gray-400" />
                                            <span className="font-medium text-gray-900">Surat Izin / Permohonan</span>
                                        </div>
                                        <a href={selectedLoan.suratIzin} target="_blank" rel="noopener noreferrer" className="text-[#0F4C81] hover:underline font-medium">Buka File</a>
                                    </div>
                                </div>
                            )}

                        </div>
                        <div className="p-6 border-t border-gray-100 flex justify-end">
                            <button
                                onClick={() => setSelectedLoan(null)}
                                className="bg-gray-100 text-gray-700 px-6 py-2 rounded-lg text-sm font-medium hover:bg-gray-200 transition-colors"
                            >
                                Tutup
                            </button>
                        </div>
                    </div>
                </div>
            )}
            <RejectReasonModal
                isOpen={rejectModalOpen}
                onClose={() => { setRejectModalOpen(false); setRejectingLoanId(null); }}
                onConfirm={handleRejectConfirm}
                title="Tolak Peminjaman"
                isPending={isPending}
            />
        </>
    );
}

'use client';

import { useRouter, useSearchParams } from 'next/navigation';
import { useState, useEffect } from 'react';
import { Filter, X } from 'lucide-react';

export default function LoanHistoryFilter() {
    const router = useRouter();
    const searchParams = useSearchParams();

    const [startDate, setStartDate] = useState(searchParams.get('startDate') || '');
    const [endDate, setEndDate] = useState(searchParams.get('endDate') || '');

    const handleFilter = () => {
        const params = new URLSearchParams(searchParams.toString());
        if (startDate) params.set('startDate', startDate);
        else params.delete('startDate');

        if (endDate) params.set('endDate', endDate);
        else params.delete('endDate');

        router.push(`?${params.toString()}`);
    };

    const clearFilter = () => {
        setStartDate('');
        setEndDate('');
        const params = new URLSearchParams(searchParams.toString());
        params.delete('startDate');
        params.delete('endDate');
        router.push(`?${params.toString()}`);
    };

    return (
        <div className="bg-white p-4 rounded-xl shadow-sm border border-gray-100 mb-6 flex flex-wrap items-end gap-4">
            <div>
                <label className="block text-xs font-medium text-gray-700 mb-1">Dari Tanggal</label>
                <input
                    type="date"
                    value={startDate}
                    onChange={(e) => setStartDate(e.target.value)}
                    className="px-3 py-2 border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-[#0F4C81]/20 focus:border-[#0F4C81]"
                />
            </div>
            <div>
                <label className="block text-xs font-medium text-gray-700 mb-1">Sampai Tanggal</label>
                <input
                    type="date"
                    value={endDate}
                    onChange={(e) => setEndDate(e.target.value)}
                    className="px-3 py-2 border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-[#0F4C81]/20 focus:border-[#0F4C81]"
                />
            </div>
            <div className="flex gap-2">
                <button
                    onClick={handleFilter}
                    className="flex items-center gap-2 px-4 py-2 bg-[#0F4C81] text-white rounded-lg text-sm font-medium hover:bg-[#0F4C81]/90 transition-colors"
                >
                    <Filter className="w-4 h-4" />
                    Filter
                </button>
                {(startDate || endDate) && (
                    <button
                        onClick={clearFilter}
                        className="flex items-center gap-2 px-4 py-2 bg-gray-100 text-gray-600 rounded-lg text-sm font-medium hover:bg-gray-200 transition-colors"
                    >
                        <X className="w-4 h-4" />
                        Reset
                    </button>
                )}
            </div>
        </div>
    );
}

'use client';

import { useState, useMemo, useCallback } from 'react';
import SearchFilter from '@/components/shared/SearchFilter';
import { Box, User, CheckCircle, XCircle } from 'lucide-react';

interface Loan {
    id: number;
    status: string;
    requestDate: Date | null;
    returnPlanDate: Date;
    student: {
        fullName: string;
        identifier: string;
    };
    item: {
        name: string;
        category: {
            name: string;
        };
    };
}

interface LoansTableWithSearchProps {
    loans: Loan[];
    onApprove: (id: number) => void;
    onReject: (id: number) => void;
    onReturn: (id: number) => void;
}

export default function LoansTableWithSearch({
    loans,
    onApprove,
    onReject,
    onReturn
}: LoansTableWithSearchProps) {
    const [searchQuery, setSearchQuery] = useState('');

    const filteredLoans = useMemo(() => {
        if (!searchQuery) return loans;
        const query = searchQuery.toLowerCase();
        return loans.filter(loan =>
            loan.student.fullName.toLowerCase().includes(query) ||
            loan.student.identifier.toLowerCase().includes(query) ||
            loan.item.name.toLowerCase().includes(query)
        );
    }, [loans, searchQuery]);

    const handleSearch = useCallback((query: string) => {
        setSearchQuery(query);
    }, []);

    return (
        <div>
            <div className="mb-4">
                <SearchFilter
                    placeholder="Cari nama mahasiswa atau alat..."
                    onSearch={handleSearch}
                    className="max-w-md"
                />
            </div>

            <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
                <table className="w-full text-left">
                    <thead className="bg-gray-50 border-b border-gray-100">
                        <tr>
                            <th className="px-6 py-4 font-semibold text-gray-700">Mahasiswa</th>
                            <th className="px-6 py-4 font-semibold text-gray-700">Alat</th>
                            <th className="px-6 py-4 font-semibold text-gray-700">Tanggal Pinjam</th>
                            <th className="px-6 py-4 font-semibold text-gray-700">Rencana Kembali</th>
                            <th className="px-6 py-4 font-semibold text-gray-700">Status</th>
                            <th className="px-6 py-4 font-semibold text-gray-700 text-center">Aksi</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-100">
                        {filteredLoans.map((loan) => (
                            <tr key={loan.id} className="hover:bg-gray-50 transition-colors">
                                <td className="px-6 py-4">
                                    <div className="flex items-center gap-2">
                                        <User className="w-4 h-4 text-gray-400" />
                                        <div>
                                            <p className="font-medium text-gray-900">{loan.student.fullName}</p>
                                            <p className="text-xs text-gray-500">{loan.student.identifier}</p>
                                        </div>
                                    </div>
                                </td>
                                <td className="px-6 py-4">
                                    <div className="flex items-center gap-2">
                                        <Box className="w-4 h-4 text-primary" />
                                        <div>
                                            <p className="font-medium text-gray-900">{loan.item.name}</p>
                                            <p className="text-xs text-gray-500">{loan.item.category.name}</p>
                                        </div>
                                    </div>
                                </td>
                                <td className="px-6 py-4 text-gray-600 text-sm">
                                    {loan.requestDate ? new Date(loan.requestDate).toLocaleDateString('id-ID') : '-'}
                                </td>
                                <td className="px-6 py-4 text-gray-600 text-sm">
                                    {new Date(loan.returnPlanDate).toLocaleDateString('id-ID')}
                                </td>
                                <td className="px-6 py-4">
                                    <span className={`inline-flex px-2 py-1 rounded text-xs font-medium ${loan.status === 'Pending' ? 'bg-yellow-50 text-yellow-700' :
                                        loan.status === 'Disetujui' ? 'bg-green-50 text-green-700' :
                                            'bg-red-50 text-red-700'
                                        }`}>
                                        {loan.status}
                                    </span>
                                </td>
                                <td className="px-6 py-4">
                                    {loan.status === 'Pending' && (
                                        <div className="flex gap-2 justify-center">
                                            <button
                                                onClick={() => onApprove(loan.id)}
                                                className="text-green-600 hover:text-green-700 p-2 hover:bg-green-50 rounded-lg transition-colors"
                                            >
                                                <CheckCircle className="w-5 h-5" />
                                            </button>
                                            <button
                                                onClick={() => onReject(loan.id)}
                                                className="text-red-600 hover:text-red-700 p-2 hover:bg-red-50 rounded-lg transition-colors"
                                            >
                                                <XCircle className="w-5 h-5" />
                                            </button>
                                        </div>
                                    )}
                                    {loan.status === 'Disetujui' && (
                                        <button
                                            onClick={() => onReturn(loan.id)}
                                            className="mx-auto flex items-center justify-center gap-1 px-3 py-1.5 bg-[#0F4C81] text-white rounded-lg text-sm hover:bg-[#0F4C81]/90 transition-colors"
                                        >
                                            <CheckCircle className="w-4 h-4" />
                                            Kembalikan
                                        </button>
                                    )}
                                </td>
                            </tr>
                        ))}
                        {filteredLoans.length === 0 && (
                            <tr>
                                <td colSpan={6} className="px-6 py-12 text-center text-gray-500">
                                    {searchQuery ? 'Tidak ada hasil pencarian' : 'Belum ada data'}
                                </td>
                            </tr>
                        )}
                    </tbody>
                </table>
            </div>

            {searchQuery && (
                <p className="text-sm text-gray-500 mt-2">
                    Menampilkan {filteredLoans.length} dari {loans.length} data
                </p>
            )}
        </div>
    );
}

'use client';

import { useState } from 'react';
import { Plus, X, Loader2, Upload } from 'lucide-react';
import { adminManualBooking } from '@/features/bookings/actions';
import { useAlert } from '@/components/providers/AlertProvider';
import { translateError } from '@/lib/error';

const PURPOSE_TEMPLATES = [
    'Penelitian/Riset',
    'Kegiatan belajar mandiri / kelompok',
    'Rapat HIMA / organisasi',
    'Praktikum atau persiapan tugas',
    'Kehadiran di area laboratorium',
    'Lainnya',
];

const ORGANISASI_OPTIONS = [
    'Pribadi',
    'HMIF',
    'Panitia Fortex',
    'Ketua Kelompok MK',
    'Lainnya',
];

interface ManualBookingButtonProps {
    rooms: { id: number; name: string; capacity: number }[];
    lecturers: { identifier: string; fullName: string; }[];
    adminId: string;
}

export default function ManualBookingButton({ rooms, lecturers, adminId }: ManualBookingButtonProps) {
    const { showAlert } = useAlert();
    const [isOpen, setIsOpen] = useState(false);
    const [isSubmitting, setIsSubmitting] = useState(false);

    // New States
    const [selectedPurpose, setSelectedPurpose] = useState('');
    const [customPurpose, setCustomPurpose] = useState('');
    const [dosenPembimbing, setDosenPembimbing] = useState('');
    const [customDosen, setCustomDosen] = useState('');
    const [organisasi, setOrganisasi] = useState('Pribadi');
    const [customOrganisasi, setCustomOrganisasi] = useState('');
    const [jumlahPeserta, setJumlahPeserta] = useState<number>(1);
    const [suratFile, setSuratFile] = useState<File | null>(null);

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            const file = e.target.files[0];
            if (file.type !== 'application/pdf') {
                showAlert({ title: 'Format Tidak Valid', message: 'Surat permohonan harus dalam format PDF.', type: 'error' });
                e.target.value = '';
                return;
            }
            if (file.size > 2 * 1024 * 1024) {
                showAlert({ title: 'Ukuran Terlalu Besar', message: 'Ukuran file maksimal 2MB', type: 'error' });
                e.target.value = '';
                return;
            }
            setSuratFile(file);
        }
    };

    async function handleSubmit(e: React.FormEvent<HTMLFormElement>) {
        e.preventDefault();
        setIsSubmitting(true);
        const formData = new FormData(e.currentTarget);

        try {
            // Upload surat permohonan if exists
            let suratPath: string | undefined;
            if (suratFile) {
                const uploadFormData = new FormData();
                uploadFormData.append('file', suratFile);
                uploadFormData.append('folder', 'surat-permohonan');

                const uploadRes = await fetch('/api/upload?type=suratPermohonan', {
                    method: 'POST',
                    body: uploadFormData,
                });

                if (uploadRes.ok) {
                    const uploadData = await uploadRes.json();
                    suratPath = uploadData.path;
                }
            }

            const finalDosen = dosenPembimbing === 'Lainnya' ? customDosen : dosenPembimbing;
            const finalPurpose = selectedPurpose === 'Lainnya' ? customPurpose : selectedPurpose;
            const finalOrganisasi = organisasi === 'Lainnya' ? customOrganisasi : organisasi;

            await adminManualBooking({
                identifier: formData.get('identifier') as string,
                fullName: formData.get('fullName') as string,
                phoneNumber: formData.get('phoneNumber') as string || undefined,
                dosenPembimbing: finalDosen || undefined,
                roomId: parseInt(formData.get('roomId') as string),
                startTime: new Date(`${formData.get('startDate')}T${formData.get('startTime')}`),
                endTime: new Date(`${formData.get('endDate')}T${formData.get('endTime')}`),
                purpose: finalPurpose,
                jumlahPeserta: jumlahPeserta,
                organisasi: finalOrganisasi,
                suratPermohonan: suratPath,
                validatorId: adminId
            });
            setIsOpen(false);

            // Reset state
            setSelectedPurpose('');
            setCustomPurpose('');
            setDosenPembimbing('');
            setCustomDosen('');
            setOrganisasi('Pribadi');
            setCustomOrganisasi('');
            setJumlahPeserta(1);
            setSuratFile(null);
            showAlert({ title: 'Berhasil', message: 'Booking manual berhasil diproses', type: 'success' });
        } catch (error: any) {
            const { title, message } = translateError(error, 'Gagal memproses booking');
            showAlert({ title, message, type: 'error' });
        } finally {
            setIsSubmitting(false);
        }
    }

    return (
        <>
            <button
                onClick={() => setIsOpen(true)}
                className="bg-[#0F4C81] text-white px-4 py-2 rounded-lg text-sm font-medium hover:bg-[#0F4C81]/90 transition-colors flex items-center gap-2"
            >
                <Plus className="w-4 h-4" />
                Booking Manual
            </button>

            {isOpen && (
                <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
                    <div className="bg-white rounded-xl shadow-xl max-w-4xl w-full max-h-[90vh] flex flex-col">
                        <div className="p-6 border-b border-gray-100 flex items-center justify-between shrink-0">
                            <h3 className="text-lg font-semibold text-gray-900">Form Booking Manual</h3>
                            <button onClick={() => setIsOpen(false)} className="text-gray-400 hover:text-gray-600">
                                <X className="w-5 h-5" />
                            </button>
                        </div>

                        <div className="flex-1 overflow-y-auto p-6">
                            <form onSubmit={handleSubmit} className="space-y-6">
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                                    {/* Kolom Kiri: Data Pemesan */}
                                    <div className="space-y-6">
                                        <div className="space-y-4">
                                            <h4 className="font-medium text-gray-900 pb-2 border-b">Data Pemesan</h4>
                                            <div className="grid grid-cols-2 gap-4">
                                                <div>
                                                    <label className="block text-sm font-medium text-gray-700 mb-1">NIM / Identifier *</label>
                                                    <input required name="identifier" className="w-full px-4 py-2 rounded-lg border border-gray-200" placeholder="010252..." />
                                                </div>
                                                <div>
                                                    <label className="block text-sm font-medium text-gray-700 mb-1">Nama Lengkap *</label>
                                                    <input required name="fullName" className="w-full px-4 py-2 rounded-lg border border-gray-200" placeholder="Budi Santoso" />
                                                </div>
                                                <div>
                                                    <label className="block text-sm font-medium text-gray-700 mb-1">Nomor HP</label>
                                                    <input name="phoneNumber" className="w-full px-4 py-2 rounded-lg border border-gray-200" placeholder="0812..." />
                                                </div>
                                                <div>
                                                    <label className="block text-sm font-medium text-gray-700 mb-1">Dosen Pembimbing</label>
                                                    <select
                                                        value={dosenPembimbing}
                                                        onChange={(e) => setDosenPembimbing(e.target.value)}
                                                        className="w-full px-4 py-2 rounded-lg border border-gray-200 bg-white"
                                                    >
                                                        <option value="">Pilih Dosen</option>
                                                        <option value="Lainnya">Lainnya (Ketik Manual)</option>
                                                        {lecturers.map(l => (
                                                            <option key={l.identifier} value={l.fullName}>{l.fullName}</option>
                                                        ))}
                                                    </select>
                                                    {dosenPembimbing === 'Lainnya' && (
                                                        <input
                                                            type="text"
                                                            value={customDosen}
                                                            onChange={(e) => setCustomDosen(e.target.value)}
                                                            placeholder="Ketik nama dosen / PIC..."
                                                            className="w-full mt-2 px-4 py-2 rounded-lg border border-gray-200"
                                                            required
                                                        />
                                                    )}
                                                </div>
                                            </div>

                                            <div>
                                                <label className="block text-sm font-medium text-gray-700 mb-1">Keperluan *</label>
                                                <select
                                                    value={selectedPurpose}
                                                    onChange={(e) => setSelectedPurpose(e.target.value)}
                                                    className="w-full px-4 py-2 rounded-lg border border-gray-200 bg-white"
                                                    required
                                                >
                                                    <option value="" disabled>-- Pilih Keperluan --</option>
                                                    {PURPOSE_TEMPLATES.map((purpose) => (
                                                        <option key={purpose} value={purpose}>{purpose}</option>
                                                    ))}
                                                </select>
                                                {selectedPurpose === 'Lainnya' && (
                                                    <textarea
                                                        value={customPurpose}
                                                        onChange={(e) => setCustomPurpose(e.target.value)}
                                                        rows={2}
                                                        placeholder="Jelaskan detail keperluan..."
                                                        className="w-full mt-2 px-4 py-2 rounded-lg border border-gray-200"
                                                        required
                                                    />
                                                )}
                                            </div>

                                            <div className="grid grid-cols-2 gap-4">
                                                <div>
                                                    <label className="block text-sm font-medium text-gray-700 mb-1">Jumlah Peserta *</label>
                                                    <input
                                                        type="number"
                                                        min={1}
                                                        value={jumlahPeserta}
                                                        onChange={(e) => setJumlahPeserta(parseInt(e.target.value))}
                                                        className="w-full px-4 py-2 rounded-lg border border-gray-200"
                                                        required
                                                    />
                                                </div>
                                                <div>
                                                    <label className="block text-sm font-medium text-gray-700 mb-1">Organisasi / Unit *</label>
                                                    <select
                                                        value={organisasi}
                                                        onChange={(e) => setOrganisasi(e.target.value)}
                                                        className="w-full px-4 py-2 rounded-lg border border-gray-200 bg-white"
                                                    >
                                                        {ORGANISASI_OPTIONS.map(org => (
                                                            <option key={org} value={org}>{org}</option>
                                                        ))}
                                                    </select>
                                                    {organisasi === 'Lainnya' && (
                                                        <input
                                                            type="text"
                                                            value={customOrganisasi}
                                                            onChange={(e) => setCustomOrganisasi(e.target.value)}
                                                            placeholder="Ketik organisasi..."
                                                            className="w-full mt-2 px-4 py-2 rounded-lg border border-gray-200"
                                                            required
                                                        />
                                                    )}
                                                </div>
                                            </div>
                                        </div>
                                    </div>

                                    {/* Kolom Kanan: Detail Booking */}
                                    <div className="space-y-6">
                                        <div className="space-y-4">
                                            <h4 className="font-medium text-gray-900 pb-2 border-b">Detail Booking</h4>

                                            <div>
                                                <label className="block text-sm font-medium text-gray-700 mb-1">Pilih Ruangan *</label>
                                                <select required name="roomId" className="w-full px-4 py-2 rounded-lg border border-gray-200 bg-white">
                                                    <option value="">Pilih Ruangan</option>
