                                <div className="flex justify-end gap-3 pt-6 border-t mt-4 sticky bottom-0 bg-white">
                                    <button type="button" onClick={() => setIsOpen(false)} className="px-5 py-2 hover:bg-gray-100 rounded-lg text-sm font-medium">Batal</button>
                                    <button type="submit" disabled={isSubmitting} className="bg-[#0F4C81] text-white px-5 py-2 rounded-lg text-sm font-medium hover:bg-[#0F4C81]/90 flex items-center shadow-lg shadow-[#0F4C81]/20">
                                        {isSubmitting ? <Loader2 className="w-4 h-4 mr-2 animate-spin" /> : 'Proses Booking'}
                                    </button>
                                </div>
                            </form>
                        </div>
                    </div>
                </div>
            )}
        </>
    );
}

'use client';

import { useState } from 'react';
import { Plus, X, Loader2, Search, Upload } from 'lucide-react';
import { adminManualLoan } from '@/features/loans/actions';
import { useAlert } from '@/components/providers/AlertProvider';
import { translateError } from '@/lib/error';

const PURPOSE_TEMPLATES = [
    'Praktikum dan Tugas Akhir',
    'Penelitian/Riset',
    'Kegiatan kemahasiswaan (HIMA/BEM/dll)',
    'Keperluan pribadi / project luar',
    'Lainnya',
];

const ORGANISASI_OPTIONS = [
    'Pribadi',
    'HMIF',
    'Panitia Fortex',
    'Ketua Kelompok MK',
    'Lainnya',
];

interface ManualLoanButtonProps {
    items: { id: number; name: string; qrCode: string; category: { name: string | null } | null }[];
    lecturers: { identifier: string; fullName: string; }[];
    adminId: string;
}

export default function ManualLoanButton({ items, lecturers, adminId }: ManualLoanButtonProps) {
    const { showAlert } = useAlert();
    const [isOpen, setIsOpen] = useState(false);
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [selectedItemIds, setSelectedItemIds] = useState<number[]>([]);
    const [itemSearch, setItemSearch] = useState('');

    // New States
    const [selectedPurpose, setSelectedPurpose] = useState('');
    const [customPurpose, setCustomPurpose] = useState('');
    const [dosenPembimbing, setDosenPembimbing] = useState('');
    const [customDosen, setCustomDosen] = useState('');
    const [organisasi, setOrganisasi] = useState('Pribadi');
    const [customOrganisasi, setCustomOrganisasi] = useState('');
    const [suratFile, setSuratFile] = useState<File | null>(null);

    const filteredItems = items.filter(i =>
        i.name.toLowerCase().includes(itemSearch.toLowerCase()) ||
        i.qrCode.toLowerCase().includes(itemSearch.toLowerCase())
    ).slice(0, 10);

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            const file = e.target.files[0];
            if (file.type !== 'application/pdf') {
                showAlert({ title: 'Format Tidak Valid', message: 'Surat izin harus dalam format PDF.', type: 'error' });
                e.target.value = '';
                return;
            }
            if (file.size > 2 * 1024 * 1024) {
                showAlert({ title: 'Ukuran Terlalu Besar', message: 'Ukuran file maksimal 2MB', type: 'error' });
                e.target.value = '';
                return;
            }
            setSuratFile(file);
        }
    };

    async function handleSubmit(e: React.FormEvent<HTMLFormElement>) {
        e.preventDefault();
        if (selectedItemIds.length === 0) {
            showAlert({ title: 'Peringatan', message: 'Pilih minimal 1 alat', type: 'warning' });
            return;
        }

        setIsSubmitting(true);
        const formData = new FormData(e.currentTarget);

        try {
            // Upload surat izin if exists
            let suratPath: string | undefined;
            if (suratFile) {
                const uploadFormData = new FormData();
                uploadFormData.append('file', suratFile);
                uploadFormData.append('folder', 'surat-izin');

                const uploadRes = await fetch('/api/upload?type=suratIzin', {
                    method: 'POST',
                    body: uploadFormData,
                });

                if (uploadRes.ok) {
                    const uploadData = await uploadRes.json();
                    suratPath = uploadData.path;
                }
            }

            const finalDosen = dosenPembimbing === 'Lainnya' ? customDosen : dosenPembimbing;
            const finalPurpose = selectedPurpose === 'Lainnya' ? customPurpose : selectedPurpose;
            const finalOrganisasi = organisasi === 'Lainnya' ? customOrganisasi : organisasi;

            const startDateTime = new Date(`${formData.get('startDate')}T${formData.get('startTime')}`);
            const endDateTime = new Date(`${formData.get('endDate')}T${formData.get('endTime')}`);

            await adminManualLoan({
                identifier: formData.get('identifier') as string,
                fullName: formData.get('fullName') as string,
                phoneNumber: formData.get('phoneNumber') as string || undefined,
                dosenPembimbing: finalDosen || undefined,
                itemIds: selectedItemIds,
                returnPlanDate: new Date(formData.get('endDate') as string), // Use endDate as returnPlanDate
                startTime: startDateTime,
                endTime: endDateTime,
                purpose: finalPurpose,
                organisasi: finalOrganisasi,
                suratIzin: suratPath,
                validatorId: adminId
            });
            setIsOpen(false);

            // Reset state
            setSelectedPurpose('');
            setCustomPurpose('');
            setDosenPembimbing('');
            setCustomDosen('');
            setOrganisasi('Pribadi');
            setCustomOrganisasi('');
            setSuratFile(null);
            setSelectedItemIds([]);
            showAlert({ title: 'Berhasil', message: 'Peminjaman manual berhasil diproses', type: 'success' });
        } catch (error: any) {
            const { title, message } = translateError(error, 'Gagal memproses peminjaman');
            showAlert({ title, message, type: 'error' });
        } finally {
            setIsSubmitting(false);
        }
    }

    return (
        <>
            <button
                onClick={() => setIsOpen(true)}
                className="bg-[#0F4C81] text-white px-4 py-2 rounded-lg text-sm font-medium hover:bg-[#0F4C81]/90 transition-colors flex items-center gap-2"
            >
                <Plus className="w-4 h-4" />
                Peminjaman Manual
            </button>

            {isOpen && (
                <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
                    <div className="bg-white rounded-xl shadow-xl max-w-4xl w-full max-h-[90vh] flex flex-col">
                        <div className="p-6 border-b border-gray-100 flex items-center justify-between shrink-0">
                            <h3 className="text-lg font-semibold text-gray-900">Form Peminjaman Manual</h3>
                            <button onClick={() => setIsOpen(false)} className="text-gray-400 hover:text-gray-600">
                                <X className="w-5 h-5" />
                            </button>
                        </div>

                        <div className="flex-1 overflow-y-auto p-6">
                            <form onSubmit={handleSubmit} className="space-y-6">
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                                    {/* Kolom Kiri: Data Peminjam & Detail */}
                                    <div className="space-y-6">
                                        <div className="space-y-4">
                                            <h4 className="font-medium text-gray-900 pb-2 border-b">Data Peminjam</h4>
                                            <div className="grid grid-cols-2 gap-4">
                                                <div>
                                                    <label className="block text-sm font-medium text-gray-700 mb-1">NIM / Identifier *</label>
                                                    <input required name="identifier" className="w-full px-4 py-2 rounded-lg border border-gray-200" placeholder="010252..." />
                                                </div>
                                                <div>
                                                    <label className="block text-sm font-medium text-gray-700 mb-1">Nama Lengkap *</label>
                                                    <input required name="fullName" className="w-full px-4 py-2 rounded-lg border border-gray-200" placeholder="Budi Santoso" />
                                                </div>
                                                <div>
                                                    <label className="block text-sm font-medium text-gray-700 mb-1">Nomor HP</label>
                                                    <input name="phoneNumber" className="w-full px-4 py-2 rounded-lg border border-gray-200" placeholder="0812..." />
                                                </div>
                                                <div>
                                                    <label className="block text-sm font-medium text-gray-700 mb-1">Dosen Pembimbing</label>
                                                    <select
                                                        value={dosenPembimbing}
                                                        onChange={(e) => setDosenPembimbing(e.target.value)}
                                                        className="w-full px-4 py-2 rounded-lg border border-gray-200 bg-white"
                                                    >
                                                        <option value="">Pilih Dosen</option>
                                                        <option value="Lainnya">Lainnya (Ketik Manual)</option>
                                                        {lecturers.map(l => (
                                                            <option key={l.identifier} value={l.fullName}>{l.fullName}</option>
                                                        ))}
                                                    </select>
                                                    {dosenPembimbing === 'Lainnya' && (
                                                        <input
                                                            type="text"
                                                            value={customDosen}
                                                            onChange={(e) => setCustomDosen(e.target.value)}
                                                            placeholder="Ketik nama dosen / PIC..."
                                                            className="w-full mt-2 px-4 py-2 rounded-lg border border-gray-200"
                                                            required
                                                        />
                                                    )}
                                                </div>
                                            </div>
                                        </div>

                                        <div className="space-y-4">
                                            <h4 className="font-medium text-gray-900 pb-2 border-b">Rencana & Keperluan</h4>
                                            <div className="grid grid-cols-2 gap-4 border p-3 rounded-lg bg-gray-50">
                                                <div>
                                                    <label className="block text-xs font-medium text-gray-500 mb-1">Tanggal Mulai *</label>
                                                    <input type="date" required name="startDate" className="w-full px-3 py-1.5 rounded-md border text-sm bg-white" />
                                                </div>
                                                <div>
                                                    <label className="block text-xs font-medium text-gray-500 mb-1">Jam Mulai *</label>
                                                    <input type="time" required name="startTime" className="w-full px-3 py-1.5 rounded-md border text-sm bg-white" />
                                                </div>
                                                <div>
                                                    <label className="block text-xs font-medium text-gray-500 mb-1">Rencana Kembali *</label>
                                                    <input type="date" required name="endDate" className="w-full px-3 py-1.5 rounded-md border text-sm bg-white" />
                                                </div>
                                                <div>
                                                    <label className="block text-xs font-medium text-gray-500 mb-1">Jam Selesai *</label>
                                                    <input type="time" required name="endTime" className="w-full px-3 py-1.5 rounded-md border text-sm bg-white" />
                                                </div>
                                            </div>

                                            <div>
                                                <label className="block text-sm font-medium text-gray-700 mb-1">Keperluan *</label>
                                                <select
                                                    value={selectedPurpose}
                                                    onChange={(e) => setSelectedPurpose(e.target.value)}
                                                    className="w-full px-4 py-2 rounded-lg border border-gray-200 bg-white"
                                                    required
                                                >
                                                    <option value="" disabled>-- Pilih Keperluan --</option>
                                                    {PURPOSE_TEMPLATES.map((purpose) => (
                                                        <option key={purpose} value={purpose}>{purpose}</option>
                                                    ))}
                                                </select>
                                                {selectedPurpose === 'Lainnya' && (
                                                    <textarea
                                                        value={customPurpose}
                                                        onChange={(e) => setCustomPurpose(e.target.value)}
                                                        rows={2}
                                                        placeholder="Jelaskan detail keperluan..."
                                                        className="w-full mt-2 px-4 py-2 rounded-lg border border-gray-200"
                                                        required
                                                    />
                                                )}
                                            </div>

                                            <div>
                                                <label className="block text-sm font-medium text-gray-700 mb-1">Organisasi / Unit *</label>
                                                <select
                                                    value={organisasi}
                                                    onChange={(e) => setOrganisasi(e.target.value)}
                                                    className="w-full px-4 py-2 rounded-lg border border-gray-200 bg-white"
                                                >
                                                    {ORGANISASI_OPTIONS.map(org => (
                                                        <option key={org} value={org}>{org}</option>
                                                    ))}
                                                </select>
                                                {organisasi === 'Lainnya' && (
                                                    <input
                                                        type="text"
                                                        value={customOrganisasi}
                                                        onChange={(e) => setCustomOrganisasi(e.target.value)}
                                                        placeholder="Ketik organisasi..."
                                                        className="w-full mt-2 px-4 py-2 rounded-lg border border-gray-200"
                                                        required
                                                    />
                                                )}
                                            </div>
                                        </div>
                                    </div>

                                    {/* Kolom Kanan: Pilih Alat & Berkas */}
                                    <div className="space-y-6">
                                        <div className="space-y-4">
                                            <h4 className="font-medium text-gray-900 pb-2 border-b">Detail Alat yang Dipinjam</h4>

                                            <div>
                                                <label className="block text-sm font-medium text-gray-700 mb-1">Pilih Alat (Multiselect) *</label>
                                                <div className="flex gap-2 mb-2">
                                                    <div className="relative flex-1">
                                                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                                                        <input
                                                            type="text"
                                                            value={itemSearch}
                                                            onChange={e => setItemSearch(e.target.value)}
                                                            className="w-full pl-9 pr-4 py-2 border rounded-lg text-sm"
                                                            placeholder="Cari alat berdasarkan nama / kode..."
                                                        />
                                                    </div>
                                                </div>
                                                <div className="border border-gray-200 rounded-lg max-h-64 overflow-y-auto p-2 bg-gray-50/50">
                                                    {filteredItems.map(item => (
                                                        <label key={item.id} className="flex items-center gap-3 p-2 hover:bg-white border border-transparent hover:border-gray-100 hover:shadow-sm rounded cursor-pointer transition-all">
                                                            <input
                                                                type="checkbox"
                                                                checked={selectedItemIds.includes(item.id)}
                                                                onChange={(e) => {
                                                                    if (e.target.checked) setSelectedItemIds(prev => [...prev, item.id]);
                                                                    else setSelectedItemIds(prev => prev.filter(id => id !== item.id));
                                                                }}
                                                                className="w-4 h-4 text-[#0F4C81] rounded focus:ring-[#0F4C81]"
                                                            />
                                                            <div>
                                                                <p className="text-sm font-medium">{item.name}</p>
                                                                <p className="text-xs text-gray-500">{item.qrCode} ({item.category?.name})</p>
                                                            </div>
                                                        </label>
                                                    ))}
                                                    {filteredItems.length === 0 && (
                                                        <div className="text-center p-4 text-gray-500 text-sm">
                                                            Tidak ada alat yang cocok.
                                                        </div>
                                                    )}
                                                </div>
                                                <p className="text-xs text-gray-500 mt-2 font-medium">Terpilih: <span className="text-[#0F4C81]">{selectedItemIds.length}</span> alat</p>
                                            </div>
                                        </div>

                                        <div className="space-y-4">
                                            <h4 className="font-medium text-gray-900 pb-2 border-b">Berkas Tambahan</h4>
                                            <div>
                                                <label className="block text-sm font-medium text-gray-700 mb-1 flex items-center gap-1">
                                                    <Upload className="w-4 h-4" /> Surat Izin Peminjaman (Opsional)
                                                </label>
                                                <div className="flex items-center gap-4 p-4 border border-gray-200 rounded-lg bg-gray-50">
                                                    <input
                                                        type="file"
                                                        accept=".pdf"
                                                        onChange={handleFileChange}
                                                        className="w-full text-sm file:mr-4 file:py-2 file:px-4 file:rounded-lg file:border-0 file:text-sm file:font-medium file:bg-white file:border file:border-gray-200 hover:file:bg-gray-50 cursor-pointer"
                                                    />
                                                </div>
                                                <p className="text-xs text-gray-500 mt-1">Upload surat izin (format .pdf, maks. 2MB)</p>
                                            </div>
                                        </div>
                                    </div>
                                </div>

                                <div className="flex justify-end gap-3 pt-6 border-t mt-4 sticky bottom-0 bg-white">
                                    <button type="button" onClick={() => setIsOpen(false)} className="px-5 py-2 hover:bg-gray-100 rounded-lg text-sm font-medium">Batal</button>
                                    <button type="submit" disabled={isSubmitting} className="bg-[#0F4C81] text-white px-5 py-2 rounded-lg text-sm font-medium hover:bg-[#0F4C81]/90 flex items-center shadow-lg shadow-[#0F4C81]/20">
                                        {isSubmitting ? <Loader2 className="w-4 h-4 mr-2 animate-spin" /> : 'Proses Peminjaman'}
                                    </button>
                                </div>
                            </form>
                        </div>
                    </div>
                </div>
            )}
        </>
    );
}

'use client';

import { useState, useTransition } from 'react';
import { Box, Check, X, Clock, ExternalLink } from 'lucide-react';
import { approveReturn, rejectReturn } from '@/features/loans/actions';

interface PendingReturn {
    id: number;
    requestDate: Date | null;
    returnPlanDate: Date;
    purpose: string | null;
    student: {
        fullName: string;
        identifier: string;
        [key: string]: unknown; // Allow additional student fields
    };
    item: {
        name: string;
        [key: string]: unknown; // Allow additional item fields
    };
    [key: string]: unknown; // Allow additional loan fields
}

interface PendingReturnsListProps {
    returns: PendingReturn[];
    validatorId: string;
}

export default function PendingReturnsList({ returns, validatorId }: PendingReturnsListProps) {
    const [isPending, startTransition] = useTransition();

    const handleApprove = (loanId: number) => {
        startTransition(async () => {
            await approveReturn(loanId, validatorId);
        });
    };

    const handleReject = (loanId: number) => {
        startTransition(async () => {
            await rejectReturn(loanId);
        });
    };

    if (returns.length === 0) {
        return (
            <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-6 md:p-12 text-center">
                <Clock className="w-12 h-12 text-gray-300 mx-auto mb-4" />
                <p className="text-gray-500">Tidak ada pengembalian yang menunggu persetujuan</p>
            </div>
        );
    }

    return (
        <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
            <div className="p-4 border-b border-gray-100">
                <h3 className="font-semibold text-gray-900">Pengembalian Menunggu Persetujuan</h3>
                <p className="text-sm text-gray-500">Pengembalian tanpa foto bukti perlu disetujui manual</p>
            </div>
            <div className="divide-y divide-gray-100">
                {returns.map((item) => (
                    <div key={item.id} className="p-4 hover:bg-gray-50 transition-colors">
                        <div className="flex items-center justify-between">
                            <div className="flex items-center gap-4">
                                <div className="w-12 h-12 rounded-lg bg-yellow-50 flex items-center justify-center">
                                    <Box className="w-6 h-6 text-yellow-600" />
                                </div>
                                <div>
                                    <p className="font-medium text-gray-900">{item.item.name}</p>
                                    <p className="text-sm text-gray-500">
                                        Dipinjam oleh: <span className="font-medium">{item.student.fullName}</span>
                                        <span className="text-gray-400"> ({item.student.identifier})</span>
                                    </p>
                                    {item.purpose && (
                                        <p className="text-xs text-gray-400 mt-1">Tujuan: {item.purpose}</p>
                                    )}
                                </div>
                            </div>
                            <div className="flex items-center gap-2">
                                <button
                                    onClick={() => handleApprove(item.id)}
                                    disabled={isPending}
                                    title="Setujui Pengembalian"
                                    className="text-green-600 hover:text-green-700 p-2 hover:bg-green-50 rounded-lg transition-colors disabled:opacity-50"
                                >
                                    <Check className="w-5 h-5" />
                                </button>
                                <button
                                    onClick={() => handleReject(item.id)}
                                    disabled={isPending}
                                    title="Tolak Pengembalian"
                                    className="text-red-600 hover:text-red-700 p-2 hover:bg-red-50 rounded-lg transition-colors disabled:opacity-50"
                                >
                                    <X className="w-5 h-5" />
                                </button>
                            </div>
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
}

'use client';

import { useState, useMemo, useTransition } from 'react';
import { User, CheckCircle, XCircle, Search, X, MapPin } from 'lucide-react';
import { updateBookingStatus } from '@/features/bookings/actions';
import RejectReasonModal from '@/components/ui/RejectReasonModal';

interface Booking {
    id: number;
    status: string | null;
    startTime: Date;
    endTime: Date;
    purpose: string | null;
    user: {
        fullName: string;
        identifier: string;
    };
    room: {
        name: string;
    };
}

interface SearchableBookingsProps {
    bookings: Booking[];
    sessionUserId: string;
}

export default function SearchableBookingsSection({ bookings, sessionUserId }: SearchableBookingsProps) {
    const [searchQuery, setSearchQuery] = useState('');
    const [isPending, startTransition] = useTransition();
    const [rejectModalOpen, setRejectModalOpen] = useState(false);
    const [rejectingBookingId, setRejectingBookingId] = useState<number | null>(null);

    // Filter active bookings (Pending + Disetujui)
    const activeBookings = useMemo(() => {
        return bookings.filter(b => b.status === 'Pending' || b.status === 'Disetujui');
    }, [bookings]);

    const filteredBookings = useMemo(() => {
        if (!searchQuery) return activeBookings;
        const query = searchQuery.toLowerCase();
        return activeBookings.filter(booking =>
            booking.user.fullName.toLowerCase().includes(query) ||
            booking.user.identifier.toLowerCase().includes(query) ||
            booking.room.name.toLowerCase().includes(query) ||
            (booking.purpose && booking.purpose.toLowerCase().includes(query))
        );
    }, [activeBookings, searchQuery]);

    const pendingCount = activeBookings.filter(b => b.status === 'Pending').length;
    const approvedCount = activeBookings.filter(b => b.status === 'Disetujui').length;

    const handleApprove = (bookingId: number) => {
        startTransition(async () => {
            await updateBookingStatus(bookingId, 'Disetujui', sessionUserId);
        });
    };

    const handleReject = (bookingId: number) => {
        setRejectingBookingId(bookingId);
        setRejectModalOpen(true);
    };

    const handleRejectConfirm = (reason: string) => {
        if (rejectingBookingId === null) return;
        const bookingId = rejectingBookingId;
        setRejectModalOpen(false);
        setRejectingBookingId(null);
        startTransition(async () => {
            await updateBookingStatus(bookingId, 'Ditolak', sessionUserId, reason || undefined);
        });
    };

    return (
        <div>
            {/* Stats */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-6">
                <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
                    <h3 className="text-gray-500 text-sm font-medium">Pending</h3>
                    <p className="text-3xl font-bold text-orange-500 mt-2">{pendingCount}</p>
                </div>
                <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
                    <h3 className="text-gray-500 text-sm font-medium">Aktif</h3>
                    <p className="text-3xl font-bold text-green-600 mt-2">{approvedCount}</p>
                </div>
            </div>

            {/* Search */}
            <div className="mb-6">
                <div className="relative max-w-md">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                    <input
                        type="text"
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                        placeholder="Cari nama pemohon atau ruangan..."
                        className="w-full pl-10 pr-10 py-2 border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-[#0F4C81]/20 focus:border-[#0F4C81]"
                    />
                    {searchQuery && (
                        <button
                            onClick={() => setSearchQuery('')}
                            className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600"
                        >
                            <X className="w-4 h-4" />
                        </button>
                    )}
                </div>
                {searchQuery && (
                    <p className="text-sm text-gray-500 mt-2">
                        Menampilkan {filteredBookings.length} dari {activeBookings.length} booking
                    </p>
                )}
            </div>

            {/* Bookings Table */}
            <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
                <div className="overflow-x-auto">
                    <table className="w-full text-left">
                        <thead className="bg-gray-50 border-b border-gray-100">
                            <tr>
                                <th className="px-6 py-4 font-semibold text-gray-700">Pemohon</th>
                                <th className="px-6 py-4 font-semibold text-gray-700">Ruangan</th>
                                <th className="px-6 py-4 font-semibold text-gray-700">Tanggal & Waktu</th>
                                <th className="px-6 py-4 font-semibold text-gray-700">Keperluan</th>
                                <th className="px-6 py-4 font-semibold text-gray-700">Status</th>
                                <th className="px-6 py-4 font-semibold text-gray-700 text-center">Aksi</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-100">
                            {filteredBookings.map((booking) => (
                                <tr key={booking.id} className={`hover:bg-gray-50 transition-colors ${isPending ? 'opacity-50' : ''}`}>
                                    <td className="px-6 py-4">
                                        <div className="flex items-center gap-2">
                                            <User className="w-4 h-4 text-gray-400" />
                                            <div>
                                                <p className="font-medium text-gray-900">{booking.user.fullName}</p>
                                                <p className="text-xs text-gray-500">{booking.user.identifier}</p>
                                            </div>
                                        </div>
                                    </td>
                                    <td className="px-6 py-4">
                                        <div className="flex items-center gap-2">
                                            <MapPin className="w-4 h-4 text-[#0F4C81]" />
                                            <p className="font-medium text-gray-900">{booking.room.name}</p>
                                        </div>
                                    </td>
                                    <td className="px-6 py-4 text-gray-600 text-sm">
                                        <div>{new Date(booking.startTime).toLocaleDateString('id-ID')}</div>
                                        <div className="text-xs text-gray-500">
                                            {new Date(booking.startTime).toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' })} -
                                            {new Date(booking.endTime).toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' })}
                                        </div>
                                    </td>
                                    <td className="px-6 py-4 text-gray-600 text-sm max-w-[200px] truncate">
                                        {booking.purpose || '-'}
                                    </td>
                                    <td className="px-6 py-4">
                                        <span className={`inline-flex px-2 py-1 rounded text-xs font-medium ${booking.status === 'Pending' ? 'bg-yellow-50 text-yellow-700' :
                                            booking.status === 'Disetujui' ? 'bg-green-50 text-green-700' :
                                                'bg-red-50 text-red-700'
                                            }`}>
                                            {booking.status}
                                        </span>
                                    </td>
                                    <td className="px-6 py-4">
                                        {booking.status === 'Pending' && (
                                            <div className="flex gap-2 justify-center">
                                                <button
                                                    onClick={() => handleApprove(booking.id)}
                                                    disabled={isPending}
                                                    className="text-green-600 hover:text-green-700 p-2 hover:bg-green-50 rounded-lg transition-colors disabled:opacity-50"
                                                >
                                                    <CheckCircle className="w-5 h-5" />
                                                </button>
                                                <button
                                                    onClick={() => handleReject(booking.id)}
                                                    disabled={isPending}
                                                    className="text-red-600 hover:text-red-700 p-2 hover:bg-red-50 rounded-lg transition-colors disabled:opacity-50"
                                                >
                                                    <XCircle className="w-5 h-5" />
                                                </button>
                                            </div>
                                        )}
                                        {booking.status === 'Disetujui' && (
                                            <span className="text-gray-400 text-sm">Aktif</span>
                                        )}
                                    </td>
                                </tr>
                            ))}
                            {filteredBookings.length === 0 && (
                                <tr>
                                    <td colSpan={6} className="px-6 py-12 text-center text-gray-500">
                                        {searchQuery ? 'Tidak ada hasil pencarian' : 'Belum ada permintaan booking.'}
                                    </td>
                                </tr>
                            )}
                        </tbody>
                    </table>
                </div>
            </div>
            <RejectReasonModal
                isOpen={rejectModalOpen}
                onClose={() => { setRejectModalOpen(false); setRejectingBookingId(null); }}
                onConfirm={handleRejectConfirm}
                title="Tolak Booking Ruangan"
                isPending={isPending}
            />
        </div>
    );
}

'use client';

import { useState, useMemo, useTransition } from 'react';
import { Box, User, CheckCircle, XCircle, Search, X } from 'lucide-react';
import { updateLoanStatus, approveReturn as approveReturnAction, rejectReturn as rejectReturnAction, adminDirectReturn } from '@/features/loans/actions';
import RejectReasonModal from '@/components/ui/RejectReasonModal';

interface Loan {
    id: number;
    status: string | null;
    requestDate: Date | null;
    returnPlanDate: Date;
    returnStatus: string | null;
    student: {
        fullName: string;
        identifier: string;
    };
    item: {
        name: string;
        category: {
            name: string;
        };
    };
}

interface PendingReturn {
    id: number;
    requestDate: Date | null;
    student: {
        fullName: string;
        identifier: string;
    };
    item: {
        name: string;
    };
}

interface SearchableLoansProps {
    loans: Loan[];
    pendingReturns: PendingReturn[];
    sessionUserId: string;
}

export default function SearchableLoansSection({ loans, pendingReturns, sessionUserId }: SearchableLoansProps) {
    const [searchQuery, setSearchQuery] = useState('');
    const [isPending, startTransition] = useTransition();
    const [rejectModalOpen, setRejectModalOpen] = useState(false);
    const [rejectingLoanId, setRejectingLoanId] = useState<number | null>(null);

    // Filter active loans (Pending + Disetujui)
    const activeLoans = useMemo(() => {
        return loans.filter(l => l.status === 'Pending' || l.status === 'Disetujui');
    }, [loans]);

    const filteredLoans = useMemo(() => {
        if (!searchQuery) return activeLoans;
        const query = searchQuery.toLowerCase();
        return activeLoans.filter(loan =>
            loan.student.fullName.toLowerCase().includes(query) ||
            loan.student.identifier.toLowerCase().includes(query) ||
            loan.item.name.toLowerCase().includes(query)
        );
    }, [activeLoans, searchQuery]);

    const filteredReturns = useMemo(() => {
        if (!searchQuery) return pendingReturns;
        const query = searchQuery.toLowerCase();
        return pendingReturns.filter(loan =>
            loan.student.fullName.toLowerCase().includes(query) ||
            loan.student.identifier.toLowerCase().includes(query) ||
            loan.item.name.toLowerCase().includes(query)
        );
    }, [pendingReturns, searchQuery]);

    const pendingLoansCount = activeLoans.filter(l => l.status === 'Pending').length;
    const approvedLoansCount = activeLoans.filter(l => l.status === 'Disetujui').length;

    const handleApprove = (loanId: number) => {
        startTransition(async () => {
            await updateLoanStatus(loanId, 'Disetujui', sessionUserId);
        });
    };

    const handleReject = (loanId: number) => {
        setRejectingLoanId(loanId);
        setRejectModalOpen(true);
    };

    const handleRejectConfirm = (reason: string) => {
        if (rejectingLoanId === null) return;
        const loanId = rejectingLoanId;
        setRejectModalOpen(false);
        setRejectingLoanId(null);
        startTransition(async () => {
            await updateLoanStatus(loanId, 'Ditolak', sessionUserId, reason || undefined);
        });
    };

    // Admin directly returns an active loan (no need for student to submit return first)
    const handleReturn = (loanId: number) => {
        startTransition(async () => {
            await adminDirectReturn(loanId, sessionUserId);
        });
    };

    const handleApproveReturn = (loanId: number) => {
        startTransition(async () => {
            await approveReturnAction(loanId, sessionUserId);
        });
    };

    const handleRejectReturn = (loanId: number) => {
        startTransition(async () => {
            await rejectReturnAction(loanId);
        });
    };

    return (
        <div>
            {/* Stats */}
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 sm:gap-6 mb-6">
                <div className="bg-white p-4 sm:p-6 rounded-xl shadow-sm border border-gray-100">
                    <h3 className="text-gray-500 text-sm font-medium">Pending</h3>
                    <p className="text-2xl sm:text-3xl font-bold text-orange-500 mt-2">{pendingLoansCount}</p>
                </div>
                <div className="bg-white p-4 sm:p-6 rounded-xl shadow-sm border border-gray-100">
                    <h3 className="text-gray-500 text-sm font-medium">Aktif</h3>
                    <p className="text-2xl sm:text-3xl font-bold text-green-600 mt-2">{approvedLoansCount}</p>
                </div>
                <div className="bg-white p-4 sm:p-6 rounded-xl shadow-sm border border-gray-100">
                    <h3 className="text-gray-500 text-sm font-medium">Pending Return</h3>
                    <p className="text-2xl sm:text-3xl font-bold text-blue-600 mt-2">{pendingReturns.length}</p>
                </div>
            </div>

            {/* Search */}
            <div className="mb-6">
                <div className="relative max-w-md">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                    <input
                        type="text"
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                        placeholder="Cari nama mahasiswa atau alat..."
                        className="w-full pl-10 pr-10 py-2 border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-[#0F4C81]/20 focus:border-[#0F4C81]"
                    />
                    {searchQuery && (
                        <button
                            onClick={() => setSearchQuery('')}
                            className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600"
                        >
                            <X className="w-4 h-4" />
                        </button>
                    )}
                </div>
                {searchQuery && (
                    <p className="text-sm text-gray-500 mt-2">
                        Menampilkan {filteredLoans.length} peminjaman, {filteredReturns.length} pengembalian
                    </p>
                )}
            </div>

            {/* Section 1: Peminjaman Table */}
            <h3 className="text-lg font-semibold text-gray-900 mb-4">📋 Peminjaman</h3>
            <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden mb-8">
                <div className="overflow-x-auto">
                    <table className="w-full text-left">
                        <thead className="bg-gray-50 border-b border-gray-100">
                            <tr>
                                <th className="px-6 py-4 font-semibold text-gray-700">Mahasiswa</th>
                                <th className="px-6 py-4 font-semibold text-gray-700">Alat</th>
                                <th className="px-6 py-4 font-semibold text-gray-700">Tanggal Pinjam</th>
                                <th className="px-6 py-4 font-semibold text-gray-700">Rencana Kembali</th>
                                <th className="px-6 py-4 font-semibold text-gray-700">Status</th>
                                <th className="px-6 py-4 font-semibold text-gray-700 text-center">Aksi</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-100">
                            {filteredLoans.map((loan) => (
                                <tr key={loan.id} className={`hover:bg-gray-50 transition-colors ${isPending ? 'opacity-50' : ''}`}>
                                    <td className="px-6 py-4">
                                        <div className="flex items-center gap-2">
                                            <User className="w-4 h-4 text-gray-400" />
                                            <div>
                                                <p className="font-medium text-gray-900">{loan.student.fullName}</p>
                                                <p className="text-xs text-gray-500">{loan.student.identifier}</p>
                                            </div>
                                        </div>
                                    </td>
                                    <td className="px-6 py-4">
                                        <div className="flex items-center gap-2">
                                            <Box className="w-4 h-4 text-[#0F4C81]" />
                                            <div>
                                                <p className="font-medium text-gray-900">{loan.item.name}</p>
                                                <p className="text-xs text-gray-500">{loan.item.category.name}</p>
                                            </div>
                                        </div>
                                    </td>
                                    <td className="px-6 py-4 text-gray-600 text-sm">
                                        {loan.requestDate ? new Date(loan.requestDate).toLocaleDateString('id-ID') : '-'}
                                    </td>
                                    <td className="px-6 py-4 text-gray-600 text-sm">
                                        {new Date(loan.returnPlanDate).toLocaleDateString('id-ID')}
                                    </td>
                                    <td className="px-6 py-4">
                                        <span className={`inline-flex px-2 py-1 rounded text-xs font-medium ${loan.status === 'Pending' ? 'bg-yellow-50 text-yellow-700' :
                                            loan.status === 'Disetujui' ? 'bg-green-50 text-green-700' :
                                                'bg-red-50 text-red-700'
                                            }`}>
                                            {loan.status}
                                        </span>
                                    </td>
                                    <td className="px-6 py-4">
                                        {loan.status === 'Pending' && (
                                            <div className="flex gap-2 justify-center">
                                                <button
                                                    onClick={() => handleApprove(loan.id)}
                                                    disabled={isPending}
                                                    className="text-green-600 hover:text-green-700 p-2 hover:bg-green-50 rounded-lg transition-colors disabled:opacity-50"
                                                >
                                                    <CheckCircle className="w-5 h-5" />
                                                </button>
                                                <button
                                                    onClick={() => handleReject(loan.id)}
                                                    disabled={isPending}
                                                    className="text-red-600 hover:text-red-700 p-2 hover:bg-red-50 rounded-lg transition-colors disabled:opacity-50"
                                                >
                                                    <XCircle className="w-5 h-5" />
                                                </button>
                                            </div>
                                        )}
                                        {loan.status === 'Disetujui' && (
                                            <button
                                                onClick={() => handleReturn(loan.id)}
                                                disabled={isPending}
                                                className="mx-auto flex items-center justify-center gap-1 px-3 py-1.5 bg-[#0F4C81] text-white rounded-lg text-sm hover:bg-[#0F4C81]/90 transition-colors disabled:opacity-50"
                                            >
                                                <CheckCircle className="w-4 h-4" />
                                                Kembalikan
                                            </button>
                                        )}
                                    </td>
                                </tr>
                            ))}
                            {filteredLoans.length === 0 && (
                                <tr>
                                    <td colSpan={6} className="px-6 py-12 text-center text-gray-500">
                                        {searchQuery ? 'Tidak ada hasil pencarian' : 'Belum ada permintaan peminjaman.'}
                                    </td>
                                </tr>
                            )}
                        </tbody>
                    </table>
                </div>
            </div>

            {/* Section 2: Pengembalian Barang */}
            <h3 className="text-lg font-semibold text-gray-900 mb-4">
                📦 Pengembalian Barang
                <span className="ml-2 text-sm font-normal text-gray-500">
                    ({filteredReturns.length} menunggu validasi)
                </span>
            </h3>
            <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
                <div className="overflow-x-auto">
                    <table className="w-full text-left">
                        <thead className="bg-gray-50 border-b border-gray-100">
                            <tr>
                                <th className="px-6 py-4 font-semibold text-gray-700">Mahasiswa</th>
                                <th className="px-6 py-4 font-semibold text-gray-700">Alat</th>
                                <th className="px-6 py-4 font-semibold text-gray-700">Tanggal Pinjam</th>
                                <th className="px-6 py-4 font-semibold text-gray-700">Status</th>
                                <th className="px-6 py-4 font-semibold text-gray-700 text-center">Aksi</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-100">
                            {filteredReturns.map((loan) => (
                                <tr key={loan.id} className={`hover:bg-gray-50 transition-colors ${isPending ? 'opacity-50' : ''}`}>
                                    <td className="px-6 py-4">
                                        <div className="flex items-center gap-2">
                                            <User className="w-4 h-4 text-gray-400" />
                                            <div>
                                                <p className="font-medium text-gray-900">{loan.student.fullName}</p>
                                                <p className="text-xs text-gray-500">{loan.student.identifier}</p>
                                            </div>
                                        </div>
                                    </td>
                                    <td className="px-6 py-4">
                                        <div className="flex items-center gap-2">
                                            <Box className="w-4 h-4 text-[#0F4C81]" />
                                            <p className="font-medium text-gray-900">{loan.item.name}</p>
                                        </div>
                                    </td>
                                    <td className="px-6 py-4 text-gray-600 text-sm">
                                        {loan.requestDate ? new Date(loan.requestDate).toLocaleDateString('id-ID') : '-'}
                                    </td>
                                    <td className="px-6 py-4">
                                        <span className="inline-flex px-2 py-1 rounded text-xs font-medium bg-orange-50 text-orange-700">
                                            Pending Return
                                        </span>
                                    </td>
                                    <td className="px-6 py-4">
                                        <div className="flex gap-2 justify-center">
                                            <button
                                                onClick={() => handleApproveReturn(loan.id)}
                                                disabled={isPending}
                                                className="flex items-center gap-1 px-3 py-1.5 bg-green-600 text-white rounded-lg text-sm hover:bg-green-700 transition-colors disabled:opacity-50"
                                            >
                                                <CheckCircle className="w-4 h-4" />
                                                Approve
                                            </button>
                                            <button
                                                onClick={() => handleRejectReturn(loan.id)}
                                                disabled={isPending}
                                                className="flex items-center gap-1 px-3 py-1.5 bg-red-600 text-white rounded-lg text-sm hover:bg-red-700 transition-colors disabled:opacity-50"
                                            >
                                                <XCircle className="w-4 h-4" />
                                                Reject
                                            </button>
                                        </div>
                                    </td>
                                </tr>
                            ))}
                            {filteredReturns.length === 0 && (
                                <tr>
                                    <td colSpan={5} className="px-6 py-8 text-center text-gray-500">
                                        {searchQuery ? 'Tidak ada hasil pencarian' : 'Tidak ada permintaan pengembalian.'}
                                    </td>
                                </tr>
                            )}
                        </tbody>
                    </table>
                </div>
            </div>
            <RejectReasonModal
                isOpen={rejectModalOpen}
                onClose={() => { setRejectModalOpen(false); setRejectingLoanId(null); }}
                onConfirm={handleRejectConfirm}
                title="Tolak Peminjaman"
                isPending={isPending}
            />
        </div>
    );
}

'use client';

import { useState, useMemo, useTransition } from 'react';
import { User, Box, Search, X, Trash2, MessageSquare, LayoutGrid, List } from 'lucide-react';
import { deleteLoan } from '@/features/loans/actions';
import { deleteBooking } from '@/features/bookings/actions';
import { useAlert } from '@/components/providers/AlertProvider';
import { translateError } from '@/lib/error';

interface CompletedLoan {
    id: number;
    requestDate: Date | null;
    status: string | null;
    rejectionReason: string | null;
    student: {
        fullName: string;
        identifier: string;
    };
    item: {
        name: string;
    };
}

interface CompletedBooking {
    id: number;
    startTime: Date;
    status: string | null;
    rejectionReason: string | null;
    user: {
        fullName: string;
        identifier: string;
    };
    room: {
        name: string;
    };
}

interface SearchableRiwayatProps {
    completedLoans: CompletedLoan[];
    completedBookings: CompletedBooking[];
}

export default function SearchableRiwayatSection({ completedLoans, completedBookings }: SearchableRiwayatProps) {
    const { showConfirm, showAlert } = useAlert();
    const [searchQuery, setSearchQuery] = useState('');
    const [isPending, startTransition] = useTransition();

    // View Mode State
    const [viewMode, setViewMode] = useState<'grid' | 'list'>(() => {
        if (typeof window !== 'undefined') {
            return window.innerWidth >= 768 ? 'list' : 'grid';
        }
        return 'list';
    });

    const filteredLoans = useMemo(() => {
        if (!searchQuery) return completedLoans;
        const query = searchQuery.toLowerCase();
        return completedLoans.filter(loan =>
            loan.student.fullName.toLowerCase().includes(query) ||
            loan.student.identifier.toLowerCase().includes(query) ||
            loan.item.name.toLowerCase().includes(query)
        );
    }, [completedLoans, searchQuery]);

    const filteredBookings = useMemo(() => {
        if (!searchQuery) return completedBookings;
        const query = searchQuery.toLowerCase();
        return completedBookings.filter(booking =>
            booking.user.fullName.toLowerCase().includes(query) ||
            booking.user.identifier.toLowerCase().includes(query) ||
            booking.room.name.toLowerCase().includes(query)
        );
    }, [completedBookings, searchQuery]);

    const handleDeleteLoan = async (loanId: number) => {
        const confirmed = await showConfirm({
            title: 'Hapus Riwayat',
            message: 'Apakah Anda yakin ingin menghapus riwayat peminjaman ini?',
            type: 'danger',
            confirmText: 'Hapus'
        });
        if (confirmed) {
            startTransition(async () => {
                try {
                    await deleteLoan(loanId);
                    showAlert({ title: 'Berhasil', message: 'Riwayat peminjaman dihapus', type: 'success' });
                } catch (error: any) {
                    const { title, message } = translateError(error, 'Gagal menghapus riwayat');
                    showAlert({ title, message, type: 'error' });
                }
            });
        }
    };

    const handleDeleteBooking = async (bookingId: number) => {
        const confirmed = await showConfirm({
            title: 'Hapus Riwayat',
            message: 'Apakah Anda yakin ingin menghapus riwayat booking ini?',
            type: 'danger',
            confirmText: 'Hapus'
        });
        if (confirmed) {
            startTransition(async () => {
                try {
                    await deleteBooking(bookingId);
