import { NextRequest, NextResponse } from 'next/server';
import * as XLSX from 'xlsx';
import { db } from '@/db';
import { practicumReports, users } from '@/db/schema';
import { eq, and, gte, lte, desc } from 'drizzle-orm';
import { getSession } from '@/lib/auth';

function getDateRange(type: string, refDate: string) {
    const base = refDate ? new Date(refDate) : new Date();

    if (type === 'harian') {
        const start = new Date(base);
        start.setHours(0, 0, 0, 0);
        const end = new Date(base);
        end.setHours(23, 59, 59, 999);
        return { start, end };
    }

    if (type === 'mingguan') {
        const day = base.getDay(); // 0=Sun
        const diffToMon = day === 0 ? -6 : 1 - day;
        const start = new Date(base);
        start.setDate(base.getDate() + diffToMon);
        start.setHours(0, 0, 0, 0);
        const end = new Date(start);
        end.setDate(start.getDate() + 6);
        end.setHours(23, 59, 59, 999);
        return { start, end };
    }

    if (type === 'bulanan') {
        const start = new Date(base.getFullYear(), base.getMonth(), 1);
        const end = new Date(base.getFullYear(), base.getMonth() + 1, 0, 23, 59, 59, 999);
        return { start, end };
    }

    // Custom: expect startDate & endDate query params
    return null;
}

export async function GET(request: NextRequest) {
    const session = await getSession();
    if (!session) {
        return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const { searchParams } = new URL(request.url);
    const periodType = searchParams.get('period') || 'bulanan'; // harian | mingguan | bulanan | custom
    const refDate = searchParams.get('date') || new Date().toISOString();
    const startParam = searchParams.get('startDate');
    const endParam = searchParams.get('endDate');

    let startDate: Date;
    let endDate: Date;

    if (periodType === 'custom' && startParam && endParam) {
        startDate = new Date(startParam);
        startDate.setHours(0, 0, 0, 0);
        endDate = new Date(endParam);
        endDate.setHours(23, 59, 59, 999);
    } else {
        const range = getDateRange(periodType, refDate);
        if (!range) {
            return NextResponse.json({ error: 'Parameter periode tidak valid' }, { status: 400 });
        }
        startDate = range.start;
        endDate = range.end;
    }

    const userId = session.user.identifier;
    const isAdmin = session.user.roleId === 1;
    const isLecturer = session.user.roleId === 2;

    // Admin: semua laporan; Dosen: laporan di matakuliah yang diajar; User biasa: laporan milik sendiri
    let reports: any[];

    if (isAdmin) {
        reports = await db
            .select({
                id: practicumReports.id,
                courseName: practicumReports.courseName,
                courseCode: practicumReports.courseCode,
                lecturerName: practicumReports.lecturerName,
                roomName: practicumReports.roomName,
                practicumDate: practicumReports.practicumDate,
                startTime: practicumReports.startTime,
                endTime: practicumReports.endTime,
                batch: practicumReports.batch,
                attendeeCount: practicumReports.attendeeCount,
                condition: practicumReports.condition,
                description: practicumReports.description,
                issues: practicumReports.issues,
                followUp: practicumReports.followUp,
                status: practicumReports.status,
                rejectionReason: practicumReports.rejectionReason,
                createdAt: practicumReports.createdAt,
                createdByName: users.fullName,
            })
            .from(practicumReports)
            .leftJoin(users, eq(practicumReports.createdBy, users.identifier))
            .where(and(
                gte(practicumReports.practicumDate, startDate),
                lte(practicumReports.practicumDate, endDate)
            ))
            .orderBy(desc(practicumReports.practicumDate));
    } else {
        reports = await db
            .select({
                id: practicumReports.id,
                courseName: practicumReports.courseName,
                courseCode: practicumReports.courseCode,
                lecturerName: practicumReports.lecturerName,
                roomName: practicumReports.roomName,
                practicumDate: practicumReports.practicumDate,
                startTime: practicumReports.startTime,
                endTime: practicumReports.endTime,
                batch: practicumReports.batch,
                attendeeCount: practicumReports.attendeeCount,
                condition: practicumReports.condition,
                description: practicumReports.description,
                issues: practicumReports.issues,
                followUp: practicumReports.followUp,
                status: practicumReports.status,
                rejectionReason: practicumReports.rejectionReason,
                createdAt: practicumReports.createdAt,
                createdByName: users.fullName,
            })
            .from(practicumReports)
            .leftJoin(users, eq(practicumReports.createdBy, users.identifier))
            .where(and(
                eq(practicumReports.createdBy, userId),
                gte(practicumReports.practicumDate, startDate),
                lte(practicumReports.practicumDate, endDate)
            ))
            .orderBy(desc(practicumReports.practicumDate));
    }

    const formatDate = (d: Date | null) => {
        if (!d) return '-';
        const dt = typeof d === 'string' ? new Date(d) : d;
        return dt.toLocaleDateString('id-ID', { day: '2-digit', month: 'long', year: 'numeric' });
    };

    const wsData = [
        [
            'No',
            'Mata Kuliah',
            'Kode MK',
            'Dosen',
            'Ruangan',
            'Tanggal Praktikum',
            'Jam Mulai',
            'Jam Selesai',
            'Angkatan',
            'Jumlah Peserta',
            'Kondisi',
            'Deskripsi',
            'Kendala',
            'Tindak Lanjut',
            'Status',
            'Alasan Penolakan',
            'Dibuat Oleh',
            'Dibuat Pada',
        ],
        ...reports.map((r, i) => [
            i + 1,
            r.courseName,
            r.courseCode,
            r.lecturerName || '-',
            r.roomName,
            formatDate(r.practicumDate),
            r.startTime,
            r.endTime,
            r.batch,
            r.attendeeCount,
            r.condition,
            r.description,
            r.issues || '-',
            r.followUp || '-',
            r.status || 'Pending',
            r.rejectionReason || '-',
            r.createdByName || '-',
            formatDate(r.createdAt),
        ]),
    ];

    const ws = XLSX.utils.aoa_to_sheet(wsData);

    // Auto column width
    const colWidths = wsData[0].map((_, colIdx) => ({
        wch: Math.max(...wsData.map(row => String(row[colIdx] ?? '').length), 10),
    }));
    ws['!cols'] = colWidths;

    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'Berita Acara');

    const periodLabel: Record<string, string> = {
        harian: 'Harian',
        mingguan: 'Mingguan',
        bulanan: 'Bulanan',
        custom: 'Kustom',
    };
    const filename = `Berita_Acara_${periodLabel[periodType] || 'Laporan'}_${new Date().toISOString().slice(0, 10)}.xlsx`;

    const buf = XLSX.write(wb, { type: 'buffer', bookType: 'xlsx' });

    return new NextResponse(buf, {
        status: 200,
        headers: {
            'Content-Type': 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
            'Content-Disposition': `attachment; filename="${filename}"`,
        },
    });
}

import { NextRequest, NextResponse } from 'next/server';
import { readFile, stat } from 'fs/promises';
import path from 'path';

export async function GET(
    request: NextRequest,
    { params }: { params: Promise<{ path: string[] }> }
) {
    try {
        const urlParams = await params;
        const filePathArray = urlParams.path || [];

        // Protection against directory traversal attacks
        if (filePathArray.some((p: string) => p.includes('..'))) {
            return new NextResponse('Invalid Path', { status: 400 });
        }

        const relativePath = filePathArray.join('/');
        const absolutePath = path.join(process.cwd(), 'public', 'uploads', relativePath);

        // Check file exists
        await stat(absolutePath);

        const fileBuffer = await readFile(absolutePath);

        // Determine content type
        let contentType = 'application/octet-stream';
        const ext = path.extname(absolutePath).toLowerCase();
        if (ext === '.pdf') contentType = 'application/pdf';
        else if (ext === '.jpg' || ext === '.jpeg') contentType = 'image/jpeg';
        else if (ext === '.png') contentType = 'image/png';
        else if (ext === '.svg') contentType = 'image/svg+xml';
        else if (ext === '.webp') contentType = 'image/webp';

        // Setting Cache-Control headers to ensure browser caches it but bypasses Next.js aggressive static optimization
        return new NextResponse(fileBuffer, {
            headers: {
                'Content-Type': contentType,
                'Cache-Control': 'public, max-age=86400, stale-while-revalidate=43200', // Cache for 1 day
            },
        });
    } catch (error) {
        // If file not found or other error
        return new NextResponse('File Not Found', { status: 404 });
    }
}

import { NextRequest, NextResponse } from 'next/server';
import { getSession, encrypt } from '@/lib/auth';
import { db } from '@/db';
import { users, roles, permissions, rolePermissions, userPermissions } from '@/db/schema';
import { eq } from 'drizzle-orm';

async function getEffectivePermissions(
    userId: string,
    roleId: number
): Promise<string[]> {
    const rolePerms = await db
        .select({ code: permissions.code })
        .from(rolePermissions)
        .innerJoin(permissions, eq(rolePermissions.permissionId, permissions.id))
        .where(eq(rolePermissions.roleId, roleId));

    const defaultCodes = new Set(rolePerms.map((rp) => rp.code));

    const userOverrides = await db
        .select({ code: permissions.code, granted: userPermissions.granted })
        .from(userPermissions)
        .innerJoin(permissions, eq(userPermissions.permissionId, permissions.id))
        .where(eq(userPermissions.userId, userId));

    for (const override of userOverrides) {
        if (override.granted) {
            defaultCodes.add(override.code);
        } else {
            defaultCodes.delete(override.code);
        }
    }

    return Array.from(defaultCodes);
}

export async function GET(request: NextRequest) {
    const session = await getSession();

    if (!session) {
        return NextResponse.redirect(new URL('/login', request.url));
    }

    const redirectTo = request.nextUrl.searchParams.get('redirectTo') || '/';

    // Fetch fresh user data from DB
    const userRows = await db
        .select()
        .from(users)
        .where(eq(users.identifier, session.user.identifier))
        .limit(1);

    if (!userRows[0]) {
        return NextResponse.redirect(new URL('/login', request.url));
    }

    const foundUser = userRows[0];

    const roleRows = await db
        .select()
        .from(roles)
        .where(eq(roles.id, foundUser.roleId))
        .limit(1);

    const roleName = roleRows[0]?.name;

    const effectivePermissions = await getEffectivePermissions(
        foundUser.identifier,
        foundUser.roleId
    );

    const expires = new Date(Date.now() + 24 * 60 * 60 * 1000);
    const newSession = await encrypt({
        user: { ...foundUser, role: roleName, permissions: effectivePermissions },
        expires,
    });

    const response = NextResponse.redirect(new URL(redirectTo, request.url));
    response.cookies.set('session', newSession, { expires, httpOnly: true });
    return response;
}

import { NextRequest, NextResponse } from 'next/server';
import { writeFile, mkdir } from 'fs/promises';
import path from 'path';
import { DocumentVerifier, type DocumentType } from '@/lib/documentVerifier';

const MAX_FILE_SIZE = 2 * 1024 * 1024; // 2MB

// Folders that require PDF-only uploads
const PDF_ONLY_FOLDERS = ['surat-izin', 'surat-permohonan'];

export async function POST(request: NextRequest) {
    try {
        const formData = await request.formData();
        const file = formData.get('file') as File;
        const folder = formData.get('folder') as string || 'general';

        // Check query params for verification
        const verify = request.nextUrl.searchParams.get('verify') === 'true';
        const docType = request.nextUrl.searchParams.get('type') as DocumentType | null;

        if (!file) {
            return NextResponse.json({ error: 'No file provided' }, { status: 400 });
        }

        // Validate file size
        if (file.size > MAX_FILE_SIZE) {
            return NextResponse.json({ error: 'Ukuran file maksimal 2MB' }, { status: 400 });
        }

        // For surat folders, enforce PDF-only
        if (PDF_ONLY_FOLDERS.includes(folder)) {
            if (file.type !== 'application/pdf') {
                return NextResponse.json(
                    { error: 'Surat harus dalam format PDF.' },
                    { status: 400 }
                );
            }
        } else {
            // General folders: allow PDF and images
            const allowedTypes = ['application/pdf', 'image/jpeg', 'image/png', 'image/jpg'];
            if (!allowedTypes.includes(file.type)) {
                return NextResponse.json({ error: 'Invalid file type. Only PDF and images allowed.' }, { status: 400 });
            }
        }

        // Create upload directory if it doesn't exist
        const uploadDir = path.join(process.cwd(), 'public', 'uploads', folder);
        await mkdir(uploadDir, { recursive: true });

        // Generate unique filename
        const timestamp = Date.now();
        const originalName = file.name.replace(/[^a-zA-Z0-9.-]/g, '_');
        const filename = `${timestamp}-${originalName}`;
        const filepath = path.join(uploadDir, filename);

        // Convert File to Buffer and save
        const bytes = await file.arrayBuffer();
        const buffer = Buffer.from(bytes);
        await writeFile(filepath, buffer);

        // Return dynamic URL path
        const publicPath = `/api/file/${folder}/${filename}`;

        // Run document verification if requested
        if (verify && docType) {
            try {
                const result = await DocumentVerifier.verify(publicPath, docType);

                if (!result.fileValid) {
                    // File saved but not a valid document
                    return NextResponse.json({
                        success: true,
                        path: publicPath,
                        filename,
                        verification: {
                            valid: false,
                            score: 0,
                            matchedKeywords: [],
                            missingKeywords: [],
                            reason: result.reason,
                            ocrUsed: false,
                            extractionMethod: 'text',
                        },
                    });
                }

                return NextResponse.json({
                    success: true,
                    path: publicPath,
                    filename,
                    verification: result.verification,
                });
            } catch (verifyError) {
                console.error('Verification error:', verifyError);
                // File saved, but verification failed — return without verification data
                return NextResponse.json({
                    success: true,
                    path: publicPath,
                    filename,
                    verification: null,
                });
            }
        }

        return NextResponse.json({
            success: true,
            path: publicPath,
            filename,
        });

    } catch (error) {
        console.error('Upload error:', error);
        return NextResponse.json({ error: 'Failed to upload file' }, { status: 500 });
    }
}

