                                            </td>
                                            <td className="px-4 py-4">
                                                {(pub.link || pub.filePath) && (
                                                    <PublicationLink
                                                        id={pub.id}
                                                        url={pub.link || pub.filePath || '#'}
                                                        className="inline-flex items-center gap-1 text-[#0F4C81] hover:text-blue-700 text-sm"
                                                    >
                                                        <ExternalLink className="w-3 h-3" />
