'use client';

import { useState, useMemo } from 'react';
import { ChevronLeft, ChevronRight, Clock } from 'lucide-react';

interface Booking {
    id: number;
    startTime: Date;
    endTime: Date;
    purpose: string;
    room: {
        id: number;
        name: string;
    };
}

interface PracticumSchedule {
    id: number;
    roomId: number;
    roomName: string | null;
    courseName: string | null;
    courseCode: string | null;
    dayOfWeek: number;
    startTime: string;
    endTime: string;
    scheduledDate: Date;
}

interface CustomCalendarProps {
    bookings: Booking[];
    practicumSchedules?: PracticumSchedule[];
    onDateSelect?: (date: Date) => void;
    selectedRoomId?: number | null;
}

const DAYS = ['Sen', 'Sel', 'Rab', 'Kam', 'Jum', 'Sab', 'Min'];
const MONTHS = [
    'Januari', 'Februari', 'Maret', 'April', 'Mei', 'Juni',
    'Juli', 'Agustus', 'September', 'Oktober', 'November', 'Desember'
];

export default function CustomCalendar({ bookings, practicumSchedules = [], onDateSelect, selectedRoomId }: CustomCalendarProps) {
    const [currentDate, setCurrentDate] = useState(new Date());
    const [selectedDate, setSelectedDate] = useState<Date>(new Date());

    // Filter bookings by room
    const filteredBookings = useMemo(() => {
        return bookings.filter(b => {
            if (selectedRoomId) {
                return b.room.id === selectedRoomId;
            }
            return true;
        });
    }, [bookings, selectedRoomId]);

    // Filter practicum schedules by room
    const filteredPracticums = useMemo(() => {
        return practicumSchedules.filter(p => {
            if (selectedRoomId) {
                return p.roomId === selectedRoomId;
            }
            return true;
        });
    }, [practicumSchedules, selectedRoomId]);

    // Get days in month
    const getDaysInMonth = (date: Date) => {
        const year = date.getFullYear();
        const month = date.getMonth();
        const firstDay = new Date(year, month, 1);
        const lastDay = new Date(year, month + 1, 0);
        const daysInMonth = lastDay.getDate();

        // Get first day of week (Monday = 0, Sunday = 6)
        let startDay = firstDay.getDay() - 1;
        if (startDay < 0) startDay = 6;

        return { daysInMonth, startDay };
    };

    // Check if date has bookings or practicum schedules
    const hasBooking = (day: number) => {
        const checkDate = new Date(currentDate.getFullYear(), currentDate.getMonth(), day);
        const hasRegularBooking = filteredBookings.some(b => {
            const bookingDate = new Date(b.startTime);
            return bookingDate.getDate() === checkDate.getDate() &&
                bookingDate.getMonth() === checkDate.getMonth() &&
                bookingDate.getFullYear() === checkDate.getFullYear();
        });
        if (hasRegularBooking) return true;

        return filteredPracticums.some(p => {
            const pDate = new Date(p.scheduledDate);
            return pDate.getDate() === checkDate.getDate() &&
                pDate.getMonth() === checkDate.getMonth() &&
                pDate.getFullYear() === checkDate.getFullYear();
        });
    };

    // Get bookings for selected date
    const getBookingsForDay = (date: Date) => {
        return filteredBookings.filter(b => {
            const bookingDate = new Date(b.startTime);
            return bookingDate.getDate() === date.getDate() &&
                bookingDate.getMonth() === date.getMonth() &&
                bookingDate.getFullYear() === date.getFullYear();
        });
    };

    // Get practicum schedules for selected date
    const getPracticumsForDay = (date: Date) => {
        return filteredPracticums.filter(p => {
            const pDate = new Date(p.scheduledDate);
            return pDate.getDate() === date.getDate() &&
                pDate.getMonth() === date.getMonth() &&
                pDate.getFullYear() === date.getFullYear();
        });
    };

    // Check if day is today
    const isToday = (day: number) => {
        const today = new Date();
        return day === today.getDate() &&
            currentDate.getMonth() === today.getMonth() &&
            currentDate.getFullYear() === today.getFullYear();
    };

    // Check if day is selected
    const isSelected = (day: number) => {
        return day === selectedDate.getDate() &&
            currentDate.getMonth() === selectedDate.getMonth() &&
            currentDate.getFullYear() === selectedDate.getFullYear();
    };

    // Handle date click
    const handleDateClick = (day: number) => {
        const newDate = new Date(currentDate.getFullYear(), currentDate.getMonth(), day);
        setSelectedDate(newDate);
        onDateSelect?.(newDate);
    };

    // Navigation
    const prevMonth = () => {
        setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1));
    };

    const nextMonth = () => {
        setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1));
    };

    const { daysInMonth, startDay } = getDaysInMonth(currentDate);
    const selectedBookings = getBookingsForDay(selectedDate);
    const selectedPracticums = getPracticumsForDay(selectedDate);

    return (
        <div className="flex flex-col h-full w-full">
            {/* Calendar Header */}
            <div className="flex items-center justify-between mb-3">
                <button
                    onClick={prevMonth}
                    className="p-1.5 hover:bg-gray-100 rounded-lg transition-colors"
                >
                    <ChevronLeft className="w-5 h-5 text-gray-600" />
                </button>
                <h3 className="text-xs font-semibold text-gray-800">
                    {MONTHS[currentDate.getMonth()]} {currentDate.getFullYear()}
                </h3>
                <button
                    onClick={nextMonth}
                    className="p-1.5 hover:bg-gray-100 rounded-lg transition-colors"
                >
                    <ChevronRight className="w-5 h-5 text-gray-600" />
                </button>
            </div>

            {/* Day Headers */}
            <div className="grid grid-cols-7 gap-0 mb-1">
                {DAYS.map(day => (
                    <div key={day} className="text-center text-[10px] font-medium text-gray-500 py-0.5">
                        {day}
                    </div>
                ))}
            </div>

            {/* Calendar Grid */}
            <div className="grid grid-cols-7 gap-0.5 mb-2">
                {/* Empty cells for start offset */}
                {Array.from({ length: startDay }).map((_, i) => (
                    <div key={`empty-${i}`} className="aspect-square w-full max-h-[40px]" />
                ))}

                {/* Day cells */}
                {Array.from({ length: daysInMonth }).map((_, i) => {
                    const day = i + 1;
                    const hasBookingToday = hasBooking(day);
                    const isTodayDate = isToday(day);
                    const isSelectedDate = isSelected(day);

                    return (
                        <button
                            key={day}
                            onClick={() => handleDateClick(day)}
                            className={`
                                aspect-square w-full max-h-[40px] flex flex-col items-center justify-center text-[11px] sm:text-xs rounded-md transition-all relative
                                ${isSelectedDate
                                    ? 'bg-[#0F4C81] text-white font-semibold shadow-sm'
                                    : isTodayDate
                                        ? 'bg-[#0F4C81]/10 text-[#0F4C81] font-semibold'
                                        : 'hover:bg-gray-100 text-gray-700'
                                }
                            `}
                        >
                            {day}
                            {hasBookingToday && !isSelectedDate && (
                                <span className="absolute bottom-1 left-1/2 -translate-x-1/2 flex gap-0.5">
                                    <span className="w-1 h-1 bg-[#0F4C81] rounded-full" />
                                </span>
                            )}
                        </button>
                    );
                })}
            </div>

            {/* Selected Date Agenda */}
            <div className="flex-1 overflow-y-auto border-t border-gray-100 pt-3">
                <h4 className="text-xs font-bold text-gray-500 uppercase tracking-wider mb-2">
                    Agenda {selectedDate.toLocaleDateString('id-ID', { day: 'numeric', month: 'short' })}
                </h4>

                <div className="space-y-2">
                    {/* Practicum schedules first (higher priority) */}
                    {selectedPracticums.length > 0 && selectedPracticums.map(practicum => (
                        <div
                            key={`p-${practicum.id}`}
                            className="bg-green-50 p-2 rounded-lg border border-green-200"
                        >
                            <div className="flex justify-between items-start mb-1">
                                <span className="text-xs font-bold text-green-700 flex items-center gap-1">
                                    <Clock className="w-3 h-3" />
                                    {practicum.startTime} - {practicum.endTime}
                                </span>
                                <span className="text-[10px] bg-green-100 border border-green-300 px-1.5 py-0.5 rounded text-green-700 font-medium">
                                    {practicum.roomName}
                                </span>
                            </div>
                            <p className="text-xs text-green-800 font-semibold">
                                🎓 Praktikum: {practicum.courseName} ({practicum.courseCode})
                            </p>
                            <p className="text-[10px] text-green-600 mt-0.5">Ruangan tidak tersedia untuk booking</p>
                        </div>
                    ))}

                    {/* Regular bookings */}
                    {selectedBookings.length > 0 ? (
                        selectedBookings.map(booking => (
                            <div
                                key={booking.id}
                                className="bg-gray-50 p-2 rounded-lg border border-gray-100"
                            >
                                <div className="flex justify-between items-start mb-1">
                                    <span className="text-xs font-bold text-[#0F4C81] flex items-center gap-1">
                                        <Clock className="w-3 h-3" />
                                        {new Date(booking.startTime).toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' })}
                                    </span>
                                    <span className="text-[10px] bg-white border px-1.5 py-0.5 rounded text-gray-500">
                                        {booking.room.name}
                                    </span>
                                </div>
                                <p className="text-xs text-gray-700 line-clamp-2">
                                    {booking.purpose}
                                </p>
                            </div>
                        ))
                    ) : (
                        selectedPracticums.length === 0 && (
                            <div className="text-center py-4 text-gray-400">
                                <p className="text-xs">Tidak ada jadwal</p>
                            </div>
                        )
                    )}
                </div>
            </div>
        </div>
    );
}

'use client';

import { X } from 'lucide-react';
import { useEffect } from 'react';

interface ModalProps {
    isOpen: boolean;
    onClose: () => void;
    title: string;
    children: React.ReactNode;
}

export default function Modal({ isOpen, onClose, title, children }: ModalProps) {
    useEffect(() => {
        const handleEscape = (e: KeyboardEvent) => {
            if (e.key === 'Escape') onClose();
        };

        if (isOpen) {
            document.addEventListener('keydown', handleEscape);
            document.body.style.overflow = 'hidden';
        }

        return () => {
            document.removeEventListener('keydown', handleEscape);
            document.body.style.overflow = 'unset';
        };
    }, [isOpen, onClose]);

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm">
            <div className="bg-white rounded-xl shadow-xl w-full max-w-2xl max-h-[90vh] flex flex-col animate-in fade-in zoom-in-95 duration-200">
                <div className="flex items-center justify-between p-6 border-b border-gray-100">
                    <h2 className="text-xl font-semibold text-gray-900">{title}</h2>
                    <button
                        onClick={onClose}
                        className="p-2 text-gray-400 hover:text-gray-600 hover:bg-gray-100 rounded-lg transition-colors"
                    >
                        <X className="w-5 h-5" />
                    </button>
                </div>
                <div className="p-6 overflow-y-auto custom-scrollbar">
                    {children}
                </div>
            </div>
        </div>
    );
}

'use client';

import { useEffect, useRef, useState } from 'react';
import QRCode from 'qrcode';
import { Download, ExternalLink } from 'lucide-react';

interface QRCodeDisplayProps {
    value: string; // The QR code value (e.g., "ITEM-xxx")
    baseUrl?: string; // Optional base URL for the QR link
}

export default function QRCodeDisplay({ value, baseUrl }: QRCodeDisplayProps) {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const modalCanvasRef = useRef<HTMLCanvasElement>(null);
    const [showModal, setShowModal] = useState(false);

    // Build the full URL if baseUrl is provided
    const qrUrl = baseUrl ? `${baseUrl}/items/${value}` : value;

    useEffect(() => {
        if (canvasRef.current) {
            QRCode.toCanvas(canvasRef.current, qrUrl, { width: 80, margin: 1 });
        }
    }, [qrUrl]);

    useEffect(() => {
        if (showModal && modalCanvasRef.current) {
            QRCode.toCanvas(modalCanvasRef.current, qrUrl, { width: 200, margin: 2 });
        }
    }, [showModal, qrUrl]);

    const downloadQR = async () => {
        // Create a new canvas for download with larger size
        const canvas = document.createElement('canvas');
        await QRCode.toCanvas(canvas, qrUrl, { width: 400, margin: 2 });
        const url = canvas.toDataURL();
        const link = document.createElement('a');
        link.download = `qr-${value}.png`;
        link.href = url;
        link.click();
    };

    return (
        <>
            <button
                onClick={() => setShowModal(true)}
                className="hover:opacity-75 transition-opacity"
            >
                <canvas ref={canvasRef} className="border border-gray-200 rounded" />
            </button>

            {showModal && (
                <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50" onClick={() => setShowModal(false)}>
                    <div className="bg-white p-8 rounded-xl shadow-xl max-w-sm" onClick={(e) => e.stopPropagation()}>
                        <h3 className="text-lg font-semibold mb-4">QR Code</h3>
                        <div className="flex justify-center mb-4">
                            <canvas ref={modalCanvasRef} className="border-2 border-gray-200 rounded-lg" />
                        </div>
                        <p className="text-sm text-gray-600 text-center mb-2 font-mono break-all">{value}</p>
                        {baseUrl && (
                            <a
                                href={qrUrl}
                                target="_blank"
                                rel="noopener noreferrer"
                                className="flex items-center justify-center gap-1 text-xs text-[#0F4C81] hover:underline mb-4"
                            >
                                <ExternalLink className="w-3 h-3" />
                                Buka halaman
                            </a>
                        )}
                        <div className="flex gap-2">
                            <button
                                onClick={downloadQR}
                                className="flex-1 bg-[#0F4C81] text-white px-4 py-2 rounded-lg hover:bg-[#0F4C81]/90 transition-colors flex items-center justify-center gap-2"
                            >
                                <Download className="w-4 h-4" />
                                Download
                            </button>
                            <button
                                onClick={() => setShowModal(false)}
                                className="flex-1 bg-gray-100 text-gray-700 px-4 py-2 rounded-lg hover:bg-gray-200 transition-colors"
                            >
                                Tutup
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </>
    );
}

'use client';

import { useState, useMemo } from 'react';
import { DayPicker } from 'react-day-picker';
import { id } from 'date-fns/locale';
import { Clock, MapPin } from 'lucide-react';
import 'react-day-picker/dist/style.css';

interface Booking {
    id: number;
    startTime: Date;
    endTime: Date;
    purpose: string;
    room: {
        id: number;
        name: string;
    };
}

interface RoomCalendarProps {
    bookings: Booking[];
    onDateSelect?: (date: Date) => void;
    selectedRoomId?: number | null;
}

export default function RoomCalendar({ bookings, onDateSelect, selectedRoomId }: RoomCalendarProps) {
    const [selectedDate, setSelectedDate] = useState<Date | undefined>(new Date());

    const handleDateSelect = (date: Date | undefined) => {
        setSelectedDate(date);
        if (date && onDateSelect) {
            onDateSelect(date);
        }
    };

    // Filter logic
    const filteredBookings = useMemo(() => {
        return bookings.filter(b => {
            if (selectedRoomId) {
                return b.room.id === selectedRoomId;
            }
            return true;
        });
    }, [bookings, selectedRoomId]);

    const getBookingsForDay = (date: Date) => {
        return filteredBookings.filter(b => {
            const bookingDate = new Date(b.startTime);
            return bookingDate.getDate() === date.getDate() &&
                bookingDate.getMonth() === date.getMonth() &&
                bookingDate.getFullYear() === date.getFullYear();
        });
    };

    const bookedDays = useMemo(() => {
        return filteredBookings.map(b => new Date(b.startTime));
    }, [filteredBookings]);

    return (
        /* PERBAIKAN 1: Hapus bg-white, shadow, dan border. 
           Gunakan h-full dan flex-col agar stack vertikal. */
        <div className="flex flex-col h-full w-full">
            
            {/* Bagian Kalender (DatePicker) */}
            <div className="flex justify-center border-b border-gray-100 pb-4 mb-4 bg-white">
                <DayPicker
                    mode="single"
                    selected={selectedDate}
                    onSelect={handleDateSelect}
                    locale={id}
                    modifiers={{ booked: bookedDays }}
                    modifiersStyles={{
                        booked: {
                            fontWeight: 'bold',
                            color: '#0F4C81', // Sesuaikan dengan warna brand Anda
                            textDecoration: 'underline'
                        }
                    }}
                    styles={{
                        caption: { color: '#1f2937' },
                        head_cell: { color: '#6b7280' },
                        // PERBAIKAN 2: Kecilkan ukuran font agar muat di sidebar
                        day: { fontSize: '0.875rem' } 
                    }}
                />
            </div>

            {/* Bagian List Agenda (Detail) */}
            <div className="flex-1 overflow-y-auto px-1 custom-scrollbar min-h-[300px]">
                {selectedDate ? (
                    <div className="animate-in fade-in slide-in-from-bottom-2 duration-300">
                        <h3 className="text-xs font-bold text-gray-500 uppercase tracking-wider mb-3 sticky top-0 bg-white py-2 z-10 border-b border-gray-50">
                            Agenda {selectedDate.toLocaleDateString('id-ID', { day: 'numeric', month: 'short' })}
                        </h3>

                        <div className="space-y-3">
                            {getBookingsForDay(selectedDate).length > 0 ? (
                                getBookingsForDay(selectedDate).map(booking => (
                                    /* Card Item Kecil */
                                    <div key={booking.id} className="bg-gray-50 p-3 rounded-lg border border-gray-100 hover:border-primary/30 transition-all">
                                        <div className="flex justify-between items-start mb-2">
                                            <div className="flex items-center gap-1.5 text-xs font-bold text-[#0F4C81]">
                                                <Clock className="w-3 h-3" />
                                                {new Date(booking.startTime).toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' })}
                                            </div>
                                            <span className="text-[10px] bg-white border px-1.5 py-0.5 rounded text-gray-500">
                                                {booking.room.name}
                                            </span>
                                        </div>
                                        <p className="text-sm text-gray-800 line-clamp-2 leading-snug">
                                            {booking.purpose}
                                        </p>
                                    </div>
                                ))
                            ) : (
                                <div className="text-center py-8 text-gray-400">
                                    <p className="text-sm">Tidak ada jadwal</p>
                                </div>
                            )}
                        </div>
                    </div>
                ) : (
                    <div className="text-center py-10 text-gray-400 italic text-sm">
                        Pilih tanggal diatas
                    </div>
                )}
            </div>
        </div>
    );
}

'use client';

import { useState, useEffect } from 'react';
import { Search, X } from 'lucide-react';

interface SearchFilterProps {
    placeholder?: string;
    onSearch: (query: string) => void;
    className?: string;
}

export default function SearchFilter({
    placeholder = "Cari...",
    onSearch,
    className = ""
}: SearchFilterProps) {
    const [query, setQuery] = useState('');

    useEffect(() => {
        const debounce = setTimeout(() => {
            onSearch(query);
        }, 300);
        return () => clearTimeout(debounce);
    }, [query, onSearch]);

    const handleClear = () => {
        setQuery('');
        onSearch('');
    };

    return (
        <div className={`relative ${className}`}>
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
            <input
                type="text"
                value={query}
                onChange={(e) => setQuery(e.target.value)}
                placeholder={placeholder}
                className="w-full pl-10 pr-10 py-2 border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-[#0F4C81]/20 focus:border-[#0F4C81]"
            />
            {query && (
                <button
                    onClick={handleClear}
                    className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600"
                >
                    <X className="w-4 h-4" />
                </button>
            )}
        </div>
    );
}

'use client';

import React, { useEffect } from 'react';

interface TimeSelectProps {
    value: string; // HH:mm format
    onChange: (val: string) => void;
    required?: boolean;
    name?: string;
}

export default function TimeSelect({ value, onChange, required, name }: TimeSelectProps) {
    const hours = Array.from({ length: 24 }, (_, i) => i.toString().padStart(2, '0'));
    const minutes = Array.from({ length: 60 }, (_, i) => i.toString().padStart(2, '0'));

    // Initialize if empty but required (or let it be controlled)
    const [hour, minute] = value ? value.split(':') : ['', ''];

    const handleHour = (e: React.ChangeEvent<HTMLSelectElement>) => {
        const newHour = e.target.value;
        onChange(`${newHour}:${minute || '00'}`);
    };

    const handleMinute = (e: React.ChangeEvent<HTMLSelectElement>) => {
        const newMinute = e.target.value;
        onChange(`${hour || '08'}:${newMinute}`);
    };

    return (
        <div className="flex items-center gap-1 w-full">
            <select
                required={required}
                value={hour}
                onChange={handleHour}
                className="w-full px-2 py-2 text-center rounded-lg border border-gray-200 focus:outline-none focus:ring-2 focus:ring-primary/20 text-sm bg-white cursor-pointer"
            >
                <option value="" disabled className="hidden">Jam</option>
                {hours.map(h => <option key={h} value={h}>{h}</option>)}
            </select>
            <span className="text-gray-500 font-bold">:</span>
            <select
                required={required}
                value={minute}
                onChange={handleMinute}
                className="w-full px-2 py-2 text-center rounded-lg border border-gray-200 focus:outline-none focus:ring-2 focus:ring-primary/20 text-sm bg-white cursor-pointer"
            >
                <option value="" disabled className="hidden">Mnt</option>
                {minutes.map(m => <option key={m} value={m}>{m}</option>)}
            </select>
            {name && <input type="hidden" name={name} value={value} />}
        </div>
    );
}

'use client';

import { useEffect, useState } from 'react';
import { createPortal } from 'react-dom';

interface ViewportPortalProps {
    children: React.ReactNode;
}

export default function ViewportPortal({ children }: ViewportPortalProps) {
    const [mounted, setMounted] = useState(false);

    useEffect(() => {
        setMounted(true);
        return () => setMounted(false);
    }, []);

    if (!mounted) {
        return null;
    }

    return createPortal(children, document.body);
}

'use client';

import { useState } from 'react';
import { XCircle, X } from 'lucide-react';

interface RejectReasonModalProps {
    isOpen: boolean;
    onClose: () => void;
    onConfirm: (reason: string) => void;
    title?: string;
    isPending?: boolean;
}

export default function RejectReasonModal({
    isOpen,
    onClose,
    onConfirm,
    title = 'Tolak Pengajuan',
    isPending = false,
}: RejectReasonModalProps) {
    const [reason, setReason] = useState('');

    if (!isOpen) return null;

    const handleConfirm = () => {
        onConfirm(reason.trim());
        setReason('');
    };

    const handleClose = () => {
        setReason('');
        onClose();
    };

    return (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
            {/* Backdrop */}
            <div
                className="fixed inset-0 bg-black/50 backdrop-blur-sm transition-opacity"
                onClick={handleClose}
            />

            {/* Modal */}
            <div className="bg-white rounded-2xl shadow-xl w-full max-w-md flex flex-col relative z-10 animate-in zoom-in-95 fade-in duration-200">
                <button
                    onClick={handleClose}
                    className="absolute right-4 top-4 text-gray-400 hover:text-gray-600 transition-colors"
                >
                    <X className="w-5 h-5" />
                </button>

                <div className="p-6 pt-8 flex flex-col items-center text-center">
                    <XCircle className="w-12 h-12 text-red-500 mb-4" />
                    <h2 className="text-xl font-bold text-gray-900 mb-2">{title}</h2>
                    <p className="text-gray-600 mb-4">
                        Apakah Anda yakin ingin menolak pengajuan ini?
                    </p>

                    <div className="w-full text-left mb-6">
                        <label className="block text-sm font-medium text-gray-700 mb-1.5">
                            Alasan Penolakan <span className="text-gray-400 font-normal">(opsional)</span>
                        </label>
                        <textarea
                            value={reason}
                            onChange={(e) => setReason(e.target.value)}
                            placeholder="Masukkan alasan penolakan..."
                            rows={3}
                            className="w-full px-3 py-2 border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-red-500/20 focus:border-red-400 resize-none placeholder:text-gray-400"
                        />
                    </div>

                    <div className="flex flex-col sm:flex-row w-full gap-3 sm:justify-center">
                        <button
                            onClick={handleClose}
                            disabled={isPending}
                            className="px-6 py-2 rounded-lg font-medium border border-gray-200 text-gray-700 hover:bg-gray-50 transition-colors focus:ring-2 focus:ring-gray-200 focus:ring-offset-2 outline-none w-full sm:w-auto"
                        >
                            Batal
                        </button>
                        <button
                            onClick={handleConfirm}
                            disabled={isPending}
                            className="px-6 py-2 rounded-lg font-medium bg-red-600 hover:bg-red-700 text-white transition-colors focus:ring-2 focus:ring-red-500 focus:ring-offset-2 outline-none w-full sm:w-auto disabled:opacity-50"
                        >
                            {isPending ? 'Memproses...' : 'Tolak'}
                        </button>
                    </div>
                </div>
            </div>
        </div>
    );
}

