                    )}
                </div>
            </div>
        </div>
    );
}

import { db } from '@/db';
import { labAttendance, users, rooms, roles } from '@/db/schema';
import { eq } from 'drizzle-orm';

/**
 * Find user by NIM (identifier) with dosenPembimbing and role for fallback logic
 */
export async function findUserByNim(nim: string) {
    const result = await db.select({
        identifier: users.identifier,
        fullName: users.fullName,
        dosenPembimbing: users.dosenPembimbing,
        roleName: roles.name,
    })
        .from(users)
        .innerJoin(roles, eq(users.roleId, roles.id))
        .where(eq(users.identifier, nim))
        .limit(1);

    return result[0] || null;
}

/**
 * Get all available rooms for attendance
 */
export async function getAvailableRooms() {
    const result = await db.select({
        id: rooms.id,
        name: rooms.name,
        location: rooms.location,
    })
        .from(rooms)
        .where(eq(rooms.status, 'Tersedia'));

    return result;
}

/**
 * Create attendance record with room, purpose, and dosen penanggung jawab
 */
export async function createAttendance(
    userId: string,
    roomId: number,
    purpose: string,
    dosenPenanggungJawab: string
) {
    const result = await db.insert(labAttendance).values({
        userId,
        roomId,
        purpose,
        dosenPenanggungJawab,
    });

    return result[0];
}

/**
 * Get attendance with user and room info
 */
export async function getAttendanceWithDetails(userId: string, roomId: number) {
    const result = await db.select({
        id: labAttendance.id,
        userId: labAttendance.userId,
        roomId: labAttendance.roomId,
        purpose: labAttendance.purpose,
        checkInTime: labAttendance.checkInTime,
        user: {
            identifier: users.identifier,
            fullName: users.fullName,
        },
        room: {
            id: rooms.id,
            name: rooms.name,
            location: rooms.location,
        }
    })
        .from(labAttendance)
        .innerJoin(users, eq(labAttendance.userId, users.identifier))
        .innerJoin(rooms, eq(labAttendance.roomId, rooms.id))
        .where(eq(labAttendance.userId, userId))
        .orderBy(labAttendance.checkInTime)
        .limit(1);

    return result[0] || null;
}

/**
 * Get today's lab attendance with user and room details
 */
export async function getTodayAttendance() {
    const { gte, desc } = await import('drizzle-orm');
    const { startOfDayWIBForDb } = await import('@/lib/timezone');

    const todayStart = startOfDayWIBForDb(0);

    const result = await db.select({
        id: labAttendance.id,
        purpose: labAttendance.purpose,
        checkInTime: labAttendance.checkInTime,
        dosenPenanggungJawab: labAttendance.dosenPenanggungJawab,
        user: {
            identifier: users.identifier,
            fullName: users.fullName,
        },
        room: {
            id: rooms.id,
            name: rooms.name,
        }
    })
        .from(labAttendance)
        .innerJoin(users, eq(labAttendance.userId, users.identifier))
        .innerJoin(rooms, eq(labAttendance.roomId, rooms.id))
        .where(gte(labAttendance.checkInTime, todayStart))
        .orderBy(desc(labAttendance.checkInTime));

    return result;
}

/**
 * Get room attendance statistics (count per room for today)
 */
export async function getRoomAttendanceStats() {
    const { gte, sql } = await import('drizzle-orm');
    const { startOfDayWIBForDb } = await import('@/lib/timezone');

    const todayStart = startOfDayWIBForDb(0);

    const result = await db.select({
        roomId: labAttendance.roomId,
        roomName: rooms.name,
        count: sql<number>`count(*)`,
    })
        .from(labAttendance)
        .innerJoin(rooms, eq(labAttendance.roomId, rooms.id))
        .where(gte(labAttendance.checkInTime, todayStart))
        .groupBy(labAttendance.roomId, rooms.name)
        .orderBy(rooms.name);

    return result;
}

'use server';

import { cookies } from 'next/headers';
import { db } from '@/db';
import { users, roles, permissions, rolePermissions, userPermissions } from '@/db/schema';
import { eq, or } from 'drizzle-orm';
import { encrypt, getSession } from '@/lib/auth';
import bcrypt from 'bcryptjs';

/**
 * Compute effective permissions for a user:
 * effective = role_defaults + user_grants - user_revocations
 */

async function getEffectivePermissions(userId: string, roleId: number): Promise<string[]> {
    // 1. Get role default permission codes
    const rolePerms = await db.select({ code: permissions.code })
        .from(rolePermissions)
        .innerJoin(permissions, eq(rolePermissions.permissionId, permissions.id))
        .where(eq(rolePermissions.roleId, roleId));

    const defaultCodes = new Set(rolePerms.map(rp => rp.code));

    // 2. Get user-level overrides
    const userOverrides = await db.select({
        code: permissions.code,
        granted: userPermissions.granted,
    })
        .from(userPermissions)
        .innerJoin(permissions, eq(userPermissions.permissionId, permissions.id))
        .where(eq(userPermissions.userId, userId));

    // 3. Apply overrides
    for (const override of userOverrides) {
        if (override.granted) {
            defaultCodes.add(override.code);
        } else {
            defaultCodes.delete(override.code);
        }
    }

    return Array.from(defaultCodes);
}

export async function login(formData: any) {
    try {
        const { email, password } = formData;

        // Find user
        const user = await db.select().from(users).where(or(eq(users.email, email), eq(users.identifier, email))).limit(1);

        if (user.length === 0) {
            return { success: false, error: 'User tidak ditemukan' };
        }

        const foundUser = user[0];

        // Verify password
        if (!foundUser.passwordHash) {
            return { success: false, error: 'User tidak memiliki password' };
        }
        const passwordMatch = await bcrypt.compare(password, foundUser.passwordHash);
        if (!passwordMatch) {
            return { success: false, error: 'Password salah' };
        }

        // Check status
        if (foundUser.status === 'Pending') {
            return { success: false, error: 'Akun Anda sedang menunggu persetujuan admin' };
        }
        if (foundUser.status === 'Rejected') {
            return { success: false, error: 'Akun Anda ditolak oleh admin' };
        }

        // Get role name
        const role = await db.select().from(roles).where(eq(roles.id, foundUser.roleId)).limit(1);
        const roleName = role[0]?.name;

        // Get effective permissions for this user
        const effectivePermissions = await getEffectivePermissions(foundUser.identifier, foundUser.roleId);

        // Create the session
        const expires = new Date(Date.now() + 24 * 60 * 60 * 1000); // 24 hours
        const session = await encrypt({
            user: { ...foundUser, role: roleName, permissions: effectivePermissions },
            expires
        });

        // Save the session in a cookie
        (await cookies()).set('session', session, { expires, httpOnly: true });

        return { success: true };
    } catch (error: any) {
        return { success: false, error: error.message || 'Login gagal, terjadi kesalahan sistem' };
    }
}

export async function logout() {
    // Destroy the session
    (await cookies()).set('session', '', { expires: new Date(0) });
}

/**
 * Transparently refresh the current user's session with latest permissions from DB.
 */
export async function refreshUserSession() {
    const session = await getSession();
    if (!session?.user) return;

    const { identifier: userId, roleId } = session.user;
    if (!userId || !roleId) return;

    const freshPermissions = await getEffectivePermissions(userId, roleId);
    const currentPerms: string[] = session.user.permissions ?? [];

    const currentSet = new Set(currentPerms);
    const freshSet = new Set(freshPermissions);
    const isSame = currentSet.size === freshSet.size && [...freshSet].every((p) => currentSet.has(p));

    if (isSame) return;

    const expires = new Date(Date.now() + 24 * 60 * 60 * 1000);
    const newSession = await encrypt({
        user: { ...session.user, permissions: freshPermissions },
        expires,
    });

    (await cookies()).set('session', newSession, { expires, httpOnly: true });
}

