}

export default function InsightCard({ insight }: InsightCardProps) {
    const bgClasses = {
        info: 'bg-blue-50 border-blue-200',
        warning: 'bg-amber-50 border-amber-200',
        success: 'bg-green-50 border-green-200',
        danger: 'bg-red-50 border-red-200',
    };

    const textClasses = {
        info: 'text-blue-800',
        warning: 'text-amber-800',
        success: 'text-green-800',
        danger: 'text-red-800',
    };

    const badgeClasses = {
        critical: 'bg-red-500 text-white',
        high: 'bg-amber-500 text-white',
        medium: 'bg-blue-100 text-blue-700',
        low: 'bg-gray-100 text-gray-600',
    };

    const priorityLabels = {
        critical: 'Kritis',
        high: 'Penting',
        medium: 'Sedang',
        low: 'Info',
    };

    return (
        <div className={`p-4 rounded-xl border ${bgClasses[insight.type]} transition-shadow hover:shadow-md`}>
            <div className="flex items-start gap-3">
                <span className="text-2xl flex-shrink-0">{insight.icon}</span>
                <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2 mb-0.5">
                        <p className={`font-semibold text-sm ${textClasses[insight.type]}`}>{insight.title}</p>
                        {insight.priority !== 'low' && (
                            <span className={`text-[10px] px-1.5 py-0.5 rounded-full font-medium whitespace-nowrap ${badgeClasses[insight.priority]}`}>
                                {priorityLabels[insight.priority]}
                            </span>
                        )}
                    </div>
                    <p className={`text-xs opacity-75 ${textClasses[insight.type]}`}>{insight.description}</p>
                    {insight.actionLabel && insight.actionHref && (
                        <Link
                            href={insight.actionHref}
                            className={`inline-block text-xs font-medium mt-2 underline underline-offset-2 ${textClasses[insight.type]}`}
                        >
                            {insight.actionLabel} →
                        </Link>
                    )}
                </div>
            </div>
        </div>
    );
}

'use client';

import { TrendingUp, TrendingDown, Minus } from 'lucide-react';
import type { TrendResult } from '../analytics';

interface StatCardProps {
    label: string;
    value: number | string;
    trend?: TrendResult;
    icon: React.ReactNode;
    color?: 'primary' | 'green' | 'yellow' | 'red';
}

export default function StatCard({ label, value, trend, icon, color = 'primary' }: StatCardProps) {
    const colorClasses = {
        primary: 'text-[#0F4C81]',
        green: 'text-green-600',
        yellow: 'text-yellow-600',
        red: 'text-red-600',
    };

    const iconBgClasses = {
        primary: 'bg-[#0F4C81]/10',
        green: 'bg-green-50',
        yellow: 'bg-yellow-50',
        red: 'bg-red-50',
    };

    return (
        <div className="bg-white p-5 rounded-xl shadow-sm border border-gray-100">
            <div className="flex items-center justify-between mb-3">
                <span className="text-gray-500 text-sm font-medium">{label}</span>
                <div className={`w-10 h-10 rounded-lg ${iconBgClasses[color]} flex items-center justify-center ${colorClasses[color]}`}>
                    {icon}
                </div>
            </div>
            <div className="flex items-end gap-3">
                <p className={`text-3xl font-bold ${colorClasses[color]}`}>{value}</p>
                {trend && (
                    <div className={`flex items-center gap-1 text-sm font-medium pb-1 ${trend.direction === 'up' ? 'text-green-600' :
                            trend.direction === 'down' ? 'text-red-600' : 'text-gray-400'
                        }`}>
                        {trend.direction === 'up' && <TrendingUp className="w-4 h-4" />}
                        {trend.direction === 'down' && <TrendingDown className="w-4 h-4" />}
                        {trend.direction === 'stable' && <Minus className="w-4 h-4" />}
                        <span>{trend.percentage}%</span>
                    </div>
                )}
            </div>
        </div>
    );
}

'use client';

import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import type { ChartDataPoint } from '../analytics';

interface TrendChartProps {
    data: ChartDataPoint[];
    title: string;
    color?: string;
}

export default function TrendChart({ data, title, color = '#0F4C81' }: TrendChartProps) {
    return (
        <div className="bg-white p-5 rounded-xl shadow-sm border border-gray-100">
            <h3 className="text-sm font-semibold text-gray-700 mb-4">{title}</h3>
            <div className="h-48">
                <ResponsiveContainer width="100%" height="100%">
                    <LineChart data={data}>
                        <CartesianGrid strokeDasharray="3 3" stroke="#f0f0f0" />
                        <XAxis
                            dataKey="name"
                            tick={{ fontSize: 11, fill: '#6b7280' }}
                            axisLine={{ stroke: '#e5e7eb' }}
                        />
                        <YAxis
                            tick={{ fontSize: 11, fill: '#6b7280' }}
                            axisLine={{ stroke: '#e5e7eb' }}
                        />
                        <Tooltip
                            contentStyle={{
                                borderRadius: '8px',
                                border: '1px solid #e5e7eb',
                                fontSize: '12px'
                            }}
                        />
                        <Line
                            type="monotone"
                            dataKey="value"
                            stroke={color}
                            strokeWidth={2}
                            dot={{ fill: color, strokeWidth: 0, r: 4 }}
                            activeDot={{ r: 6, stroke: color, strokeWidth: 2, fill: '#fff' }}
                        />
                    </LineChart>
                </ResponsiveContainer>
            </div>
        </div>
    );
}

/**
 * Dashboard Service
 * Business logic for dashboard statistics and data
 * 
 * UPDATED: Removed academic tables (assignments, practicalReports)
 * Now only handles inventory and bookings
 */

import { db } from '@/db';
import { items, itemLoans, roomBookings, users, rooms, itemCategories, governanceDocs } from '@/db/schema';
import { eq, and, gte, desc, sql } from 'drizzle-orm';

export class DashboardService {
    /**
     * Get admin dashboard statistics
     */
    static async getAdminStats() {
        const [
            totalItems,
            activeLoans,
            pendingLoans,
            pendingBookings,
            itemStats
        ] = await Promise.all([
            db.select({ count: sql<number>`count(*)` }).from(items),
            db.select({ count: sql<number>`count(*)` }).from(itemLoans).where(eq(itemLoans.status, 'Disetujui')),
            db.select({ count: sql<number>`count(*)` }).from(itemLoans).where(eq(itemLoans.status, 'Pending')),
            db.select({ count: sql<number>`count(*)` }).from(roomBookings).where(eq(roomBookings.status, 'Pending')),
            db.select({
                status: items.status,
                count: sql<number>`count(*)`,
            })
                .from(items)
                .groupBy(items.status),
        ]);

        const recentLoansRaw = await db
            .select({
                loan: itemLoans,
                student: users,
                item: items,
            })
            .from(itemLoans)
            .leftJoin(users, eq(itemLoans.studentId, users.identifier))
            .leftJoin(items, eq(itemLoans.itemId, items.id))
            .orderBy(desc(itemLoans.requestDate))
            .limit(5);

        const recentLoans = recentLoansRaw.map(row => ({
            ...row.loan,
            student: row.student!,
            item: row.item!,
        }));

        const recentBookingsRaw = await db
            .select({
                booking: roomBookings,
                user: users,
                room: rooms,
            })
            .from(roomBookings)
            .leftJoin(users, eq(roomBookings.userId, users.identifier))
            .leftJoin(rooms, eq(roomBookings.roomId, rooms.id))
            .orderBy(desc(roomBookings.startTime))
            .limit(5);

        const recentBookings = recentBookingsRaw.map(row => ({
            ...row.booking,
            user: row.user!,
            room: row.room!,
        }));

        // Auto-approved loans (with surat izin) - for notifications (only unread)
        const autoApprovedLoansRaw = await db
            .select({
                loan: itemLoans,
                student: users,
                item: items,
            })
            .from(itemLoans)
            .leftJoin(users, eq(itemLoans.studentId, users.identifier))
            .leftJoin(items, eq(itemLoans.itemId, items.id))
            .where(and(
                eq(itemLoans.status, 'Disetujui'),
                eq(itemLoans.notificationRead, '0'),
                sql`${itemLoans.suratIzin} IS NOT NULL AND ${itemLoans.suratIzin} != ''`
            ))
            .orderBy(desc(itemLoans.requestDate))
            .limit(10);

        const autoApprovedLoans = autoApprovedLoansRaw.map(row => ({
            ...row.loan,
            student: row.student!,
            item: row.item!,
        }));

        // Auto-approved bookings (with surat permohonan) - for notifications (only unread)
        const autoApprovedBookingsRaw = await db
            .select({
                booking: roomBookings,
                user: users,
                room: rooms,
            })
            .from(roomBookings)
            .leftJoin(users, eq(roomBookings.userId, users.identifier))
            .leftJoin(rooms, eq(roomBookings.roomId, rooms.id))
            .where(and(
                eq(roomBookings.status, 'Disetujui'),
                eq(roomBookings.notificationRead, '0'),
                sql`${roomBookings.suratPermohonan} IS NOT NULL AND ${roomBookings.suratPermohonan} != ''`
            ))
            .orderBy(desc(roomBookings.startTime))
            .limit(10);

        const autoApprovedBookings = autoApprovedBookingsRaw.map(row => ({
            ...row.booking,
            user: row.user!,
            room: row.room!,
        }));

        // Auto-returned loans (with return photo) - for notifications (only unread)
        const autoReturnedLoansRaw = await db
            .select({
                loan: itemLoans,
                student: users,
                item: items,
            })
            .from(itemLoans)
            .leftJoin(users, eq(itemLoans.studentId, users.identifier))
            .leftJoin(items, eq(itemLoans.itemId, items.id))
            .where(and(
                eq(itemLoans.returnStatus, 'Dikembalikan'),
                eq(itemLoans.returnNotificationRead, '0'),
                sql`${itemLoans.returnPhoto} IS NOT NULL AND ${itemLoans.returnPhoto} != ''`
            ))
            .orderBy(desc(itemLoans.actualReturnDate))
            .limit(10);

        const autoReturnedLoans = autoReturnedLoansRaw.map(row => ({
            ...row.loan,
            student: row.student!,
            item: row.item!,
        }));

        // Count pending returns for admin
        const pendingReturns = await db.select({ count: sql<number>`count(*)` })
            .from(itemLoans)
            .where(eq(itemLoans.returnStatus, 'Pending'));

        return {
            totalItems: totalItems[0].count,
            activeLoans: activeLoans[0].count,
            pendingLoans: pendingLoans[0].count,
            pendingBookings: pendingBookings[0].count,
            pendingReturns: pendingReturns[0].count,
            itemStats,
            recentLoans,
            recentBookings,
            autoApprovedLoans,
            autoApprovedBookings,
            autoReturnedLoans,
        };
    }

    /**
     * Get student dashboard data
     */
    static async getStudentDashboard(userId: string) {
        const today = new Date();

        const activeLoansRaw = await db
            .select({
                loan: itemLoans,
                item: items,
                category: itemCategories,
                room: rooms,
            })
            .from(itemLoans)
            .leftJoin(items, eq(itemLoans.itemId, items.id))
            .leftJoin(itemCategories, eq(items.categoryId, itemCategories.id))
            .leftJoin(rooms, eq(items.roomId, rooms.id))
            .where(and(
                eq(itemLoans.studentId, userId),
                eq(itemLoans.status, 'Disetujui')
            ))
            .orderBy(itemLoans.returnPlanDate);

        const activeLoans = activeLoansRaw.map(row => ({
            ...row.loan,
            item: {
                ...row.item!,
                category: row.category!,
                room: row.room!,
            },
        }));

        const upcomingBookingsRaw = await db
            .select({
                booking: roomBookings,
                room: rooms,
            })
            .from(roomBookings)
            .leftJoin(rooms, eq(roomBookings.roomId, rooms.id))
            .where(and(
                eq(roomBookings.userId, userId),
                eq(roomBookings.status, 'Disetujui'),
                gte(roomBookings.startTime, today)
            ))
            .orderBy(roomBookings.startTime)
            .limit(5);

        const upcomingBookings = upcomingBookingsRaw.map(row => ({
            ...row.booking,
            room: row.room!,
        }));

        const pendingRequestsRaw = await db
            .select({
                loan: itemLoans,
                item: items,
            })
            .from(itemLoans)
            .leftJoin(items, eq(itemLoans.itemId, items.id))
            .where(and(
                eq(itemLoans.studentId, userId),
                eq(itemLoans.status, 'Pending')
            ));

        const pendingRequests = pendingRequestsRaw.map(row => ({
            ...row.loan,
            item: row.item!,
        }));

        return {
            activeLoans,
            upcomingBookings,
            pendingRequests,
        };
    }

    /**
     * Get lecturer dashboard data
     * Users with governance.view permission also see latest LPJ documents
     */
    static async getLecturerDashboard(userId: string, showLPJ: boolean = false) {
        const today = new Date();

        const activeLoansRaw = await db
            .select({
                loan: itemLoans,
                item: items,
                category: itemCategories,
                room: rooms,
            })
            .from(itemLoans)
            .leftJoin(items, eq(itemLoans.itemId, items.id))
            .leftJoin(itemCategories, eq(items.categoryId, itemCategories.id))
            .leftJoin(rooms, eq(items.roomId, rooms.id))
            .where(and(
                eq(itemLoans.studentId, userId),
                eq(itemLoans.status, 'Disetujui')
            ))
            .orderBy(itemLoans.returnPlanDate);

        const activeLoans = activeLoansRaw.map(row => ({
            ...row.loan,
            item: {
                ...row.item!,
                category: row.category!,
                room: row.room!,
            },
        }));

        const upcomingBookingsRaw = await db
            .select({
                booking: roomBookings,
                room: rooms,
            })
            .from(roomBookings)
            .leftJoin(rooms, eq(roomBookings.roomId, rooms.id))
            .where(and(
                eq(roomBookings.userId, userId),
                gte(roomBookings.startTime, today)
            ))
            .orderBy(roomBookings.startTime)
            .limit(10);

        const upcomingBookings = upcomingBookingsRaw.map(row => ({
            ...row.booking,
            room: row.room!,
        }));

        const pendingRequestsRaw = await db
            .select({
                loan: itemLoans,
                item: items,
            })
            .from(itemLoans)
            .leftJoin(items, eq(itemLoans.itemId, items.id))
            .where(and(
                eq(itemLoans.studentId, userId),
                eq(itemLoans.status, 'Pending')
            ));

        const pendingRequests = pendingRequestsRaw.map(row => ({
            ...row.loan,
            item: row.item!,
        }));

        // Fetch LPJ documents if user has governance.view permission
        let latestLPJ: { id: number; title: string; filePath: string; coverPath: string | null; createdAt: Date | null; uploaderName: string | null }[] = [];
        if (showLPJ) {
            latestLPJ = await db
                .select({
                    id: governanceDocs.id,
                    title: governanceDocs.title,
                    filePath: governanceDocs.filePath,
                    coverPath: governanceDocs.coverPath,
                    createdAt: governanceDocs.createdAt,
                    uploaderName: users.fullName,
                })
                .from(governanceDocs)
                .leftJoin(users, eq(governanceDocs.adminId, users.identifier))
                .where(eq(governanceDocs.type, 'LPJ Bulanan'))
                .orderBy(desc(governanceDocs.createdAt))
                .limit(5);
        }

        return {
            activeLoans,
            upcomingBookings,
            pendingRequests,
            totalBookings: upcomingBookings.length,
            latestLPJ,
        };
    }

    /**
     * Mark loan notification as read
     */
    static async markLoanNotificationRead(loanId: number) {
        await db.update(itemLoans)
            .set({ notificationRead: '1' })
            .where(eq(itemLoans.id, loanId));
    }

    /**
     * Mark booking notification as read
     */
    static async markBookingNotificationRead(bookingId: number) {
        await db.update(roomBookings)
            .set({ notificationRead: '1' })
            .where(eq(roomBookings.id, bookingId));
    }

    /**
     * Mark all notifications as read (including return notifications)
     */
    static async markAllNotificationsRead() {
        await Promise.all([
            // Auto-approved loan notifications
            db.update(itemLoans)
                .set({ notificationRead: '1' })
                .where(and(
                    eq(itemLoans.status, 'Disetujui'),
                    eq(itemLoans.notificationRead, '0'),
                    sql`${itemLoans.suratIzin} IS NOT NULL AND ${itemLoans.suratIzin} != ''`
                )),
            // Auto-approved booking notifications
            db.update(roomBookings)
                .set({ notificationRead: '1' })
                .where(and(
                    eq(roomBookings.status, 'Disetujui'),
                    eq(roomBookings.notificationRead, '0'),
                    sql`${roomBookings.suratPermohonan} IS NOT NULL AND ${roomBookings.suratPermohonan} != ''`
                )),
            // Auto-returned loan notifications
            db.update(itemLoans)
                .set({ returnNotificationRead: '1' })
                .where(and(
                    eq(itemLoans.returnStatus, 'Dikembalikan'),
                    eq(itemLoans.returnNotificationRead, '0'),
                    sql`${itemLoans.returnPhoto} IS NOT NULL AND ${itemLoans.returnPhoto} != ''`
                ))
        ]);
    }

    /**
     * Get loan trend data for last 7 days
     */
    static async getLoanTrendData() {
        const days = 7;
        const data: { date: string; count: number }[] = [];

        for (let i = days - 1; i >= 0; i--) {
            const date = new Date();
            date.setDate(date.getDate() - i);
            date.setHours(0, 0, 0, 0);

            const nextDate = new Date(date);
            nextDate.setDate(nextDate.getDate() + 1);

            const result = await db
                .select({ count: sql<number>`count(*)` })
                .from(itemLoans)
                .where(and(
                    gte(itemLoans.requestDate, date),
                    sql`${itemLoans.requestDate} < ${nextDate}`
                ));

            data.push({
                date: date.toISOString(),
                count: result[0]?.count || 0
            });
        }

        return data;
    }

    /**
     * Get bookings by room for chart
     */
    static async getBookingsByRoom() {
        const result = await db
            .select({
                name: rooms.name,
                count: sql<number>`count(*)`,
            })
            .from(roomBookings)
            .leftJoin(rooms, eq(roomBookings.roomId, rooms.id))
            .groupBy(rooms.name)
            .orderBy(sql`count(*) DESC`)
            .limit(5);

        return result.map(r => ({
            name: r.name || 'Unknown',
            value: r.count
        }));
    }

    /**
     * Get loans by category for chart
     */
    static async getLoansByCategory() {
        const result = await db
            .select({
                name: itemCategories.name,
                count: sql<number>`count(*)`,
            })
            .from(itemLoans)
            .leftJoin(items, eq(itemLoans.itemId, items.id))
            .leftJoin(itemCategories, eq(items.categoryId, itemCategories.id))
            .groupBy(itemCategories.name)
            .orderBy(sql`count(*) DESC`)
            .limit(5);

        return result.map(r => ({
            name: r.name || 'Unknown',
            value: r.count
        }));
    }

    /**
     * Get idle items (not borrowed for 60+ days)
     */
    static async getIdleItemsCount() {
        const sixtyDaysAgo = new Date();
        sixtyDaysAgo.setDate(sixtyDaysAgo.getDate() - 60);

        const result = await db
            .select({ count: sql<number>`count(*)` })
            .from(items)
            .where(and(
                eq(items.status, 'Tersedia'),
                sql`${items.id} NOT IN (
                    SELECT DISTINCT item_id FROM item_loans 
                    WHERE request_date >= ${sixtyDaysAgo}
                )`
            ));

        return result[0]?.count || 0;
    }

    /**
     * Get all pending counts for insights
     */
    static async getPendingCounts() {
        const [pendingLoans, pendingBookings, pendingUsers] = await Promise.all([
            db.select({ count: sql<number>`count(*)` }).from(itemLoans).where(eq(itemLoans.status, 'Pending')),
            db.select({ count: sql<number>`count(*)` }).from(roomBookings).where(eq(roomBookings.status, 'Pending')),
            db.select({ count: sql<number>`count(*)` }).from(users).where(eq(users.status, 'Pending')),
        ]);

        return {
            pendingLoans: pendingLoans[0]?.count || 0,
            pendingBookings: pendingBookings[0]?.count || 0,
            pendingUsers: pendingUsers[0]?.count || 0,
            pendingPublications: 0
        };
    }

    /**
     * Get recent bookings for peak hour detection
     */
    static async getRecentBookings(days: number = 30) {
        const startDate = new Date();
        startDate.setDate(startDate.getDate() - days);

        const result = await db
            .select({ startTime: roomBookings.startTime })
            .from(roomBookings)
            .where(gte(roomBookings.startTime, startDate));

        return result;
    }

    /**
     * Get overdue loans (past return plan date but still active)
     */
    static async getOverdueLoans() {
        const now = new Date();
        const result = await db
            .select({
                id: itemLoans.id,
                studentName: users.fullName,
                itemName: items.name,
                returnPlanDate: itemLoans.returnPlanDate,
            })
            .from(itemLoans)
            .leftJoin(users, eq(itemLoans.studentId, users.identifier))
            .leftJoin(items, eq(itemLoans.itemId, items.id))
            .where(and(
                eq(itemLoans.status, 'Disetujui'),
                sql`${itemLoans.returnPlanDate} < ${now}`
            ));
        return result;
    }

    /**
     * Get loans with return deadlines in the next N days
     */
    static async getUpcomingDeadlines(days: number = 3) {
        const now = new Date();
        const deadline = new Date();
        deadline.setDate(deadline.getDate() + days);
        const result = await db
            .select({ count: sql<number>`count(*)` })
            .from(itemLoans)
            .where(and(
                eq(itemLoans.status, 'Disetujui'),
                gte(itemLoans.returnPlanDate, now),
                sql`${itemLoans.returnPlanDate} <= ${deadline}`
            ));
        return result[0]?.count || 0;
    }

    /**
     * Get booking stats grouped by day of week (0=Sun..6=Sat)
     */
    static async getDayOfWeekStats() {
        const thirtyDaysAgo = new Date();
        thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);
        const result = await db
            .select({
                dayOfWeek: sql<number>`DAYOFWEEK(${roomBookings.startTime})`,
                count: sql<number>`count(*)`,
            })
            .from(roomBookings)
            .where(gte(roomBookings.startTime, thirtyDaysAgo))
            .groupBy(sql`DAYOFWEEK(${roomBookings.startTime})`);
        return result;
    }

    /**
     * Get room utilization: total bookings per room + item availability %
     */
    static async getRoomUtilization() {
        const [totalItems, unavailableItems, totalRooms, bookingCounts] = await Promise.all([
            db.select({ count: sql<number>`count(*)` }).from(items),
            db.select({ count: sql<number>`count(*)` }).from(items).where(
                sql`${items.status} != 'Tersedia'`
            ),
            db.select({ count: sql<number>`count(*)` }).from(rooms),
            db.select({
                roomName: rooms.name,
                count: sql<number>`count(*)`,
            })
                .from(roomBookings)
                .leftJoin(rooms, eq(roomBookings.roomId, rooms.id))
                .where(eq(roomBookings.status, 'Disetujui'))
                .groupBy(rooms.name)
                .orderBy(sql`count(*) DESC`)
                .limit(5),
        ]);

        const total = totalItems[0]?.count || 1;
        const unavail = unavailableItems[0]?.count || 0;

        return {
            itemAvailabilityRate: Math.round(((total - unavail) / total) * 100),
            unavailableItems: unavail,
            totalItems: total,
            totalRooms: totalRooms[0]?.count || 0,
            topRooms: bookingCounts,
        };
    }

    /**
     * Get loan trend data for last 14 days (extended for comparison)
     */
    static async getLoanTrend14Days() {
        const days = 14;
        const data: { date: string; count: number }[] = [];
        for (let i = days - 1; i >= 0; i--) {
            const date = new Date();
            date.setDate(date.getDate() - i);
            date.setHours(0, 0, 0, 0);
            const nextDate = new Date(date);
            nextDate.setDate(nextDate.getDate() + 1);
            const result = await db
                .select({ count: sql<number>`count(*)` })
                .from(itemLoans)
                .where(and(
                    gte(itemLoans.requestDate, date),
                    sql`${itemLoans.requestDate} < ${nextDate}`
                ));
            data.push({ date: date.toISOString(), count: result[0]?.count || 0 });
        }
        return data;
    }

    /**
     * Aggregate all smart analytics data in one call
     */
    static async getSmartAnalyticsData() {
        const [
            overdueLoans,
            upcomingDeadlines,
            dayOfWeekStats,
            roomUtilization,
            trendData14,
            idleItems,
            pendingCounts,
            recentBookings,
        ] = await Promise.all([
            this.getOverdueLoans(),
            this.getUpcomingDeadlines(3),
            this.getDayOfWeekStats(),
            this.getRoomUtilization(),
            this.getLoanTrend14Days(),
            this.getIdleItemsCount(),
            this.getPendingCounts(),
            this.getRecentBookings(30),
        ]);

        return {
            overdueLoans,
            upcomingDeadlines,
            dayOfWeekStats,
            roomUtilization,
            trendData14,
            idleItems,
            pendingCounts,
            recentBookings,
        };
    }
}

'use server';

import { db } from '@/db';
import { governanceDocs, users } from '@/db/schema';
import { eq, desc } from 'drizzle-orm';
import { requirePermission } from '@/lib/auth';
import { revalidatePath } from 'next/cache';
import { mkdir, unlink, writeFile } from 'fs/promises';
import { join } from 'path';

const MAX_FILE_SIZE = 10 * 1024 * 1024; // 10MB
const DOWNLOAD_CENTER_TYPE = 'Pusat Download' as const;

export async function getDownloadCenterDocs() {
    const docs = await db
        .select({
            id: governanceDocs.id,
            title: governanceDocs.title,
            filePath: governanceDocs.filePath,
            createdAt: governanceDocs.createdAt,
            uploaderName: users.fullName,
        })
        .from(governanceDocs)
        .leftJoin(users, eq(governanceDocs.adminId, users.identifier))
        .where(eq(governanceDocs.type, DOWNLOAD_CENTER_TYPE))
        .orderBy(desc(governanceDocs.createdAt));

    return docs;
}

export async function uploadDownloadCenterDoc(formData: FormData) {
    try {
        await requirePermission('download-center.manage');

        const file = formData.get('file') as File;
        const title = (formData.get('title') as string)?.trim();
        const adminId = formData.get('adminId') as string;

        if (!file || file.size === 0) {
            return { success: false, error: 'Tidak ada file yang diunggah' };
        }

        if (!title) {
            return { success: false, error: 'Judul dokumen wajib diisi' };
        }

        if (file.size > MAX_FILE_SIZE) {
            return { success: false, error: 'Ukuran file maksimal 10MB' };
        }

        const uploadDir = join(process.cwd(), 'public', 'uploads', 'download-center');
        await mkdir(uploadDir, { recursive: true });

        const uniqueSuffix = `${Date.now()}-${Math.round(Math.random() * 1e9)}`;
        const filename = `${uniqueSuffix}-${file.name.replace(/[^a-zA-Z0-9.-]/g, '_')}`;
        const filePath = join(uploadDir, filename);

        const bytes = await file.arrayBuffer();
        await writeFile(filePath, Buffer.from(bytes));

        await db.insert(governanceDocs).values({
            adminId,
            title,
            filePath: `/uploads/download-center/${filename}`,
            type: DOWNLOAD_CENTER_TYPE,
            coverPath: null,
        });

        revalidatePath('/admin/download-center');
        revalidatePath('/lecturer/download-center');
        revalidatePath('/student/download-center');

        return { success: true };
    } catch (error: any) {
        return { success: false, error: error.message || 'Gagal upload dokumen pusat download' };
    }
}

export async function deleteDownloadCenterDoc(id: number) {
    try {
        await requirePermission('download-center.manage');

        const existing = await db.select().from(governanceDocs).where(eq(governanceDocs.id, id)).limit(1);
        const doc = existing[0];

        if (doc?.filePath && doc.filePath.startsWith('/uploads/download-center/')) {
            const relativePath = doc.filePath.replace('/uploads/', '');
            const absolutePath = join(process.cwd(), 'public', relativePath);
            try {
                await unlink(absolutePath);
            } catch {
                // ignore if file already removed
            }
        }

        await db.delete(governanceDocs).where(eq(governanceDocs.id, id));

        revalidatePath('/admin/download-center');
        revalidatePath('/lecturer/download-center');
        revalidatePath('/student/download-center');

        return { success: true };
    } catch (error: any) {
        return { success: false, error: error.message || 'Gagal menghapus dokumen pusat download' };
    }
}

'use client';

import { useState, useTransition } from 'react';
import { Download, Upload, Trash2, FileText } from 'lucide-react';
import { deleteDownloadCenterDoc, uploadDownloadCenterDoc } from '@/features/download-center/actions';

interface DownloadDoc {
    id: number;
    title: string;
    filePath: string;
    createdAt: Date | null;
    uploaderName: string | null;
}

interface Props {
    docs: DownloadDoc[];
    adminId: string;
    canManage: boolean;
}

function formatDate(date: Date | null) {
    if (!date) return '-';
    return new Date(date).toLocaleDateString('id-ID', {
        day: '2-digit',
        month: 'short',
        year: 'numeric',
    });
}

export default function DownloadCenterManager({ docs, adminId, canManage }: Props) {
    const [isPending, startTransition] = useTransition();
    const [message, setMessage] = useState<{ type: 'success' | 'error'; text: string } | null>(null);

    const handleUpload = (formData: FormData) => {
        startTransition(async () => {
            const result = await uploadDownloadCenterDoc(formData);
            if (result.success) {
                setMessage({ type: 'success', text: 'Dokumen berhasil diupload' });
            } else {
                setMessage({ type: 'error', text: result.error || 'Upload gagal' });
            }
        });
    };

    const handleDelete = (id: number) => {
        if (!confirm('Hapus dokumen ini dari Pusat Download?')) return;
        startTransition(async () => {
            const result = await deleteDownloadCenterDoc(id);
            if (result.success) {
                setMessage({ type: 'success', text: 'Dokumen berhasil dihapus' });
            } else {
                setMessage({ type: 'error', text: result.error || 'Hapus gagal' });
            }
        });
    };

    return (
        <div className="space-y-6">
            {message && (
                <div className={`p-3 rounded-lg text-sm ${message.type === 'success' ? 'bg-green-50 text-green-700' : 'bg-red-50 text-red-700'}`}>
                    {message.text}
                </div>
            )}

            {canManage && (
                <form action={handleUpload} className="bg-white border border-gray-200 rounded-xl p-5 space-y-4">
                    <h2 className="text-base font-semibold text-gray-900 flex items-center gap-2">
                        <Upload className="w-4 h-4" />
                        Upload Dokumen
                    </h2>
                    <input type="hidden" name="adminId" value={adminId} />
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                        <input
                            name="title"
                            type="text"
                            placeholder="Judul dokumen"
                            required
                            className="px-3 py-2 border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-[#0F4C81]/20"
                        />
                        <input
                            name="file"
                            type="file"
                            required
                            className="px-3 py-2 border border-gray-200 rounded-lg text-sm"
                        />
                    </div>
                    <div className="text-xs text-gray-500">Maksimal ukuran file 10MB.</div>
                    <button
                        type="submit"
                        disabled={isPending}
                        className="inline-flex items-center gap-2 px-4 py-2 bg-[#0F4C81] text-white rounded-lg text-sm font-medium hover:bg-[#0D3F6B] disabled:opacity-50"
                    >
                        <Upload className="w-4 h-4" />
                        {isPending ? 'Memproses...' : 'Upload ke Pusat Download'}
                    </button>
                </form>
            )}

            <div className="bg-white border border-gray-200 rounded-xl overflow-hidden">
                <div className="px-5 py-4 border-b border-gray-100">
                    <h2 className="text-base font-semibold text-gray-900">Daftar Dokumen</h2>
                </div>

                {docs.length === 0 ? (
                    <div className="p-10 text-center text-gray-500 text-sm">Belum ada dokumen di Pusat Download.</div>
                ) : (
                    <div className="divide-y divide-gray-100">
                        {docs.map((doc) => (
                            <div key={doc.id} className="px-5 py-4 flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3">
                                <div className="min-w-0">
                                    <p className="text-sm font-semibold text-gray-900 break-words flex items-center gap-2">
                                        <FileText className="w-4 h-4 text-gray-500" />
                                        {doc.title}
                                    </p>
                                    <p className="text-xs text-gray-500 mt-1">
                                        Upload: {formatDate(doc.createdAt)}
                                        {doc.uploaderName ? ` • Oleh ${doc.uploaderName}` : ''}
                                    </p>
                                </div>
                                <div className="flex items-center gap-2">
                                    <a
                                        href={doc.filePath}
                                        target="_blank"
                                        rel="noopener noreferrer"
                                        className="inline-flex items-center gap-1.5 px-3 py-2 rounded-lg text-sm bg-gray-100 hover:bg-gray-200 text-gray-800"
                                    >
                                        <Download className="w-4 h-4" />
                                        Download
                                    </a>
                                    {canManage && (
                                        <button
                                            onClick={() => handleDelete(doc.id)}
                                            className="inline-flex items-center gap-1.5 px-3 py-2 rounded-lg text-sm bg-red-50 hover:bg-red-100 text-red-700"
                                        >
                                            <Trash2 className="w-4 h-4" />
                                            Hapus
                                        </button>
                                    )}
                                </div>
                            </div>
                        ))}
                    </div>
                )}
            </div>
        </div>
    );
}

'use server';

import { db } from '@/db';
import { governanceDocs, users } from '@/db/schema';
import { eq, desc, inArray } from 'drizzle-orm';
import { revalidatePath } from 'next/cache';
import { writeFile } from 'fs/promises';
import { join } from 'path';
import { mkdir } from 'fs/promises';
import { requirePermission } from '@/lib/auth';
import { deleteFile } from '@/lib/upload';

const MAX_FILE_SIZE = 2 * 1024 * 1024; // 2MB

export async function getGovernanceDocs(type: string) {
    const docs = await db
        .select({
            id: governanceDocs.id,
            title: governanceDocs.title,
            filePath: governanceDocs.filePath,
            coverPath: governanceDocs.coverPath,
            type: governanceDocs.type,
            createdAt: governanceDocs.createdAt,
            uploaderName: users.fullName,
        })
        .from(governanceDocs)
        .leftJoin(users, eq(governanceDocs.adminId, users.identifier))
        .where(eq(governanceDocs.type, type as any))
        .orderBy(desc(governanceDocs.createdAt));

    return docs;
}

export async function getAllGovernanceDocsForDownload() {
    return await db
        .select({
            id: governanceDocs.id,
            title: governanceDocs.title,
            filePath: governanceDocs.filePath,
            coverPath: governanceDocs.coverPath,
            type: governanceDocs.type,
            createdAt: governanceDocs.createdAt,
            uploaderName: users.fullName,
        })
        .from(governanceDocs)
        .leftJoin(users, eq(governanceDocs.adminId, users.identifier))
        .where(inArray(governanceDocs.type, ['SOP', 'LPJ Bulanan', 'Template Surat']))
        .orderBy(desc(governanceDocs.createdAt));
}

export async function uploadGovernanceDoc(formData: FormData) {
    try {
        await requirePermission('governance.manage');
        const file = formData.get('file') as File;
        const coverFile = formData.get('cover') as File | null;
        const title = formData.get('title') as string;
        const type = formData.get('type') as 'SOP' | 'LPJ Bulanan' | 'Template Surat';
        const adminId = formData.get('adminId') as string;

        if (!file || file.size === 0) {
            return { success: false, error: 'Tidak ada file yang diunggah' };
        }

        if (file.size > MAX_FILE_SIZE) {
            return { success: false, error: 'Ukuran file dokumen maksimal 2MB' };
        }

        if (coverFile && coverFile.size > MAX_FILE_SIZE) {
            return { success: false, error: 'Ukuran file cover maksimal 2MB' };
        }

        const bytes = await file.arrayBuffer();
        const buffer = Buffer.from(bytes);

        const uploadDir = join(process.cwd(), 'public', 'uploads', 'governance');
        await mkdir(uploadDir, { recursive: true });

        const uniqueSuffix = `${Date.now()}-${Math.round(Math.random() * 1E9)}`;
        const filename = `${uniqueSuffix}-${file.name.replace(/[^a-zA-Z0-9.-]/g, '_')}`;
        const filePath = join(uploadDir, filename);

        await writeFile(filePath, buffer);

        // Handle Cover Image
        let coverPath = null;
        if (coverFile && coverFile.size > 0) {
            const coverBytes = await coverFile.arrayBuffer();
            const coverBuffer = Buffer.from(coverBytes);
            const coverFilename = `cover-${uniqueSuffix}-${coverFile.name.replace(/[^a-zA-Z0-9.-]/g, '_')}`;
            const coverFilePath = join(uploadDir, coverFilename);
            await writeFile(coverFilePath, coverBuffer);
            coverPath = `/uploads/governance/${coverFilename}`;
        }

        await db.insert(governanceDocs).values({
            adminId,
            title,
            filePath: `/uploads/governance/${filename}`,
            coverPath,
            type,
        });

        revalidatePath('/admin/governance');
        revalidatePath('/student/manage/governance');
        revalidatePath('/lecturer/manage/governance');
        revalidatePath('/');
        return { success: true };
    } catch (error: any) {
        return { success: false, error: error.message || 'Gagal mengupload dokumen tata kelola' };
    }
}

export async function updateGovernanceDoc(id: number, formData: FormData) {
    try {
        await requirePermission('governance.manage');
        const file = formData.get('file') as File | null;
        const coverFile = formData.get('cover') as File | null;
        const title = formData.get('title') as string;
        const type = formData.get('type') as 'SOP' | 'LPJ Bulanan' | 'Template Surat' | 'Video Profil';

        // Fetch old record to delete old files when replaced
        const oldDoc = await db.select().from(governanceDocs).where(eq(governanceDocs.id, id)).limit(1);

        const updateData: any = {
            title,
            type,
        };

        const uploadDir = join(process.cwd(), 'public', 'uploads', 'governance');
        await mkdir(uploadDir, { recursive: true });
        const uniqueSuffix = `${Date.now()}-${Math.round(Math.random() * 1E9)}`;

        if (file && file.size > 0) {
            if (file.size > MAX_FILE_SIZE) {
                return { success: false, error: 'Ukuran file dokumen maksimal 2MB' };
            }
            // Delete old file from disk
            if (oldDoc[0]?.filePath) {
                await deleteFile(oldDoc[0].filePath);
            }
            const bytes = await file.arrayBuffer();
            const buffer = Buffer.from(bytes);
            const filename = `${uniqueSuffix}-${file.name.replace(/[^a-zA-Z0-9.-]/g, '_')}`;
            const filePath = join(uploadDir, filename);
            await writeFile(filePath, buffer);
            updateData.filePath = `/uploads/governance/${filename}`;
        }

        if (coverFile && coverFile.size > 0) {
            if (coverFile.size > MAX_FILE_SIZE) {
                return { success: false, error: 'Ukuran file cover maksimal 2MB' };
            }
            // Delete old cover from disk
            if (oldDoc[0]?.coverPath) {
                await deleteFile(oldDoc[0].coverPath);
            }
            const coverBytes = await coverFile.arrayBuffer();
            const coverBuffer = Buffer.from(coverBytes);
            const coverFilename = `cover-${uniqueSuffix}-${coverFile.name.replace(/[^a-zA-Z0-9.-]/g, '_')}`;
            const coverFilePath = join(uploadDir, coverFilename);
            await writeFile(coverFilePath, coverBuffer);
            updateData.coverPath = `/uploads/governance/${coverFilename}`;
        }

        await db.update(governanceDocs)
            .set(updateData)
            .where(eq(governanceDocs.id, id));

        revalidatePath('/admin/governance');
        revalidatePath('/student/manage/governance');
        revalidatePath('/lecturer/manage/governance');
        revalidatePath('/');
        return { success: true };
    } catch (error: any) {
        return { success: false, error: error.message || 'Gagal memperbarui dokumen tata kelola' };
    }
}

export async function deleteGovernanceDoc(id: number) {
    try {
        await requirePermission('governance.manage');

        // Fetch record to get file paths before deleting
        const doc = await db.select().from(governanceDocs).where(eq(governanceDocs.id, id)).limit(1);
        if (doc[0]?.filePath) {
            await deleteFile(doc[0].filePath);
        }
        if (doc[0]?.coverPath) {
            await deleteFile(doc[0].coverPath);
        }

        await db.delete(governanceDocs).where(eq(governanceDocs.id, id));
        revalidatePath('/admin/governance');
        revalidatePath('/student/manage/governance');
        revalidatePath('/lecturer/manage/governance');
        revalidatePath('/');
        return { success: true };
    } catch (error: any) {
        return { success: false, error: error.message || 'Gagal menghapus dokumen' };
    }
}

'use client';

import { useState } from 'react';
import { Upload, FileSpreadsheet, AlertCircle, CheckCircle, X } from 'lucide-react';
import { bulkEnrollUsers, parseCSV, getRoleByName, BulkEnrollmentInput } from '@/features/users/enrollment';

interface BulkEnrollmentProps {
    onSuccess?: () => void;
}

export default function BulkEnrollment({ onSuccess }: BulkEnrollmentProps) {
    const [isLoading, setIsLoading] = useState(false);
    const [preview, setPreview] = useState<BulkEnrollmentInput[]>([]);
    const [roleId, setRoleId] = useState<number | null>(null);
    const [result, setResult] = useState<{ success: number; failed: number; errors: { identifier: string; error: string }[] } | null>(null);
    const [error, setError] = useState<string | null>(null);

    const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;

        setError(null);
        setResult(null);

        // Get Mahasiswa role
        const role = await getRoleByName('Mahasiswa');
        if (!role) {
            setError('Role Mahasiswa tidak ditemukan');
            return;
        }
        setRoleId(role.id);

        const reader = new FileReader();
        reader.onload = async (event) => {
            const csvString = event.target?.result as string;
            try {
                const data = await parseCSV(csvString, role.id);
                if (data.length === 0) {
                    setError('Tidak ada data valid dalam file. Pastikan format CSV benar.');
                    return;
                }
                setPreview(data);
            } catch (err) {
                setError('Gagal membaca file. Pastikan format CSV benar.');
            }
        };
        reader.readAsText(file);
    };

    const handleSubmit = async () => {
        if (preview.length === 0) return;

        setIsLoading(true);
        setError(null);

        try {
            const res = await bulkEnrollUsers(preview);
            setResult(res);
            if (res.success > 0 && onSuccess) {
                onSuccess();
            }
        } catch (err: any) {
            setError(err.message || 'Terjadi kesalahan saat menyimpan data');
        } finally {
            setIsLoading(false);
        }
    };

    const handleClear = () => {
        setPreview([]);
        setResult(null);
        setError(null);
        const input = document.getElementById('csv-upload') as HTMLInputElement;
        if (input) input.value = '';
    };

    return (
        <div className="bg-white p-4 md:p-6 rounded-xl shadow-sm border border-gray-100 mb-8">
            <h2 className="text-lg font-semibold mb-4 flex items-center gap-2">
                <Upload className="w-5 h-5 text-primary" />
                Bulk Enrollment (Pre-registrasi)
            </h2>

            <div className="mb-4 p-3 sm:p-4 bg-blue-50 rounded-lg text-sm text-blue-700 overflow-hidden">
                <p className="font-medium mb-1">Petunjuk:</p>
                <p className="break-words">Upload file CSV dengan format:</p>
                <code className="block mt-1 bg-blue-100 px-2 py-1 rounded text-xs break-all whitespace-normal">fullName,identifier,batch,studyType,programStudi,dosenPembimbing</code>
                <p className="mt-1 text-xs">Baris pertama akan diabaikan (header). User akan berstatus &quot;Pre-registered&quot; dan perlu daftar akun untuk mengaktifkan.</p>
                <p className="mt-1 text-xs text-blue-600"><strong>Tip:</strong> Jika nilai mengandung koma (misal: &quot;Dr. Budi, M.Kom&quot;), bungkus dengan tanda kutip ganda.</p>
            </div>

            {/* File Upload */}
            <div className="mb-4">
                <label className="block text-sm font-medium text-gray-700 mb-2">Upload CSV</label>
                <input
                    id="csv-upload"
                    type="file"
                    accept=".csv"
                    onChange={handleFileChange}
                    className="block w-full text-sm text-gray-500 file:mr-4 file:py-2 file:px-4 file:rounded-lg file:border-0 file:text-sm file:font-semibold file:bg-primary/10 file:text-primary hover:file:bg-primary/20 cursor-pointer"
                />
            </div>

            {/* Error Display */}
            {error && (
                <div className="mb-4 p-3 bg-red-50 text-red-600 rounded-lg flex items-center gap-2 text-sm">
                    <AlertCircle className="w-4 h-4" />
                    {error}
                </div>
            )}

            {/* Result Display */}
            {result && (
                <div className={`mb-4 p-3 rounded-lg text-sm ${result.failed === 0 ? 'bg-green-50 text-green-700' : 'bg-yellow-50 text-yellow-700'}`}>
                    <div className="flex items-center gap-2 mb-2">
                        <CheckCircle className="w-4 h-4" />
                        <span className="font-medium">Hasil: {result.success} berhasil, {result.failed} gagal</span>
                    </div>
                    {result.errors.length > 0 && (
                        <ul className="text-xs list-disc pl-5">
                            {result.errors.slice(0, 5).map((err, i) => (
                                <li key={i}>{err.identifier}: {err.error}</li>
                            ))}
                            {result.errors.length > 5 && <li>...dan {result.errors.length - 5} lainnya</li>}
                        </ul>
                    )}
                </div>
            )}

            {/* Preview Table */}
            {preview.length > 0 && !result && (
                <div className="mb-4">
                    <div className="flex items-center justify-between mb-2">
                        <h3 className="text-sm font-medium text-gray-700">Preview ({preview.length} data)</h3>
                        <button onClick={handleClear} className="text-xs text-gray-500 hover:text-gray-700 flex items-center gap-1">
                            <X className="w-3 h-3" /> Clear
                        </button>
                    </div>
                    <div className="max-h-60 overflow-x-auto overflow-y-auto border rounded-lg">
                        <table className="w-full text-xs">
                            <thead className="bg-gray-50 sticky top-0">
                                <tr>
                                    <th className="px-3 py-2 text-left">Nama</th>
                                    <th className="px-3 py-2 text-left">NIM</th>
                                    <th className="px-3 py-2 text-left">Angkatan</th>
                                    <th className="px-3 py-2 text-left">Tipe</th>
                                    <th className="px-3 py-2 text-left">Prodi</th>
                                    <th className="px-3 py-2 text-left">Pembimbing</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y">
                                {preview.slice(0, 10).map((row, i) => (
                                    <tr key={i} className="hover:bg-gray-50">
                                        <td className="px-3 py-2">{row.fullName}</td>
                                        <td className="px-3 py-2">{row.identifier}</td>
                                        <td className="px-3 py-2">{row.batch || '-'}</td>
                                        <td className="px-3 py-2">{row.studyType || 'Reguler'}</td>
                                        <td className="px-3 py-2">{row.programStudi || 'Informatika'}</td>
                                        <td className="px-3 py-2">{row.dosenPembimbing || '-'}</td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                        {preview.length > 10 && (
                            <div className="text-xs text-center py-2 text-gray-500 bg-gray-50">
                                ...dan {preview.length - 10} data lainnya
                            </div>
                        )}
                    </div>
                </div>
            )}

            {/* Submit Button */}
            {preview.length > 0 && !result && (
                <button
                    onClick={handleSubmit}
                    disabled={isLoading}
                    className="bg-[#0F4C81] text-white px-4 py-2 rounded-lg text-sm font-medium hover:bg-[#0F4C81]/90 transition-colors disabled:opacity-50 flex items-center gap-2"
                >
                    <FileSpreadsheet className="w-4 h-4" />
                    {isLoading ? 'Menyimpan...' : `Simpan ${preview.length} Data`}
                </button>
            )}

            {/* Reset after success */}
            {result && (
                <button
                    onClick={handleClear}
                    className="bg-gray-100 text-gray-700 px-4 py-2 rounded-lg text-sm font-medium hover:bg-gray-200 transition-colors"
                >
                    Upload File Baru
                </button>
            )}
        </div>
    );
}

'use client';

import { useState } from 'react';
import { Download, Users, Package, Calendar, Loader2 } from 'lucide-react';
import { exportAttendanceData, exportLoanData, exportBookingData } from '@/features/governance/export-actions';

export default function DataExport() {
    const [isLoading, setIsLoading] = useState<string | null>(null);
    const [startDate, setStartDate] = useState(() => {
        // Default: first day of current month
        const now = new Date();
        return `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-01`;
    });
    const [endDate, setEndDate] = useState(() => {
        // Default: today
        return new Date().toISOString().split('T')[0];
    });
    const [result, setResult] = useState<{ type: string; count: number } | null>(null);

    const downloadCSV = (csv: string, filename: string) => {
        const blob = new Blob(['\ufeff' + csv], { type: 'text/csv;charset=utf-8;' }); // BOM for Excel
        const url = URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = url;
        link.download = filename;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        URL.revokeObjectURL(url);
    };

    const handleExport = async (type: 'attendance' | 'loans' | 'bookings') => {
        setIsLoading(type);
        setResult(null);

        try {
            const filters = { startDate, endDate };
            let data;
            let filename;

            switch (type) {
                case 'attendance':
                    data = await exportAttendanceData(filters);
                    filename = `kehadiran_${startDate}_${endDate}.csv`;
                    break;
                case 'loans':
                    data = await exportLoanData(filters);
                    filename = `peminjaman_${startDate}_${endDate}.csv`;
                    break;
                case 'bookings':
                    data = await exportBookingData(filters);
                    filename = `booking_ruangan_${startDate}_${endDate}.csv`;
                    break;
            }

            if (data.count > 0) {
                downloadCSV(data.csv, filename);
                setResult({ type, count: data.count });
            } else {
                setResult({ type, count: 0 });
            }
        } catch (error) {
            console.error('Export error:', error);
            alert('Gagal mengekspor data');
        } finally {
            setIsLoading(null);
        }
    };

    const exportItems = [
        {
            id: 'attendance',
            title: 'Data Kehadiran',
            description: 'Export data presensi/absensi pengguna laboratorium',
            icon: Users,
            color: 'text-blue-600',
            bgColor: 'bg-blue-50',
        },
        {
            id: 'loans',
            title: 'Data Peminjaman Alat',
            description: 'Export data peminjaman alat dan inventaris',
            icon: Package,
            color: 'text-green-600',
            bgColor: 'bg-green-50',
        },
        {
            id: 'bookings',
            title: 'Data Booking Ruangan',
            description: 'Export data reservasi ruangan laboratorium',
            icon: Calendar,
            color: 'text-purple-600',
            bgColor: 'bg-purple-50',
        },
    ];

    return (
        <div className="bg-white p-4 md:p-6 rounded-xl shadow-sm border border-gray-100 mt-8">
            <h2 className="text-lg font-semibold mb-4 flex items-center gap-2">
                <Download className="w-5 h-5 text-primary" />
                Export Laporan
            </h2>

            <div className="mb-6 p-4 bg-gray-50 rounded-lg">
                <p className="text-sm font-medium text-gray-700 mb-3">Filter Periode</p>
                <div className="flex flex-col sm:flex-row gap-4 items-start sm:items-center">
                    <div className="flex items-center gap-2">
                        <label className="text-sm text-gray-600">Dari:</label>
                        <input
                            type="date"
                            value={startDate}
                            onChange={(e) => setStartDate(e.target.value)}
                            className="px-3 py-2 border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-primary/20"
                        />
                    </div>
                    <div className="flex items-center gap-2">
                        <label className="text-sm text-gray-600">Sampai:</label>
                        <input
                            type="date"
                            value={endDate}
                            onChange={(e) => setEndDate(e.target.value)}
                            className="px-3 py-2 border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-primary/20"
                        />
                    </div>
                </div>
            </div>

            {result && (
                <div className={`mb-4 p-3 rounded-lg text-sm ${result.count > 0 ? 'bg-green-50 text-green-700' : 'bg-yellow-50 text-yellow-700'}`}>
                    {result.count > 0
                        ? `✅ Berhasil mengekspor ${result.count} data ${result.type === 'attendance' ? 'kehadiran' : result.type === 'loans' ? 'peminjaman' : 'booking'}`
                        : `⚠️ Tidak ada data ${result.type === 'attendance' ? 'kehadiran' : result.type === 'loans' ? 'peminjaman' : 'booking'} pada periode yang dipilih`
                    }
                </div>
            )}

            <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                {exportItems.map((item) => (
                    <div
                        key={item.id}
                        className={`p-4 rounded-xl border border-gray-100 ${item.bgColor} hover:shadow-md transition-shadow`}
                    >
                        <div className="flex items-start gap-3 mb-3">
                            <div className={`p-2 rounded-lg bg-white shadow-sm`}>
                                <item.icon className={`w-5 h-5 ${item.color}`} />
                            </div>
                            <div className="flex-1">
                                <h3 className="font-medium text-gray-900">{item.title}</h3>
                                <p className="text-xs text-gray-500 mt-0.5">{item.description}</p>
                            </div>
                        </div>
                        <button
                            onClick={() => handleExport(item.id as 'attendance' | 'loans' | 'bookings')}
                            disabled={isLoading !== null}
                            className={`w-full flex items-center justify-center gap-2 px-4 py-2.5 rounded-lg text-sm font-medium transition-all ${isLoading === item.id
                                    ? 'bg-gray-300 text-gray-500'
                                    : 'bg-[#0F4C81] text-white hover:bg-[#0F4C81]/90'
                                } disabled:opacity-50`}
                        >
                            {isLoading === item.id ? (
                                <>
                                    <Loader2 className="w-4 h-4 animate-spin" />
                                    Mengekspor...
                                </>
                            ) : (
                                <>
                                    <Download className="w-4 h-4" />
                                    Download CSV
                                </>
                            )}
                        </button>
                    </div>
                ))}
            </div>
        </div>
    );
}

'use client';

import { Trash2, FileText, ExternalLink, Edit, Search, X } from 'lucide-react';
import { useState, useMemo } from 'react';

interface Document {
    id: number;
    title: string;
    filePath: string;
    type: string;
    createdAt?: Date | null;
}

interface DocumentListProps {
    documents: Document[];
    onDelete: (id: number) => any;
    onEdit?: (doc: Document) => void;
}

export default function DocumentList({ documents, onDelete, onEdit }: DocumentListProps) {
    const [searchQuery, setSearchQuery] = useState('');

    const filteredDocuments = useMemo(() => {
        if (!searchQuery) return documents;
        const query = searchQuery.toLowerCase();
        return documents.filter(doc =>
            doc.title.toLowerCase().includes(query)
        );
    }, [documents, searchQuery]);

    return (
        <div>
            {/* Search */}
            <div className="mb-4">
                <div className="relative max-w-md">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                    <input
                        type="text"
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                        placeholder="Cari judul dokumen..."
                        className="w-full pl-10 pr-10 py-2 border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-[#0F4C81]/20 focus:border-[#0F4C81]"
                    />
                    {searchQuery && (
                        <button
                            onClick={() => setSearchQuery('')}
                            className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600"
                        >
                            <X className="w-4 h-4" />
                        </button>
                    )}
                </div>
                {searchQuery && (
                    <p className="text-sm text-gray-500 mt-2">
                        Menampilkan {filteredDocuments.length} dari {documents.length} dokumen
                    </p>
                )}
            </div>

            {filteredDocuments.length === 0 ? (
                <div className="text-center py-12 text-gray-500">
                    {searchQuery ? 'Tidak ada hasil pencarian' : 'Belum ada dokumen.'}
                </div>
            ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    {filteredDocuments.map((doc) => (
                        <div key={doc.id} className="bg-white rounded-xl shadow-sm border border-gray-100 p-4 hover:shadow-md transition-shadow">
                            <div className="flex items-start justify-between">
                                <div className="flex items-start gap-3 flex-1 min-w-0">
                                    <FileText className="w-5 h-5 text-[#0F4C81] flex-shrink-0 mt-0.5" />
                                    <div className="min-w-0 flex-1">
                                        <h4 className="font-medium text-gray-900 truncate">{doc.title}</h4>
                                        {doc.createdAt && (
                                            <p className="text-xs text-gray-500 mt-1">
                                                {new Date(doc.createdAt).toLocaleDateString('id-ID')}
                                            </p>
                                        )}
                                    </div>
                                </div>
                                <div className="flex items-center gap-1 flex-shrink-0">
                                    <a
                                        href={doc.filePath}
                                        target="_blank"
                                        rel="noopener noreferrer"
                                        className="text-blue-500 hover:text-blue-700 p-1.5 hover:bg-blue-50 rounded-lg transition-colors"
                                        title="Lihat File"
                                    >
                                        <ExternalLink className="w-4 h-4" />
                                    </a>
                                    {onEdit && (
                                        <button
                                            onClick={() => onEdit(doc)}
                                            className="text-gray-500 hover:text-gray-700 p-1.5 hover:bg-gray-100 rounded-lg transition-colors"
                                            title="Edit"
                                        >
                                            <Edit className="w-4 h-4" />
                                        </button>
                                    )}
                                    <button
                                        onClick={async () => {
                                            if (confirm('Hapus dokumen ini?')) {
                                                try {
                                                    const res = await onDelete(doc.id);
                                                    if (res?.error) alert(res.error);
                                                } catch (err) {
                                                    alert('Gagal menghapus dokumen');
                                                }
                                            }
                                        }}
                                        className="text-red-500 hover:text-red-700 p-1.5 hover:bg-red-50 rounded-lg transition-colors"
                                        title="Hapus"
                                    >
                                        <Trash2 className="w-4 h-4" />
                                    </button>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            )}
        </div>
    );
}

'use client';

import { useState, useMemo } from 'react';
import { Download, FileText, FileCheck, FileSignature, Search, X, Calendar, User } from 'lucide-react';

interface DownloadDocument {
    id: number;
    title: string;
    filePath: string;
    coverPath: string | null;
    type: string;
    createdAt: Date | null;
    uploaderName: string | null;
}

interface DownloadCenterProps {
    documents: DownloadDocument[];
}

type FilterType = 'all' | 'SOP' | 'LPJ Bulanan' | 'Template Surat';

const typeConfig: Record<string, { icon: typeof FileText; color: string; bg: string }> = {
    'SOP': { icon: FileCheck, color: 'text-blue-600', bg: 'bg-blue-50' },
    'LPJ Bulanan': { icon: FileText, color: 'text-green-600', bg: 'bg-green-50' },
    'Template Surat': { icon: FileSignature, color: 'text-purple-600', bg: 'bg-purple-50' },
};

export default function DownloadCenter({ documents }: DownloadCenterProps) {
    const [filter, setFilter] = useState<FilterType>('all');
    const [searchQuery, setSearchQuery] = useState('');

    const filteredDocuments = useMemo(() => {
        let docs = documents;
        if (filter !== 'all') docs = docs.filter(d => d.type === filter);
        if (searchQuery) {
            const query = searchQuery.toLowerCase();
            docs = docs.filter(d => d.title.toLowerCase().includes(query));
        }
        return docs;
    }, [documents, filter, searchQuery]);

    const counts = useMemo(() => ({
        all: documents.length,
        SOP: documents.filter(d => d.type === 'SOP').length,
        'LPJ Bulanan': documents.filter(d => d.type === 'LPJ Bulanan').length,
        'Template Surat': documents.filter(d => d.type === 'Template Surat').length,
    }), [documents]);

    const formatDate = (date: Date | string | null) => {
        if (!date) return '-';
        const d = typeof date === 'string' ? new Date(date) : date;
        if (isNaN(d.getTime())) return '-';
        return d.toLocaleDateString('id-ID', { day: 'numeric', month: 'short', year: 'numeric' });
    };

    return (
        <div className="space-y-6">
            <div>
                <h1 className="text-2xl font-bold text-gray-900">Pusat Download</h1>
                <p className="text-gray-500 text-sm mt-1">Download template, SOP, surat, dan dokumen lainnya</p>
            </div>

            {/* Filter Tabs */}
            <div className="flex flex-wrap gap-2">
                {([
                    { key: 'all', label: 'Semua', icon: Download },
                    { key: 'SOP', label: 'SOP', icon: FileCheck },
                    { key: 'LPJ Bulanan', label: 'LPJ Bulanan', icon: FileText },
                    { key: 'Template Surat', label: 'Template Surat', icon: FileSignature },
                ] as const).map(({ key, label, icon: Icon }) => (
                    <button
                        key={key}
                        onClick={() => setFilter(key)}
                        className={`inline-flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-medium transition-all ${
                            filter === key
                                ? 'bg-[#0F4C81] text-white shadow-sm'
                                : 'bg-white text-gray-600 hover:bg-gray-50 border border-gray-200'
                        }`}
                    >
                        <Icon className="w-4 h-4" />
                        {label}
                        <span className={`inline-flex items-center justify-center px-2 py-0.5 rounded-full text-xs font-bold ${
                            filter === key ? 'bg-white/20 text-white' : 'bg-gray-100 text-gray-600'
                        }`}>
                            {counts[key]}
                        </span>
                    </button>
                ))}
            </div>

            {/* Search */}
            <div className="relative max-w-md">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                <input
                    type="text"
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    placeholder="Cari dokumen..."
                    className="w-full pl-10 pr-10 py-2.5 border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-[#0F4C81]/20 focus:border-[#0F4C81]"
                />
                {searchQuery && (
                    <button onClick={() => setSearchQuery('')} className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600">
                        <X className="w-4 h-4" />
                    </button>
                )}
            </div>

            {(searchQuery || filter !== 'all') && (
                <p className="text-sm text-gray-500">Menampilkan {filteredDocuments.length} dari {documents.length} dokumen</p>
            )}

            {/* Document Grid */}
            {filteredDocuments.length === 0 ? (
                <div className="text-center py-16 bg-white rounded-xl border border-gray-100">
                    <div className="w-16 h-16 rounded-full bg-gray-100 flex items-center justify-center mx-auto mb-4">
                        <FileText className="w-7 h-7 text-gray-400" />
                    </div>
                    <h3 className="text-gray-600 font-medium text-lg">Tidak ada dokumen</h3>
                    <p className="text-sm text-gray-400 mt-1">
                        {searchQuery ? 'Coba ubah kata pencarian' : 'Belum ada dokumen yang diupload'}
                    </p>
                </div>
            ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                    {filteredDocuments.map((doc) => {
                        const config = typeConfig[doc.type] || typeConfig['SOP'];
                        const Icon = config.icon;
                        return (
                            <div key={doc.id} className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden hover:shadow-md transition-shadow group">
                                {doc.coverPath && (
                                    <div className="h-32 bg-gray-100 overflow-hidden">
                                        <img src={doc.coverPath} alt={doc.title} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-300" />
                                    </div>
                                )}
                                <div className="p-4">
                                    <div className="flex items-center gap-2 mb-2">
                                        <span className={`inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-medium ${config.bg} ${config.color}`}>
                                            <Icon className="w-3 h-3" />
                                            {doc.type}
                                        </span>
                                    </div>
                                    <h3 className="font-semibold text-gray-900 text-sm line-clamp-2 mb-3">{doc.title}</h3>
                                    <div className="space-y-1.5 mb-4">
                                        {doc.uploaderName && (
                                            <div className="flex items-center gap-1.5 text-xs text-gray-500">
                                                <User className="w-3 h-3" />
                                                <span>{doc.uploaderName}</span>
                                            </div>
                                        )}
                                        <div className="flex items-center gap-1.5 text-xs text-gray-500">
                                            <Calendar className="w-3 h-3" />
                                            <span>{formatDate(doc.createdAt)}</span>
                                        </div>
                                    </div>
                                    <a
                                        href={doc.filePath}
                                        target="_blank"
                                        rel="noopener noreferrer"
                                        download
                                        className="w-full inline-flex items-center justify-center gap-2 px-4 py-2.5 rounded-lg bg-[#0F4C81] text-white text-sm font-medium hover:bg-[#0F4C81]/90 transition-colors"
                                    >
                                        <Download className="w-4 h-4" />
                                        Download
                                    </a>
                                </div>
                            </div>
                        );
                    })}
                </div>
            )}
        </div>
    );
}

