                {permissions.canManageUsers && (
                    <button
                        onClick={() => { setActiveTab('users'); setEditingDoc(null); }}
                        className={`flex items-center gap-2 px-4 py-2.5 rounded-lg text-sm font-medium transition-all whitespace-nowrap ${activeTab === 'users' ? 'bg-white text-[#0F4C81] shadow-sm' : 'text-gray-500 hover:text-gray-700 hover:bg-gray-200/50'}`}
                    >
                        <Users className="w-4 h-4" />
                        Manajemen User
                    </button>
                )}
                {permissions.canManageHero && (
                    <button
                        onClick={() => { setActiveTab('hero'); setEditingDoc(null); }}
                        className={`flex items-center gap-2 px-4 py-2.5 rounded-lg text-sm font-medium transition-all whitespace-nowrap ${activeTab === 'hero' ? 'bg-white text-[#0F4C81] shadow-sm' : 'text-gray-500 hover:text-gray-700 hover:bg-gray-200/50'}`}
                    >
                        <ImageIcon className="w-4 h-4" />
                        Hero Section
                    </button>
                )}
            </div>

            {/* Content */}
            <div>
                {activeTab === 'sop' && permissions.canManageGovernance && (
                    <>
                        <GovernanceUploadForm adminId={adminId} allowedTypes={['SOP']} initialData={editingDoc?.type === 'SOP' ? editingDoc : null} onCancel={handleCancelEdit} />
                        <DocumentList documents={sops} onEdit={handleEdit} onDelete={deleteGovernanceDoc} />
                    </>
                )}

                {activeTab === 'lpj' && permissions.canManageGovernance && (
                    <>
                        <GovernanceUploadForm adminId={adminId} allowedTypes={['LPJ Bulanan']} initialData={editingDoc?.type === 'LPJ Bulanan' ? editingDoc : null} onCancel={handleCancelEdit} />
                        <DocumentList documents={lpjs} onEdit={handleEdit} onDelete={deleteGovernanceDoc} />
                        <DataExport />
                    </>
                )}

                {activeTab === 'template-surat' && permissions.canManageGovernance && (
                    <>
                        <GovernanceUploadForm adminId={adminId} allowedTypes={['Template Surat']} initialData={editingDoc?.type === 'Template Surat' ? editingDoc : null} onCancel={handleCancelEdit} />
                        <DocumentList documents={templateSurats} onEdit={handleEdit} onDelete={deleteGovernanceDoc} />
                    </>
                )}

                {activeTab === 'users' && permissions.canManageUsers && (
                    <>
                        {!showUserForm ? (
                            <>
                                <div className="mb-6 flex justify-end">
                                    <button onClick={() => setShowUserForm(true)} className="bg-[#0F4C81] text-white px-4 py-2 rounded-lg text-sm font-medium hover:bg-[#0F4C81]/90 transition-colors flex items-center gap-2">
                                        <Users className="w-4 h-4" />
                                        Tambah User Baru
                                    </button>
                                </div>
                                <BulkEnrollment />
                                <UserList users={users} roles={roles} lecturers={lecturers} allPermissions={allPermissions} rolePermissionMap={rolePermissionMap} />
                            </>
                        ) : (
                            <UserForm roles={roles} lecturers={lecturers} onSuccess={() => setShowUserForm(false)} onCancel={() => setShowUserForm(false)} />
                        )}
                    </>
                )}

                {activeTab === 'hero' && permissions.canManageHero && (
                    <HeroPhotoManager initialPhotos={heroPhotos} />
                )}
            </div>
        </div>
    );
}

'use client';

import { uploadGovernanceDoc, updateGovernanceDoc } from '@/features/governance/actions';
import { Upload } from 'lucide-react';
import { useState } from 'react';

interface GovernanceUploadFormProps {
    adminId: string;
    allowedTypes: string[];
    initialData?: any;
    onCancel?: () => void;
}

export default function GovernanceUploadForm({ adminId, allowedTypes, initialData, onCancel }: GovernanceUploadFormProps) {
    const [isSubmitting, setIsSubmitting] = useState(false);
    const isEdit = !!initialData;

    return (
        <div className="bg-white p-4 md:p-6 rounded-xl shadow-sm border border-gray-100 mb-8">
            <h2 className="text-lg font-semibold mb-4 flex items-center gap-2">
                <Upload className="w-5 h-5 text-primary" />
                {isEdit ? 'Edit Dokumen Tata Kelola' : 'Upload Dokumen Tata Kelola'}
            </h2>
            <form action={async (formData) => {
                setIsSubmitting(true);
                try {
                    let res;
                    if (isEdit) {
                        res = await updateGovernanceDoc(initialData.id, formData);
                    } else {
                        res = await uploadGovernanceDoc(formData);
                    }

                    if (res?.error) {
                        alert(res.error);
                    } else {
                        if (isEdit && onCancel) onCancel();
                        if (!isEdit) {
                            const form = document.getElementById('gov-upload-form') as HTMLFormElement;
                            form?.reset();
                        }
                    }
                } catch (error) {
                    alert('Gagal menyimpan dokumen');
                    console.error(error);
                } finally {
                    setIsSubmitting(false);
                }
            }} id="gov-upload-form" className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <input type="hidden" name="adminId" value={adminId} />

                <div className="md:col-span-2">
                    <label className="block text-sm font-medium text-gray-700 mb-1">Judul Dokumen</label>
                    <input
                        name="title"
                        defaultValue={initialData?.title}
                        required
                        placeholder="Contoh: SOP Peminjaman Alat"
                        className="w-full px-4 py-2 rounded-lg border border-gray-200 focus:outline-none focus:ring-2 focus:ring-primary/20"
                    />
                </div>

                <div className="md:col-span-2">
                    <label className="block text-sm font-medium text-gray-700 mb-1">Tipe Dokumen</label>
                    <select
                        name="type"
                        defaultValue={initialData?.type}
                        required
                        className="w-full px-4 py-2 rounded-lg border border-gray-200 focus:outline-none focus:ring-2 focus:ring-primary/20"
                    >
                        {allowedTypes.map(type => (
                            <option key={type} value={type}>{type}</option>
                        ))}
                    </select>
                </div>

                <div className="md:col-span-2">
                    <label className="block text-sm font-medium text-gray-700 mb-1">
                        {isEdit ? 'File Dokumen (PDF) - Biarkan kosong jika tidak ingin mengubah' : 'File Dokumen (PDF)'}
                    </label>
                    <input
                        type="file"
                        name="file"
                        required={!isEdit}
                        accept=".pdf"
                        className="w-full max-w-full overflow-hidden text-ellipsis px-4 py-2 rounded-lg border border-gray-200 focus:outline-none focus:ring-2 focus:ring-primary/20 file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-sm file:font-semibold file:bg-primary/10 file:text-primary hover:file:bg-primary/20"
                    />
                    <p className="text-xs text-gray-500 mt-1">Format: PDF. Maks. 2MB</p>
                </div>

                <div className="md:col-span-2">
                    <label className="block text-sm font-medium text-gray-700 mb-1">
                        {isEdit ? 'Cover Image (Opsional) - Biarkan kosong jika tidak ingin mengubah' : 'Cover Image (Opsional, untuk SOP)'}
                    </label>
                    <input type="file" name="cover" accept="image/*" className="w-full max-w-full overflow-hidden text-ellipsis px-4 py-2 rounded-lg border border-gray-200 focus:outline-none focus:ring-2 focus:ring-primary/20 file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-sm file:font-semibold file:bg-primary/10 file:text-primary hover:file:bg-primary/20" />
                    <p className="text-xs text-gray-500 mt-1">Format: JPG, PNG. Maks. 2MB. Disarankan rasio 1:1 atau portrait.</p>
                </div>

                <div className="md:col-span-2 flex gap-2">
                    <button
                        type="submit"
                        disabled={isSubmitting}
                        className="bg-[#0F4C81] text-white px-4 py-2 rounded-lg text-sm font-medium hover:bg-[#0F4C81]/90 transition-colors disabled:opacity-50 w-full md:w-auto"
                    >
                        {isSubmitting ? 'Menyimpan...' : (isEdit ? 'Simpan Perubahan' : 'Upload Dokumen')}
                    </button>
                    {isEdit && onCancel && (
                        <button
                            type="button"
                            onClick={onCancel}
                            className="bg-gray-100 text-gray-700 px-6 py-2 rounded-lg hover:bg-gray-200 transition-colors font-medium w-full md:w-auto"
                        >
                            Batal
                        </button>
                    )}
                </div>
            </form>
        </div>
    );
}

'use client';

import { createUser, updateUser } from '@/features/users/actions';
import { useState, useMemo } from 'react';
import { UserPlus, Save, Loader2 } from 'lucide-react';

interface Role {
    id: number;
    name: string;
}

interface Lecturer {
    identifier: string;
    fullName: string;
}

interface UserFormProps {
    roles: Role[];
    lecturers: Lecturer[];
    initialData?: any;
    onSuccess?: () => void;
    onCancel?: () => void;
}

export default function UserForm({ roles, lecturers, initialData, onSuccess, onCancel }: UserFormProps) {
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [selectedRoleId, setSelectedRoleId] = useState<number | undefined>(initialData?.roleId);

    // Derived state for role checking
    const isStudent = useMemo(() => {
        if (!selectedRoleId) return false;
        const selectedRole = roles.find(r => r.id === selectedRoleId);
        return selectedRole?.name === 'Mahasiswa';
    }, [selectedRoleId, roles]);

    const isEdit = !!initialData;

    return (
        <div className="bg-white p-4 md:p-6 rounded-xl shadow-sm border border-gray-100 mb-8">
            <h2 className="text-lg font-semibold mb-4 flex items-center gap-2">
                {isEdit ? <Save className="w-5 h-5 text-primary" /> : <UserPlus className="w-5 h-5 text-primary" />}
                {isEdit ? 'Edit User' : 'Tambah User Baru'}
            </h2>
            <form action={async (formData) => {
                setIsSubmitting(true);
                try {
                    const data: any = {
                        fullName: formData.get('fullName') as string,
                        identifier: formData.get('identifier') as string,
                        email: formData.get('email') as string,
                        roleId: parseInt(formData.get('roleId') as string),
                        passwordHash: formData.get('password') as string || undefined,
                    };

                    // Append student specific data
                    if (isStudent) {
                        const batch = formData.get('batch');
                        const studyType = formData.get('studyType');
                        const programStudi = formData.get('programStudi');
                        const dosenPembimbing = formData.get('dosenPembimbing');

                        // We enforce validation here as well
                        if (!batch || !studyType) {
                            throw new Error('Angkatan dan Tipe Belajar wajib diisi untuk Mahasiswa');
                        }

                        data.batch = parseInt(batch as string);
                        data.studyType = studyType as 'Reguler' | 'Hybrid';
                        data.programStudi = (programStudi as string) || 'Informatika';
                        data.dosenPembimbing = dosenPembimbing as string || undefined;
                    }

                    if (isEdit) {
                        await updateUser(initialData.identifier, data);
                    } else {
                        if (!data.passwordHash) throw new Error('Password wajib diisi untuk user baru');
                        await createUser(data);
                    }

                    if (onSuccess) onSuccess();
                    if (!isEdit) {
                        const form = document.getElementById('user-form') as HTMLFormElement;
                        form?.reset();
                        setSelectedRoleId(undefined);
                    }
                } catch (error: any) {
                    alert(error.message || 'Gagal menyimpan user');
                } finally {
                    setIsSubmitting(false);
                }
            }} id="user-form" className="grid grid-cols-1 md:grid-cols-2 gap-4">

                <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Nama Lengkap</label>
                    <input
                        name="fullName"
                        defaultValue={initialData?.fullName}
                        required
                        className="w-full px-4 py-2 rounded-lg border border-gray-200 focus:outline-none focus:ring-2 focus:ring-primary/20"
                        placeholder="Contoh: Budi Santoso"
                    />
                </div>

                <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">NIM / NIDN</label>
                    <input
                        name="identifier"
                        defaultValue={initialData?.identifier}
                        required
                        className="w-full px-4 py-2 rounded-lg border border-gray-200 focus:outline-none focus:ring-2 focus:ring-primary/20"
                        placeholder="Contoh: 0102521001"
                    />
                </div>

                <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Email</label>
                    <input
                        name="email"
                        type="email"
                        defaultValue={initialData?.email}
                        required
                        className="w-full px-4 py-2 rounded-lg border border-gray-200 focus:outline-none focus:ring-2 focus:ring-primary/20"
                        placeholder="nama@uai.ac.id"
                    />
                </div>

                <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Role</label>
                    <select
                        name="roleId"
                        value={selectedRoleId || ''}
                        onChange={(e) => setSelectedRoleId(parseInt(e.target.value))}
                        required
                        className="w-full px-4 py-2 rounded-lg border border-gray-200 focus:outline-none focus:ring-2 focus:ring-primary/20 bg-white"
                    >
                        <option value="">Pilih Role</option>
                        {roles.map(role => (
                            <option key={role.id} value={role.id}>{role.name}</option>
                        ))}
                    </select>
                </div>

                {isStudent && (
                    <>
                        <div className="animate-in fade-in duration-300">
                            <label className="block text-sm font-medium text-gray-700 mb-1">Angkatan <span className="text-red-500">*</span></label>
                            <select
                                name="batch"
                                defaultValue={initialData?.batch || new Date().getFullYear()}
                                required
                                className="w-full px-4 py-2 rounded-lg border border-gray-200 focus:outline-none focus:ring-2 focus:ring-primary/20 bg-white"
                            >
                                <option value="">Pilih Tahun</option>
                                {Array.from({ length: 5 }, (_, i) => new Date().getFullYear() - i).map(year => (
                                    <option key={year} value={year}>{year}</option>
                                ))}
                            </select>
                        </div>
                        <div className="animate-in fade-in duration-300">
                            <label className="block text-sm font-medium text-gray-700 mb-1">Tipe Belajar <span className="text-red-500">*</span></label>
                            <select
                                name="studyType"
                                defaultValue={initialData?.studyType || 'Reguler'}
                                required
                                className="w-full px-4 py-2 rounded-lg border border-gray-200 focus:outline-none focus:ring-2 focus:ring-primary/20 bg-white"
                            >
                                <option value="">Pilih Tipe</option>
                                <option value="Reguler">Reguler</option>
                                <option value="Hybrid">Hybrid</option>
                            </select>
                        </div>
                        <div className="animate-in fade-in duration-300">
                            <label className="block text-sm font-medium text-gray-700 mb-1">Program Studi</label>
                            <input
                                name="programStudi"
                                defaultValue={initialData?.programStudi || 'Informatika'}
                                className="w-full px-4 py-2 rounded-lg border border-gray-200 focus:outline-none focus:ring-2 focus:ring-primary/20"
                                placeholder="Contoh: Informatika"
                            />
                        </div>
                        <div className="animate-in fade-in duration-300">
                            <label className="block text-sm font-medium text-gray-700 mb-1">Dosen Pembimbing <span className="text-red-500">*</span></label>
                            <select
                                name="dosenPembimbing"
                                defaultValue={initialData?.dosenPembimbing || ''}
                                required
                                className="w-full px-4 py-2 rounded-lg border border-gray-200 focus:outline-none focus:ring-2 focus:ring-primary/20 bg-white"
                            >
                                <option value="">Pilih Dosen Pembimbing</option>
                                {lecturers.map(lecturer => (
                                    <option key={lecturer.identifier} value={lecturer.fullName}>
                                        {lecturer.fullName} ({lecturer.identifier})
                                    </option>
                                ))}
                            </select>
                        </div>
                    </>
                )}

                <div className="md:col-span-2">
                    <label className="block text-sm font-medium text-gray-700 mb-1">
                        {isEdit ? 'Password (Kosongkan jika tidak ingin mengubah)' : 'Password'} <span className="text-xs text-gray-400 font-normal">Min. 6 karakter</span>
                    </label>
                    <input
                        name="password"
                        type="password"
                        required={!isEdit}
                        className="w-full px-4 py-2 rounded-lg border border-gray-200 focus:outline-none focus:ring-2 focus:ring-primary/20"
                        placeholder={isEdit ? '********' : 'Masukan password...'}
                    />
                </div>

                <div className="md:col-span-2 flex gap-2 pt-2">
                    <button
                        type="submit"
                        disabled={isSubmitting}
                        className="bg-[#0F4C81] text-white px-6 py-2 rounded-lg text-sm font-medium hover:bg-[#0F4C81]/90 transition-colors disabled:opacity-50 flex items-center justify-center min-w-[120px]"
                    >
                        {isSubmitting ? (
                            <>
                                <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                                Menyimpan...
                            </>
                        ) : (
                            'Simpan User'
                        )}
                    </button>
                    {onCancel && (
                        <button
                            type="button"
                            onClick={onCancel}
                            disabled={isSubmitting}
                            className="bg-gray-100 text-gray-700 px-6 py-2 rounded-lg hover:bg-gray-200 transition-colors font-medium border border-gray-200"
                        >
                            Batal
                        </button>
                    )}
                </div>
            </form>
        </div>
    );
}

'use client';

import { deleteUser } from '@/features/users/actions';
import { Trash2, Edit, User, Search, X, Shield, Check, Loader2, LayoutGrid, List } from 'lucide-react';
import { useState, useMemo, useTransition } from 'react';
import UserForm from './UserForm';
import { getUserPermissionOverrides, updateUserPermissions } from '@/features/permissions/actions';

interface Permission {
    id: number;
    code: string;
    name: string;
    category: string;
    description: string | null;
}

interface UserListProps {
    users: any[];
    roles: any[];
    lecturers: { identifier: string; fullName: string }[];
    allPermissions?: Permission[];
    rolePermissionMap?: Record<number, string[]>;
}

export default function UserList({ users, roles, lecturers, allPermissions = [], rolePermissionMap = {} }: UserListProps) {
    const [editingUser, setEditingUser] = useState<any>(null);
    const [searchQuery, setSearchQuery] = useState('');
    
    // View Mode State
    const [viewMode, setViewMode] = useState<'grid' | 'list'>(() => {
        if (typeof window !== 'undefined') {
            return window.innerWidth >= 768 ? 'list' : 'grid';
        }
        return 'list';
    });

    // Permission modal state
    const [permUser, setPermUser] = useState<any>(null);
    const [isPermModalOpen, setIsPermModalOpen] = useState(false);
    const [userOverrides, setUserOverrides] = useState<{ code: string; granted: boolean }[]>([]);
    const [isLoading, setIsLoading] = useState(false);
    const [isPending, startTransition] = useTransition();
    const [saveMessage, setSaveMessage] = useState('');

    const filteredUsers = useMemo(() => {
        if (!searchQuery) return users;
        const query = searchQuery.toLowerCase();
        return users.filter(user =>
            user.fullName.toLowerCase().includes(query) ||
            user.identifier.toLowerCase().includes(query) ||
            (user.email && user.email.toLowerCase().includes(query))
        );
    }, [users, searchQuery]);

    // Group permissions by category
    const permissionsByCategory = useMemo(() => {
        const grouped: Record<string, Permission[]> = {};
        for (const perm of allPermissions) {
            if (!grouped[perm.category]) grouped[perm.category] = [];
            grouped[perm.category].push(perm);
        }
        return grouped;
    }, [allPermissions]);

    // --- Permission Modal logic ---
    const openPermModal = async (user: any) => {
        setPermUser(user);
        setIsPermModalOpen(true);
        setIsLoading(true);
        setSaveMessage('');
        try {
            const overrides = await getUserPermissionOverrides(user.identifier);
            setUserOverrides(overrides.map(o => ({ code: o.code, granted: o.granted ? true : false })));
        } catch {
            setUserOverrides([]);
        } finally {
            setIsLoading(false);
        }
    };

    const closePermModal = () => {
        setIsPermModalOpen(false);
        setPermUser(null);
        setUserOverrides([]);
        setSaveMessage('');
    };

    const isRoleDefault = (permCode: string): boolean => {
        if (!permUser) return false;
        return (rolePermissionMap[permUser.roleId] || []).includes(permCode);
    };

    const isPermissionEnabled = (permCode: string): boolean => {
        const override = userOverrides.find(o => o.code === permCode);
        if (override !== undefined) return override.granted;
        return isRoleDefault(permCode);
    };

    const togglePermission = (permCode: string) => {
        const isDefault = isRoleDefault(permCode);
        const existing = userOverrides.find(o => o.code === permCode);

        if (existing !== undefined) {
            // Remove override → revert to role default behavior
            setUserOverrides(prev => prev.filter(o => o.code !== permCode));
        } else {
            // Add override → flip from default
            setUserOverrides(prev => [...prev, { code: permCode, granted: !isDefault }]);
        }
    };

    const handleSavePerm = () => {
        if (!permUser) return;
        startTransition(async () => {
            try {
                await updateUserPermissions(permUser.identifier, userOverrides);
                setSaveMessage('Berhasil disimpan! Perubahan akan aktif otomatis saat user membuka halaman berikutnya.');
            } catch {
                setSaveMessage('Gagal menyimpan permission.');
            }
        });
    };

    if (editingUser) {
        return (
            <UserForm
                roles={roles}
                lecturers={lecturers}
                initialData={editingUser}
                onSuccess={() => setEditingUser(null)}
                onCancel={() => setEditingUser(null)}
            />
        );
    }

    return (
        <>
            <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
                {/* Search */}
                <div className="p-4 border-b border-gray-100">
                    <div className="relative max-w-md">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                        <input
                            type="text"
                            value={searchQuery}
                            onChange={(e) => setSearchQuery(e.target.value)}
                            placeholder="Cari nama, NIM/NIDN, atau email..."
                            className="w-full pl-10 pr-10 py-2 border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-[#0F4C81]/20 focus:border-[#0F4C81]"
                        />
                        {searchQuery && (
                            <button
                                onClick={() => setSearchQuery('')}
                                className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600"
                            >
                                <X className="w-4 h-4" />
                            </button>
                        )}
                    </div>
                    <div className="flex items-center justify-between mt-4">
                        {searchQuery ? (
                            <p className="text-sm text-gray-500">
                                Menampilkan {filteredUsers.length} dari {users.length} user
                            </p>
                        ) : (
                            <p className="text-sm text-gray-500">Total {users.length} user</p>
                        )}

                        <div className="hidden md:flex items-center bg-gray-100 rounded-lg p-0.5 ml-auto">
                            <button
                                onClick={() => setViewMode('grid')}
                                className={`p-1.5 rounded ${viewMode === 'grid' ? 'bg-white shadow-sm text-[#0F4C81]' : 'text-gray-500 hover:text-gray-700'}`} title="Tampilan Grid">
                                <LayoutGrid className="w-4 h-4" />
                            </button>
                            <button
                                onClick={() => setViewMode('list')}
                                className={`p-1.5 rounded ${viewMode === 'list' ? 'bg-white shadow-sm text-[#0F4C81]' : 'text-gray-500 hover:text-gray-700'}`} title="Tampilan List">
                                <List className="w-4 h-4" />
                            </button>
                        </div>
                    </div>
                </div>

                {/* Table View */}
                <div className={`overflow-x-auto ${viewMode === 'list' ? 'block' : 'hidden'}`}>
                    <table className="min-w-full divide-y divide-gray-200">
                    <thead className="bg-gray-50 border-b border-gray-100">
                        <tr>
                            <th className="px-6 py-4 font-semibold text-gray-700">Nama Lengkap</th>
                            <th className="px-6 py-4 font-semibold text-gray-700">NIM/NIDN</th>
                            <th className="px-6 py-4 font-semibold text-gray-700">Email</th>
                            <th className="px-6 py-4 font-semibold text-gray-700">Role</th>
                            <th className="px-6 py-4 font-semibold text-gray-700 text-center">Aksi</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-100">
                        {filteredUsers.map((user) => (
