/**
 * Export room booking data to CSV format
 */
export async function exportBookingData(filters: ExportFilters) {
    const { startDate, endDate } = filters;

    const records = await db
        .select({
            id: roomBookings.id,
            userName: users.fullName,
            userIdentifier: users.identifier,
            roomName: rooms.name,
            startTime: roomBookings.startTime,
            endTime: roomBookings.endTime,
            purpose: roomBookings.purpose,
            status: roomBookings.status,
            organisasi: roomBookings.organisasi,
            jumlahPeserta: roomBookings.jumlahPeserta,
            dosenPembimbing: roomBookings.dosenPembimbing,
        })
        .from(roomBookings)
        .leftJoin(users, eq(roomBookings.userId, users.identifier))
        .leftJoin(rooms, eq(roomBookings.roomId, rooms.id))
        .where(
            and(
                gte(roomBookings.startTime, new Date(startDate)),
                lte(roomBookings.startTime, new Date(endDate + 'T23:59:59'))
            )
        )
        .orderBy(roomBookings.startTime);

    const headers = ['No', 'Nama', 'NIM/NIDN', 'Ruangan', 'Tanggal', 'Jam Mulai', 'Jam Selesai', 'Status', 'Organisasi', 'Jumlah Peserta', 'Dosen Pembimbing', 'Keperluan'];
    const rows = records.map((r, i) => {
        const start = r.startTime ? new Date(r.startTime) : null;
        const end = r.endTime ? new Date(r.endTime) : null;

        return [
            i + 1,
            escapeCSV(r.userName),
            escapeIdentifier(r.userIdentifier),
            escapeCSV(r.roomName),
            escapeCSV(start ? start.toLocaleDateString('id-ID') : '-'),
            escapeCSV(start ? start.toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' }) : '-'),
            escapeCSV(end ? end.toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' }) : '-'),
            escapeCSV(r.status),
            escapeCSV(r.organisasi),
            r.jumlahPeserta || '-',
            escapeCSV(r.dosenPembimbing),
            escapeCSV(r.purpose)
        ];
    });

    const csvContent = [headers.join(','), ...rows.map(row => row.join(','))].join('\n');
    return { csv: csvContent, count: records.length };
}

'use server';

import { HeroPhotoService } from './service';
import { revalidatePath } from 'next/cache';
import { saveFile, deleteFile } from '@/lib/upload';
import { requirePermission } from '@/lib/auth';

export async function getHeroPhotos() {
    return HeroPhotoService.getAll();
}

export async function addHeroPhoto(formData: FormData) {
    await requirePermission('hero.manage');
    const title = formData.get('title') as string;
    const description = formData.get('description') as string;
    const link = formData.get('link') as string;
    const focalX = parseInt(formData.get('focalX') as string) || 50;
    const focalY = parseInt(formData.get('focalY') as string) || 50;
    const file = formData.get('file') as File;

    if (!file || file.size === 0) {
        throw new Error('Image file is required');
    }

    const imageUrl = await saveFile(file);

    await HeroPhotoService.create({
        title,
        description,
        imageUrl,
        focalX,
        focalY,
        link: link || null,
    });

    revalidatePath('/');
    revalidatePath('/admin/hero-photos');
}

export async function updateHeroPhoto(id: number, formData: FormData) {
    await requirePermission('hero.manage');
    const title = formData.get('title') as string;
    const description = formData.get('description') as string;
    const link = formData.get('link') as string;

    // Parse focal points - if empty, do not override
    const focalXStr = formData.get('focalX');
    const focalYStr = formData.get('focalY');
    const focalX = focalXStr ? parseInt(focalXStr as string) : undefined;
    const focalY = focalYStr ? parseInt(focalYStr as string) : undefined;

    const file = formData.get('file') as File;

    let imageUrl: string | undefined;

    if (file && file.size > 0) {
        // Get old photo to delete
        const oldPhoto = await HeroPhotoService.getById(id);

        if (oldPhoto?.imageUrl) {
            await deleteFile(oldPhoto.imageUrl);
        }

        imageUrl = await saveFile(file);
    }

    await HeroPhotoService.update(id, {
        title,
        description,
        imageUrl,
        focalX,
        focalY,
        link: link || null,
    });

    revalidatePath('/');
    revalidatePath('/admin/hero-photos');
}

export async function deleteHeroPhoto(id: number) {
    await requirePermission('hero.manage');
    const photo = await HeroPhotoService.getById(id);

    if (photo?.imageUrl) {
        await deleteFile(photo.imageUrl);
    }

    await HeroPhotoService.delete(id);
    revalidatePath('/');
    revalidatePath('/admin/hero-photos');
}

/**
 * Hero Photo Service
 * Business logic for hero photos/carousel management
 */

import { db } from '@/db';
import { heroPhotos } from '@/db/schema';
import { eq, desc } from 'drizzle-orm';

export interface CreateHeroPhotoInput {
    title: string;
    description?: string;
    imageUrl: string;
    focalX: number;
    focalY: number;
    link?: string | null;
}

export interface UpdateHeroPhotoInput {
    title: string;
    description?: string;
    imageUrl?: string;
    focalX?: number;
    focalY?: number;
    link?: string | null;
}

export class HeroPhotoService {
    /**
     * Get all hero photos
     */
    static async getAll() {
        return await db.select().from(heroPhotos).orderBy(desc(heroPhotos.createdAt));
    }

    /**
     * Get a hero photo by ID
     */
    static async getById(id: number) {
        return await db.query.heroPhotos.findFirst({
            where: eq(heroPhotos.id, id)
        });
    }

    /**
     * Create a new hero photo
     */
    static async create(data: CreateHeroPhotoInput) {
        await db.insert(heroPhotos).values({
            title: data.title,
            description: data.description,
            imageUrl: data.imageUrl,
            focalX: data.focalX,
            focalY: data.focalY,
            link: data.link || null,
        });
    }

    /**
     * Update a hero photo
     */
    static async update(id: number, data: UpdateHeroPhotoInput) {
        const updateData: any = {
            title: data.title,
            description: data.description,
            link: data.link || null,
        };

        if (data.focalX !== undefined) updateData.focalX = data.focalX;
        if (data.focalY !== undefined) updateData.focalY = data.focalY;

        if (data.imageUrl) {
            updateData.imageUrl = data.imageUrl;
        }

        await db.update(heroPhotos)
            .set(updateData)
            .where(eq(heroPhotos.id, id));
    }

    /**
     * Delete a hero photo
     */
    static async delete(id: number) {
        await db.delete(heroPhotos).where(eq(heroPhotos.id, id));
    }
}

