import { db } from '@/db';
import { permissions, rolePermissions, userPermissions, users, roles } from '@/db/schema';
import { eq, and, sql } from 'drizzle-orm';

export class PermissionService {
    /**
     * Get all available permissions, grouped by category
     */
    static async getAllPermissions() {
        return await db.select().from(permissions).orderBy(permissions.category, permissions.code);
    }

    /**
     * Get role default permission codes
     */
    static async getRolePermissions(roleId: number): Promise<string[]> {
        const result = await db.select({ code: permissions.code })
            .from(rolePermissions)
            .innerJoin(permissions, eq(rolePermissions.permissionId, permissions.id))
            .where(eq(rolePermissions.roleId, roleId));
        return result.map(r => r.code);
    }

    /**
     * Get all role permissions as a map: roleId -> permission codes
     */
    static async getRolePermissionMap(): Promise<Record<number, string[]>> {
        const allRolePerms = await db.select({
            roleId: rolePermissions.roleId,
            code: permissions.code,
        })
            .from(rolePermissions)
            .innerJoin(permissions, eq(rolePermissions.permissionId, permissions.id));

        const map: Record<number, string[]> = {};
        for (const rp of allRolePerms) {
            if (!map[rp.roleId]) map[rp.roleId] = [];
            map[rp.roleId].push(rp.code);
        }
        return map;
    }

    /**
     * Get user-level permission overrides
     */
    static async getUserOverrides(userId: string) {
        return await db.select({
            id: userPermissions.id,
            permissionId: userPermissions.permissionId,
            code: permissions.code,
            name: permissions.name,
            category: permissions.category,
            granted: userPermissions.granted,
        })
            .from(userPermissions)
            .innerJoin(permissions, eq(userPermissions.permissionId, permissions.id))
            .where(eq(userPermissions.userId, userId));
    }

    /**
     * Get effective permissions for a user (role defaults + user overrides)
     */
    static async getEffectivePermissions(userId: string, roleId: number): Promise<string[]> {
        const rolePerms = await db.select({ code: permissions.code })
            .from(rolePermissions)
            .innerJoin(permissions, eq(rolePermissions.permissionId, permissions.id))
            .where(eq(rolePermissions.roleId, roleId));

        const defaultCodes = new Set(rolePerms.map(rp => rp.code));

        const userOverrides = await db.select({
            code: permissions.code,
            granted: userPermissions.granted,
        })
            .from(userPermissions)
            .innerJoin(permissions, eq(userPermissions.permissionId, permissions.id))
            .where(eq(userPermissions.userId, userId));

        for (const override of userOverrides) {
            if (override.granted) {
                defaultCodes.add(override.code);
            } else {
                defaultCodes.delete(override.code);
            }
        }

        return Array.from(defaultCodes);
    }

    /**
     * Set a user-level permission override (grant or revoke)
     */
    static async setUserPermission(userId: string, permissionCode: string, granted: boolean) {
        const perm = await db.select().from(permissions).where(eq(permissions.code, permissionCode)).limit(1);
        if (perm.length === 0) throw new Error(`Permission '${permissionCode}' not found`);

        // Upsert: insert or update on duplicate
        const existing = await db.select().from(userPermissions)
            .where(and(
                eq(userPermissions.userId, userId),
                eq(userPermissions.permissionId, perm[0].id)
            )).limit(1);

        if (existing.length > 0) {
            await db.update(userPermissions)
                .set({ granted })
                .where(eq(userPermissions.id, existing[0].id));
        } else {
            await db.insert(userPermissions).values({
                userId,
                permissionId: perm[0].id,
                granted,
            });
        }
    }

    /**
     * Remove a user-level permission override (revert to role default)
     */
    static async removeUserPermission(userId: string, permissionCode: string) {
        const perm = await db.select().from(permissions).where(eq(permissions.code, permissionCode)).limit(1);
        if (perm.length === 0) return;

        await db.delete(userPermissions)
            .where(and(
                eq(userPermissions.userId, userId),
                eq(userPermissions.permissionId, perm[0].id)
            ));
    }

    /**
     * Bulk set user permissions — replaces all user overrides
     */
    static async setUserPermissions(userId: string, permissionOverrides: { code: string; granted: boolean }[]) {
        // Clear existing overrides for this user
        await db.delete(userPermissions).where(eq(userPermissions.userId, userId));

        if (permissionOverrides.length === 0) return;

        // Get permission ids
        const allPerms = await db.select().from(permissions);
        const permMap = new Map(allPerms.map(p => [p.code, p.id]));

        const values = permissionOverrides
            .filter(o => permMap.has(o.code))
            .map(o => ({
                userId,
                permissionId: permMap.get(o.code)!,
                granted: o.granted,
            }));

        if (values.length > 0) {
            await db.insert(userPermissions).values(values);
        }
    }
}

'use server';

import { PracticumReportService } from './service';
import { revalidatePath } from 'next/cache';
import { requirePermission, getSession } from '@/lib/auth';
import { createPracticumReportSchema, verifyPracticumReportSchema } from './validator';
import type { CreatePracticumReportInput, VerifyPracticumReportInput } from './types';

/**
 * Get all practicum reports (admin)
 */
export async function getAllPracticumReports() {
    await requirePermission('practicum.manage');
    return PracticumReportService.getAllWithDetails();
}

/**
 * Get practicum reports for current lecturer's courses
 */
export async function getLecturerPracticumReports() {
    const session = await getSession();
    if (!session) throw new Error('Anda harus login');
    return PracticumReportService.getByLecturerId(session.user.identifier);
}

/**
 * Get practicum reports created by the current user
 */
export async function getMyPracticumReports() {
    const session = await getSession();
    if (!session) throw new Error('Anda harus login');
    return PracticumReportService.getByUser(session.user.identifier);
}

/**
 * Get set of scheduledPracticumIds already reported by current user
 */
export async function getMyReportedScheduleIds() {
    const session = await getSession();
    if (!session) throw new Error('Anda harus login');
    const set = await PracticumReportService.getReportedScheduleIds(session.user.identifier);
    return Array.from(set);
}

/**
 * Create a new practicum report (Berita Acara)
 */
export async function createPracticumReport(data: CreatePracticumReportInput) {
    try {
        const session = await requirePermission('practicum.manage');
        const validated = createPracticumReportSchema.parse(data);

        // Fetch lecturer name from DB if not provided
        let lecturerName = validated.lecturerName;
        if (!lecturerName) {
            lecturerName = await PracticumReportService.getLecturerName(validated.scheduledPracticumId);
        }

        await PracticumReportService.create(
            { ...validated, lecturerName } as CreatePracticumReportInput,
            session.user.identifier
        );

        revalidatePath('/admin/scheduled-practicum');
        revalidatePath('/student/manage/scheduled-practicum');
        revalidatePath('/lecturer/manage/scheduled-practicum');

        return { success: true };
    } catch (error: any) {
        console.error('Error creating practicum report:', error);
        return { success: false, error: error.message || 'Gagal membuat berita acara' };
    }
}

/**
 * Verify a practicum report (admin or lecturer of the course)
 */
export async function verifyPracticumReport(id: number, data: VerifyPracticumReportInput) {
    try {
        const session = await getSession();
        if (!session) throw new Error('Anda harus login');

        if (session.user.roleId !== 1 && session.user.roleId !== 2) {
            throw new Error('Anda tidak memiliki akses untuk verifikasi berita acara');
        }

        const validated = verifyPracticumReportSchema.parse(data);
        await PracticumReportService.verify(id, validated as VerifyPracticumReportInput, session.user.identifier);

        revalidatePath('/admin/scheduled-practicum');
        revalidatePath('/student/manage/scheduled-practicum');
        revalidatePath('/lecturer/manage/scheduled-practicum');

        return { success: true };
    } catch (error: any) {
        console.error('Error verifying practicum report:', error);
        return { success: false, error: error.message || 'Gagal memverifikasi berita acara' };
    }
}

/**
 * Verify practicum report as lecturer (only for own courses)
 */
export async function lecturerVerifyPracticumReport(id: number, data: VerifyPracticumReportInput) {
    try {
        const session = await getSession();
        if (!session) throw new Error('Anda harus login');

        const belongs = await PracticumReportService.belongsToLecturer(id, session.user.identifier);
        if (!belongs) {
            throw new Error('Anda hanya dapat memverifikasi berita acara matakuliah yang Anda ampu');
        }

        const validated = verifyPracticumReportSchema.parse(data);
        await PracticumReportService.verify(id, validated as VerifyPracticumReportInput, session.user.identifier);

        revalidatePath('/admin/scheduled-practicum');
        revalidatePath('/lecturer/manage/scheduled-practicum');

        return { success: true };
    } catch (error: any) {
        console.error('Error verifying practicum report (lecturer):', error);
        return { success: false, error: error.message || 'Gagal memverifikasi berita acara' };
    }
}

/**
 * Delete a practicum report (admin only)
 */
export async function deletePracticumReport(id: number) {
    try {
        const session = await getSession();
        if (!session || session.user.roleId !== 1) {
            throw new Error('Hanya admin yang dapat menghapus berita acara');
        }

        await PracticumReportService.delete(id);

        revalidatePath('/admin/scheduled-practicum');
        revalidatePath('/student/manage/scheduled-practicum');
        revalidatePath('/lecturer/manage/scheduled-practicum');

        return { success: true };
    } catch (error: any) {
        console.error('Error deleting practicum report:', error);
        return { success: false, error: error.message || 'Gagal menghapus berita acara' };
    }
}

/**
 * Delete a practicum report as lecturer (only their courses)
 */
export async function lecturerDeletePracticumReport(id: number) {
    try {
        const session = await getSession();
        if (!session) throw new Error('Anda harus login');

        const belongs = await PracticumReportService.belongsToLecturer(id, session.user.identifier);
        if (!belongs) {
            throw new Error('Anda hanya dapat menghapus berita acara matakuliah yang Anda ampu');
        }

        await PracticumReportService.delete(id);

        revalidatePath('/lecturer/manage/scheduled-practicum');
        revalidatePath('/admin/scheduled-practicum');

        return { success: true };
    } catch (error: any) {
        console.error('Error deleting practicum report (lecturer):', error);
        return { success: false, error: error.message || 'Gagal menghapus berita acara' };
    }
}

/**
 * Delete all practicum reports (admin only)
 */
export async function deleteAllPracticumReports() {
    try {
        const session = await getSession();
        if (!session || session.user.roleId !== 1) {
            throw new Error('Hanya admin yang dapat menghapus semua berita acara');
        }

        await PracticumReportService.deleteAll();

        revalidatePath('/admin/scheduled-practicum');
        revalidatePath('/student/manage/scheduled-practicum');
        revalidatePath('/lecturer/manage/scheduled-practicum');

        return { success: true };
    } catch (error: any) {
        console.error('Error deleting all practicum reports:', error);
        return { success: false, error: error.message || 'Gagal menghapus semua berita acara' };
    }
}

'use client';

import { useState, useTransition } from 'react';
import { FileText, Eye, CheckCircle, XCircle, AlertCircle, Trash2, Check, X, AlertTriangle, Calendar, Clock, Users } from 'lucide-react';
import type { PracticumReportWithDetails, PracticumReportStatus, PracticumCondition } from '@/features/practicum-reports/types';
import { STATUS_COLORS, CONDITION_COLORS } from '@/features/practicum-reports/types';
import { verifyPracticumReport, deletePracticumReport, deleteAllPracticumReports } from '@/features/practicum-reports/actions';
import { useRouter } from 'next/navigation';

interface AdminPracticumReportTableProps {
    reports: PracticumReportWithDetails[];
}

const StatusIcon = ({ status }: { status: PracticumReportStatus | null }) => {
    switch (status) {
        case 'Diverifikasi': return <CheckCircle className="w-4 h-4" />;
        case 'Ditolak': return <XCircle className="w-4 h-4" />;
        default: return <AlertCircle className="w-4 h-4" />;
    }
};

export default function AdminPracticumReportTable({ reports }: AdminPracticumReportTableProps) {
    const router = useRouter();
    const [isPending, startTransition] = useTransition();
    const [selectedReport, setSelectedReport] = useState<PracticumReportWithDetails | null>(null);
    const [showRejectModal, setShowRejectModal] = useState(false);
    const [showDeleteModal, setShowDeleteModal] = useState(false);
    const [showDeleteAllModal, setShowDeleteAllModal] = useState(false);
    const [reportToDelete, setReportToDelete] = useState<PracticumReportWithDetails | null>(null);
    const [rejectionReason, setRejectionReason] = useState('');
    const [message, setMessage] = useState<{ type: 'success' | 'error'; text: string } | null>(null);

    const formatDate = (date: Date | string | null | undefined) => {
        if (!date) return '-';
        const d = typeof date === 'string' ? new Date(date) : date;
        if (isNaN(d.getTime())) return '-';
        return d.toLocaleDateString('id-ID', { day: 'numeric', month: 'short', year: 'numeric' });
    };

    const formatFullDate = (date: Date | string | null | undefined) => {
        if (!date) return '-';
        const d = typeof date === 'string' ? new Date(date) : date;
        if (isNaN(d.getTime())) return '-';
        const days = ['Minggu', 'Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat', 'Sabtu'];
        const months = ['Januari', 'Februari', 'Maret', 'April', 'Mei', 'Juni', 'Juli', 'Agustus', 'September', 'Oktober', 'November', 'Desember'];
        return `${days[d.getDay()]}, ${d.getDate()} ${months[d.getMonth()]} ${d.getFullYear()}`;
    };

    const handleVerify = (report: PracticumReportWithDetails) => {
        startTransition(async () => {
            const result = await verifyPracticumReport(report.id, { status: 'Diverifikasi' });
            if (result.success) {
                setMessage({ type: 'success', text: 'Berita acara berhasil diverifikasi!' });
                router.refresh();
            } else {
                setMessage({ type: 'error', text: result.error || 'Gagal memverifikasi' });
            }
        });
    };

    const handleReject = () => {
        if (!selectedReport || !rejectionReason.trim()) return;
        startTransition(async () => {
            const result = await verifyPracticumReport(selectedReport.id, {
                status: 'Ditolak',
                rejectionReason: rejectionReason.trim(),
            });
            if (result.success) {
                setMessage({ type: 'success', text: 'Berita acara berhasil ditolak!' });
                setShowRejectModal(false);
                setSelectedReport(null);
                setRejectionReason('');
                router.refresh();
            } else {
                setMessage({ type: 'error', text: result.error || 'Gagal menolak berita acara' });
            }
        });
    };

    const handleDelete = () => {
        if (!reportToDelete) return;
        startTransition(async () => {
            const result = await deletePracticumReport(reportToDelete.id);
            if (result.success) {
                setMessage({ type: 'success', text: 'Berita acara berhasil dihapus!' });
                setShowDeleteModal(false);
                setReportToDelete(null);
                router.refresh();
            } else {
                setMessage({ type: 'error', text: result.error || 'Gagal menghapus' });
            }
        });
    };

    const handleDeleteAll = () => {
        startTransition(async () => {
            const result = await deleteAllPracticumReports();
            if (result.success) {
                setMessage({ type: 'success', text: 'Semua berita acara berhasil dihapus!' });
                setShowDeleteAllModal(false);
                router.refresh();
            } else {
                setMessage({ type: 'error', text: result.error || 'Gagal menghapus semua berita acara' });
            }
        });
    };

    if (reports.length === 0) {
        return (
            <div className="text-center py-12">
                <div className="w-16 h-16 rounded-full bg-gray-100 flex items-center justify-center mx-auto mb-3">
                    <FileText className="w-7 h-7 text-gray-400" />
                </div>
                <p className="text-gray-500 font-medium">Belum ada berita acara</p>
                <p className="text-gray-400 text-sm mt-1">Berita acara akan muncul setelah asisten praktikum mengisi form</p>
            </div>
        );
    }

    return (
        <>
            {/* Message */}
            {message && (
                <div className={`mb-4 p-3 rounded-lg text-sm ${message.type === 'success' ? 'bg-green-50 text-green-700 border border-green-200' : 'bg-red-50 text-red-700 border border-red-200'}`}>
                    {message.text}
                </div>
            )}

            {/* Header Actions */}
            <div className="flex justify-between items-center mb-4">
                <p className="text-sm text-gray-500">{reports.length} berita acara ditemukan</p>
                <button
                    onClick={() => setShowDeleteAllModal(true)}
                    className="inline-flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium text-red-600 hover:bg-red-50 rounded-lg border border-red-200 transition-colors"
                >
                    <Trash2 className="w-3.5 h-3.5" />
                    Hapus Semua
                </button>
            </div>

            <div className="overflow-x-auto">
                <table className="w-full text-sm">
                    <thead>
                        <tr className="border-b border-gray-100">
                            <th className="text-left py-3 px-4 text-xs font-semibold text-gray-500 uppercase tracking-wider">Mata Kuliah</th>
                            <th className="text-left py-3 px-4 text-xs font-semibold text-gray-500 uppercase tracking-wider">Tanggal</th>
                            <th className="text-left py-3 px-4 text-xs font-semibold text-gray-500 uppercase tracking-wider">Pengisi</th>
                            <th className="text-left py-3 px-4 text-xs font-semibold text-gray-500 uppercase tracking-wider">Kondisi</th>
                            <th className="text-left py-3 px-4 text-xs font-semibold text-gray-500 uppercase tracking-wider">Status</th>
                            <th className="text-left py-3 px-4 text-xs font-semibold text-gray-500 uppercase tracking-wider">Aksi</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-50">
                        {reports.map((report) => (
                            <tr key={report.id} className="hover:bg-gray-50 transition-colors">
                                <td className="py-3 px-4">
                                    <p className="font-medium text-gray-900">{report.courseName}</p>
                                    <p className="text-xs text-blue-600 font-medium">{report.courseCode}</p>
                                </td>
                                <td className="py-3 px-4">
                                    <div className="flex items-center gap-1.5 text-gray-600 text-xs">
                                        <Calendar className="w-3.5 h-3.5 text-gray-400" />
                                        {formatDate(report.practicumDate)}
                                    </div>
                                    <div className="flex items-center gap-1.5 text-gray-500 text-xs mt-0.5">
                                        <Clock className="w-3 h-3 text-gray-400" />
                                        {report.startTime} - {report.endTime}
                                    </div>
                                </td>
                                <td className="py-3 px-4">
                                    <p className="text-sm text-gray-700">{report.createdByName || report.createdBy}</p>
                                </td>
                                <td className="py-3 px-4">
                                    <span className={`inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium ${CONDITION_COLORS[report.condition as PracticumCondition] || 'bg-gray-100 text-gray-700'}`}>
                                        {report.condition}
                                    </span>
                                </td>
                                <td className="py-3 px-4">
                                    <span className={`inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-medium ${STATUS_COLORS[(report.status || 'Pending') as PracticumReportStatus]}`}>
                                        <StatusIcon status={report.status as PracticumReportStatus | null} />
                                        {report.status || 'Pending'}
                                    </span>
                                </td>
                                <td className="py-3 px-4">
                                    <div className="flex items-center gap-1">
                                        <button
                                            onClick={() => setSelectedReport(report)}
                                            className="p-1.5 text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"
                                            title="Lihat Detail"
                                        >
                                            <Eye className="w-3.5 h-3.5" />
                                        </button>
                                        {(report.status === 'Pending' || report.status === 'Ditolak') && (
                                            <button
                                                onClick={() => handleVerify(report)}
                                                disabled={isPending}
                                                className="p-1.5 text-green-600 hover:bg-green-50 rounded-lg transition-colors disabled:opacity-50"
                                                title="Verifikasi"
                                            >
                                                <Check className="w-3.5 h-3.5" />
                                            </button>
                                        )}
                                        {(report.status === 'Pending' || report.status === 'Diverifikasi') && (
                                            <button
                                                onClick={() => { setSelectedReport(report); setShowRejectModal(true); }}
                                                disabled={isPending}
                                                className="p-1.5 text-orange-600 hover:bg-orange-50 rounded-lg transition-colors disabled:opacity-50"
                                                title="Tolak"
                                            >
                                                <X className="w-3.5 h-3.5" />
                                            </button>
                                        )}
                                        <button
                                            onClick={() => { setReportToDelete(report); setShowDeleteModal(true); }}
                                            disabled={isPending}
                                            className="p-1.5 text-red-500 hover:bg-red-50 rounded-lg transition-colors disabled:opacity-50"
                                            title="Hapus"
                                        >
                                            <Trash2 className="w-3.5 h-3.5" />
                                        </button>
                                    </div>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>

            {/* Detail Modal */}
            {selectedReport && !showRejectModal && (
                <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-[120] p-4">
                    <div className="bg-white rounded-xl shadow-xl max-w-2xl w-full max-h-[90vh] overflow-y-auto">
                        <div className="p-5 border-b border-gray-100 flex items-center justify-between bg-gradient-to-r from-blue-50 to-indigo-50">
                            <div className="flex items-center gap-3">
                                <div className="p-2 bg-blue-100 rounded-lg">
                                    <FileText className="w-5 h-5 text-blue-600" />
                                </div>
                                <div>
                                    <h3 className="text-lg font-bold text-gray-900">Detail Berita Acara</h3>
                                    <p className="text-sm text-blue-600">{selectedReport.courseCode} - {selectedReport.courseName}</p>
                                </div>
                            </div>
                            <button onClick={() => setSelectedReport(null)} className="text-gray-400 hover:text-gray-600 p-1">
                                <X className="w-5 h-5" />
                            </button>
                        </div>

                        <div className="p-6 space-y-5">
                            <div className="flex items-center gap-3">
                                <span className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-sm font-medium ${STATUS_COLORS[(selectedReport.status || 'Pending') as PracticumReportStatus]}`}>
                                    <StatusIcon status={selectedReport.status as PracticumReportStatus | null} />
                                    {selectedReport.status || 'Pending'}
                                </span>
                                {selectedReport.verifiedByName && (
                                    <span className="text-xs text-gray-500">oleh {selectedReport.verifiedByName}</span>
                                )}
                            </div>

                            {selectedReport.status === 'Ditolak' && selectedReport.rejectionReason && (
                                <div className="p-3 bg-red-50 border border-red-200 rounded-lg">
                                    <p className="text-sm font-medium text-red-700">Alasan Penolakan:</p>
                                    <p className="text-sm text-red-600 mt-1">{selectedReport.rejectionReason}</p>
                                </div>
                            )}

                            <div className="bg-gray-50 rounded-lg p-4 space-y-2">
                                <h4 className="text-sm font-semibold text-gray-700">Informasi Jadwal</h4>
                                <div className="grid grid-cols-2 gap-2 text-sm">
                                    <div><span className="text-gray-500">Tanggal:</span> <span className="font-medium">{formatFullDate(selectedReport.practicumDate)}</span></div>
                                    <div><span className="text-gray-500">Waktu:</span> <span className="font-medium">{selectedReport.startTime} - {selectedReport.endTime}</span></div>
                                    <div><span className="text-gray-500">Ruangan:</span> <span className="font-medium">{selectedReport.roomName}</span></div>
                                    <div><span className="text-gray-500">Dosen:</span> <span className="font-medium">{selectedReport.lecturerName || '-'}</span></div>
                                    <div><span className="text-gray-500">Pengisi:</span> <span className="font-medium">{selectedReport.createdByName || selectedReport.createdBy}</span></div>
                                </div>
                            </div>

                            <div className="space-y-3">
                                <div className="grid grid-cols-2 gap-3 text-sm">
                                    <div><span className="text-gray-500">Angkatan:</span> <span className="font-medium ml-1">{selectedReport.batch}</span></div>
                                    <div><span className="text-gray-500">Jumlah Hadir:</span> <span className="font-medium ml-1">{selectedReport.attendeeCount} orang</span></div>
                                    <div className="col-span-2">
                                        <span className="text-gray-500">Kondisi: </span>
                                        <span className={`inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium ml-1 ${CONDITION_COLORS[selectedReport.condition as PracticumCondition]}`}>
                                            {selectedReport.condition}
                                        </span>
                                    </div>
                                </div>
                                <div>
                                    <p className="text-xs font-semibold text-gray-500 uppercase tracking-wider mb-1">Deskripsi Pelaksanaan</p>
                                    <p className="text-sm text-gray-700 whitespace-pre-wrap">{selectedReport.description}</p>
                                </div>
                                {selectedReport.issues && (
                                    <div>
                                        <p className="text-xs font-semibold text-gray-500 uppercase tracking-wider mb-1">Kendala</p>
                                        <p className="text-sm text-gray-700 whitespace-pre-wrap">{selectedReport.issues}</p>
                                    </div>
                                )}
                                {selectedReport.followUp && (
                                    <div>
                                        <p className="text-xs font-semibold text-gray-500 uppercase tracking-wider mb-1">Tindak Lanjut</p>
                                        <p className="text-sm text-gray-700 whitespace-pre-wrap">{selectedReport.followUp}</p>
                                    </div>
                                )}
                            </div>

                            <div className="flex gap-3 pt-4 border-t border-gray-100">
                                {(selectedReport.status === 'Pending' || selectedReport.status === 'Ditolak') && (
                                    <button
                                        onClick={() => { handleVerify(selectedReport); setSelectedReport(null); }}
                                        disabled={isPending}
                                        className="flex items-center gap-1.5 px-4 py-2 bg-green-600 text-white rounded-lg text-sm font-medium hover:bg-green-700 disabled:opacity-50"
                                    >
                                        <Check className="w-4 h-4" />
                                        Verifikasi
                                    </button>
                                )}
                                {(selectedReport.status === 'Pending' || selectedReport.status === 'Diverifikasi') && (
                                    <button
                                        onClick={() => setShowRejectModal(true)}
                                        disabled={isPending}
                                        className="flex items-center gap-1.5 px-4 py-2 bg-orange-500 text-white rounded-lg text-sm font-medium hover:bg-orange-600 disabled:opacity-50"
                                    >
                                        <X className="w-4 h-4" />
                                        Tolak
                                    </button>
                                )}
                                <button
                                    onClick={() => setSelectedReport(null)}
                                    className="px-4 py-2 text-sm font-medium text-gray-600 hover:bg-gray-100 rounded-lg transition-colors"
                                >
                                    Tutup
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
            )}

            {/* Reject Modal */}
            {showRejectModal && selectedReport && (
                <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-[130] p-4">
                    <div className="bg-white rounded-xl shadow-xl max-w-md w-full p-6">
                        <h3 className="text-lg font-bold text-gray-900 mb-2">Tolak Berita Acara</h3>
                        <p className="text-sm text-gray-500 mb-4">
                            {selectedReport.courseCode} - {selectedReport.courseName}
                        </p>
                        <div className="mb-4">
                            <label className="block text-sm font-medium text-gray-700 mb-1">
                                Alasan Penolakan <span className="text-red-500">*</span>
                            </label>
                            <textarea
                                rows={3}
                                value={rejectionReason}
                                onChange={e => setRejectionReason(e.target.value)}
                                placeholder="Tuliskan alasan penolakan..."
                                className="w-full px-4 py-2.5 rounded-lg border border-gray-200 focus:outline-none focus:ring-2 focus:ring-red-200 resize-none text-sm"
                            />
                        </div>
                        <div className="flex gap-3">
                            <button
                                onClick={handleReject}
                                disabled={isPending || !rejectionReason.trim()}
                                className="flex-1 bg-red-600 text-white px-4 py-2.5 rounded-lg text-sm font-medium hover:bg-red-700 disabled:opacity-50"
                            >
                                {isPending ? 'Menolak...' : 'Tolak'}
                            </button>
                            <button
                                onClick={() => { setShowRejectModal(false); setRejectionReason(''); }}
                                className="px-4 py-2.5 text-sm font-medium text-gray-600 hover:bg-gray-100 rounded-lg"
                            >
                                Batal
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* Delete Confirm Modal */}
            {showDeleteModal && reportToDelete && (
                <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-[130] p-4">
                    <div className="bg-white rounded-xl shadow-xl max-w-md w-full p-6">
                        <div className="flex items-center gap-3 mb-4">
                            <div className="p-2 bg-red-100 rounded-lg">
                                <AlertTriangle className="w-5 h-5 text-red-600" />
                            </div>
                            <h3 className="text-lg font-bold text-gray-900">Hapus Berita Acara?</h3>
                        </div>
                        <p className="text-sm text-gray-600 mb-6">
                            Berita acara <strong>{reportToDelete.courseCode} - {reportToDelete.courseName}</strong> akan dihapus permanen.
                        </p>
                        <div className="flex gap-3">
                            <button
                                onClick={handleDelete}
                                disabled={isPending}
                                className="flex-1 bg-red-600 text-white px-4 py-2.5 rounded-lg text-sm font-medium hover:bg-red-700 disabled:opacity-50"
                            >
                                {isPending ? 'Menghapus...' : 'Hapus'}
                            </button>
                            <button
                                onClick={() => { setShowDeleteModal(false); setReportToDelete(null); }}
                                className="px-4 py-2.5 text-sm font-medium text-gray-600 hover:bg-gray-100 rounded-lg"
                            >
                                Batal
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* Delete All Confirm Modal */}
            {showDeleteAllModal && (
                <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-[130] p-4">
                    <div className="bg-white rounded-xl shadow-xl max-w-md w-full p-6">
                        <div className="flex items-center gap-3 mb-4">
                            <div className="p-2 bg-red-100 rounded-lg">
                                <AlertTriangle className="w-5 h-5 text-red-600" />
                            </div>
                            <h3 className="text-lg font-bold text-gray-900">Hapus Semua?</h3>
                        </div>
                        <p className="text-sm text-gray-600 mb-6">
                            Semua <strong>{reports.length} berita acara</strong> akan dihapus permanen. Tindakan ini tidak dapat dibatalkan.
                        </p>
                        <div className="flex gap-3">
                            <button
                                onClick={handleDeleteAll}
                                disabled={isPending}
                                className="flex-1 bg-red-600 text-white px-4 py-2.5 rounded-lg text-sm font-medium hover:bg-red-700 disabled:opacity-50"
                            >
                                {isPending ? 'Menghapus...' : 'Hapus Semua'}
                            </button>
                            <button
                                onClick={() => setShowDeleteAllModal(false)}
                                className="px-4 py-2.5 text-sm font-medium text-gray-600 hover:bg-gray-100 rounded-lg"
                            >
                                Batal
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </>
    );
}

'use client';

import { useState, useTransition } from 'react';
import { Upload, FileText, Trash2, Download, X, ChevronDown } from 'lucide-react';
import { uploadPracticumLpjDoc, deletePracticumLpjDoc } from '@/features/practicum-reports/lpj-actions';

const MONTHS = [
    'Januari', 'Februari', 'Maret', 'April', 'Mei', 'Juni',
    'Juli', 'Agustus', 'September', 'Oktober', 'November', 'Desember',
];

interface Schedule {
    id: number;
    courseName: string;
    courseCode: string;
}

interface LpjDoc {
    id: number;
    scheduledPracticumId: number;
    title: string;
    description: string | null;
    filePath: string;
    periodMonth: number;
    periodYear: number;
    createdAt: Date | null;
    uploaderName: string | null;
    uploaderId: string;
}

interface AllPracticumLpjManagerProps {
    schedules: Schedule[];
    initialDocs: LpjDoc[];
    currentUserId: string;
    isAdmin?: boolean;
}

export default function AllPracticumLpjManager({
    schedules,
    initialDocs,
    currentUserId,
    isAdmin = false,
}: AllPracticumLpjManagerProps) {
    const [isPending, startTransition] = useTransition();
    const [docs, setDocs] = useState(initialDocs);
    const [showForm, setShowForm] = useState(false);
    const [message, setMessage] = useState<{ type: 'success' | 'error'; text: string } | null>(null);

    const now = new Date();
    const [title, setTitle] = useState('');
    const [description, setDescription] = useState('');
    const [selectedScheduleId, setSelectedScheduleId] = useState<string>('');
    const [periodMonth, setPeriodMonth] = useState(now.getMonth() + 1);
    const [periodYear, setPeriodYear] = useState(now.getFullYear());
    const [file, setFile] = useState<File | null>(null);

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (!file) { setMessage({ type: 'error', text: 'Pilih file terlebih dahulu' }); return; }
        if (!selectedScheduleId) { setMessage({ type: 'error', text: 'Pilih jadwal praktikum' }); return; }

        const fd = new FormData();
        fd.append('file', file);
        fd.append('title', title);
        fd.append('description', description);
        fd.append('scheduledPracticumId', selectedScheduleId);
        fd.append('periodMonth', String(periodMonth));
        fd.append('periodYear', String(periodYear));

        startTransition(async () => {
            const res = await uploadPracticumLpjDoc(fd);
            if (res.success) {
                setMessage({ type: 'success', text: 'LPJ berhasil diunggah!' });
                setShowForm(false);
                setTitle('');
                setDescription('');
                setFile(null);
                setSelectedScheduleId('');
                window.location.reload();
            } else {
                setMessage({ type: 'error', text: res.error || 'Gagal mengunggah' });
            }
        });
    };

    const handleDelete = (id: number) => {
        if (!confirm('Hapus dokumen LPJ ini?')) return;
        startTransition(async () => {
            const res = await deletePracticumLpjDoc(id);
            if (res.success) {
                setDocs(prev => prev.filter(d => d.id !== id));
                setMessage({ type: 'success', text: 'Dokumen berhasil dihapus' });
            } else {
                setMessage({ type: 'error', text: res.error || 'Gagal menghapus' });
            }
        });
    };

    const currentYear = now.getFullYear();
    const yearOptions = Array.from({ length: 5 }, (_, i) => currentYear - 2 + i);

    const scheduleMap = new Map(schedules.map(s => [s.id, s]));

    return (
        <div className="space-y-4">
            {/* Header */}
            <div className="flex items-center justify-between">
                <div>
                    <h2 className="text-lg font-bold text-gray-900">LPJ Praktikum</h2>
                    <p className="text-sm text-gray-500 mt-0.5">Laporan pertanggungjawaban per jadwal praktikum</p>
                </div>
                <button
                    onClick={() => { setShowForm(v => !v); setMessage(null); }}
                    className="flex items-center gap-1.5 px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white text-sm font-medium rounded-lg transition-colors"
                >
                    {showForm ? <X className="w-4 h-4" /> : <Upload className="w-4 h-4" />}
                    {showForm ? 'Tutup Form' : 'Upload LPJ Baru'}
                </button>
            </div>

            {/* Message */}
            {message && (
                <div className={`flex items-center gap-2 p-3 rounded-lg text-sm ${message.type === 'success' ? 'bg-green-50 text-green-700 border border-green-200' : 'bg-red-50 text-red-700 border border-red-200'}`}>
                    <span className="flex-1">{message.text}</span>
                    <button onClick={() => setMessage(null)}><X className="w-4 h-4" /></button>
                </div>
            )}

            {/* Upload Form */}
            {showForm && (
                <div className="bg-gray-50 border border-gray-200 rounded-xl p-5 space-y-4">
                    <h3 className="font-semibold text-gray-800">Form Upload LPJ</h3>
                    <form onSubmit={handleSubmit} className="space-y-4">
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Jadwal Praktikum *</label>
                            <select
                                value={selectedScheduleId}
                                onChange={e => setSelectedScheduleId(e.target.value)}
                                required
                                className="w-full border border-gray-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
                            >
                                <option value="">-- Pilih Jadwal --</option>
                                {schedules.map(s => (
                                    <option key={s.id} value={s.id}>{s.courseCode} – {s.courseName}</option>
                                ))}
                            </select>
                        </div>

                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Judul LPJ *</label>
                            <input
                                type="text"
                                value={title}
                                onChange={e => setTitle(e.target.value)}
                                required
                                placeholder="Contoh: LPJ Praktikum Basis Data Mei 2026"
                                className="w-full border border-gray-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
                            />
                        </div>

                        <div className="grid grid-cols-2 gap-3">
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">Bulan *</label>
                                <select
                                    value={periodMonth}
                                    onChange={e => setPeriodMonth(parseInt(e.target.value))}
                                    className="w-full border border-gray-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
                                >
                                    {MONTHS.map((m, i) => (
                                        <option key={i + 1} value={i + 1}>{m}</option>
                                    ))}
                                </select>
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">Tahun *</label>
                                <select
                                    value={periodYear}
                                    onChange={e => setPeriodYear(parseInt(e.target.value))}
                                    className="w-full border border-gray-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
                                >
                                    {yearOptions.map(y => <option key={y} value={y}>{y}</option>)}
                                </select>
                            </div>
                        </div>

                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Keterangan</label>
                            <textarea
                                value={description}
                                onChange={e => setDescription(e.target.value)}
                                rows={2}
                                placeholder="Keterangan tambahan (opsional)"
                                className="w-full border border-gray-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 resize-none"
                            />
                        </div>

                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">
                                File LPJ * <span className="text-gray-400 font-normal">(PDF/DOC/DOCX, maks 10MB)</span>
                            </label>
                            <input
                                type="file"
                                accept=".pdf,.doc,.docx"
                                onChange={e => setFile(e.target.files?.[0] || null)}
                                required
                                className="w-full text-sm text-gray-500 file:mr-3 file:py-1.5 file:px-3 file:rounded-lg file:border-0 file:text-xs file:font-medium file:bg-blue-50 file:text-blue-700 hover:file:bg-blue-100"
                            />
                        </div>

                        <div className="flex gap-2 pt-1">
                            <button
                                type="submit"
                                disabled={isPending}
                                className="flex items-center gap-2 px-4 py-2 bg-blue-600 hover:bg-blue-700 disabled:opacity-60 text-white text-sm font-medium rounded-lg transition-colors"
                            >
                                {isPending
                                    ? <span className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" />
                                    : <Upload className="w-4 h-4" />
                                }
                                {isPending ? 'Mengunggah...' : 'Upload LPJ'}
                            </button>
                            <button
                                type="button"
                                onClick={() => { setShowForm(false); setMessage(null); }}
                                className="px-4 py-2 border border-gray-200 text-gray-600 text-sm rounded-lg hover:bg-gray-50 transition-colors"
                            >
                                Batal
                            </button>
                        </div>
                    </form>
                </div>
            )}

            {/* Document List */}
            <div className="bg-white rounded-xl border border-gray-100 overflow-hidden">
                {docs.length === 0 ? (
                    <div className="text-center py-12">
                        <div className="w-14 h-14 rounded-full bg-gray-100 flex items-center justify-center mx-auto mb-3">
                            <FileText className="w-6 h-6 text-gray-400" />
                        </div>
                        <p className="text-gray-500 font-medium text-sm">Belum ada LPJ</p>
                        <p className="text-gray-400 text-xs mt-1">Klik "Upload LPJ Baru" untuk mulai mengunggah</p>
                    </div>
                ) : (
                    <div className="divide-y divide-gray-50">
                        {docs.map(doc => {
                            const sched = scheduleMap.get(doc.scheduledPracticumId);
                            const canDelete = isAdmin || doc.uploaderId === currentUserId;
                            return (
                                <div key={doc.id} className="flex items-center gap-3 px-4 py-3 hover:bg-gray-50 transition-colors">
                                    <div className="p-2 bg-blue-50 rounded-lg shrink-0">
                                        <FileText className="w-4 h-4 text-blue-600" />
                                    </div>
                                    <div className="flex-1 min-w-0">
                                        <p className="text-sm font-medium text-gray-900 truncate">{doc.title}</p>
                                        <div className="flex flex-wrap gap-x-3 gap-y-0.5 mt-0.5">
                                            <span className="text-xs text-blue-700 font-medium">
                                                {sched ? `${sched.courseCode} – ${sched.courseName}` : `Jadwal #${doc.scheduledPracticumId}`}
                                            </span>
                                            <span className="text-xs text-gray-500">
                                                {MONTHS[doc.periodMonth - 1]} {doc.periodYear}
                                            </span>
                                            <span className="text-xs text-gray-400">
                                                oleh {doc.uploaderName || 'Unknown'}
                                            </span>
                                        </div>
                                        {doc.description && (
                                            <p className="text-xs text-gray-500 mt-0.5 truncate">{doc.description}</p>
                                        )}
                                    </div>
                                    <div className="flex items-center gap-1 shrink-0">
                                        <a
                                            href={doc.filePath}
                                            target="_blank"
                                            rel="noopener noreferrer"
                                            className="p-1.5 text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"
                                            title="Unduh"
                                        >
                                            <Download className="w-4 h-4" />
                                        </a>
                                        {canDelete && (
                                            <button
                                                onClick={() => handleDelete(doc.id)}
                                                disabled={isPending}
                                                className="p-1.5 text-red-500 hover:bg-red-50 rounded-lg transition-colors disabled:opacity-50"
                                                title="Hapus"
                                            >
                                                <Trash2 className="w-4 h-4" />
                                            </button>
                                        )}
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                )}
            </div>
        </div>
    );
}

'use client';

import { useState, useTransition } from 'react';
import { FileText, Clock, MapPin, BookOpen, CheckCircle, AlertCircle, Plus, ChevronLeft, ChevronRight, Download, Calendar } from 'lucide-react';
import type { ScheduledPracticumWithDetails } from '@/features/scheduled-practicum/types';
import type { PracticumReport } from '@/features/practicum-reports/types';
import { STATUS_COLORS } from '@/features/practicum-reports/types';
import PracticumReportForm from './PracticumReportForm';
import PracticumReportTable from './PracticumReportTable';
import { useRouter } from 'next/navigation';

interface BeritaAcaraManagerProps {
    schedules: ScheduledPracticumWithDetails[];
    myReports: PracticumReport[];
    reportedScheduleIds: number[];
}

const MONTH_NAMES = [
    'Januari', 'Februari', 'Maret', 'April', 'Mei', 'Juni',
    'Juli', 'Agustus', 'September', 'Oktober', 'November', 'Desember',
];
const CAL_HEADERS = ['Sen', 'Sel', 'Rab', 'Kam', 'Jum', 'Sab', 'Min'];
const DAY_NAMES = ['Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat', 'Sabtu', 'Minggu'];

function getCalendarDays(year: number, month: number) {
    const firstDay = new Date(year, month, 1);
    let startPad = firstDay.getDay() - 1;
    if (startPad < 0) startPad = 6;
    const daysInMonth = new Date(year, month + 1, 0).getDate();
    const daysInPrev = new Date(year, month, 0).getDate();
    const days: { date: Date; isCurrentMonth: boolean }[] = [];
    for (let i = startPad - 1; i >= 0; i--)
        days.push({ date: new Date(year, month - 1, daysInPrev - i), isCurrentMonth: false });
    for (let d = 1; d <= daysInMonth; d++)
        days.push({ date: new Date(year, month, d), isCurrentMonth: true });
    const remaining = 42 - days.length;
    for (let d = 1; d <= remaining; d++)
        days.push({ date: new Date(year, month + 1, d), isCurrentMonth: false });
    return days;
}

function jsDayToOurDay(jsDay: number) { return jsDay === 0 ? 6 : jsDay - 1; }

function toDateKey(d: Date | string) {
    const dt = typeof d === 'string' ? new Date(d) : d;
    return `${dt.getFullYear()}-${String(dt.getMonth() + 1).padStart(2, '0')}-${String(dt.getDate()).padStart(2, '0')}`;
}

export default function BeritaAcaraManager({ schedules, myReports, reportedScheduleIds }: BeritaAcaraManagerProps) {
    const router = useRouter();
    const now = new Date();
    const [year, setYear] = useState(now.getFullYear());
    const [month, setMonth] = useState(now.getMonth());
    const [selectedDate, setSelectedDate] = useState<Date | null>(null);

    const [showForm, setShowForm] = useState(false);
    const [selectedSchedule, setSelectedSchedule] = useState<ScheduledPracticumWithDetails | null>(null);

    // Download state
    const [downloadPeriod, setDownloadPeriod] = useState<'harian' | 'mingguan' | 'bulanan' | 'custom'>('bulanan');
    const [downloadStartDate, setDownloadStartDate] = useState('');
    const [downloadEndDate, setDownloadEndDate] = useState('');
    const [isDownloading, setIsDownloading] = useState(false);

    const handleDownload = async () => {
        setIsDownloading(true);
        try {
            const params = new URLSearchParams({ period: downloadPeriod });
            if (downloadPeriod === 'custom') {
                if (!downloadStartDate || !downloadEndDate) {
                    alert('Pilih tanggal mulai dan akhir untuk periode kustom');
                    return;
                }
                params.set('startDate', downloadStartDate);
                params.set('endDate', downloadEndDate);
            } else {
                params.set('date', new Date().toISOString());
            }
            const url = `/api/berita-acara/download?${params.toString()}`;
            const res = await fetch(url);
            if (!res.ok) throw new Error('Gagal mengunduh');
            const blob = await res.blob();
            const a = document.createElement('a');
            a.href = URL.createObjectURL(blob);
            const period: Record<string, string> = { harian: 'Harian', mingguan: 'Mingguan', bulanan: 'Bulanan', custom: 'Kustom' };
            a.download = `Berita_Acara_${period[downloadPeriod]}_${new Date().toISOString().slice(0, 10)}.xlsx`;
            a.click();
            URL.revokeObjectURL(a.href);
        } catch {
            alert('Gagal mengunduh file. Silakan coba lagi.');
        } finally {
            setIsDownloading(false);
        }
    };

    const reportedIds = new Set(reportedScheduleIds);

    // Map: dateKey → schedules
    const dateMap = new Map<string, ScheduledPracticumWithDetails[]>();
    for (const s of schedules) {
        if (s.scheduledDate) {
            const key = toDateKey(s.scheduledDate);
            if (!dateMap.has(key)) dateMap.set(key, []);
            dateMap.get(key)!.push(s);
        }
    }

    const calendarDays = getCalendarDays(year, month);

    const prevMonth = () => { if (month === 0) { setMonth(11); setYear(y => y - 1); } else setMonth(m => m - 1); };
    const nextMonth = () => { if (month === 11) { setMonth(0); setYear(y => y + 1); } else setMonth(m => m + 1); };

    const selectedSchedules = selectedDate ? (dateMap.get(toDateKey(selectedDate)) || []) : [];

    const openForm = (schedule: ScheduledPracticumWithDetails) => {
        setSelectedSchedule(schedule);
        setShowForm(true);
    };

    const handleSuccess = () => {
        router.refresh();
    };

    return (
        <div className="space-y-6">
            <div className="flex flex-col sm:flex-row sm:items-start sm:justify-between gap-4">
                <div>
                    <h1 className="text-2xl font-bold text-gray-900">Berita Acara Praktikum</h1>
                    <p className="text-gray-500 text-sm mt-1">Isi berita acara untuk jadwal praktikum yang telah berlangsung</p>
                </div>

                {/* Download Panel */}
                <div className="flex flex-col gap-2 bg-white border border-gray-200 rounded-xl p-3 shadow-sm shrink-0">
                    <div className="flex items-center gap-2">
                        <Download className="w-4 h-4 text-gray-500" />
                        <span className="text-sm font-semibold text-gray-700">Unduh Riwayat (Excel)</span>
                    </div>
                    <div className="flex flex-wrap items-center gap-2">
                        <select
                            value={downloadPeriod}
                            onChange={e => setDownloadPeriod(e.target.value as any)}
                            className="text-sm border border-gray-200 rounded-lg px-2 py-1.5 focus:outline-none focus:ring-2 focus:ring-blue-500"
                        >
                            <option value="harian">Harian (hari ini)</option>
                            <option value="mingguan">Mingguan (minggu ini)</option>
                            <option value="bulanan">Bulanan (bulan ini)</option>
                            <option value="custom">Kustom (pilih rentang)</option>
                        </select>
                        {downloadPeriod === 'custom' && (
                            <div className="flex items-center gap-1 flex-wrap">
                                <input
                                    type="date"
                                    value={downloadStartDate}
                                    onChange={e => setDownloadStartDate(e.target.value)}
                                    className="text-sm border border-gray-200 rounded-lg px-2 py-1.5 focus:outline-none focus:ring-2 focus:ring-blue-500"
                                />
                                <span className="text-gray-400">–</span>
                                <input
                                    type="date"
                                    value={downloadEndDate}
                                    onChange={e => setDownloadEndDate(e.target.value)}
                                    className="text-sm border border-gray-200 rounded-lg px-2 py-1.5 focus:outline-none focus:ring-2 focus:ring-blue-500"
                                />
                            </div>
                        )}
                        <button
                            onClick={handleDownload}
                            disabled={isDownloading}
                            className="flex items-center gap-1.5 px-3 py-1.5 bg-green-600 hover:bg-green-700 disabled:opacity-60 text-white text-sm font-medium rounded-lg transition-colors whitespace-nowrap"
                        >
                            {isDownloading
                                ? <span className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" />
                                : <Download className="w-4 h-4" />
                            }
                            {isDownloading ? 'Mengunduh...' : 'Unduh'}
                        </button>
                    </div>
                </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                {/* Calendar */}
                <div className="lg:col-span-2">
                    <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
                        <div className="px-5 py-4 border-b border-gray-100 flex items-center justify-between bg-gradient-to-r from-blue-50 to-indigo-50">
                            <button onClick={prevMonth} className="p-1.5 hover:bg-white/70 rounded-lg transition-colors">
                                <ChevronLeft className="w-5 h-5 text-gray-600" />
                            </button>
                            <div className="text-center">
                                <h2 className="text-lg font-bold text-gray-900">{MONTH_NAMES[month]} {year}</h2>
                                <button onClick={() => { setYear(now.getFullYear()); setMonth(now.getMonth()); }} className="text-xs text-blue-600 hover:underline mt-0.5">
                                    Hari Ini
                                </button>
                            </div>
                            <button onClick={nextMonth} className="p-1.5 hover:bg-white/70 rounded-lg transition-colors">
                                <ChevronRight className="w-5 h-5 text-gray-600" />
                            </button>
                        </div>

                        <div className="grid grid-cols-7 bg-gray-50 border-b border-gray-100">
                            {CAL_HEADERS.map(d => (
                                <div key={d} className="py-2.5 text-center text-xs font-semibold text-gray-500 uppercase tracking-wider">{d}</div>
                            ))}
                        </div>

                        <div className="grid grid-cols-7">
                            {calendarDays.map((cell, idx) => {
                                const daySchedules = dateMap.get(toDateKey(cell.date)) || [];
                                const has = daySchedules.length > 0;
                                const today = cell.date.toDateString() === now.toDateString();
                                const selected = selectedDate?.toDateString() === cell.date.toDateString();

                                return (
                                    <button
                                        key={idx}
                                        type="button"
                                        onClick={() => setSelectedDate(cell.date)}
                                        className={`
                                            relative min-h-[72px] p-1.5 border-b border-r border-gray-100 text-left transition-all duration-150 group
                                            ${!cell.isCurrentMonth ? 'bg-gray-50/60' : ''}
                                            ${selected ? 'ring-2 ring-blue-500 ring-inset z-10' : ''}
                                            ${has && cell.isCurrentMonth ? 'bg-blue-50 hover:bg-blue-100' : 'hover:bg-gray-50'}
                                        `}
                                    >
                                        <div className="flex items-center justify-between">
                                            <span className={`
                                                inline-flex items-center justify-center w-7 h-7 rounded-full text-sm font-medium
                                                ${today ? 'bg-blue-600 text-white shadow-sm'
                                                    : cell.isCurrentMonth
                                                        ? has ? 'text-blue-800 font-semibold' : 'text-gray-700'
                                                        : 'text-gray-400'
                                                }
                                            `}>
                                                {cell.date.getDate()}
                                            </span>
                                            {has && cell.isCurrentMonth && (
                                                <span className="inline-flex items-center justify-center w-5 h-5 rounded-full bg-blue-600 text-white text-[10px] font-bold">
                                                    {daySchedules.length}
                                                </span>
                                            )}
                                        </div>
                                        {has && cell.isCurrentMonth && (
                                            <div className="mt-1 space-y-0.5">
                                                {daySchedules.slice(0, 2).map(s => (
                                                    <div key={s.id} className={`text-[10px] leading-tight px-1.5 py-0.5 rounded-sm truncate font-medium ${reportedIds.has(s.id) ? 'bg-green-600/15 text-green-800' : 'bg-blue-600/15 text-blue-800'}`}>
                                                        {s.courseCode}
                                                    </div>
                                                ))}
                                                {daySchedules.length > 2 && (
                                                    <div className="text-[10px] text-blue-600 px-1.5 font-medium">+{daySchedules.length - 2} lagi</div>
                                                )}
                                            </div>
                                        )}
                                    </button>
                                );
                            })}
                        </div>

                        <div className="px-5 py-3 bg-gray-50 border-t border-gray-100 flex items-center gap-4 text-xs text-gray-500">
                            <span className="flex items-center gap-1.5">
                                <span className="w-3 h-3 rounded-sm bg-blue-50 border border-blue-300" />
                                Ada jadwal
                            </span>
                            <span className="flex items-center gap-1.5">
                                <span className="w-3 h-3 rounded-sm bg-green-600/15 border border-green-300" />
                                Sudah diisi
                            </span>
                        </div>
                    </div>
                </div>

                {/* Detail Panel */}
                <div className="lg:col-span-1">
                    <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden sticky top-8">
                        <div className="px-5 py-4 bg-gradient-to-r from-blue-50 to-indigo-50 border-b border-gray-100">
                            {selectedDate ? (
                                <div>
                                    <p className="text-xs text-blue-600 font-semibold uppercase tracking-wider">Detail Tanggal</p>
                                    <h3 className="text-lg font-bold text-gray-900 mt-0.5">
                                        {DAY_NAMES[jsDayToOurDay(selectedDate.getDay())]}, {selectedDate.getDate()} {MONTH_NAMES[selectedDate.getMonth()]}
                                    </h3>
                                    <p className="text-xs text-gray-500">{selectedDate.getFullYear()}</p>
                                </div>
                            ) : (
                                <div>
                                    <p className="text-xs text-blue-600 font-semibold uppercase tracking-wider">Berita Acara</p>
                                    <p className="text-sm text-gray-500 mt-1">Pilih tanggal untuk melihat jadwal</p>
                                </div>
                            )}
                        </div>

                        <div className="p-4">
                            {selectedDate ? (
                                selectedSchedules.length > 0 ? (
                                    <div className="space-y-3">
                                        {selectedSchedules.map(s => {
                                            const alreadyFilled = reportedIds.has(s.id);
                                            return (
                                                <div key={s.id} className={`rounded-lg border p-3 ${alreadyFilled ? 'border-green-100 bg-green-50/50' : 'border-blue-100 bg-blue-50/50'}`}>
                                                    <div className="flex items-start gap-2">
                                                        <div className={`w-1 self-stretch rounded-full shrink-0 mt-0.5 ${alreadyFilled ? 'bg-green-500' : 'bg-blue-500'}`} />
                                                        <div className="flex-1 min-w-0">
                                                            <p className="font-semibold text-gray-900 text-sm">{s.courseName}</p>
                                                            <p className={`text-xs font-medium ${alreadyFilled ? 'text-green-700' : 'text-blue-700'}`}>{s.courseCode}</p>
                                                            {s.moduleName && (
                                                                <p className="text-xs text-emerald-600 mt-1 flex items-center gap-1">
                                                                    <BookOpen className="w-3 h-3" />
                                                                    {s.moduleName}
                                                                </p>
                                                            )}
                                                            <div className="flex flex-col gap-1 mt-2 text-xs text-gray-600">
                                                                <span className="inline-flex items-center gap-1">
                                                                    <Clock className={`w-3 h-3 ${alreadyFilled ? 'text-green-600' : 'text-blue-600'}`} />
                                                                    {s.startTime} – {s.endTime}
                                                                </span>
                                                                <span className="inline-flex items-center gap-1">
                                                                    <MapPin className={`w-3 h-3 ${alreadyFilled ? 'text-green-600' : 'text-blue-600'}`} />
                                                                    {s.roomName}
                                                                </span>
                                                            </div>
                                                        </div>
                                                    </div>
                                                    {alreadyFilled ? (
                                                        <div className="mt-3 flex items-center gap-1.5 text-xs text-green-700 font-medium">
                                                            <CheckCircle className="w-3.5 h-3.5" />
                                                            Berita acara sudah diisi
                                                        </div>
                                                    ) : (
                                                        <button
                                                            onClick={() => openForm(s)}
                                                            className="mt-3 w-full flex items-center justify-center gap-1.5 px-3 py-2 bg-blue-600 text-white text-xs font-medium rounded-lg hover:bg-blue-700 transition-colors"
                                                        >
                                                            <Plus className="w-3.5 h-3.5" />
                                                            Isi Berita Acara
                                                        </button>
                                                    )}
                                                </div>
                                            );
                                        })}
                                    </div>
                                ) : (
                                    <div className="text-center py-6">
                                        <div className="w-12 h-12 rounded-full bg-gray-100 flex items-center justify-center mx-auto mb-3">
                                            <FileText className="w-5 h-5 text-gray-400" />
                                        </div>
                                        <p className="text-sm text-gray-500">Tidak ada jadwal di tanggal ini</p>
                                    </div>
                                )
                            ) : (
                                <div className="text-center py-8">
                                    <div className="w-16 h-16 rounded-full bg-blue-50 flex items-center justify-center mx-auto mb-3">
                                        <FileText className="w-7 h-7 text-blue-400" />
                                    </div>
                                    <p className="text-sm text-gray-400">Klik tanggal pada kalender</p>
                                </div>
                            )}
                        </div>
                    </div>
                </div>
            </div>

            {/* Riwayat Berita Acara */}
            {myReports.length > 0 && (
                <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
                    <div className="px-5 py-4 border-b border-gray-100 bg-gradient-to-r from-blue-50 to-indigo-50">
                        <div className="flex items-center gap-3">
                            <div className="p-2 bg-blue-100 rounded-lg">
                                <FileText className="w-5 h-5 text-blue-600" />
                            </div>
                            <div>
                                <h2 className="text-lg font-bold text-gray-900">Riwayat Berita Acara</h2>
                                <p className="text-sm text-gray-500">Berita acara yang telah Anda isi</p>
                            </div>
                        </div>
                    </div>
                    <div className="p-4">
                        <PracticumReportTable reports={myReports} />
                    </div>
                </div>
            )}

            {/* Form Modal */}
            {showForm && selectedSchedule && (
                <PracticumReportForm
                    isOpen={showForm}
                    onClose={() => { setShowForm(false); setSelectedSchedule(null); }}
                    schedule={selectedSchedule}
                    onSuccess={handleSuccess}
                />
            )}
        </div>
    );
}

'use client';

import { useState, useTransition } from 'react';
import { FileText, Eye, Calendar, Clock, Users, CheckCircle, XCircle, AlertCircle, Check, X, Trash2, AlertTriangle } from 'lucide-react';
import type { PracticumReportWithDetails, PracticumReportStatus, PracticumCondition } from '@/features/practicum-reports/types';
import { lecturerVerifyPracticumReport, lecturerDeletePracticumReport } from '@/features/practicum-reports/actions';
import { useRouter } from 'next/navigation';
import ViewportPortal from '@/components/shared/ViewportPortal';

interface LecturerPracticumReportTableProps {
    reports: PracticumReportWithDetails[];
}

const statusColors: Record<PracticumReportStatus, string> = {
    'Pending': 'bg-yellow-100 text-yellow-800',
    'Diverifikasi': 'bg-green-100 text-green-800',
    'Ditolak': 'bg-red-100 text-red-800',
};

const conditionColors: Record<PracticumCondition, string> = {
    'Lancar': 'bg-green-100 text-green-800',
    'Kurang Lancar': 'bg-yellow-100 text-yellow-800',
    'Terkendala': 'bg-red-100 text-red-800',
};

const StatusIcon = ({ status }: { status: PracticumReportStatus }) => {
    switch (status) {
        case 'Diverifikasi': return <CheckCircle className="w-4 h-4" />;
        case 'Ditolak': return <XCircle className="w-4 h-4" />;
        default: return <AlertCircle className="w-4 h-4" />;
    }
};

export default function LecturerPracticumReportTable({ reports }: LecturerPracticumReportTableProps) {
    const router = useRouter();
    const [isPending, startTransition] = useTransition();
    const [selectedReport, setSelectedReport] = useState<PracticumReportWithDetails | null>(null);
    const [showRejectModal, setShowRejectModal] = useState(false);
    const [showDeleteModal, setShowDeleteModal] = useState(false);
    const [reportToDelete, setReportToDelete] = useState<PracticumReportWithDetails | null>(null);
    const [rejectionReason, setRejectionReason] = useState('');
    const [message, setMessage] = useState<{ type: 'success' | 'error'; text: string } | null>(null);

    const formatDate = (date: Date | string | null | undefined) => {
        if (!date) return '-';
        const d = typeof date === 'string' ? new Date(date) : date;
        if (isNaN(d.getTime())) return '-';
        return d.toLocaleDateString('id-ID', { day: 'numeric', month: 'short', year: 'numeric' });
    };

    const formatFullDate = (date: Date | string | null | undefined) => {
        if (!date) return '-';
        const d = typeof date === 'string' ? new Date(date) : date;
        if (isNaN(d.getTime())) return '-';
        const days = ['Minggu', 'Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat', 'Sabtu'];
        const months = ['Januari', 'Februari', 'Maret', 'April', 'Mei', 'Juni', 'Juli', 'Agustus', 'September', 'Oktober', 'November', 'Desember'];
        return `${days[d.getDay()]}, ${d.getDate()} ${months[d.getMonth()]} ${d.getFullYear()}`;
    };

    const formatDateTime = (date: Date | string | null | undefined) => {
        if (!date) return '-';
        const d = typeof date === 'string' ? new Date(date) : date;
        if (isNaN(d.getTime())) return '-';
        return d.toLocaleString('id-ID', { day: 'numeric', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' });
    };

    const handleVerify = (report: PracticumReportWithDetails) => {
        startTransition(async () => {
            const result = await lecturerVerifyPracticumReport(report.id, { status: 'Diverifikasi' });
            if (result.success) {
                setMessage({ type: 'success', text: 'Berita acara berhasil diverifikasi!' });
                router.refresh();
            } else {
                setMessage({ type: 'error', text: result.error || 'Gagal memverifikasi berita acara' });
            }
        });
    };

    const handleReject = () => {
        if (!selectedReport || !rejectionReason.trim()) return;
        startTransition(async () => {
            const result = await lecturerVerifyPracticumReport(selectedReport.id, { status: 'Ditolak', rejectionReason: rejectionReason.trim() });
            if (result.success) {
                setMessage({ type: 'success', text: 'Berita acara berhasil ditolak!' });
                setShowRejectModal(false);
                setSelectedReport(null);
                setRejectionReason('');
                router.refresh();
            } else {
                setMessage({ type: 'error', text: result.error || 'Gagal menolak berita acara' });
            }
        });
    };

    const openRejectModal = (report: PracticumReportWithDetails) => { setSelectedReport(report); setRejectionReason(''); setShowRejectModal(true); };
    const openDeleteModal = (report: PracticumReportWithDetails) => { setReportToDelete(report); setShowDeleteModal(true); };

    const handleDelete = () => {
        if (!reportToDelete) return;
        startTransition(async () => {
            const result = await lecturerDeletePracticumReport(reportToDelete.id);
            if (result.success) {
                setMessage({ type: 'success', text: 'Berita acara berhasil dihapus!' });
                setShowDeleteModal(false);
                setReportToDelete(null);
                router.refresh();
            } else {
                setMessage({ type: 'error', text: result.error || 'Gagal menghapus berita acara' });
            }
        });
    };

    if (reports.length === 0) {
        return (
            <div className="text-center py-12">
                <div className="w-20 h-20 rounded-full bg-gray-100 flex items-center justify-center mx-auto mb-4">
                    <FileText className="w-9 h-9 text-gray-400" />
                </div>
                <h3 className="text-gray-600 font-medium text-lg">Belum ada berita acara</h3>
                <p className="text-sm text-gray-400 mt-1">Berita acara dari mahasiswa untuk matakuliah Anda akan muncul di sini</p>
            </div>
        );
    }

    return (
        <>
            {message && (
                <div className={`mb-4 p-3 rounded-lg text-sm ${message.type === 'success' ? 'bg-green-50 text-green-700 border border-green-200' : 'bg-red-50 text-red-700 border border-red-200'}`}>
                    {message.text}
                </div>
            )}

            <div className="overflow-x-auto">
                <table className="min-w-full divide-y divide-gray-200">
                    <thead className="bg-gray-50">
                        <tr>
                            <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider whitespace-nowrap">Tanggal Praktikum</th>
                            <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider whitespace-nowrap">Matakuliah</th>
                            <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider whitespace-nowrap">Dibuat Oleh</th>
                            <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider whitespace-nowrap">Ruangan</th>
                            <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider whitespace-nowrap">Angkatan</th>
                            <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider whitespace-nowrap">Hadir</th>
                            <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider whitespace-nowrap">Kondisi</th>
                            <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider whitespace-nowrap">Status</th>
                            <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider whitespace-nowrap">Aksi</th>
                        </tr>
                    </thead>
                    <tbody className="bg-white divide-y divide-gray-200">
                        {reports.map((report) => (
                            <tr key={report.id} className="hover:bg-gray-50 transition-colors">
                                <td className="px-4 py-3 whitespace-nowrap">
                                    <div className="flex items-center gap-2">
                                        <Calendar className="w-4 h-4 text-gray-400" />
                                        <span className="text-sm text-gray-900">{formatDate(report.practicumDate)}</span>
                                    </div>
                                    <div className="flex items-center gap-2 mt-0.5">
                                        <Clock className="w-3 h-3 text-gray-300" />
                                        <span className="text-xs text-gray-500">{report.startTime} - {report.endTime}</span>
                                    </div>
                                </td>
                                <td className="px-4 py-3 whitespace-nowrap">
                                    <div className="text-sm font-medium text-gray-900">{report.courseCode}</div>
                                    <div className="text-xs text-gray-500 max-w-[200px] truncate">{report.courseName}</div>
                                </td>
                                <td className="px-4 py-3 whitespace-nowrap">
                                    <span className="text-sm text-gray-900">{report.createdByName || report.createdBy}</span>
                                </td>
                                <td className="px-4 py-3 whitespace-nowrap">
                                    <span className="text-sm text-gray-900">{report.roomName}</span>
                                </td>
                                <td className="px-4 py-3 whitespace-nowrap">
                                    <span className="text-sm text-gray-900">{report.batch}</span>
                                </td>
                                <td className="px-4 py-3 whitespace-nowrap">
                                    <div className="flex items-center gap-1.5">
                                        <Users className="w-4 h-4 text-gray-400" />
                                        <span className="text-sm text-gray-900">{report.attendeeCount}</span>
                                    </div>
                                </td>
                                <td className="px-4 py-3 whitespace-nowrap">
                                    <span className={`inline-flex items-center px-2.5 py-1 rounded-full text-xs font-medium ${conditionColors[report.condition as PracticumCondition]}`}>
                                        {report.condition}
                                    </span>
                                </td>
                                <td className="px-4 py-3 whitespace-nowrap">
                                    <span className={`inline-flex items-center gap-1 px-2.5 py-1 rounded-full text-xs font-medium ${statusColors[(report.status || 'Pending') as PracticumReportStatus]}`}>
                                        <StatusIcon status={(report.status || 'Pending') as PracticumReportStatus} />
                                        {report.status || 'Pending'}
                                    </span>
                                </td>
                                <td className="px-4 py-3 whitespace-nowrap">
                                    <div className="flex items-center gap-1">
                                        <button onClick={() => setSelectedReport(report)} className="p-1.5 text-blue-600 hover:bg-blue-50 rounded-lg transition-colors" title="Lihat Detail">
                                            <Eye className="w-4 h-4" />
                                        </button>
                                        {(report.status === 'Pending' || !report.status) && (
                                            <>
                                                <button onClick={() => handleVerify(report)} disabled={isPending} className="p-1.5 text-green-600 hover:bg-green-50 rounded-lg transition-colors disabled:opacity-50" title="Verifikasi">
                                                    <Check className="w-4 h-4" />
                                                </button>
                                                <button onClick={() => openRejectModal(report)} disabled={isPending} className="p-1.5 text-red-600 hover:bg-red-50 rounded-lg transition-colors disabled:opacity-50" title="Tolak">
                                                    <X className="w-4 h-4" />
                                                </button>
                                            </>
                                        )}
                                        <button onClick={() => openDeleteModal(report)} disabled={isPending} className="p-1.5 text-gray-500 hover:bg-gray-100 rounded-lg transition-colors disabled:opacity-50" title="Hapus">
                                            <Trash2 className="w-4 h-4" />
                                        </button>
                                    </div>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>

            {/* Detail Modal */}
            {selectedReport && !showRejectModal && (
                <ViewportPortal>
                    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-[120] p-4">
                        <div className="bg-white rounded-xl shadow-xl max-w-2xl w-full max-h-[90vh] overflow-y-auto">
                            <div className="p-5 border-b border-gray-100 flex items-center justify-between bg-gradient-to-r from-blue-50 to-indigo-50">
                                <div className="flex items-center gap-3">
                                    <div className="p-2 bg-blue-100 rounded-lg">
                                        <FileText className="w-5 h-5 text-blue-600" />
                                    </div>
                                    <div>
                                        <h3 className="text-lg font-bold text-gray-900">Detail Berita Acara</h3>
                                        <p className="text-sm text-blue-600">{selectedReport.courseCode} - {selectedReport.courseName}</p>
                                    </div>
                                </div>
                                <button onClick={() => setSelectedReport(null)} className="text-gray-400 hover:text-gray-600 p-1">
                                    <X className="w-5 h-5" />
                                </button>
                            </div>
                            <div className="p-6 space-y-5">
                                <div className={`flex items-center gap-2 px-4 py-3 rounded-lg ${statusColors[(selectedReport.status || 'Pending') as PracticumReportStatus]}`}>
                                    <StatusIcon status={(selectedReport.status || 'Pending') as PracticumReportStatus} />
                                    <div>
                                        <span className="font-medium">Status: {selectedReport.status || 'Pending'}</span>
                                        {selectedReport.status === 'Ditolak' && selectedReport.rejectionReason && (
                                            <p className="text-sm mt-0.5">Alasan: {selectedReport.rejectionReason}</p>
                                        )}
                                        {selectedReport.status === 'Diverifikasi' && selectedReport.verifiedAt && (
                                            <p className="text-sm mt-0.5">Diverifikasi pada {formatDateTime(selectedReport.verifiedAt)}</p>
                                        )}
                                    </div>
                                </div>
                                <div className="bg-purple-50 rounded-lg p-4">
                                    <h4 className="text-sm font-semibold text-purple-700 mb-2">Informasi Pembuat</h4>
                                    <p className="text-sm text-gray-900">
                                        <span className="font-medium">{selectedReport.createdByName}</span>
                                        <span className="text-gray-500 ml-2">({selectedReport.createdBy})</span>
                                    </p>
                                    <p className="text-xs text-gray-500 mt-1">Dibuat pada: {formatDateTime(selectedReport.createdAt)}</p>
                                </div>
                                <div className="bg-gray-50 rounded-lg p-4">
                                    <h4 className="text-sm font-semibold text-gray-700 mb-3">Informasi Jadwal</h4>
                                    <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                                        <div className="flex items-start gap-2 text-sm">
                                            <FileText className="w-4 h-4 text-blue-500 mt-0.5" />
                                            <div>
                                                <span className="text-gray-500">Matakuliah</span>
                                                <p className="font-medium text-gray-900">{selectedReport.courseCode} - {selectedReport.courseName}</p>
                                            </div>
                                        </div>
                                        <div className="flex items-start gap-2 text-sm">
                                            <Calendar className="w-4 h-4 text-blue-500 mt-0.5" />
                                            <div>
                                                <span className="text-gray-500">Hari/Tanggal</span>
                                                <p className="font-medium text-gray-900">{formatFullDate(selectedReport.practicumDate)}</p>
                                            </div>
                                        </div>
                                        <div className="flex items-start gap-2 text-sm">
                                            <Clock className="w-4 h-4 text-blue-500 mt-0.5" />
                                            <div>
                                                <span className="text-gray-500">Waktu</span>
                                                <p className="font-medium text-gray-900">{selectedReport.startTime} - {selectedReport.endTime}</p>
                                            </div>
                                        </div>
                                        <div className="flex items-start gap-2 text-sm">
                                            <Users className="w-4 h-4 text-blue-500 mt-0.5" />
                                            <div>
                                                <span className="text-gray-500">Ruang Lab</span>
                                                <p className="font-medium text-gray-900">{selectedReport.roomName}</p>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                                <div className="space-y-4">
                                    <h4 className="text-sm font-semibold text-gray-700">Informasi Pelaksanaan</h4>
                                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                                        <div className="bg-gray-50 rounded-lg p-3">
                                            <span className="text-xs text-gray-500">Angkatan</span>
                                            <p className="font-semibold text-gray-900 mt-0.5">{selectedReport.batch}</p>
                                        </div>
                                        <div className="bg-gray-50 rounded-lg p-3">
                                            <span className="text-xs text-gray-500">Mahasiswa Hadir</span>
                                            <div className="flex items-center gap-1.5 mt-0.5">
                                                <Users className="w-4 h-4 text-gray-400" />
                                                <span className="font-semibold text-gray-900">{selectedReport.attendeeCount} orang</span>
                                            </div>
                                        </div>
                                        <div className="bg-gray-50 rounded-lg p-3">
                                            <span className="text-xs text-gray-500">Kondisi</span>
                                            <div className="mt-0.5">
                                                <span className={`inline-flex items-center px-2.5 py-1 rounded-full text-xs font-medium ${conditionColors[selectedReport.condition as PracticumCondition]}`}>
                                                    {selectedReport.condition}
                                                </span>
                                            </div>
                                        </div>
                                    </div>
                                    <div>
                                        <span className="text-sm font-medium text-gray-700">Deskripsi Pelaksanaan</span>
                                        <p className="mt-1 text-sm text-gray-600 bg-gray-50 rounded-lg p-3 whitespace-pre-wrap">{selectedReport.description}</p>
                                    </div>
                                    {selectedReport.issues && (
                                        <div>
                                            <span className="text-sm font-medium text-gray-700">Kendala</span>
                                            <p className="mt-1 text-sm text-gray-600 bg-yellow-50 rounded-lg p-3 whitespace-pre-wrap border border-yellow-100">{selectedReport.issues}</p>
                                        </div>
                                    )}
                                    {selectedReport.followUp && (
                                        <div>
                                            <span className="text-sm font-medium text-gray-700">Tindak Lanjut</span>
                                            <p className="mt-1 text-sm text-gray-600 bg-blue-50 rounded-lg p-3 whitespace-pre-wrap border border-blue-100">{selectedReport.followUp}</p>
                                        </div>
                                    )}
                                </div>
                            </div>
                            <div className="p-4 border-t border-gray-100 bg-gray-50 flex gap-2">
                                {(selectedReport.status === 'Pending' || !selectedReport.status) && (
                                    <>
                                        <button onClick={() => handleVerify(selectedReport)} disabled={isPending} className="flex-1 inline-flex items-center justify-center gap-2 px-4 py-2.5 rounded-lg text-sm font-medium bg-green-600 text-white hover:bg-green-700 transition-colors disabled:opacity-50">
                                            <Check className="w-4 h-4" />
                                            {isPending ? 'Memproses...' : 'Verifikasi'}
                                        </button>
                                        <button onClick={() => setShowRejectModal(true)} disabled={isPending} className="flex-1 inline-flex items-center justify-center gap-2 px-4 py-2.5 rounded-lg text-sm font-medium bg-red-600 text-white hover:bg-red-700 transition-colors disabled:opacity-50">
                                            <X className="w-4 h-4" />
                                            Tolak
                                        </button>
                                    </>
                                )}
                                <button onClick={() => setSelectedReport(null)} className="px-4 py-2.5 rounded-lg text-sm font-medium text-gray-600 hover:bg-gray-200 transition-colors">
                                    Tutup
                                </button>
                            </div>
                        </div>
                    </div>
                </ViewportPortal>
            )}

            {/* Reject Modal */}
            {showRejectModal && selectedReport && (
                <ViewportPortal>
                    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-[120] p-4">
                        <div className="bg-white rounded-xl shadow-xl max-w-md w-full">
                            <div className="p-5 border-b border-gray-100">
                                <h3 className="text-lg font-bold text-gray-900">Tolak Berita Acara</h3>
                                <p className="text-sm text-gray-500 mt-1">{selectedReport.courseCode} - {selectedReport.courseName}</p>
                            </div>
                            <div className="p-5">
                                <label className="block text-sm font-medium text-gray-700 mb-2">
                                    Alasan Penolakan <span className="text-red-500">*</span>
                                </label>
                                <textarea
                                    value={rejectionReason}
                                    onChange={(e) => setRejectionReason(e.target.value)}
                                    rows={4}
                                    placeholder="Tuliskan alasan penolakan berita acara..."
                                    className="w-full px-4 py-2.5 rounded-lg border border-gray-200 focus:outline-none focus:ring-2 focus:ring-red-200 focus:border-red-400 resize-none"
                                />
                            </div>
                            <div className="p-4 border-t border-gray-100 bg-gray-50 flex gap-2">
                                <button onClick={handleReject} disabled={isPending || !rejectionReason.trim()} className="flex-1 inline-flex items-center justify-center gap-2 px-4 py-2.5 rounded-lg text-sm font-medium bg-red-600 text-white hover:bg-red-700 transition-colors disabled:opacity-50 disabled:cursor-not-allowed">
                                    <X className="w-4 h-4" />
                                    {isPending ? 'Memproses...' : 'Konfirmasi Tolak'}
                                </button>
                                <button onClick={() => { setShowRejectModal(false); setRejectionReason(''); }} disabled={isPending} className="px-4 py-2.5 rounded-lg text-sm font-medium text-gray-600 hover:bg-gray-200 transition-colors">
                                    Batal
                                </button>
                            </div>
                        </div>
                    </div>
                </ViewportPortal>
            )}

            {/* Delete Modal */}
            {showDeleteModal && reportToDelete && (
                <ViewportPortal>
                    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-[120] p-4">
                        <div className="bg-white rounded-xl shadow-xl max-w-md w-full">
                            <div className="p-5 border-b border-gray-100">
                                <div className="flex items-center gap-3">
                                    <div className="p-2 bg-red-100 rounded-lg">
                                        <AlertTriangle className="w-5 h-5 text-red-600" />
                                    </div>
                                    <div>
                                        <h3 className="text-lg font-bold text-gray-900">Hapus Berita Acara</h3>
                                        <p className="text-sm text-gray-500">Tindakan ini tidak dapat dibatalkan</p>
                                    </div>
                                </div>
                            </div>
                            <div className="p-5">
                                <p className="text-sm text-gray-600">Apakah Anda yakin ingin menghapus berita acara untuk:</p>
                                <div className="mt-3 p-3 bg-gray-50 rounded-lg">
                                    <p className="font-medium text-gray-900">{reportToDelete.courseCode} - {reportToDelete.courseName}</p>
                                    <p className="text-sm text-gray-500 mt-1">{formatDate(reportToDelete.practicumDate)} | {reportToDelete.startTime} - {reportToDelete.endTime}</p>
                                    <p className="text-sm text-gray-500">Dibuat oleh: {reportToDelete.createdByName || reportToDelete.createdBy}</p>
                                </div>
                            </div>
                            <div className="p-4 border-t border-gray-100 bg-gray-50 flex gap-2">
                                <button onClick={handleDelete} disabled={isPending} className="flex-1 inline-flex items-center justify-center gap-2 px-4 py-2.5 rounded-lg text-sm font-medium bg-red-600 text-white hover:bg-red-700 transition-colors disabled:opacity-50">
                                    <Trash2 className="w-4 h-4" />
                                    {isPending ? 'Menghapus...' : 'Ya, Hapus'}
                                </button>
                                <button onClick={() => { setShowDeleteModal(false); setReportToDelete(null); }} disabled={isPending} className="px-4 py-2.5 rounded-lg text-sm font-medium text-gray-600 hover:bg-gray-200 transition-colors">
                                    Batal
                                </button>
                            </div>
                        </div>
                    </div>
                </ViewportPortal>
            )}
        </>
    );
}

'use client';

import { useState, useTransition } from 'react';
import { Upload, FileText, Trash2, Download, X, ChevronDown, ChevronUp } from 'lucide-react';
import { uploadPracticumLpjDoc, deletePracticumLpjDoc } from '@/features/practicum-reports/lpj-actions';

const MONTHS = [
    'Januari', 'Februari', 'Maret', 'April', 'Mei', 'Juni',
    'Juli', 'Agustus', 'September', 'Oktober', 'November', 'Desember',
];

interface LpjDoc {
    id: number;
    scheduledPracticumId: number;
    title: string;
    description: string | null;
    filePath: string;
    periodMonth: number;
    periodYear: number;
    createdAt: Date | null;
    uploaderName: string | null;
    uploaderId: string;
}

interface PracticumLpjManagerProps {
    scheduledPracticumId: number;
    courseName: string;
    initialDocs: LpjDoc[];
    currentUserId: string;
}

export default function PracticumLpjManager({
    scheduledPracticumId,
    courseName,
    initialDocs,
    currentUserId,
}: PracticumLpjManagerProps) {
    const [isPending, startTransition] = useTransition();
    const [docs, setDocs] = useState(initialDocs);
    const [showForm, setShowForm] = useState(false);
    const [message, setMessage] = useState<{ type: 'success' | 'error'; text: string } | null>(null);

    const now = new Date();
    const [title, setTitle] = useState('');
    const [description, setDescription] = useState('');
    const [periodMonth, setPeriodMonth] = useState(now.getMonth() + 1);
    const [periodYear, setPeriodYear] = useState(now.getFullYear());
    const [file, setFile] = useState<File | null>(null);

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (!file) { setMessage({ type: 'error', text: 'Pilih file terlebih dahulu' }); return; }

        const fd = new FormData();
        fd.append('file', file);
        fd.append('title', title);
        fd.append('description', description);
        fd.append('scheduledPracticumId', String(scheduledPracticumId));
        fd.append('periodMonth', String(periodMonth));
        fd.append('periodYear', String(periodYear));

        startTransition(async () => {
            const res = await uploadPracticumLpjDoc(fd);
            if (res.success) {
                setMessage({ type: 'success', text: 'LPJ berhasil diunggah!' });
                setShowForm(false);
                setTitle('');
                setDescription('');
                setFile(null);
                // Refresh list — simple window reload for now
                window.location.reload();
            } else {
                setMessage({ type: 'error', text: res.error || 'Gagal mengunggah' });
            }
        });
    };

    const handleDelete = (id: number) => {
        if (!confirm('Hapus dokumen LPJ ini?')) return;
        startTransition(async () => {
            const res = await deletePracticumLpjDoc(id);
            if (res.success) {
                setDocs(prev => prev.filter(d => d.id !== id));
                setMessage({ type: 'success', text: 'Dokumen berhasil dihapus' });
            } else {
                setMessage({ type: 'error', text: res.error || 'Gagal menghapus' });
            }
        });
    };

    const currentYear = now.getFullYear();
    const yearOptions = Array.from({ length: 5 }, (_, i) => currentYear - 2 + i);

    return (
        <div className="space-y-4">
            {/* Header */}
            <div className="flex items-center justify-between">
                <div>
                    <h3 className="font-semibold text-gray-900 text-sm">LPJ Praktikum</h3>
                    <p className="text-xs text-gray-500 mt-0.5">{courseName}</p>
                </div>
                <button
                    onClick={() => { setShowForm(v => !v); setMessage(null); }}
                    className="flex items-center gap-1.5 px-3 py-1.5 bg-blue-600 hover:bg-blue-700 text-white text-xs font-medium rounded-lg transition-colors"
                >
                    {showForm ? <ChevronUp className="w-3.5 h-3.5" /> : <Upload className="w-3.5 h-3.5" />}
                    {showForm ? 'Tutup' : 'Upload LPJ'}
                </button>
            </div>

            {/* Message */}
            {message && (
                <div className={`flex items-center gap-2 p-3 rounded-lg text-sm ${message.type === 'success' ? 'bg-green-50 text-green-700' : 'bg-red-50 text-red-700'}`}>
                    <span className="flex-1">{message.text}</span>
                    <button onClick={() => setMessage(null)}><X className="w-3.5 h-3.5" /></button>
                </div>
            )}

            {/* Upload Form */}
            {showForm && (
                <form onSubmit={handleSubmit} className="bg-gray-50 rounded-xl p-4 space-y-3 border border-gray-200">
                    <h4 className="font-medium text-gray-800 text-sm">Upload LPJ Baru</h4>

                    <div>
                        <label className="block text-xs font-medium text-gray-600 mb-1">Judul LPJ *</label>
                        <input
                            type="text"
                            value={title}
                            onChange={e => setTitle(e.target.value)}
                            required
                            placeholder="Contoh: LPJ Praktikum Basis Data Mei 2026"
                            className="w-full border border-gray-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
                        />
                    </div>

                    <div className="grid grid-cols-2 gap-3">
                        <div>
                            <label className="block text-xs font-medium text-gray-600 mb-1">Bulan *</label>
                            <select
                                value={periodMonth}
                                onChange={e => setPeriodMonth(parseInt(e.target.value))}
                                className="w-full border border-gray-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
                            >
                                {MONTHS.map((m, i) => (
                                    <option key={i + 1} value={i + 1}>{m}</option>
                                ))}
                            </select>
                        </div>
                        <div>
                            <label className="block text-xs font-medium text-gray-600 mb-1">Tahun *</label>
                            <select
                                value={periodYear}
                                onChange={e => setPeriodYear(parseInt(e.target.value))}
                                className="w-full border border-gray-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
                            >
                                {yearOptions.map(y => <option key={y} value={y}>{y}</option>)}
                            </select>
                        </div>
                    </div>

                    <div>
                        <label className="block text-xs font-medium text-gray-600 mb-1">Keterangan</label>
                        <textarea
                            value={description}
                            onChange={e => setDescription(e.target.value)}
                            rows={2}
                            placeholder="Keterangan tambahan (opsional)"
                            className="w-full border border-gray-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 resize-none"
                        />
                    </div>

                    <div>
                        <label className="block text-xs font-medium text-gray-600 mb-1">File LPJ * <span className="text-gray-400">(PDF/DOC/DOCX, maks 10MB)</span></label>
                        <input
                            type="file"
                            accept=".pdf,.doc,.docx"
                            onChange={e => setFile(e.target.files?.[0] || null)}
                            required
                            className="w-full text-sm text-gray-500 file:mr-3 file:py-1.5 file:px-3 file:rounded-lg file:border-0 file:text-xs file:font-medium file:bg-blue-50 file:text-blue-700 hover:file:bg-blue-100"
                        />
                    </div>

                    <div className="flex gap-2 pt-1">
                        <button
                            type="submit"
                            disabled={isPending}
                            className="flex items-center gap-1.5 px-4 py-2 bg-blue-600 hover:bg-blue-700 disabled:opacity-60 text-white text-sm font-medium rounded-lg transition-colors"
                        >
                            {isPending ? <span className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" /> : <Upload className="w-4 h-4" />}
                            {isPending ? 'Mengunggah...' : 'Upload'}
                        </button>
                        <button
                            type="button"
                            onClick={() => setShowForm(false)}
                            className="px-4 py-2 border border-gray-200 text-gray-600 text-sm rounded-lg hover:bg-gray-50 transition-colors"
                        >
                            Batal
                        </button>
                    </div>
                </form>
            )}

            {/* Document List */}
            {docs.length === 0 ? (
                <div className="text-center py-6 text-gray-400">
                    <FileText className="w-8 h-8 mx-auto mb-2 opacity-40" />
                    <p className="text-xs">Belum ada LPJ yang diunggah</p>
                </div>
            ) : (
                <div className="space-y-2">
                    {docs.map(doc => (
                        <div key={doc.id} className="flex items-center justify-between bg-white border border-gray-100 rounded-lg px-3 py-2.5 gap-2">
                            <div className="flex items-center gap-2.5 min-w-0">
                                <div className="p-1.5 bg-blue-50 rounded-lg shrink-0">
                                    <FileText className="w-4 h-4 text-blue-600" />
                                </div>
                                <div className="min-w-0">
                                    <p className="text-sm font-medium text-gray-900 truncate">{doc.title}</p>
                                    <p className="text-xs text-gray-500">{MONTHS[doc.periodMonth - 1]} {doc.periodYear} · {doc.uploaderName || 'Unknown'}</p>
                                </div>
                            </div>
                            <div className="flex items-center gap-1 shrink-0">
                                <a
                                    href={doc.filePath}
                                    target="_blank"
                                    rel="noopener noreferrer"
                                    className="p-1.5 text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"
                                    title="Unduh"
                                >
                                    <Download className="w-4 h-4" />
                                </a>
                                {(doc.uploaderId === currentUserId) && (
                                    <button
                                        onClick={() => handleDelete(doc.id)}
                                        disabled={isPending}
                                        className="p-1.5 text-red-500 hover:bg-red-50 rounded-lg transition-colors disabled:opacity-50"
                                        title="Hapus"
                                    >
                                        <Trash2 className="w-4 h-4" />
                                    </button>
                                )}
                            </div>
                        </div>
                    ))}
                </div>
            )}
        </div>
    );
}

'use client';

import { useState, useTransition } from 'react';
import { X, FileText, Users, Calendar, Clock, MapPin, User } from 'lucide-react';
import { createPracticumReport } from '@/features/practicum-reports/actions';
import type { ScheduledPracticumWithDetails } from '@/features/scheduled-practicum/types';
import type { PracticumCondition } from '@/features/practicum-reports/types';

interface PracticumReportFormProps {
    isOpen: boolean;
    onClose: () => void;
    schedule: ScheduledPracticumWithDetails;
    onSuccess?: () => void;
}

const CONDITION_OPTIONS_LIST: { value: PracticumCondition; label: string }[] = [
    { value: 'Lancar', label: 'Lancar' },
    { value: 'Kurang Lancar', label: 'Kurang Lancar' },
    { value: 'Terkendala', label: 'Terkendala' },
];

export default function PracticumReportForm({ isOpen, onClose, schedule, onSuccess }: PracticumReportFormProps) {
    const [isPending, startTransition] = useTransition();
    const [error, setError] = useState<string | null>(null);
    const [condition, setCondition] = useState<PracticumCondition | ''>('');

    if (!isOpen) return null;

    const formatDate = (date: Date | string) => {
        const d = typeof date === 'string' ? new Date(date) : date;
        const days = ['Minggu', 'Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat', 'Sabtu'];
        const months = ['Januari', 'Februari', 'Maret', 'April', 'Mei', 'Juni', 'Juli', 'Agustus', 'September', 'Oktober', 'November', 'Desember'];
        return `${days[d.getDay()]}, ${d.getDate()} ${months[d.getMonth()]} ${d.getFullYear()}`;
    };

    const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
        e.preventDefault();
        setError(null);

        const fd = new FormData(e.currentTarget);

        const data = {
            scheduledPracticumId: schedule.id,
            courseName: schedule.courseName || '',
            courseCode: schedule.courseCode || '',
            lecturerName: (schedule as any).lecturerName || null,
            roomName: schedule.roomName || '',
            practicumDate: new Date(schedule.scheduledDate),
            startTime: schedule.startTime,
            endTime: schedule.endTime,
            batch: fd.get('batch') as string,
            attendeeCount: parseInt(fd.get('attendeeCount') as string),
            condition: fd.get('condition') as PracticumCondition,
            description: fd.get('description') as string,
            issues: (fd.get('issues') as string) || undefined,
            followUp: (fd.get('followUp') as string) || undefined,
        };

        startTransition(async () => {
            const result = await createPracticumReport(data);
            if (result.success) {
                onSuccess?.();
                onClose();
            } else {
                setError(result.error || 'Gagal menyimpan berita acara');
            }
        });
    };

    return (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-[120] p-4">
            <div className="bg-white rounded-xl shadow-xl max-w-2xl w-full max-h-[90vh] overflow-y-auto">
                {/* Header */}
                <div className="p-5 border-b border-gray-100 flex items-center justify-between bg-gradient-to-r from-blue-50 to-indigo-50">
                    <div className="flex items-center gap-3">
                        <div className="p-2 bg-blue-100 rounded-lg">
                            <FileText className="w-5 h-5 text-blue-600" />
                        </div>
                        <div>
                            <h3 className="text-lg font-bold text-gray-900">Isi Berita Acara Praktikum</h3>
                            <p className="text-sm text-blue-600">{schedule.courseCode} - {schedule.courseName}</p>
                        </div>
                    </div>
                    <button onClick={onClose} className="text-gray-400 hover:text-gray-600 p-1">
                        <X className="w-5 h-5" />
                    </button>
                </div>

                {/* Form */}
                <form onSubmit={handleSubmit} className="p-6 space-y-5">
                    {error && (
                        <div className="p-3 rounded-lg bg-red-50 text-red-700 text-sm border border-red-200">
                            {error}
                        </div>
                    )}

                    {/* Info dari Jadwal (Read-only) */}
                    <div className="bg-gray-50 rounded-lg p-4 space-y-3">
                        <h4 className="text-sm font-semibold text-gray-700 mb-3">Informasi Jadwal (Otomatis)</h4>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                            <div className="flex items-center gap-2 text-sm">
                                <FileText className="w-4 h-4 text-blue-500 shrink-0" />
                                <span className="text-gray-500">Matakuliah:</span>
                                <span className="font-medium text-gray-900">{schedule.courseCode} - {schedule.courseName}</span>
                            </div>

                            <div className="flex items-center gap-2 text-sm">
                                <User className="w-4 h-4 text-blue-500 shrink-0" />
                                <span className="text-gray-500">Dosen:</span>
                                <span className="font-medium text-gray-900">{(schedule as any).lecturerName || '-'}</span>
                            </div>

                            <div className="flex items-center gap-2 text-sm">
                                <Calendar className="w-4 h-4 text-blue-500 shrink-0" />
                                <span className="text-gray-500">Tanggal:</span>
                                <span className="font-medium text-gray-900">{formatDate(schedule.scheduledDate)}</span>
                            </div>

                            <div className="flex items-center gap-2 text-sm">
                                <Clock className="w-4 h-4 text-blue-500 shrink-0" />
                                <span className="text-gray-500">Waktu:</span>
                                <span className="font-medium text-gray-900">{schedule.startTime} - {schedule.endTime}</span>
                            </div>

                            <div className="flex items-center gap-2 text-sm md:col-span-2">
                                <MapPin className="w-4 h-4 text-blue-500 shrink-0" />
                                <span className="text-gray-500">Ruang Lab:</span>
                                <span className="font-medium text-gray-900">{schedule.roomName}</span>
                            </div>
                        </div>
                    </div>

                    {/* Form Fields */}
                    <div className="space-y-4">
                        {/* Angkatan */}
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">
                                Angkatan <span className="text-red-500">*</span>
                            </label>
                            <input
                                type="text"
                                name="batch"
                                required
                                placeholder="Contoh: 2023, 2022-2023"
                                className="w-full px-4 py-2.5 rounded-lg border border-gray-200 focus:outline-none focus:ring-2 focus:ring-blue-200 focus:border-blue-400"
                            />
                        </div>

                        {/* Jumlah Mahasiswa Hadir */}
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">
                                Jumlah Mahasiswa Hadir <span className="text-red-500">*</span>
                            </label>
                            <div className="relative">
                                <Users className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                                <input
                                    type="number"
                                    name="attendeeCount"
                                    required
                                    min="0"
                                    placeholder="0"
                                    className="w-full pl-10 pr-4 py-2.5 rounded-lg border border-gray-200 focus:outline-none focus:ring-2 focus:ring-blue-200 focus:border-blue-400"
                                />
                            </div>
                        </div>

                        {/* Kondisi Praktikum */}
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-2">
                                Kondisi Praktikum <span className="text-red-500">*</span>
                            </label>
                            <div className="flex flex-wrap gap-3">
                                {CONDITION_OPTIONS_LIST.map((opt) => (
                                    <label
                                        key={opt.value}
                                        className={`
                                            flex items-center gap-2 px-4 py-2.5 rounded-lg border cursor-pointer transition-all
                                            ${condition === opt.value
                                                ? opt.value === 'Lancar'
                                                    ? 'bg-green-50 border-green-500 text-green-700'
                                                    : opt.value === 'Kurang Lancar'
                                                        ? 'bg-yellow-50 border-yellow-500 text-yellow-700'
                                                        : 'bg-red-50 border-red-500 text-red-700'
                                                : 'bg-white border-gray-200 hover:border-gray-300'
                                            }
                                        `}
                                    >
                                        <input
                                            type="radio"
                                            name="condition"
                                            value={opt.value}
                                            required
                                            checked={condition === opt.value}
                                            onChange={(e) => setCondition(e.target.value as PracticumCondition)}
                                            className="sr-only"
                                        />
                                        <div className={`w-4 h-4 rounded-full border-2 flex items-center justify-center
                                            ${condition === opt.value
                                                ? opt.value === 'Lancar' ? 'border-green-500'
                                                    : opt.value === 'Kurang Lancar' ? 'border-yellow-500'
                                                        : 'border-red-500'
                                                : 'border-gray-300'
                                            }
                                        `}>
                                            {condition === opt.value && (
                                                <div className={`w-2 h-2 rounded-full
                                                    ${opt.value === 'Lancar' ? 'bg-green-500'
                                                        : opt.value === 'Kurang Lancar' ? 'bg-yellow-500'
                                                            : 'bg-red-500'
                                                    }
                                                `} />
                                            )}
                                        </div>
                                        <span className="text-sm font-medium">{opt.label}</span>
                                    </label>
                                ))}
                            </div>
                        </div>

                        {/* Deskripsi Pelaksanaan */}
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">
                                Deskripsi Singkat Pelaksanaan <span className="text-red-500">*</span>
                            </label>
                            <textarea
                                name="description"
                                required
                                rows={3}
                                maxLength={2000}
                                placeholder="Deskripsikan secara singkat bagaimana pelaksanaan praktikum hari ini..."
                                className="w-full px-4 py-2.5 rounded-lg border border-gray-200 focus:outline-none focus:ring-2 focus:ring-blue-200 focus:border-blue-400 resize-none"
                            />
                        </div>

                        {/* Kendala */}
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">
                                Kendala <span className="text-gray-400 text-xs">(Opsional)</span>
                            </label>
                            <textarea
                                name="issues"
                                rows={2}
                                maxLength={2000}
                                placeholder="Tuliskan kendala yang dihadapi selama praktikum (jika ada)..."
                                className="w-full px-4 py-2.5 rounded-lg border border-gray-200 focus:outline-none focus:ring-2 focus:ring-blue-200 focus:border-blue-400 resize-none"
                            />
                        </div>

                        {/* Tindak Lanjut */}
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">
                                Tindak Lanjut <span className="text-gray-400 text-xs">(Opsional)</span>
                            </label>
                            <textarea
                                name="followUp"
                                rows={2}
                                maxLength={2000}
                                placeholder="Tuliskan tindak lanjut yang diperlukan (jika ada)..."
                                className="w-full px-4 py-2.5 rounded-lg border border-gray-200 focus:outline-none focus:ring-2 focus:ring-blue-200 focus:border-blue-400 resize-none"
                            />
                        </div>
                    </div>

                    {/* Actions */}
                    <div className="flex gap-3 pt-4 border-t border-gray-100">
                        <button
                            type="submit"
                            disabled={isPending}
                            className="flex-1 bg-blue-600 text-white px-6 py-2.5 rounded-lg text-sm font-medium hover:bg-blue-700 transition-colors disabled:opacity-50 disabled:cursor-not-allowed shadow-sm"
                        >
                            {isPending ? 'Menyimpan...' : 'Simpan Berita Acara'}
                        </button>
                        <button
                            type="button"
                            onClick={onClose}
                            disabled={isPending}
                            className="px-6 py-2.5 rounded-lg text-sm font-medium text-gray-600 hover:bg-gray-100 transition-colors"
                        >
                            Batal
                        </button>
                    </div>
                </form>
            </div>
        </div>
    );
}

'use client';

import { useState } from 'react';
import { FileText, Eye, Calendar, Clock, CheckCircle, XCircle, AlertCircle } from 'lucide-react';
import type { PracticumReport, PracticumReportStatus, PracticumCondition } from '@/features/practicum-reports/types';
import { STATUS_COLORS, CONDITION_COLORS } from '@/features/practicum-reports/types';

interface PracticumReportTableProps {
    reports: PracticumReport[];
}

export default function PracticumReportTable({ reports }: PracticumReportTableProps) {
    const [selectedReport, setSelectedReport] = useState<PracticumReport | null>(null);

    const formatDate = (date: Date | string | null | undefined) => {
        if (!date) return '-';
        const d = typeof date === 'string' ? new Date(date) : date;
        if (isNaN(d.getTime())) return '-';
        return d.toLocaleDateString('id-ID', { day: 'numeric', month: 'short', year: 'numeric' });
    };

    const formatFullDate = (date: Date | string | null | undefined) => {
        if (!date) return '-';
        const d = typeof date === 'string' ? new Date(date) : date;
        if (isNaN(d.getTime())) return '-';
        const days = ['Minggu', 'Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat', 'Sabtu'];
        const months = ['Januari', 'Februari', 'Maret', 'April', 'Mei', 'Juni', 'Juli', 'Agustus', 'September', 'Oktober', 'November', 'Desember'];
        return `${days[d.getDay()]}, ${d.getDate()} ${months[d.getMonth()]} ${d.getFullYear()}`;
    };

    const StatusIcon = ({ status }: { status: PracticumReportStatus | null }) => {
        switch (status) {
            case 'Diverifikasi': return <CheckCircle className="w-4 h-4" />;
            case 'Ditolak': return <XCircle className="w-4 h-4" />;
            default: return <AlertCircle className="w-4 h-4" />;
        }
    };

    if (reports.length === 0) {
        return (
            <div className="text-center py-12">
                <div className="w-16 h-16 rounded-full bg-gray-100 flex items-center justify-center mx-auto mb-3">
                    <FileText className="w-7 h-7 text-gray-400" />
                </div>
                <p className="text-gray-500 font-medium">Belum ada berita acara</p>
                <p className="text-gray-400 text-sm mt-1">Berita acara yang Anda isi akan muncul di sini</p>
            </div>
        );
    }

    return (
        <>
            <div className="overflow-x-auto">
                <table className="w-full text-sm">
                    <thead>
                        <tr className="border-b border-gray-100">
                            <th className="text-left py-3 px-4 text-xs font-semibold text-gray-500 uppercase tracking-wider">Mata Kuliah</th>
                            <th className="text-left py-3 px-4 text-xs font-semibold text-gray-500 uppercase tracking-wider">Tanggal</th>
                            <th className="text-left py-3 px-4 text-xs font-semibold text-gray-500 uppercase tracking-wider">Kondisi</th>
                            <th className="text-left py-3 px-4 text-xs font-semibold text-gray-500 uppercase tracking-wider">Status</th>
                            <th className="text-left py-3 px-4 text-xs font-semibold text-gray-500 uppercase tracking-wider">Aksi</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-50">
                        {reports.map((report) => (
                            <tr key={report.id} className="hover:bg-gray-50 transition-colors">
                                <td className="py-3 px-4">
                                    <p className="font-medium text-gray-900">{report.courseName}</p>
                                    <p className="text-xs text-blue-600 font-medium">{report.courseCode}</p>
                                </td>
                                <td className="py-3 px-4">
                                    <div className="flex items-center gap-1.5 text-gray-600">
                                        <Calendar className="w-3.5 h-3.5 text-gray-400" />
                                        <span>{formatDate(report.practicumDate)}</span>
                                    </div>
                                    <div className="flex items-center gap-1.5 text-gray-500 text-xs mt-0.5">
                                        <Clock className="w-3 h-3 text-gray-400" />
                                        <span>{report.startTime} - {report.endTime}</span>
                                    </div>
                                </td>
                                <td className="py-3 px-4">
                                    <span className={`inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium ${CONDITION_COLORS[report.condition as PracticumCondition] || 'bg-gray-100 text-gray-700'}`}>
                                        {report.condition}
                                    </span>
                                </td>
                                <td className="py-3 px-4">
                                    <span className={`inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-medium ${STATUS_COLORS[(report.status || 'Pending') as PracticumReportStatus]}`}>
                                        <StatusIcon status={report.status as PracticumReportStatus | null} />
                                        {report.status || 'Pending'}
                                    </span>
                                    {report.status === 'Ditolak' && report.rejectionReason && (
                                        <p className="text-xs text-red-500 mt-1 max-w-[180px] truncate" title={report.rejectionReason}>
                                            {report.rejectionReason}
                                        </p>
                                    )}
                                </td>
                                <td className="py-3 px-4">
                                    <button
                                        onClick={() => setSelectedReport(report)}
                                        className="inline-flex items-center gap-1 px-3 py-1.5 text-xs font-medium text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"
                                    >
                                        <Eye className="w-3.5 h-3.5" />
                                        Detail
                                    </button>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>

            {/* Detail Modal */}
            {selectedReport && (
                <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-[120] p-4">
                    <div className="bg-white rounded-xl shadow-xl max-w-2xl w-full max-h-[90vh] overflow-y-auto">
                        <div className="p-5 border-b border-gray-100 flex items-center justify-between bg-gradient-to-r from-blue-50 to-indigo-50">
                            <div className="flex items-center gap-3">
                                <div className="p-2 bg-blue-100 rounded-lg">
                                    <FileText className="w-5 h-5 text-blue-600" />
                                </div>
                                <div>
                                    <h3 className="text-lg font-bold text-gray-900">Detail Berita Acara</h3>
                                    <p className="text-sm text-blue-600">{selectedReport.courseCode} - {selectedReport.courseName}</p>
                                </div>
                            </div>
                            <button onClick={() => setSelectedReport(null)} className="text-gray-400 hover:text-gray-600 p-1">
                                <XCircle className="w-5 h-5" />
                            </button>
                        </div>

                        <div className="p-6 space-y-5">
                            {/* Status */}
                            <div className="flex items-center gap-2">
                                <span className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-sm font-medium ${STATUS_COLORS[(selectedReport.status || 'Pending') as PracticumReportStatus]}`}>
                                    <StatusIcon status={selectedReport.status as PracticumReportStatus | null} />
                                    {selectedReport.status || 'Pending'}
                                </span>
                            </div>

                            {selectedReport.status === 'Ditolak' && selectedReport.rejectionReason && (
                                <div className="p-3 bg-red-50 border border-red-200 rounded-lg">
                                    <p className="text-sm font-medium text-red-700">Alasan Penolakan:</p>
                                    <p className="text-sm text-red-600 mt-1">{selectedReport.rejectionReason}</p>
                                </div>
                            )}

                            {/* Info Jadwal */}
                            <div className="bg-gray-50 rounded-lg p-4 space-y-2">
                                <h4 className="text-sm font-semibold text-gray-700">Informasi Jadwal</h4>
                                <div className="grid grid-cols-2 gap-2 text-sm">
                                    <div><span className="text-gray-500">Tanggal:</span> <span className="font-medium">{formatFullDate(selectedReport.practicumDate)}</span></div>
                                    <div><span className="text-gray-500">Waktu:</span> <span className="font-medium">{selectedReport.startTime} - {selectedReport.endTime}</span></div>
                                    <div><span className="text-gray-500">Ruangan:</span> <span className="font-medium">{selectedReport.roomName}</span></div>
                                    <div><span className="text-gray-500">Dosen:</span> <span className="font-medium">{selectedReport.lecturerName || '-'}</span></div>
                                </div>
                            </div>

                            {/* Isi Berita Acara */}
                            <div className="space-y-3">
                                <div className="grid grid-cols-2 gap-3 text-sm">
                                    <div><span className="text-gray-500">Angkatan:</span> <span className="font-medium ml-1">{selectedReport.batch}</span></div>
                                    <div><span className="text-gray-500">Jumlah Hadir:</span> <span className="font-medium ml-1">{selectedReport.attendeeCount} orang</span></div>
                                    <div className="col-span-2">
                                        <span className="text-gray-500">Kondisi: </span>
                                        <span className={`inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium ml-1 ${CONDITION_COLORS[selectedReport.condition as PracticumCondition]}`}>
                                            {selectedReport.condition}
                                        </span>
                                    </div>
                                </div>
                                <div>
                                    <p className="text-xs font-semibold text-gray-500 uppercase tracking-wider mb-1">Deskripsi Pelaksanaan</p>
                                    <p className="text-sm text-gray-700 whitespace-pre-wrap">{selectedReport.description}</p>
                                </div>
                                {selectedReport.issues && (
                                    <div>
                                        <p className="text-xs font-semibold text-gray-500 uppercase tracking-wider mb-1">Kendala</p>
                                        <p className="text-sm text-gray-700 whitespace-pre-wrap">{selectedReport.issues}</p>
                                    </div>
                                )}
                                {selectedReport.followUp && (
                                    <div>
                                        <p className="text-xs font-semibold text-gray-500 uppercase tracking-wider mb-1">Tindak Lanjut</p>
                                        <p className="text-sm text-gray-700 whitespace-pre-wrap">{selectedReport.followUp}</p>
                                    </div>
                                )}
                            </div>

                            <div className="pt-4 border-t border-gray-100">
                                <button
                                    onClick={() => setSelectedReport(null)}
                                    className="px-6 py-2.5 rounded-lg text-sm font-medium text-gray-600 hover:bg-gray-100 transition-colors"
                                >
                                    Tutup
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
            )}
        </>
    );
}

'use server';

import { db } from '@/db';
import { practicumLpjDocs } from '@/db/schema';
import { eq, desc, and } from 'drizzle-orm';
import { users } from '@/db/schema';
import { revalidatePath } from 'next/cache';
import { requireAnyPermission, getSession } from '@/lib/auth';
import { mkdir, writeFile } from 'fs/promises';
import { join } from 'path';

const MAX_FILE_SIZE = 10 * 1024 * 1024; // 10MB

export async function getPracticumLpjDocs(scheduledPracticumId?: number) {
    const session = await getSession();
    if (!session) throw new Error('Unauthorized');

    const conditions = [];
    if (scheduledPracticumId) {
        conditions.push(eq(practicumLpjDocs.scheduledPracticumId, scheduledPracticumId));
    }

    return db
        .select({
            id: practicumLpjDocs.id,
            scheduledPracticumId: practicumLpjDocs.scheduledPracticumId,
            title: practicumLpjDocs.title,
            description: practicumLpjDocs.description,
            filePath: practicumLpjDocs.filePath,
            periodMonth: practicumLpjDocs.periodMonth,
            periodYear: practicumLpjDocs.periodYear,
            createdAt: practicumLpjDocs.createdAt,
            uploaderName: users.fullName,
            uploaderId: practicumLpjDocs.uploaderId,
        })
        .from(practicumLpjDocs)
        .leftJoin(users, eq(practicumLpjDocs.uploaderId, users.identifier))
        .where(conditions.length > 0 ? and(...conditions) : undefined)
        .orderBy(desc(practicumLpjDocs.createdAt));
}

export async function uploadPracticumLpjDoc(formData: FormData) {
    try {
        const session = await requireAnyPermission(['practicum.manage', 'practicum.assist']);

        const file = formData.get('file') as File;
        const title = formData.get('title') as string;
        const description = formData.get('description') as string;
        const scheduledPracticumId = parseInt(formData.get('scheduledPracticumId') as string);
        const periodMonth = parseInt(formData.get('periodMonth') as string);
        const periodYear = parseInt(formData.get('periodYear') as string);

        if (!file || file.size === 0) return { success: false, error: 'Tidak ada file yang dipilih' };
        if (file.size > MAX_FILE_SIZE) return { success: false, error: 'Ukuran file maksimal 10MB' };
        if (!title?.trim()) return { success: false, error: 'Judul wajib diisi' };
        if (!scheduledPracticumId || !periodMonth || !periodYear) return { success: false, error: 'Data tidak lengkap' };

        const bytes = await file.arrayBuffer();
        const buffer = Buffer.from(bytes);

        const uploadDir = join(process.cwd(), 'public', 'uploads', 'practicum-lpj');
        await mkdir(uploadDir, { recursive: true });

        const uniqueSuffix = `${Date.now()}-${Math.round(Math.random() * 1e9)}`;
        const safeFilename = `${uniqueSuffix}-${file.name.replace(/[^a-zA-Z0-9.\-_]/g, '_')}`;
        await writeFile(join(uploadDir, safeFilename), buffer);

        await db.insert(practicumLpjDocs).values({
            scheduledPracticumId,
            uploaderId: session.user.identifier,
            title: title.trim(),
            description: description?.trim() || null,
            filePath: `/uploads/practicum-lpj/${safeFilename}`,
            periodMonth,
            periodYear,
        });

        revalidatePath('/admin/scheduled-practicum');
        revalidatePath('/lecturer/manage/scheduled-practicum');
        revalidatePath('/student/manage/scheduled-practicum');

        return { success: true };
    } catch (error: any) {
        console.error('Error uploading LPJ:', error);
        return { success: false, error: error.message || 'Gagal mengunggah LPJ' };
    }
}

export async function deletePracticumLpjDoc(id: number) {
    try {
        const session = await requireAnyPermission(['practicum.manage', 'practicum.assist']);

        const [doc] = await db
            .select({ uploaderId: practicumLpjDocs.uploaderId })
            .from(practicumLpjDocs)
            .where(eq(practicumLpjDocs.id, id));

        if (!doc) return { success: false, error: 'Dokumen tidak ditemukan' };

        const isAdmin = session.user.roleId === 1;
        const isOwner = doc.uploaderId === session.user.identifier;
        if (!isAdmin && !isOwner) return { success: false, error: 'Anda tidak berhak menghapus dokumen ini' };

        await db.delete(practicumLpjDocs).where(eq(practicumLpjDocs.id, id));

        revalidatePath('/admin/scheduled-practicum');
        revalidatePath('/lecturer/manage/scheduled-practicum');
        revalidatePath('/student/manage/scheduled-practicum');

        return { success: true };
    } catch (error: any) {
        return { success: false, error: error.message || 'Gagal menghapus LPJ' };
    }
}

/**
 * Practicum Report (Berita Acara) Service
 */

import { db } from '@/db';
import { practicumReports, users, scheduledPracticums, courses } from '@/db/schema';
import { eq, desc, and, sql } from 'drizzle-orm';
import type { CreatePracticumReportInput, VerifyPracticumReportInput } from './types';

export class PracticumReportService {
    /**
     * Get all practicum reports with creator & verifier details (for admin/lecturer)
     */
    static async getAllWithDetails() {
        const results = await db.execute(sql`
            SELECT
                pr.id,
                pr.scheduled_practicum_id as scheduledPracticumId,
                pr.created_by as createdBy,
                pr.course_name as courseName,
                pr.course_code as courseCode,
                pr.lecturer_name as lecturerName,
                pr.room_name as roomName,
                pr.practicum_date as practicumDate,
                pr.start_time as startTime,
                pr.end_time as endTime,
                pr.batch,
                pr.attendee_count as attendeeCount,
                pr.condition as \`condition\`,
                pr.description,
                pr.issues,
                pr.follow_up as followUp,
                pr.report_status as status,
                pr.verified_by as verifiedBy,
                pr.verified_at as verifiedAt,
                pr.rejection_reason as rejectionReason,
                pr.created_at as createdAt,
                pr.updated_at as updatedAt,
                u1.full_name as createdByName,
                u2.full_name as verifiedByName
            FROM practicum_reports pr
            LEFT JOIN users u1 ON pr.created_by = u1.identifier
            LEFT JOIN users u2 ON pr.verified_by = u2.identifier
            ORDER BY pr.created_at DESC
        `);

        return (results as unknown as any[][])[0] as any[];
    }

    /**
     * Get practicum reports for a specific lecturer's courses
     */
    static async getByLecturerId(lecturerId: string) {
        const results = await db.execute(sql`
            SELECT
                pr.id,
                pr.scheduled_practicum_id as scheduledPracticumId,
                pr.created_by as createdBy,
                pr.course_name as courseName,
                pr.course_code as courseCode,
                pr.lecturer_name as lecturerName,
                pr.room_name as roomName,
                pr.practicum_date as practicumDate,
                pr.start_time as startTime,
                pr.end_time as endTime,
                pr.batch,
                pr.attendee_count as attendeeCount,
                pr.condition as \`condition\`,
                pr.description,
                pr.issues,
                pr.follow_up as followUp,
                pr.report_status as status,
                pr.verified_by as verifiedBy,
                pr.verified_at as verifiedAt,
                pr.rejection_reason as rejectionReason,
                pr.created_at as createdAt,
                pr.updated_at as updatedAt,
                u1.full_name as createdByName,
                u2.full_name as verifiedByName
            FROM practicum_reports pr
            LEFT JOIN users u1 ON pr.created_by = u1.identifier
            LEFT JOIN users u2 ON pr.verified_by = u2.identifier
            LEFT JOIN scheduled_practicums sp ON pr.scheduled_practicum_id = sp.id
            LEFT JOIN courses c ON sp.course_id = c.id
            WHERE c.lecturer_id = ${lecturerId}
            ORDER BY pr.created_at DESC
        `);

        return (results as unknown as any[][])[0] as any[];
    }

    /**
     * Get practicum reports created by a specific user
     */
    static async getByUser(userIdentifier: string) {
        return await db
            .select({
                id: practicumReports.id,
                scheduledPracticumId: practicumReports.scheduledPracticumId,
                createdBy: practicumReports.createdBy,
                courseName: practicumReports.courseName,
                courseCode: practicumReports.courseCode,
                lecturerName: practicumReports.lecturerName,
                roomName: practicumReports.roomName,
                practicumDate: practicumReports.practicumDate,
                startTime: practicumReports.startTime,
                endTime: practicumReports.endTime,
                batch: practicumReports.batch,
                attendeeCount: practicumReports.attendeeCount,
                condition: practicumReports.condition,
                description: practicumReports.description,
                issues: practicumReports.issues,
                followUp: practicumReports.followUp,
                status: practicumReports.status,
                verifiedBy: practicumReports.verifiedBy,
                verifiedAt: practicumReports.verifiedAt,
                rejectionReason: practicumReports.rejectionReason,
                createdAt: practicumReports.createdAt,
                updatedAt: practicumReports.updatedAt,
            })
            .from(practicumReports)
            .where(eq(practicumReports.createdBy, userIdentifier))
            .orderBy(desc(practicumReports.createdAt));
    }

    /**
     * Get practicum report by ID with details
     */
    static async getById(id: number) {
        const results = await db.execute(sql`
            SELECT
                pr.id,
                pr.scheduled_practicum_id as scheduledPracticumId,
                pr.created_by as createdBy,
                pr.course_name as courseName,
                pr.course_code as courseCode,
                pr.lecturer_name as lecturerName,
                pr.room_name as roomName,
                pr.practicum_date as practicumDate,
                pr.start_time as startTime,
                pr.end_time as endTime,
                pr.batch,
                pr.attendee_count as attendeeCount,
                pr.condition as \`condition\`,
                pr.description,
                pr.issues,
                pr.follow_up as followUp,
                pr.report_status as status,
                pr.verified_by as verifiedBy,
                pr.verified_at as verifiedAt,
                pr.rejection_reason as rejectionReason,
                pr.created_at as createdAt,
                pr.updated_at as updatedAt,
                u1.full_name as createdByName,
                u2.full_name as verifiedByName
            FROM practicum_reports pr
            LEFT JOIN users u1 ON pr.created_by = u1.identifier
            LEFT JOIN users u2 ON pr.verified_by = u2.identifier
            WHERE pr.id = ${id}
            LIMIT 1
        `);

        const rows = (results as unknown as any[][])[0] as any[];
        return rows[0] || null;
    }

    /**
     * Check if a report already exists for a scheduled practicum by a user
     */
    static async existsForUserAndSchedule(userIdentifier: string, scheduledPracticumId: number): Promise<boolean> {
        const results = await db
            .select({ id: practicumReports.id })
            .from(practicumReports)
            .where(and(
                eq(practicumReports.createdBy, userIdentifier),
                eq(practicumReports.scheduledPracticumId, scheduledPracticumId)
            ))
            .limit(1);

        return results.length > 0;
    }

    /**
     * Get set of scheduledPracticumIds that a user has already reported
     */
    static async getReportedScheduleIds(userIdentifier: string): Promise<Set<number>> {
        const results = await db
            .select({ scheduledPracticumId: practicumReports.scheduledPracticumId })
            .from(practicumReports)
            .where(eq(practicumReports.createdBy, userIdentifier));

        return new Set(results.map(r => r.scheduledPracticumId));
    }

    /**
     * Get the lecturer name for a scheduled practicum (from courses → users)
     */
    static async getLecturerName(scheduledPracticumId: number): Promise<string | null> {
        const results = await db.execute(sql`
            SELECT u.full_name
            FROM scheduled_practicums sp
            LEFT JOIN courses c ON sp.course_id = c.id
            LEFT JOIN users u ON c.lecturer_id = u.identifier
            WHERE sp.id = ${scheduledPracticumId}
            LIMIT 1
        `);
        const rows = (results as unknown as any[][])[0] as any[];
        return rows[0]?.full_name || null;
    }

    /**
     * Create a new practicum report
     */
    static async create(data: CreatePracticumReportInput, createdBy: string) {
        const exists = await this.existsForUserAndSchedule(createdBy, data.scheduledPracticumId);
        if (exists) {
            throw new Error('Anda sudah mengisi berita acara untuk jadwal praktikum ini');
        }

        await db.insert(practicumReports).values({
            scheduledPracticumId: data.scheduledPracticumId,
            createdBy,
            courseName: data.courseName,
            courseCode: data.courseCode,
            lecturerName: data.lecturerName,
            roomName: data.roomName,
            practicumDate: data.practicumDate,
            startTime: data.startTime,
            endTime: data.endTime,
            batch: data.batch,
            attendeeCount: data.attendeeCount,
            condition: data.condition,
            description: data.description,
            issues: data.issues || null,
            followUp: data.followUp || null,
            status: 'Pending',
        });
    }

    /**
     * Verify (approve/reject) a practicum report
     */
    static async verify(id: number, data: VerifyPracticumReportInput, verifiedBy: string) {
        await db.update(practicumReports)
            .set({
                status: data.status,
                verifiedBy,
                verifiedAt: new Date(),
                rejectionReason: data.rejectionReason || null,
                updatedAt: new Date(),
            })
            .where(eq(practicumReports.id, id));
    }

    /**
     * Check if a report belongs to a lecturer's courses
     */
    static async belongsToLecturer(reportId: number, lecturerId: string): Promise<boolean> {
        const results = await db.execute(sql`
            SELECT pr.id
            FROM practicum_reports pr
            LEFT JOIN scheduled_practicums sp ON pr.scheduled_practicum_id = sp.id
            LEFT JOIN courses c ON sp.course_id = c.id
            WHERE pr.id = ${reportId} AND c.lecturer_id = ${lecturerId}
            LIMIT 1
        `);
        const rows = (results as unknown as any[][])[0] as any[];
        return rows.length > 0;
    }

    /**
     * Delete a practicum report by ID
     */
    static async delete(id: number) {
        await db.delete(practicumReports).where(eq(practicumReports.id, id));
    }

    /**
     * Delete all practicum reports
     */
    static async deleteAll() {
        await db.delete(practicumReports);
    }
}

/**
 * Practicum Report (Berita Acara) Validator
 */

import { z } from 'zod';

export const createPracticumReportSchema = z.object({
    scheduledPracticumId: z.coerce.number().min(1, 'Jadwal praktikum harus dipilih'),

    // Snapshot data
    courseName: z.string().min(1, 'Nama matakuliah diperlukan'),
    courseCode: z.string().min(1, 'Kode matakuliah diperlukan'),
    lecturerName: z.string().nullable(),
    roomName: z.string().min(1, 'Nama ruangan diperlukan'),
    practicumDate: z.coerce.date(),
    startTime: z.string().regex(/^\d{2}:\d{2}$/, 'Format waktu harus HH:MM'),
    endTime: z.string().regex(/^\d{2}:\d{2}$/, 'Format waktu harus HH:MM'),

    // Data yang diisi pengguna
    batch: z.string().min(1, 'Angkatan harus diisi'),
    attendeeCount: z.coerce.number().min(0, 'Jumlah kehadiran tidak boleh negatif'),
    condition: z.enum(['Lancar', 'Kurang Lancar', 'Terkendala'], {
        message: 'Kondisi praktikum harus dipilih',
    }),
    description: z.string().min(1, 'Deskripsi pelaksanaan harus diisi').max(2000, 'Deskripsi maksimal 2000 karakter'),
    issues: z.string().max(2000, 'Kendala maksimal 2000 karakter').optional(),
    followUp: z.string().max(2000, 'Tindak lanjut maksimal 2000 karakter').optional(),
});

export const verifyPracticumReportSchema = z.object({
    status: z.enum(['Diverifikasi', 'Ditolak'], {
        message: 'Status verifikasi harus dipilih',
    }),
    rejectionReason: z.string().max(1000, 'Alasan penolakan maksimal 1000 karakter').optional(),
}).refine((data) => {
    if (data.status === 'Ditolak' && (!data.rejectionReason || data.rejectionReason.trim() === '')) {
        return false;
    }
    return true;
}, {
    message: 'Alasan penolakan harus diisi jika status ditolak',
    path: ['rejectionReason'],
});

'use server';

import { PracticumService } from './service';
import { revalidatePath } from 'next/cache';
import { requirePermission } from '@/lib/auth';
import { deleteFile } from '@/lib/upload';
import type { CreateModuleInput, UpdateModuleInput } from './types';

/**
 * Get all practicum modules
 */
export async function getModules() {
    return PracticumService.getAll();
}

/**
 * Get modules for courses taught by a specific lecturer
 */
export async function getModulesByLecturerId(lecturerId: string) {
    return PracticumService.getByLecturerId(lecturerId);
}

/**
 * Get module by ID
 */
export async function getModuleById(id: number) {
    return PracticumService.getById(id);
}

/**
 * Search modules
 */
export async function searchModules(query: string) {
    return PracticumService.search(query);
}

/**
 * Get modules by course
 */
export async function getModulesByCourse(courseId: number) {
    return PracticumService.getByCourseId(courseId);
}

/**
 * Create new module
 */
export async function createModule(data: CreateModuleInput) {
    await requirePermission('practicum.manage');
    await PracticumService.create(data);
    revalidatePath('/admin/practicum');
    revalidatePath('/lecturer/practicum');
    revalidatePath('/student/practicum');
}

/**
 * Update module
 */
export async function updateModule(id: number, data: UpdateModuleInput) {
    await requirePermission('practicum.manage');

    // Delete old file if a new filePath is provided
    if (data.filePath) {
        const oldModule = await PracticumService.getById(id);
        if (oldModule?.filePath && oldModule.filePath !== data.filePath) {
            await deleteFile(oldModule.filePath);
        }
    }

    await PracticumService.update(id, data);
    revalidatePath('/admin/practicum');
    revalidatePath('/lecturer/practicum');
    revalidatePath('/student/practicum');
}

/**
 * Delete module
 */
export async function deleteModule(id: number) {
    await requirePermission('practicum.manage');

    // Delete file from disk before DB delete
    const mod = await PracticumService.getById(id);
    if (mod?.filePath) {
        await deleteFile(mod.filePath);
    }

    await PracticumService.delete(id);
    revalidatePath('/admin/practicum');
    revalidatePath('/lecturer/practicum');
    revalidatePath('/student/practicum');
}

'use client';

import { useState, useMemo } from 'react';
import { BookOpen, Search, ExternalLink, FileText, LayoutGrid, List } from 'lucide-react';
import type { PracticumModuleWithCourse } from '@/features/practicum/types';
import type { CourseWithLecturer } from '@/features/courses/types';

interface ModuleListProps {
    modules: PracticumModuleWithCourse[];
    courses: CourseWithLecturer[];
}

export default function ModuleList({ modules, courses }: ModuleListProps) {
    // Search & Filter
    const [searchQuery, setSearchQuery] = useState('');
    const [filterCourseId, setFilterCourseId] = useState('');

    // Pagination & View Mode
    const [viewMode, setViewMode] = useState<'grid' | 'list'>(() => {
        if (typeof window !== 'undefined') {
            return window.innerWidth >= 768 ? 'list' : 'grid';
        }
        return 'list';
    });
    const [currentPage, setCurrentPage] = useState(1);
    const perPage = 12;

    // Filtered modules
    const filteredModules = useMemo(() => {
        return modules.filter(m => {
            if (searchQuery) {
                const query = searchQuery.toLowerCase();
                if (!m.name.toLowerCase().includes(query)) {
                    return false;
                }
            }
            if (filterCourseId) {
                if (m.courseId !== parseInt(filterCourseId)) {
                    return false;
                }
            }
            return true;
        });
    }, [modules, searchQuery, filterCourseId]);

    // Apply pagination
    const totalPages = Math.ceil(filteredModules.length / perPage);
    const paginatedModules = useMemo(() => {
        const startIndex = (currentPage - 1) * perPage;
        return filteredModules.slice(startIndex, startIndex + perPage);
    }, [filteredModules, currentPage, perPage]);

    // Handle search/filter changes (reset pagination)
    const handleSearchChange = (val: string) => {
        setSearchQuery(val);
        setCurrentPage(1);
    };

    const handleCourseFilterChange = (val: string) => {
        setFilterCourseId(val);
        setCurrentPage(1);
    };

    return (
        <div className="space-y-6">
            {/* Header */}
            <div>
                <h1 className="text-2xl font-bold text-gray-900">Modul Praktikum</h1>
                <p className="text-gray-500 text-sm mt-1">Daftar modul praktikum yang tersedia</p>
            </div>

            {/* Search & Filter */}
            <div className="bg-white p-4 rounded-xl shadow-sm border border-gray-100">
                <div className="flex flex-col md:flex-row gap-3">
                    <div className="flex-1 relative">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                        <input
                            type="text"
                            placeholder="Cari modul..."
                            value={searchQuery}
                            onChange={(e) => handleSearchChange(e.target.value)}
                            className="w-full pl-10 pr-4 py-2 rounded-lg border border-gray-200 focus:outline-none focus:ring-2 focus:ring-primary/20"
                        />
                    </div>
                    <select
                        value={filterCourseId}
                        onChange={(e) => handleCourseFilterChange(e.target.value)}
                        className="px-4 py-2 rounded-lg border border-gray-200 focus:outline-none focus:ring-2 focus:ring-primary/20 min-w-0 w-full sm:min-w-[11.25rem] sm:w-auto"
                    >
                        <option value="">Semua Mata Kuliah</option>
                        {courses.map(course => (
                            <option key={course.id} value={course.id}>{course.code} - {course.name}</option>
                        ))}
                    </select>
                </div>

            </div>

            {/* Toolbar */}
            <div className="flex items-center justify-between">
                <p className="text-sm text-gray-500">
                    Menampilkan {filteredModules.length > 0 ? (currentPage - 1) * perPage + 1 : 0}-{Math.min(currentPage * perPage, filteredModules.length)} dari {filteredModules.length} modul
                </p>
                <div className="hidden md:flex items-center bg-gray-100 rounded-lg p-0.5">
                    <button
                        onClick={() => setViewMode('grid')}
                        className={`p-1.5 rounded ${viewMode === 'grid' ? 'bg-white shadow-sm text-[#0F4C81]' : 'text-gray-500 hover:text-gray-700'}`} title="Tampilan Grid">
                        <LayoutGrid className="w-4 h-4" />
                    </button>
                    <button
                        onClick={() => setViewMode('list')}
                        className={`p-1.5 rounded ${viewMode === 'list' ? 'bg-white shadow-sm text-[#0F4C81]' : 'text-gray-500 hover:text-gray-700'}`} title="Tampilan List">
                        <List className="w-4 h-4" />
                    </button>
                </div>
            </div>

            {/* Module List */}
            {filteredModules.length === 0 ? (
                <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-8 text-center">
                    <BookOpen className="w-12 h-12 text-gray-300 mx-auto mb-3" />
                    <p className="text-gray-500">
                        {searchQuery || filterCourseId ? 'Tidak ada modul yang sesuai filter.' : 'Belum ada modul praktikum.'}
                    </p>
                </div>
            ) : viewMode === 'list' ? (
                <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
                    <div className="overflow-x-auto">
                        <table className="w-full">
                            <thead>
                                <tr className="border-b border-gray-100 text-left text-sm text-gray-500">
                                    <th className="px-6 py-3 font-medium">Judul Modul</th>
                                    <th className="px-4 py-3 font-medium">Mata Kuliah</th>
                                    <th className="px-4 py-3 font-medium">Deskripsi</th>
                                    <th className="px-4 py-3 font-medium">Akses</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-100">
                                {paginatedModules.map((module) => (
                                    <tr key={module.id} className="hover:bg-gray-50 transition-colors">
                                        <td className="px-6 py-4">
                                            <div className="flex items-center gap-2">
                                                <BookOpen className="w-4 h-4 text-[#0F4C81] flex-shrink-0" />
                                                <span className="font-medium text-gray-900 line-clamp-1">{module.name}</span>
                                            </div>
                                        </td>
                                        <td className="px-4 py-4 text-sm text-gray-600">
                                            {module.courseName ? (
                                                <span className="inline-flex px-2 py-0.5 rounded text-xs font-medium bg-blue-50 text-blue-700 whitespace-nowrap">
                                                    {module.courseCode} - {module.courseName}
                                                </span>
                                            ) : '-'}
                                        </td>
                                        <td className="px-4 py-4 text-sm text-gray-500">
                                            <p className="line-clamp-2 max-w-xs">{module.description || '-'}</p>
                                        </td>
                                        <td className="px-4 py-4">
                                            {module.filePath || module.moduleLink ? (
                                                <div className="flex items-center gap-2 flex-wrap">
                                                    {module.filePath && (
                                                        <a
                                                            href={module.filePath}
                                                            target="_blank"
                                                            rel="noopener noreferrer"
                                                            className="inline-flex items-center gap-1 text-[#0F4C81] hover:text-blue-700 text-sm font-medium"
                                                        >
                                                            <ExternalLink className="w-3 h-3" /> File
                                                        </a>
                                                    )}
                                                    {module.moduleLink && (
                                                        <a
                                                            href={module.moduleLink}
                                                            target="_blank"
                                                            rel="noopener noreferrer"
                                                            className="inline-flex items-center gap-1 text-emerald-700 hover:text-emerald-800 text-sm font-medium"
                                                        >
                                                            <ExternalLink className="w-3 h-3" /> Link
                                                        </a>
                                                    )}
                                                </div>
                                            ) : (
                                                <span className="text-gray-400 text-sm">Tidak tersedia</span>
                                            )}
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </div>
            ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                    {paginatedModules.map((module) => (
                        <div key={module.id} className="bg-white rounded-xl shadow-sm border border-gray-100 p-5 hover:shadow-md transition-shadow">
                            <div className="flex items-center gap-2 mb-3">
                                <BookOpen className="w-5 h-5 text-[#0F4C81]" />
                                <h3 className="font-semibold text-gray-900 line-clamp-1">{module.name}</h3>
                            </div>
                            {module.description && (
                                <p className="text-sm text-gray-600 mb-3 line-clamp-2">{module.description}</p>
                            )}
                            {module.courseName && (
                                <div className="mb-3">
                                    <span className="inline-flex px-2 py-0.5 rounded text-xs font-medium bg-blue-50 text-blue-700">
                                        {module.courseCode} - {module.courseName}
                                    </span>
                                </div>
                            )}
                            {module.filePath || module.moduleLink ? (
                                <div className="flex items-center gap-2 flex-wrap">
                                    {module.filePath && (
                                        <a
                                            href={module.filePath}
                                            target="_blank"
                                            rel="noopener noreferrer"
                                            className="inline-flex items-center gap-2 text-sm text-white bg-[#0F4C81] hover:bg-[#0F4C81]/90 px-3 py-1.5 rounded-lg transition-colors w-max"
                                        >
                                            <ExternalLink className="w-3 h-3" />
                                            Download Modul
                                        </a>
                                    )}
                                    {module.moduleLink && (
                                        <a
                                            href={module.moduleLink}
                                            target="_blank"
                                            rel="noopener noreferrer"
                                            className="inline-flex items-center gap-2 text-sm text-emerald-700 bg-emerald-50 hover:bg-emerald-100 px-3 py-1.5 rounded-lg transition-colors w-max"
                                        >
                                            <ExternalLink className="w-3 h-3" />
                                            Buka Link
                                        </a>
                                    )}
                                </div>
                            ) : (
                                <span className="inline-flex items-center gap-1 text-sm text-gray-400">
                                    <FileText className="w-3 h-3" />
                                    File belum tersedia
                                </span>
                            )}
                        </div>
                    ))}
                </div>
            )}

            {/* Pagination Controls */}
            {totalPages > 1 && (
                <div className="flex items-center justify-center gap-2 mt-6">
                    <button
                        onClick={() => setCurrentPage(p => Math.max(1, p - 1))}
                        disabled={currentPage === 1}
                        className={`px-4 py-2 rounded-lg text-sm transition-colors ${currentPage === 1
                            ? 'bg-gray-100 text-gray-400 cursor-not-allowed'
                            : 'bg-white border border-gray-200 text-gray-600 hover:bg-gray-50'
                            }`}
                    >
                        ← Sebelumnya
                    </button>

                    {Array.from({ length: Math.min(totalPages, 7) }, (_, i) => {
                        let pageNum: number;
                        if (totalPages <= 7) pageNum = i + 1;
                        else if (currentPage <= 4) pageNum = i + 1;
                        else if (currentPage >= totalPages - 3) pageNum = totalPages - 6 + i;
                        else pageNum = currentPage - 3 + i;

                        return (
                            <button
                                key={pageNum}
                                onClick={() => setCurrentPage(pageNum)}
                                className={`px-3 py-2 rounded-lg text-sm transition-colors ${pageNum === currentPage
                                    ? 'bg-[#0F4C81] text-white'
                                    : 'bg-white border border-gray-200 text-gray-600 hover:bg-gray-50'
                                    }`}
                            >
                                {pageNum}
                            </button>
                        );
                    })}

                    <button
                        onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))}
                        disabled={currentPage === totalPages}
                        className={`px-4 py-2 rounded-lg text-sm transition-colors ${currentPage === totalPages
                            ? 'bg-gray-100 text-gray-400 cursor-not-allowed'
                            : 'bg-white border border-gray-200 text-gray-600 hover:bg-gray-50'
                            }`}
                    >
                        Selanjutnya →
                    </button>
                </div>
            )}
        </div>
    );
}

'use client';

import { useState, useTransition, useMemo } from 'react';
import { BookOpen, Plus, Trash2, Edit, Upload, X, Search, FileText, ExternalLink, LayoutGrid, List as ListIcon } from 'lucide-react';
import { createModule, updateModule, deleteModule } from '@/features/practicum/actions';
import type { PracticumModuleWithCourse } from '@/features/practicum/types';
import type { CourseWithLecturer } from '@/features/courses/types';

interface ModuleManagerProps {
    modules: PracticumModuleWithCourse[];
    courses: CourseWithLecturer[];
}

export default function ModuleManager({ modules, courses }: ModuleManagerProps) {
    const [isPending, startTransition] = useTransition();
    const [message, setMessage] = useState<{ type: 'success' | 'error'; text: string } | null>(null);
    const [showForm, setShowForm] = useState(false);
    const [editingModule, setEditingModule] = useState<PracticumModuleWithCourse | null>(null);
    const [selectedFile, setSelectedFile] = useState<File | null>(null);

    // Search & Filter
    const [searchQuery, setSearchQuery] = useState('');
    const [filterCourseId, setFilterCourseId] = useState('');

    // Pagination & View Mode
    const [viewMode, setViewMode] = useState<'grid' | 'list'>(() => {
        if (typeof window !== 'undefined') {
            return window.innerWidth >= 768 ? 'list' : 'grid';
        }
        return 'list';
    });
    const [currentPage, setCurrentPage] = useState(1);
    const perPage = 12;

    // Filtered modules
    const filteredModules = useMemo(() => {
        return modules.filter(m => {
            if (searchQuery) {
                const query = searchQuery.toLowerCase();
                if (!m.name.toLowerCase().includes(query)) return false;
            }
            if (filterCourseId) {
                if (m.courseId !== parseInt(filterCourseId)) return false;
            }
            return true;
        });
    }, [modules, searchQuery, filterCourseId]);

    // Apply pagination
    const totalPages = Math.ceil(filteredModules.length / perPage);
    const paginatedModules = useMemo(() => {
        const startIndex = (currentPage - 1) * perPage;
        return filteredModules.slice(startIndex, startIndex + perPage);
    }, [filteredModules, currentPage, perPage]);

    // Navigate back to page 1 if search/filter changes
    const handleSearchChange = (val: string) => {
        setSearchQuery(val);
        setCurrentPage(1);
    };

    const handleCourseFilterChange = (val: string) => {
        setFilterCourseId(val);
        setCurrentPage(1);
    };

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            if (file.size > 2 * 1024 * 1024) {
                alert('Ukuran file maksimal 2MB');
                e.target.value = '';
                return;
            }
            setSelectedFile(file);
        }
    };

    const normalizeLink = (raw: string): string => {
        const trimmed = raw.trim();
        if (!trimmed) return '';
        if (/^https?:\/\//i.test(trimmed)) return trimmed;
        return `https://${trimmed}`;
    };

    const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
        e.preventDefault();
        const formData = new FormData(e.currentTarget);
        const name = formData.get('name') as string;
        const description = formData.get('description') as string;
        const courseId = formData.get('courseId') as string;
        const moduleLink = normalizeLink((formData.get('moduleLink') as string) || '');

        startTransition(async () => {
            try {
                let filePath: string | undefined;

                // Upload file if selected
                if (selectedFile) {
                    const uploadFormData = new FormData();
                    uploadFormData.append('file', selectedFile);
                    uploadFormData.append('folder', 'practicum');

                    const uploadRes = await fetch('/api/upload', {
                        method: 'POST',
                        body: uploadFormData,
                    });

                    if (!uploadRes.ok) {
                        throw new Error('Gagal mengupload file');
                    }

                    const uploadData = await uploadRes.json();
                    filePath = uploadData.path;
                }

                if (editingModule) {
                    await updateModule(editingModule.id, {
                        name,
                        description: description || undefined,
                        courseId: courseId ? parseInt(courseId) : undefined,
                        filePath: filePath || undefined,
                        moduleLink,
                    });
                    setMessage({ type: 'success', text: 'Modul berhasil diperbarui!' });
                } else {
                    await createModule({
                        name,
                        description: description || undefined,
                        courseId: courseId ? parseInt(courseId) : undefined,
                        filePath,
                        moduleLink,
                    });
                    setMessage({ type: 'success', text: 'Modul berhasil ditambahkan!' });
                }

                setShowForm(false);
                setEditingModule(null);
                setSelectedFile(null);
            } catch {
                setMessage({ type: 'error', text: 'Gagal menyimpan modul' });
            }
        });
    };

    const handleDelete = (id: number) => {
        if (!confirm('Hapus modul ini?')) return;
        startTransition(async () => {
            try {
                await deleteModule(id);
                setMessage({ type: 'success', text: 'Modul berhasil dihapus!' });
            } catch {
                setMessage({ type: 'error', text: 'Gagal menghapus modul' });
            }
        });
    };

    const handleEdit = (module: PracticumModuleWithCourse) => {
        setEditingModule(module);
        setShowForm(true);
        setSelectedFile(null);
    };

    return (
        <div className="space-y-6">
            {/* Header */}
            <div className="flex justify-between items-center">
                <div>
                    <h1 className="text-2xl font-bold text-gray-900">Modul Praktikum</h1>
                    <p className="text-gray-500 text-sm mt-1">Kelola modul praktikum laboratorium</p>
                </div>
                <button
                    onClick={() => { setShowForm(true); setEditingModule(null); }}
                    className="bg-[#0F4C81] text-white px-4 py-2 rounded-lg text-sm font-medium hover:bg-[#0F4C81]/90 transition-colors flex items-center gap-2"
                >
                    <Plus className="w-4 h-4" />
                    Tambah Modul
                </button>
            </div>

            {/* Message */}
            {message && (
                <div className={`p-4 rounded-lg ${message.type === 'success' ? 'bg-green-50 text-green-700' : 'bg-red-50 text-red-700'}`}>
                    {message.text}
                </div>
            )}

            {/* Form Modal */}
            {showForm && (
                <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
                    <div className="bg-white rounded-xl shadow-xl max-w-2xl w-full max-h-[90vh] overflow-y-auto">
                        <div className="p-6 border-b border-gray-100 flex items-center justify-between">
                            <h3 className="text-lg font-semibold text-gray-900">
                                {editingModule ? 'Edit Modul' : 'Tambah Modul Baru'}
                            </h3>
                            <button onClick={() => { setShowForm(false); setEditingModule(null); }} className="text-gray-400 hover:text-gray-600">
                                <X className="w-5 h-5" />
                            </button>
                        </div>
                        <form onSubmit={handleSubmit} className="p-6 space-y-4">
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">Nama Modul *</label>
                                <input
                                    name="name"
                                    required
                                    defaultValue={editingModule?.name || ''}
                                    className="w-full px-4 py-2 rounded-lg border border-gray-200 focus:outline-none focus:ring-2 focus:ring-primary/20"
                                    placeholder="Modul 1 - Dasar Kriptografi"
                                />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">Mata Kuliah</label>
                                <select
                                    name="courseId"
                                    defaultValue={editingModule?.courseId || ''}
                                    className="w-full px-4 py-2 rounded-lg border border-gray-200 focus:outline-none focus:ring-2 focus:ring-primary/20"
                                >
                                    <option value="">-- Pilih Mata Kuliah --</option>
                                    {courses.map(course => (
                                        <option key={course.id} value={course.id}>
                                            {course.code} - {course.name}
                                        </option>
                                    ))}
                                </select>
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">
                                    {editingModule ? 'File (Opsional - biarkan kosong jika tidak ingin mengubah)' : 'File'}
                                </label>
                                <div className="border-2 border-dashed border-gray-200 rounded-lg p-4 text-center hover:bg-gray-50 transition-colors cursor-pointer relative">
                                    <input
                                        type="file"
                                        accept=".pdf,.doc,.docx,.ppt,.pptx"
                                        onChange={handleFileChange}
                                        className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
                                    />
                                    {selectedFile ? (
                                        <div className="flex items-center justify-center gap-2 text-[#0F4C81]">
                                            <FileText className="w-5 h-5" />
                                            <span className="text-sm">{selectedFile.name}</span>
                                        </div>
                                    ) : editingModule?.filePath ? (
                                        <div className="text-sm text-gray-500">
                                            File saat ini: {editingModule.filePath.split('/').pop()}
                                            <br />
                                            <span className="text-xs">Klik untuk mengganti</span>
                                        </div>
                                    ) : (
                                        <div className="py-4">
                                            <Upload className="w-8 h-8 text-gray-400 mx-auto mb-2" />
                                            <p className="text-sm text-gray-500">Klik atau drag file ke sini</p>
                                            <p className="text-xs text-gray-400 mt-1">PDF, DOC, DOCX, PPT, PPTX (Maks. 2MB)</p>
                                        </div>
                                    )}
                                </div>
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">Link Modul (Opsional)</label>
                                <input
                                    name="moduleLink"
                                    type="url"
                                    defaultValue={editingModule?.moduleLink || ''}
                                    className="w-full px-4 py-2 rounded-lg border border-gray-200 focus:outline-none focus:ring-2 focus:ring-primary/20"
                                    placeholder="https://drive.google.com/..."
                                />
                                <p className="text-xs text-gray-400 mt-1">Bisa isi link Google Drive, OneDrive, GitBook, atau URL lainnya.</p>
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-1">Deskripsi</label>
                                <textarea
                                    name="description"
                                    rows={3}
                                    defaultValue={editingModule?.description || ''}
                                    className="w-full px-4 py-2 rounded-lg border border-gray-200 focus:outline-none focus:ring-2 focus:ring-primary/20"
                                    placeholder="Deskripsi modul..."
                                />
                            </div>
                            <div className="flex gap-3 pt-4">
                                <button
                                    type="submit"
                                    disabled={isPending}
                                    className="bg-[#0F4C81] text-white px-6 py-2 rounded-lg text-sm font-medium hover:bg-[#0F4C81]/90 transition-colors disabled:opacity-50"
                                >
                                    {isPending ? 'Menyimpan...' : editingModule ? 'Simpan Perubahan' : 'Tambah Modul'}
                                </button>
                                <button
                                    type="button"
                                    onClick={() => { setShowForm(false); setEditingModule(null); }}
                                    className="text-gray-500 hover:text-gray-700 px-6 py-2 rounded-lg text-sm font-medium"
                                >
                                    Batal
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            )}

            {/* Search & Filter */}
            <div className="bg-white p-4 rounded-xl shadow-sm border border-gray-100 mt-6">
                <div className="flex flex-col md:flex-row gap-3">
                    <div className="flex-1 relative">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                        <input
                            type="text"
                            placeholder="Cari modul..."
                            value={searchQuery}
                            onChange={(e) => handleSearchChange(e.target.value)}
                            className="w-full pl-10 pr-4 py-2 rounded-lg border border-gray-200 focus:outline-none focus:ring-2 focus:ring-[#0F4C81]/20"
                        />
                    </div>
                    <select
                        value={filterCourseId}
                        onChange={(e) => handleCourseFilterChange(e.target.value)}
                        className="px-4 py-2 rounded-lg border border-gray-200 focus:outline-none focus:ring-2 focus:ring-[#0F4C81]/20 min-w-0 w-full sm:min-w-[11.25rem] sm:w-auto"
                    >
                        <option value="">Semua Mata Kuliah</option>
                        {courses.map(course => (
                            <option key={course.id} value={course.id}>{course.code} - {course.name}</option>
                        ))}
                    </select>
                </div>
            </div>

            {/* Toolbar */}
            <div className="flex items-center justify-between mb-4">
                <p className="text-xs text-gray-500">
                    Menampilkan {filteredModules.length > 0 ? (currentPage - 1) * perPage + 1 : 0}-{Math.min(currentPage * perPage, filteredModules.length)} dari {filteredModules.length} modul
                </p>
                <div className="hidden md:flex items-center bg-gray-100 rounded-lg p-0.5">
                    <button
                        onClick={() => setViewMode('grid')}
                        className={`p-1.5 rounded ${viewMode === 'grid' ? 'bg-white shadow-sm text-[#0F4C81]' : 'text-gray-500 hover:text-gray-700'}`} title="Tampilan Grid">
                        <LayoutGrid className="w-4 h-4" />
                    </button>
                    <button
                        onClick={() => setViewMode('list')}
                        className={`p-1.5 rounded ${viewMode === 'list' ? 'bg-white shadow-sm text-[#0F4C81]' : 'text-gray-500 hover:text-gray-700'}`} title="Tampilan List">
                        <ListIcon className="w-4 h-4" />
                    </button>
                </div>
            </div>

            {/* Module Content */}
            {filteredModules.length === 0 ? (
                <div className="bg-white text-center py-12 rounded-xl border border-gray-100 shadow-sm text-gray-500">
                    <BookOpen className="w-12 h-12 text-gray-300 mx-auto mb-2" />
                    <p className="text-sm">
                        {searchQuery || filterCourseId ? 'Tidak ada modul yang sesuai filter.' : 'Belum ada modul praktikum.'}
                    </p>
                </div>
            ) : viewMode === 'list' ? (
                <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
                    <div className="overflow-x-auto">
                        <table className="w-full text-sm">
                            <thead className="bg-gray-50 border-b border-gray-100">
                                <tr>
                                    <th className="text-left px-6 py-3 font-semibold text-gray-600">Nama Modul</th>
                                    <th className="text-left px-6 py-3 font-semibold text-gray-600">Mata Kuliah</th>
                                    <th className="text-left px-6 py-3 font-semibold text-gray-600">Akses Modul</th>
                                    <th className="text-center px-6 py-3 font-semibold text-gray-600">Aksi</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-50">
                                {paginatedModules.map((module) => (
                                    <tr key={module.id} className="hover:bg-gray-50/50 transition-colors">
                                        <td className="px-6 py-4">
                                            <div className="flex items-center gap-2">
                                                <BookOpen className="w-4 h-4 text-[#0F4C81]" />
                                                <div className="font-medium text-gray-900">{module.name}</div>
                                            </div>
                                            {module.description && (
                                                <p className="text-xs text-gray-500 mt-1 line-clamp-1">{module.description}</p>
                                            )}
                                        </td>
                                        <td className="px-6 py-4">
                                            {module.courseName ? (
                                                <span className="inline-flex px-2 py-0.5 rounded text-xs font-medium bg-blue-50 text-blue-700 border border-blue-100">
                                                    {module.courseCode} - {module.courseName}
                                                </span>
                                            ) : (
                                                <span className="text-gray-400 text-xs">-</span>
                                            )}
                                        </td>
                                        <td className="px-6 py-4">
                                            {module.filePath || module.moduleLink ? (
                                                <div className="flex flex-wrap items-center gap-2">
                                                    {module.filePath && (
