                                <div className="flex items-center gap-2">
                                    <BookOpen className="w-5 h-5 text-[#0F4C81]" />
                                    <h3 className="font-semibold text-gray-900 line-clamp-1">{module.name}</h3>
                                </div>
                                <div className="flex gap-1 ml-2 flex-shrink-0">
                                    <button
                                        onClick={() => handleEdit(module)}
                                        className="text-blue-500 hover:text-blue-700 p-1.5 hover:bg-blue-50 rounded-lg transition-colors"
                                        title="Edit"
                                    >
                                        <Edit className="w-4 h-4" />
                                    </button>
                                    <button
                                        onClick={() => handleDelete(module.id)}
                                        className="text-red-500 hover:text-red-700 p-1.5 hover:bg-red-50 rounded-lg transition-colors"
                                        title="Hapus"
                                    >
                                        <Trash2 className="w-4 h-4" />
                                    </button>
                                </div>
                            </div>
                            {module.description && (
                                <p className="text-sm text-gray-600 mb-3 line-clamp-2">{module.description}</p>
                            )}
                            <div className="flex items-end justify-between mt-4 top-auto">
                                <div>
                                    {module.courseName && (
                                        <div className="mb-2">
                                            <span className="inline-flex px-2 py-0.5 rounded text-xs font-medium bg-blue-50 text-blue-700 border border-blue-100">
                                                {module.courseCode} - {module.courseName}
                                            </span>
                                        </div>
                                    )}
                                </div>
                                <div>
                                    <div className="flex items-center gap-2">
                                        {module.filePath && (
                                            <a
                                                href={module.filePath}
                                                target="_blank"
                                                rel="noopener noreferrer"
                                                className="inline-flex items-center gap-1 text-xs font-medium text-[#0F4C81] hover:text-blue-800 bg-blue-50/50 hover:bg-blue-100 px-2.5 py-1.5 rounded-lg transition-colors"
                                            >
                                                <ExternalLink className="w-3.5 h-3.5" />
                                                File
                                            </a>
                                        )}
                                        {module.moduleLink && (
                                            <a
                                                href={module.moduleLink}
                                                target="_blank"
                                                rel="noopener noreferrer"
                                                className="inline-flex items-center gap-1 text-xs font-medium text-emerald-700 hover:text-emerald-800 bg-emerald-50 hover:bg-emerald-100 px-2.5 py-1.5 rounded-lg transition-colors"
                                            >
                                                <ExternalLink className="w-3.5 h-3.5" />
                                                Link
                                            </a>
                                        )}
                                    </div>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            )}

            {/* Pagination Controls */}
            {totalPages > 1 && (
                <div className="flex items-center justify-center gap-2 mt-6">
                    <button
                        onClick={() => setCurrentPage(p => Math.max(1, p - 1))}
                        disabled={currentPage === 1}
                        className={`px-4 py-2 rounded-lg text-sm transition-colors ${currentPage === 1
                            ? 'bg-gray-100 text-gray-400 cursor-not-allowed'
                            : 'bg-white border border-gray-200 text-gray-600 hover:bg-gray-50'
                            }`}
                    >
                        ← Sebelumnya
                    </button>

                    {Array.from({ length: Math.min(totalPages, 7) }, (_, i) => {
                        let pageNum: number;
                        if (totalPages <= 7) pageNum = i + 1;
                        else if (currentPage <= 4) pageNum = i + 1;
                        else if (currentPage >= totalPages - 3) pageNum = totalPages - 6 + i;
                        else pageNum = currentPage - 3 + i;

                        return (
                            <button
                                key={pageNum}
                                onClick={() => setCurrentPage(pageNum)}
                                className={`px-3 py-2 rounded-lg text-sm transition-colors ${pageNum === currentPage
                                    ? 'bg-[#0F4C81] text-white'
                                    : 'bg-white border border-gray-200 text-gray-600 hover:bg-gray-50'
                                    }`}
                            >
                                {pageNum}
                            </button>
                        );
                    })}

                    <button
                        onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))}
                        disabled={currentPage === totalPages}
                        className={`px-4 py-2 rounded-lg text-sm transition-colors ${currentPage === totalPages
                            ? 'bg-gray-100 text-gray-400 cursor-not-allowed'
                            : 'bg-white border border-gray-200 text-gray-600 hover:bg-gray-50'
                            }`}
                    >
                        Selanjutnya →
                    </button>
                </div>
            )}
        </div>
    );
}

/**
 * Practicum Module Service
 * Business logic for practicum modules management
 */

import { db } from '@/db';
import { practicumModules, courses } from '@/db/schema';
import { eq, desc, like, or } from 'drizzle-orm';
import type { CreateModuleInput, UpdateModuleInput } from './types';

export class PracticumService {
    /**
     * Get all modules with course info
     */
    static async getAll() {
        return await db
            .select({
                id: practicumModules.id,
                courseId: practicumModules.courseId,
                name: practicumModules.name,
                description: practicumModules.description,
                filePath: practicumModules.filePath,
                moduleLink: practicumModules.moduleLink,
                createdAt: practicumModules.createdAt,
                updatedAt: practicumModules.updatedAt,
                courseName: courses.name,
                courseCode: courses.code,
            })
            .from(practicumModules)
            .leftJoin(courses, eq(practicumModules.courseId, courses.id))
            .orderBy(desc(practicumModules.createdAt));
    }

    /**
     * Get all modules for courses taught by a specific lecturer
     */
    static async getByLecturerId(lecturerId: string) {
        return await db
            .select({
                id: practicumModules.id,
                courseId: practicumModules.courseId,
                name: practicumModules.name,
                description: practicumModules.description,
                filePath: practicumModules.filePath,
                moduleLink: practicumModules.moduleLink,
                createdAt: practicumModules.createdAt,
                updatedAt: practicumModules.updatedAt,
                courseName: courses.name,
                courseCode: courses.code,
            })
            .from(practicumModules)
            .leftJoin(courses, eq(practicumModules.courseId, courses.id))
            .where(eq(courses.lecturerId, lecturerId))
            .orderBy(desc(practicumModules.createdAt));
    }

    /**
     * Get module by ID with course info
     */
    static async getById(id: number) {
        const results = await db
            .select({
                id: practicumModules.id,
                courseId: practicumModules.courseId,
                name: practicumModules.name,
                description: practicumModules.description,
                filePath: practicumModules.filePath,
                moduleLink: practicumModules.moduleLink,
                createdAt: practicumModules.createdAt,
                updatedAt: practicumModules.updatedAt,
                courseName: courses.name,
                courseCode: courses.code,
            })
            .from(practicumModules)
            .leftJoin(courses, eq(practicumModules.courseId, courses.id))
            .where(eq(practicumModules.id, id))
            .limit(1);

        return results[0] || null;
    }

    /**
     * Search modules by name
     */
    static async search(query: string) {
        const searchTerm = `%${query}%`;
        return await db
            .select({
                id: practicumModules.id,
                courseId: practicumModules.courseId,
                name: practicumModules.name,
                description: practicumModules.description,
                filePath: practicumModules.filePath,
                moduleLink: practicumModules.moduleLink,
                createdAt: practicumModules.createdAt,
                updatedAt: practicumModules.updatedAt,
                courseName: courses.name,
                courseCode: courses.code,
            })
            .from(practicumModules)
            .leftJoin(courses, eq(practicumModules.courseId, courses.id))
            .where(like(practicumModules.name, searchTerm))
            .orderBy(desc(practicumModules.createdAt));
    }

    /**
     * Get modules by course ID
     */
    static async getByCourseId(courseId: number) {
        return await db
            .select()
            .from(practicumModules)
            .where(eq(practicumModules.courseId, courseId))
            .orderBy(practicumModules.name);
    }

    /**
     * Create new module
     */
    static async create(data: CreateModuleInput) {
        await db.insert(practicumModules).values({
            courseId: data.courseId || null,
            name: data.name,
            description: data.description || null,
            filePath: data.filePath || null,
            moduleLink: data.moduleLink || null,
        });
    }

    /**
     * Update module
     */
    static async update(id: number, data: UpdateModuleInput) {
        const updateData: Record<string, any> = {
            updatedAt: new Date(),
        };

        if (data.courseId !== undefined) updateData.courseId = data.courseId;
        if (data.name !== undefined) updateData.name = data.name;
        if (data.description !== undefined) updateData.description = data.description;
        if (data.filePath !== undefined) updateData.filePath = data.filePath;
        if (data.moduleLink !== undefined) updateData.moduleLink = data.moduleLink || null;

        await db.update(practicumModules).set(updateData).where(eq(practicumModules.id, id));
    }

    /**
     * Delete module
     */
    static async delete(id: number) {
        await db.delete(practicumModules).where(eq(practicumModules.id, id));
    }
}

'use server';

import { PublicationService, PublicationFilters } from './service';
import { revalidatePath } from 'next/cache';
import { requirePermission, requireAnyPermission } from '@/lib/auth';
import { deleteFile } from '@/lib/upload';

// Admin/Dosen creates and publishes directly
export async function createPublication(data: {
    uploaderId: string;
    authorName: string;
    title: string;
    abstract?: string;
    keywords?: string;
    link?: string;
    filePath?: string;
    publishYear?: number;
    publishMonth?: number;
    publishDay?: number;
}) {
    await requireAnyPermission(['publications.manage', 'dashboard.lecturer']);
    await PublicationService.create(data);
    revalidatePath('/publications');
    revalidatePath('/admin/publications');
    revalidatePath('/lecturer/publications');
}

// Admin/Dosen updates a publication
export async function updatePublication(id: number, data: {
    title?: string;
    authorName?: string;
    abstract?: string;
    keywords?: string;
    link?: string;
    filePath?: string;
    publishYear?: number;
    publishMonth?: number | null;
    publishDay?: number | null;
}) {
    await requireAnyPermission(['publications.manage', 'dashboard.lecturer']);

    // Delete old file if a new filePath is provided
    if (data.filePath) {
        const oldPub = await PublicationService.getById(id);
        if (oldPub?.filePath && oldPub.filePath !== data.filePath) {
            await deleteFile(oldPub.filePath);
        }
    }

    await PublicationService.update(id, data);
    revalidatePath('/publications');
    revalidatePath('/admin/publications');
    revalidatePath('/lecturer/publications');
}

// Get publications for public view (with pagination)
export async function getPublicPublications(filters?: PublicationFilters) {
    return PublicationService.getPublished(filters);
}

// Get all publications for admin/dosen (with pagination)
export async function getPublications(filters?: PublicationFilters) {
    return PublicationService.getAll(filters);
}

// Get single publication
export async function getPublication(id: number) {
    return PublicationService.getById(id);
}

// Get all unique keywords
export async function getPublicationKeywords() {
    return PublicationService.getAllKeywords();
}

// Get all unique years
export async function getPublicationYears() {
    return PublicationService.getAllYears();
}

export async function deletePublication(id: number) {
    await requireAnyPermission(['publications.manage', 'dashboard.lecturer']);

    // Delete file from disk before DB delete
    const pub = await PublicationService.getById(id);
    if (pub?.filePath) {
        await deleteFile(pub.filePath);
    }

    await PublicationService.delete(id);
    revalidatePath('/publications');
    revalidatePath('/admin/publications');
    revalidatePath('/lecturer/publications');
    revalidatePath('/'); // Invalidate homepage "Top Publications" cache
}

export async function incrementViewCount(id: number) {
    await PublicationService.incrementViewCount(id);
    revalidatePath('/publications');
    revalidatePath('/');
}

export async function getTopPublications(limit: number = 5) {
    return PublicationService.getTop(limit);
}

// Like functionality
export async function togglePublicationLike(publicationId: number, userId: string) {
    const result = await PublicationService.toggleLike(publicationId, userId);
    revalidatePath('/publications');
    revalidatePath('/');
    return result;
}

export async function getPublicationLikeCount(publicationId: number) {
    return PublicationService.getLikeCount(publicationId);
}

export async function checkUserLikedPublication(publicationId: number, userId: string) {
    return PublicationService.checkUserLiked(publicationId, userId);
}

export async function getPublicationLikeCounts(publicationIds: number[]) {
    return PublicationService.getLikeCounts(publicationIds);
}

export async function getUserLikedPublicationIds(userId: string, publicationIds: number[]) {
    return PublicationService.getUserLikedIds(userId, publicationIds);
}

'use client';

import { useState, useTransition, useEffect } from 'react';
import { Heart } from 'lucide-react';
import { togglePublicationLike, getPublicationLikeCount, checkUserLikedPublication } from '@/features/publications/actions';

interface LikeButtonProps {
    publicationId: number;
    userId?: string; // null if not logged in
    initialLiked?: boolean;
    initialLikeCount?: number;
}

export default function LikeButton({ publicationId, userId, initialLiked, initialLikeCount }: LikeButtonProps) {
    const [isPending, startTransition] = useTransition();
    const [liked, setLiked] = useState(initialLiked ?? false);
    const [likeCount, setLikeCount] = useState(initialLikeCount ?? 0);
    const [loaded, setLoaded] = useState(initialLikeCount !== undefined);

    // Fetch data if not provided initially (for client components)
    useEffect(() => {
        if (!loaded) {
            const fetchData = async () => {
                const count = await getPublicationLikeCount(publicationId);
                setLikeCount(count);
                if (userId) {
                    const isLiked = await checkUserLikedPublication(publicationId, userId);
                    setLiked(isLiked);
                }
                setLoaded(true);
            };
            fetchData();
        }
    }, [publicationId, userId, loaded]);

    const handleLike = () => {
        if (!userId) {
            // Not logged in - show message or redirect
            alert('Silakan login untuk menyukai publikasi');
            return;
        }

        startTransition(async () => {
            const result = await togglePublicationLike(publicationId, userId);
            setLiked(result.liked);
            setLikeCount(result.likeCount);
        });
    };

    return (
        <button
            onClick={handleLike}
            disabled={isPending || !loaded}
            className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-sm font-medium transition-all disabled:opacity-50 ${liked
                    ? 'bg-red-50 text-red-600 hover:bg-red-100'
                    : 'bg-gray-50 text-gray-600 hover:bg-gray-100'
                }`}
        >
            <Heart
                className={`w-4 h-4 transition-transform ${liked ? 'fill-red-500 text-red-500 scale-110' : ''}`}
            />
            <span>{likeCount}</span>
        </button>
    );
}

