export async function updateUserProfile(data: {
    fullName?: string;
    identifier?: string;
    currentPassword: string;
    newEmail?: string;
    newPassword?: string;
    confirmNewPassword?: string;
}) {
    const session = await getSession();
    if (!session?.user) {
        throw new Error('Unauthorized');
    }

    const userId = session.user.identifier;

    // Get current user and role
    const userRecord = await UserService.getById(userId);
    if (!userRecord) {
        throw new Error('User not found');
    }

    const { user, roleName } = userRecord;

    // Verify current password
    if (!user.passwordHash) {
        throw new Error('Akun ini belum memiliki password. Silakan daftar ulang.');
    }
    const passwordMatch = await UserService.verifyPassword(data.currentPassword, user.passwordHash);
    if (!passwordMatch) {
        throw new Error('Password saat ini salah');
    }

    const updateData: any = {};
    const isAdmin = roleName === 'Admin';

    // Handle Identity Update (Admin Only)
    if (isAdmin) {
        if (data.fullName && data.fullName !== user.fullName) {
            updateData.fullName = data.fullName;
        }

        if (data.identifier && data.identifier !== user.identifier) {
            const isUnique = await UserService.isIdentifierUnique(data.identifier, userId);
            if (!isUnique) {
                throw new Error('NIM/NIDN sudah digunakan user lain');
            }
            updateData.identifier = data.identifier;
        }
    }

    // Handle Email Update
    if (data.newEmail && data.newEmail !== user.email) {
        const isUnique = await UserService.isEmailUnique(data.newEmail, userId);
        if (!isUnique) {
            throw new Error('Email sudah digunakan user lain');
        }
        updateData.email = data.newEmail;
    }

    // Handle Password Update
    if (data.newPassword) {
        if (data.newPassword !== data.confirmNewPassword) {
            throw new Error('Konfirmasi password baru tidak sesuai');
        }
        updateData.passwordHash = await UserService.hashPassword(data.newPassword);
    }

    if (Object.keys(updateData).length > 0) {
        await UserService.update(userId, {
            fullName: updateData.fullName || user.fullName,
            identifier: updateData.identifier || user.identifier,
            email: updateData.email || user.email,
            roleId: user.roleId,
            passwordHash: updateData.passwordHash,
        });
        revalidatePath('/admin/profile');
        revalidatePath('/student/profile');
        revalidatePath('/lecturer/profile');
    }
}

'use client';

import { useState } from 'react';
import { useRouter } from 'next/navigation';
import { updateUserProfile } from '@/features/users/actions';

interface ProfileFormProps {
    user: {
        fullName: string;
        identifier: string;
        email: string;
        roleName?: string;
        batch?: number;
        studyType?: string;
    };
}

export default function ProfileForm({ user }: ProfileFormProps) {
    const router = useRouter();
    const [submitting, setSubmitting] = useState(false);
    const [error, setError] = useState('');
    const [success, setSuccess] = useState('');

    const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
        e.preventDefault();
        setSubmitting(true);
        setError('');
        setSuccess('');

        const formData = new FormData(e.currentTarget);
        const data = {
            fullName: formData.get('fullName') as string || undefined,
            identifier: formData.get('identifier') as string || undefined,
            currentPassword: formData.get('currentPassword') as string,
            newEmail: formData.get('newEmail') as string || undefined,
            newPassword: formData.get('newPassword') as string || undefined,
            confirmNewPassword: formData.get('confirmNewPassword') as string || undefined,
        };

        try {
            if (!data.currentPassword) {
                throw new Error('Password saat ini diperlukan untuk menyimpan perubahan.');
            }

            if (data.newEmail && !data.newEmail.includes('@')) {
                throw new Error('Format email tidak valid.');
            }

            if (data.newPassword) {
                if (data.newPassword.length < 6) {
                    throw new Error('Password baru minimal 6 karakter.');
                }
                if (data.newPassword !== data.confirmNewPassword) {
                    throw new Error('Konfirmasi password baru tidak sesuai.');
                }
            }

            // Only call server action for Allowed fields
            await updateUserProfile({
                fullName: data.fullName,
                identifier: data.identifier,
                currentPassword: data.currentPassword,
                newEmail: data.newEmail,
                newPassword: data.newPassword,
                confirmNewPassword: data.confirmNewPassword
            });

            setSuccess('Profil berhasil diperbaharui.');
            // Clear passwords and new email field only, preserve identity fields
            const form = e.target as HTMLFormElement;
            (form.querySelector('input[name="currentPassword"]') as HTMLInputElement).value = '';
            (form.querySelector('input[name="newPassword"]') as HTMLInputElement).value = '';
            (form.querySelector('input[name="confirmNewPassword"]') as HTMLInputElement).value = '';
            (form.querySelector('input[name="newEmail"]') as HTMLInputElement).value = '';

            router.refresh();
        } catch (err: any) {
            setError(err.message || 'Gagal memperbarui profil');
        } finally {
            setSubmitting(false);
        }
    };

    const isAdmin = user.roleName === 'Admin';

    return (
        <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-6 max-w-2xl">
            <h2 className="text-lg font-semibold text-gray-900 mb-6">Profil Pengguna</h2>

            {error && (
