                <div className="flex justify-end pt-2">
                    <button
                        type="submit"
                        disabled={submitting}
                        className="px-6 py-2 bg-[#0F4C81] text-white text-sm font-semibold rounded-lg hover:bg-[#0F4C81]/90 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                    >
                        {submitting ? 'Menyimpan...' : 'Simpan Perubahan'}
                    </button>
                </div>
            </form>
        </div>
    );
}

'use server';

import { db } from '@/db';
import { users, roles } from '@/db/schema';
import { eq, and } from 'drizzle-orm';
import { revalidatePath } from 'next/cache';

export interface BulkEnrollmentInput {
    fullName: string;
    identifier: string;
    roleId: number;
    batch?: number;
    studyType?: 'Reguler' | 'Hybrid';
    programStudi?: string;
    dosenPembimbing?: string;
}

/**
 * Bulk enroll users from CSV/Excel data
 * Creates users with 'Pre-registered' status (no account yet)
 */
export async function bulkEnrollUsers(data: BulkEnrollmentInput[]) {
    const results = {
        success: 0,
        failed: 0,
        errors: [] as { identifier: string; error: string }[],
    };

    for (const user of data) {
        try {
            // Check if user with same identifier already exists
            const existing = await db.query.users.findFirst({
                where: (users, { eq }) => eq(users.identifier, user.identifier)
            });

            if (existing) {
                results.failed++;
                results.errors.push({
                    identifier: user.identifier,
                    error: 'User dengan NIM/NIDN ini sudah ada'
                });
                continue;
            }

            // Create pre-registered user
            await db.insert(users).values({
                fullName: user.fullName,
                identifier: user.identifier,
                roleId: user.roleId,
                batch: user.batch,
                studyType: user.studyType || 'Reguler',
                programStudi: user.programStudi || 'Informatika',
                dosenPembimbing: user.dosenPembimbing,
                status: 'Pre-registered',
                // email and passwordHash are null for pre-registered users
            });

            results.success++;
        } catch (error: any) {
            results.failed++;
            results.errors.push({
                identifier: user.identifier,
                error: error.message || 'Unknown error'
            });
        }
    }

    revalidatePath('/admin/governance');
    return results;
}

/**
 * Get role ID by name
 */
export async function getRoleByName(name: string) {
    const role = await db.query.roles.findFirst({
        where: (roles, { eq }) => eq(roles.name, name)
    });
    return role;
}

/**
 * Check if identifier exists in pre-registered users
 * Returns user data if found, null otherwise
 */
export async function checkPreRegisteredUser(identifier: string) {
    if (!identifier || identifier.length < 3) return null;

    const user = await db.query.users.findFirst({
        where: (users, { and, eq }) => and(
            eq(users.identifier, identifier),
            eq(users.status, 'Pre-registered')
        )
    });

    if (!user) return null;

    return {
        fullName: user.fullName,
        batch: user.batch,
        studyType: user.studyType,
        programStudi: user.programStudi,
        dosenPembimbing: user.dosenPembimbing,
    };
}

/**
 * Parse CSV string to enrollment data
 * Expected format: fullName,identifier,batch,studyType,programStudi,dosenPembimbing
 * Values containing commas should be wrapped in double quotes, e.g., "Dewi Lestari, S.T, M.Kom"
 */
export async function parseCSV(csvString: string, roleId: number): Promise<BulkEnrollmentInput[]> {
    const lines = csvString.trim().split('\n');
    const data: BulkEnrollmentInput[] = [];

    // Helper function to parse CSV line respecting quoted values
    const parseCSVLine = (line: string): string[] => {
        const result: string[] = [];
        let current = '';
        let inQuotes = false;

        for (let i = 0; i < line.length; i++) {
            const char = line[i];

            if (char === '"') {
                inQuotes = !inQuotes;
            } else if (char === ',' && !inQuotes) {
                result.push(current.trim());
                current = '';
            } else {
                current += char;
            }
        }
        result.push(current.trim()); // Push last value
        return result;
    };

    // Skip header row
    for (let i = 1; i < lines.length; i++) {
        const line = lines[i].trim();
        if (!line) continue;

        const parts = parseCSVLine(line);
        if (parts.length < 2) continue;

        const [fullName, identifier, batch, studyType, programStudi, dosenPembimbing] = parts;

        data.push({
            fullName,
            identifier,
            roleId,
            batch: batch ? parseInt(batch) : undefined,
            studyType: studyType as 'Reguler' | 'Hybrid' || 'Reguler',
            programStudi: programStudi || 'Informatika',
            dosenPembimbing: dosenPembimbing || undefined,
        });
    }

    return data;
}

'use server';

import { db } from '@/db';
import { users, roles } from '@/db/schema';
import { eq, or, and } from 'drizzle-orm';
import bcrypt from 'bcryptjs';

export async function register(formData: FormData): Promise<{ success: true } | { success: false; error: string }> {
    const fullName = formData.get('fullName') as string;
    const identifier = formData.get('identifier') as string;
    const email = formData.get('email') as string;
    const password = formData.get('password') as string;
    const confirmPassword = formData.get('confirmPassword') as string;

    if (password !== confirmPassword) {
        return { success: false, error: 'Password tidak cocok' };
    }

    const batch = formData.get('batch') ? parseInt(formData.get('batch') as string) : null;
    const studyType = formData.get('studyType') as 'Reguler' | 'Hybrid' | null;
    const programStudi = (formData.get('programStudi') as string) || 'Informatika';
    const dosenPembimbing = formData.get('dosenPembimbing') as string;

    if (!batch || !studyType) {
        return { success: false, error: 'Mohon lengkapi data angkatan dan tipe belajar' };
    }

    if (!dosenPembimbing) {
        return { success: false, error: 'Mohon pilih dosen pembimbing' };
    }

    try {
        // Check if email is already used by another user
        const existingEmail = await db.select().from(users).where(eq(users.email, email)).limit(1);
        if (existingEmail.length > 0) {
            return { success: false, error: 'Email sudah terdaftar' };
        }

        // Check if there's a pre-registered user with matching fullName and identifier
        const preRegisteredUser = await db.select().from(users).where(
            and(
                eq(users.identifier, identifier),
                eq(users.status, 'Pre-registered')
            )
        ).limit(1);

        // Hash password
        const hashedPassword = await bcrypt.hash(password, 10);

        if (preRegisteredUser.length > 0) {
            // Verify fullName matches (case-insensitive)
            const matchName = preRegisteredUser[0].fullName.toLowerCase().trim() === fullName.toLowerCase().trim();

            if (matchName) {
                // Update pre-registered user to activate their account
                await db.update(users)
                    .set({
                        email,
                        passwordHash: hashedPassword,
                        status: 'Active', // Auto-activate!
                        batch: batch || preRegisteredUser[0].batch,
                        studyType: studyType || preRegisteredUser[0].studyType,
                        programStudi: programStudi || preRegisteredUser[0].programStudi,
                        dosenPembimbing: dosenPembimbing || preRegisteredUser[0].dosenPembimbing,
                    })
                    .where(eq(users.identifier, preRegisteredUser[0].identifier));

                return { success: true };
            } else {
                return { success: false, error: 'Nama tidak cocok dengan data yang terdaftar. Hubungi admin jika ada kesalahan data.' };
            }
        }

        // Check if identifier is already used by an active/pending user
        const existingIdentifier = await db.select().from(users).where(eq(users.identifier, identifier)).limit(1);
        if (existingIdentifier.length > 0) {
            return { success: false, error: 'NIM/NIDN sudah terdaftar' };
        }

        // Get 'Mahasiswa' role
        const studentRole = await db.select().from(roles).where(eq(roles.name, 'Mahasiswa')).limit(1);

        if (studentRole.length === 0) {
            return { success: false, error: 'Role Mahasiswa tidak ditemukan. Hubungi administrator.' };
        }

        // Create new user (not pre-registered, so requires approval)
        await db.insert(users).values({
            fullName,
            identifier,
            email,
            passwordHash: hashedPassword,
            roleId: studentRole[0].id,
            status: 'Pending', // Requires admin approval
            batch,
            studyType,
            programStudi,
            dosenPembimbing
        });

        return { success: true };
    } catch (error) {
        console.error('Registration error:', error);
        return { success: false, error: 'Terjadi kesalahan saat mendaftar. Silakan coba lagi.' };
    }
}

/**
 * User Service
 * Business logic for user management
 */

import bcrypt from 'bcryptjs';
import { db } from '@/db';
import { users, roles } from '@/db/schema';
import { eq, desc, and, ne, or } from 'drizzle-orm';

export interface CreateUserInput {
    fullName: string;
    identifier: string;
    email: string;
    passwordHash: string;
    roleId: number;
    batch?: number;
    studyType?: 'Reguler' | 'Hybrid';
    programStudi?: string;
    dosenPembimbing?: string;
}

export interface UpdateUserInput {
    fullName: string;
    identifier: string;
    email: string;
    roleId: number;
    passwordHash?: string;
    batch?: number;
    studyType?: 'Reguler' | 'Hybrid';
    programStudi?: string;
    dosenPembimbing?: string;
}

export class UserService {
    /**
     * Get all users with role information
     */
    static async getAll() {
        const allUsers = await db
            .select({
                identifier: users.identifier,
                fullName: users.fullName,
                email: users.email,
                roleId: users.roleId,
                roleName: roles.name,
                createdAt: users.createdAt,
                batch: users.batch,
                studyType: users.studyType,
                programStudi: users.programStudi,
                dosenPembimbing: users.dosenPembimbing,
                customRoleEnabled: users.customRoleEnabled,
            })
            .from(users)
            .leftJoin(roles, eq(users.roleId, roles.id))
            .orderBy(desc(users.createdAt));

        return allUsers;
    }

    /**
     * Get all roles
     */
    static async getRoles() {
        return await db.select().from(roles);
    }

    /**
     * Get all lecturers (users with role "Dosen")
     */
    static async getLecturers() {
        const lecturers = await db
            .select({
                identifier: users.identifier,
                fullName: users.fullName,
            })
            .from(users)
            .innerJoin(roles, eq(users.roleId, roles.id))
            .where(eq(roles.name, 'Dosen'))
            .orderBy(users.fullName);

        return lecturers;
    }

    /**
     * Create a new user
     */
    static async create(data: CreateUserInput) {
        const existing = await db.query.users.findFirst({
            where: (users, { or, eq }) => or(
                eq(users.identifier, data.identifier),
                eq(users.email, data.email)
            )
        });

        if (existing) {
            throw new Error('NIM/NIDN atau Email sudah terdaftar');
        }

        const hashedPassword = await bcrypt.hash(data.passwordHash, 10);
        const userData = { ...data, passwordHash: hashedPassword };

        await db.insert(users).values(userData);
    }

    /**
     * Update an existing user
     */
    static async update(id: string, data: UpdateUserInput) {
        const existing = await db.query.users.findFirst({
            where: (users, { or, eq, and, ne }) => and(
                ne(users.identifier, id),
                or(
                    eq(users.identifier, data.identifier),
                    eq(users.email, data.email)
                )
            )
        });

        if (existing) {
            throw new Error('NIM/NIDN atau Email sudah digunakan user lain');
        }

        const updateData: any = { ...data };

        if (updateData.passwordHash) {
            updateData.passwordHash = await bcrypt.hash(updateData.passwordHash, 10);
        } else {
            delete updateData.passwordHash;
        }

        await db.update(users).set(updateData).where(eq(users.identifier, id));
    }

    /**
     * Delete a user
     */
    static async delete(id: string) {
        await db.delete(users).where(eq(users.identifier, id));
    }

    /**
     * Get pending users
     */
    static async getPending() {
        return await db.select({
            identifier: users.identifier,
            fullName: users.fullName,
            email: users.email,
            createdAt: users.createdAt,
            role: roles.name,
        })
            .from(users)
            .innerJoin(roles, eq(users.roleId, roles.id))
            .where(eq(users.status, 'Pending'));
    }

    /**
     * Get rejected users
     */
    static async getRejected() {
        return await db.select({
            identifier: users.identifier,
            fullName: users.fullName,
            email: users.email,
            createdAt: users.createdAt,
            role: roles.name,
        })
            .from(users)
            .innerJoin(roles, eq(users.roleId, roles.id))
            .where(eq(users.status, 'Rejected'))
            .orderBy(desc(users.createdAt));
    }

    /**
     * Update user status
     */
    static async updateStatus(userId: string, status: 'Active' | 'Rejected') {
        await db.update(users)
            .set({ status })
            .where(eq(users.identifier, userId));
    }

    static async setCustomRoleEnabled(userId: string, enabled: boolean) {
        await db.update(users)
            .set({ customRoleEnabled: enabled })
            .where(eq(users.identifier, userId));
    }

    /**
     * Get user by ID with role
     */
    static async getById(userId: string) {
        const usersWithRoles = await db
            .select({
                user: users,
                roleName: roles.name,
            })
            .from(users)
            .leftJoin(roles, eq(users.roleId, roles.id))
            .where(eq(users.identifier, userId))
            .limit(1);

        return usersWithRoles[0] || null;
    }

    /**
     * Verify password
     */
    static async verifyPassword(plainPassword: string, hashedPassword: string) {
        return bcrypt.compare(plainPassword, hashedPassword);
    }

    /**
     * Hash password
     */
    static async hashPassword(password: string) {
        return bcrypt.hash(password, 10);
    }

    /**
     * Check if identifier is unique (excluding a specific user)
     */
    static async isIdentifierUnique(identifier: string, excludeUserId?: string) {
        const conditions = [eq(users.identifier, identifier)];
        if (excludeUserId) {
            conditions.push(ne(users.identifier, excludeUserId));
        }

        const existing = await db.query.users.findFirst({
            where: and(...conditions)
        });

        return !existing;
    }

    /**
     * Check if email is unique (excluding a specific user)
     */
    static async isEmailUnique(email: string, excludeUserId?: string) {
        const conditions = [eq(users.email, email)];
        if (excludeUserId) {
            conditions.push(ne(users.identifier, excludeUserId));
        }

        const existing = await db.query.users.findFirst({
            where: and(...conditions)
        });

        return !existing;
    }
}

/**
 * User Validators
 * Zod schemas for user-related input validation
 */

import { z } from 'zod';

export const CreateUserSchema = z.object({
    fullName: z.string().min(2, 'Nama harus minimal 2 karakter'),
    identifier: z.string().min(5, 'NIM/NIDN harus minimal 5 karakter'),
    email: z.string().email('Format email tidak valid'),
    passwordHash: z.string().min(6, 'Password harus minimal 6 karakter'),
    roleId: z.number().positive('Role ID harus positif'),
    batch: z.number().optional(),
    studyType: z.enum(['Reguler', 'Hybrid']).optional(),
});

export const UpdateUserSchema = z.object({
    fullName: z.string().min(2, 'Nama harus minimal 2 karakter'),
    identifier: z.string().min(5, 'NIM/NIDN harus minimal 5 karakter'),
    email: z.string().email('Format email tidak valid'),
    roleId: z.number().positive('Role ID harus positif'),
    passwordHash: z.string().min(6, 'Password harus minimal 6 karakter').optional(),
    batch: z.number().optional(),
    studyType: z.enum(['Reguler', 'Hybrid']).optional(),
});

export const UpdateProfileSchema = z.object({
    fullName: z.string().min(2).optional(),
    identifier: z.string().min(5).optional(),
    currentPassword: z.string().min(1, 'Password saat ini wajib diisi'),
    newEmail: z.string().email().optional(),
    newPassword: z.string().min(6).optional(),
    confirmNewPassword: z.string().optional(),
}).refine(
    (data) => {
        if (data.newPassword && data.newPassword !== data.confirmNewPassword) {
            return false;
        }
        return true;
    },
    { message: 'Konfirmasi password tidak sesuai', path: ['confirmNewPassword'] }
);

// Type exports
export type CreateUserInput = z.infer<typeof CreateUserSchema>;
export type UpdateUserInput = z.infer<typeof UpdateUserSchema>;
export type UpdateProfileInput = z.infer<typeof UpdateProfileSchema>;

import { SignJWT, jwtVerify } from 'jose';
import { cookies } from 'next/headers';
import { NextRequest, NextResponse } from 'next/server';

const secretKey = 'secret'; // TODO: Move to .env
const key = new TextEncoder().encode(secretKey);

export async function encrypt(payload: any) {
    return await new SignJWT(payload)
        .setProtectedHeader({ alg: 'HS256' })
        .setIssuedAt()
        .setExpirationTime('24h') // Session expires in 24 hours
        .sign(key);
}

export async function decrypt(input: string): Promise<any> {
    const { payload } = await jwtVerify(input, key, {
        algorithms: ['HS256'],
    });
    return payload;
}

export async function getSession() {
    const session = (await cookies()).get('session')?.value;
    if (!session) return null;
    return await decrypt(session);
}

/**
 * Require a specific permission. Throws if user doesn't have it.
 */
export async function requirePermission(permission: string) {
    const session = await getSession();
    if (!session) {
        throw new Error('Unauthorized: Not logged in');
    }
    if (!hasPermission(session, permission)) {
        throw new Error(`Unauthorized: Permission '${permission}' required`);
    }
    return session;
}

/**
 * Require ANY of the specified permissions. Throws if user has none.
 */
export async function requireAnyPermission(permissions: string[]) {
    const session = await getSession();
    if (!session) {
        throw new Error('Unauthorized: Not logged in');
    }
    if (!hasAnyPermission(session, permissions)) {
        throw new Error(`Unauthorized: One of [${permissions.join(', ')}] permissions required`);
    }
    return session;
}

/**
 * Check if session has a specific permission (non-throwing).
 */
export function hasPermission(session: any, permission: string): boolean {
    return session?.user?.permissions?.includes(permission) ?? false;
}

/**
 * Check if session has ANY of the specified permissions.
 */
export function hasAnyPermission(session: any, permissions: string[]): boolean {
    return permissions.some(p => hasPermission(session, p));
}

export async function updateSession(request: NextRequest) {
    const session = request.cookies.get('session')?.value;
    if (!session) return;

    // Refresh the session so it doesn't expire
    const parsed = await decrypt(session);
    parsed.expires = new Date(Date.now() + 24 * 60 * 60 * 1000); // 24 hours
    const res = NextResponse.next();
    res.cookies.set({
        name: 'session',
        value: await encrypt(parsed),
        httpOnly: true,
        expires: parsed.expires,
    });
    return res;
}

import { headers } from 'next/headers';

/**
 * Detect if the request is from a mobile device using User-Agent header.
 * Returns true if mobile, false if desktop/tablet.
 */
export async function isMobileRequest(): Promise<boolean> {
    const headersList = await headers();
    const userAgent = headersList.get('user-agent') || '';
    return /Android|webOS|iPhone|iPod|BlackBerry|IEMobile|Opera Mini/i.test(userAgent);
}

/**
 * Get the default view mode based on device type.
 * Desktop => 'list', Mobile => 'grid'
 */
export async function getDefaultViewMode(): Promise<'list' | 'grid'> {
    const mobile = await isMobileRequest();
    return mobile ? 'grid' : 'list';
}

/**
 * Document Verifier — Hybrid PDF Verification
 * Validates uploaded documents (surat izin / surat permohonan) for auto-approve.
 * 
 * Level 1: File validation (PDF only, min size, magic bytes, page count)
 * Level 2: Text extraction (pdf-parse first, then Tesseract.js OCR fallback for scanned PDFs)
 * Level 3: Keyword matching against extracted text
 */

import { readFile, access } from 'fs/promises';
import path from 'path';

// pdf-parse doesn't ship types, so require it
// eslint-disable-next-line @typescript-eslint/no-require-imports
const pdfParse = require('pdf-parse');

// ─── Types ───────────────────────────────────────────────────

export type DocumentType = 'suratIzin' | 'suratPermohonan';

export interface FileValidationResult {
    valid: boolean;
    reason?: string;
}

export interface VerificationResult {
    valid: boolean;
    score: number; // 0-100 percentage
    matchedKeywords: string[];
    missingKeywords: string[];
    extractionMethod: 'text' | 'ocr' | 'hybrid';
    ocrUsed: boolean;
}

// ─── Keyword Configuration ──────────────────────────────────

/** Shared keywords for all document types */
const SHARED_KEYWORDS = [
    'UNIVERSITAS AL-AZHAR INDONESIA',
    'FAKULTAS SAINS DAN TEKNOLOGI',
    'Informatika',
    'Nomor',
    'Perihal',
    'Lampiran',
    'Menyetujui',
];

/** Keywords specific to each document type */
const TYPE_KEYWORDS: Record<DocumentType, string[][]> = {
    suratIzin: [
        ['peminjaman'],
        ['permohonan'],
        ['kegiatan'],
        ['Dekan', 'Wakil Dekan', 'Rektor'],          // any one matches
        ['Ketua Pelaksana', 'Ketua Himpunan'],        // any one matches
        ['ttd', 'tanda tangan', 'Tanda Tangan'],
    ],
    suratPermohonan: [
        ['peminjaman', 'penggunaan ruangan'],
        ['permohonan'],
        ['kegiatan'],
        ['Ketua Program Studi', 'Dekan', 'Wakil Dekan'],
        ['Ketua Pelaksana', 'Ketua Himpunan'],
        ['ttd', 'tanda tangan', 'Tanda Tangan'],
    ],
};

const MIN_FILE_SIZE = 5 * 1024; // 5KB minimum
const PDF_MAGIC_BYTES = Buffer.from('%PDF-');
const VALIDITY_THRESHOLD = 0.5; // 50% of keywords must match
const MIN_TEXT_LENGTH = 50; // Minimum characters to consider text extraction successful

// ─── OCR Helper ─────────────────────────────────────────────

const MAX_OCR_WIDTH = 1200; // Maximum width for OCR images — prevents worker crashes on large scans

/**
 * Downscale raw pixel data to a manageable size for OCR.
 * Uses nearest-neighbor sampling for speed (OCR doesn't need smooth interpolation).
 */
function downscalePixels(
    data: Uint8ClampedArray | Uint8Array,
    srcWidth: number,
    srcHeight: number,
    channels: number,
    maxWidth: number
): { data: Uint8ClampedArray; width: number; height: number } {
    if (srcWidth <= maxWidth) {
        return { data: new Uint8ClampedArray(data), width: srcWidth, height: srcHeight };
    }

    const scale = maxWidth / srcWidth;
    const dstWidth = Math.floor(srcWidth * scale);
    const dstHeight = Math.floor(srcHeight * scale);
    const dstData = new Uint8ClampedArray(dstWidth * dstHeight * channels);

    for (let dy = 0; dy < dstHeight; dy++) {
        const sy = Math.floor(dy / scale);
        for (let dx = 0; dx < dstWidth; dx++) {
            const sx = Math.floor(dx / scale);
            const srcIdx = (sy * srcWidth + sx) * channels;
            const dstIdx = (dy * dstWidth + dx) * channels;
            for (let c = 0; c < channels; c++) {
                dstData[dstIdx + c] = data[srcIdx + c] || 0;
            }
        }
    }

    return { data: dstData, width: dstWidth, height: dstHeight };
}

/**
 * Convert raw RGB pixel data to an uncompressed BMP buffer.
 * Tesseract.js needs a proper image format — raw pixel arrays won't work.
 */
function rawPixelsToBmp(data: Uint8ClampedArray | Uint8Array, width: number, height: number, channels: number): Buffer {
    // BMP with 24-bit color (RGB)
    const rowSize = Math.ceil((width * 3) / 4) * 4; // Rows must be 4-byte aligned
    const pixelDataSize = rowSize * height;
    const fileSize = 54 + pixelDataSize; // 14 (file header) + 40 (info header) + pixel data

    const bmp = Buffer.alloc(fileSize);

    // ── File Header (14 bytes) ──
    bmp.write('BM', 0);                    // Signature
    bmp.writeUInt32LE(fileSize, 2);        // File size
    bmp.writeUInt32LE(0, 6);               // Reserved
    bmp.writeUInt32LE(54, 10);             // Pixel data offset

    // ── Info Header (40 bytes) ──
    bmp.writeUInt32LE(40, 14);             // Header size
    bmp.writeInt32LE(width, 18);           // Width
    bmp.writeInt32LE(-height, 22);         // Height (negative = top-down)
    bmp.writeUInt16LE(1, 26);              // Color planes
    bmp.writeUInt16LE(24, 28);             // Bits per pixel (24 = RGB)
    bmp.writeUInt32LE(0, 30);              // Compression (0 = none)
    bmp.writeUInt32LE(pixelDataSize, 34);  // Image size
    bmp.writeInt32LE(2835, 38);            // X pixels per meter (72 DPI)
    bmp.writeInt32LE(2835, 42);            // Y pixels per meter
    bmp.writeUInt32LE(0, 46);              // Colors used
    bmp.writeUInt32LE(0, 50);              // Important colors

    // ── Pixel Data ──
    // BMP stores pixels as BGR, top-down (because we used negative height)
    for (let y = 0; y < height; y++) {
        for (let x = 0; x < width; x++) {
            const srcIdx = (y * width + x) * channels;
            const dstIdx = 54 + y * rowSize + x * 3;

            const r = data[srcIdx] || 0;
            const g = data[srcIdx + 1] || 0;
            const b = data[srcIdx + 2] || 0;

            bmp[dstIdx] = b;     // Blue
            bmp[dstIdx + 1] = g; // Green
            bmp[dstIdx + 2] = r; // Red
        }
    }

    return bmp;
}

/**
 * Extract text from a scanned PDF using Tesseract.js OCR.
 * Extracts embedded images from PDF pages via pdfjs-dist, converts to BMP, then runs OCR.
 */
async function extractTextWithOCR(buffer: Buffer): Promise<string> {
    try {
        // Dynamic imports to avoid loading heavy modules unless needed
        const { createWorker } = await import('tesseract.js');
        const pdfjsLib = await import('pdfjs-dist/legacy/build/pdf.mjs');

        // Load PDF document
        const pdfData = new Uint8Array(buffer);
        const pdf = await pdfjsLib.getDocument({ data: pdfData }).promise;

        // Only OCR the first 2 pages (enough for surat header + body)
        const pagesToProcess = Math.min(pdf.numPages, 2);
        const ocrTexts: string[] = [];

        // Create Tesseract worker with Indonesian + English
        const worker = await createWorker('ind+eng');

        for (let pageNum = 1; pageNum <= pagesToProcess; pageNum++) {
            const page = await pdf.getPage(pageNum);

            // Step A: Try text content layer first (cheaper than OCR)
            try {
                const textContent = await page.getTextContent();
                const pageText = textContent.items
                    .map((item: Record<string, unknown>) => (typeof item.str === 'string' ? item.str : ''))
                    .join(' ');

                if (pageText.trim().length > MIN_TEXT_LENGTH) {
                    ocrTexts.push(pageText);
                    continue; // Skip OCR for this page — text layer is sufficient
                }
            } catch {
                // Text extraction failed, proceed to image extraction
            }

            // Step B: Extract embedded images from the page and OCR them
            let pageOcrDone = false;
            try {
                const ops = await page.getOperatorList();
                const pdfjsOps = pdfjsLib.OPS;

                for (let i = 0; i < ops.fnArray.length; i++) {
                    if (pageOcrDone) break;

                    if (ops.fnArray[i] === pdfjsOps.paintImageXObject ||
                        ops.fnArray[i] === pdfjsOps.paintXObject) {
                        const imgName = ops.argsArray[i][0];
                        try {
                            const img = await page.objs.get(imgName);
                            if (img && img.data && img.width > 100 && img.height > 100) {
                                // Determine channels: kind 1 = Grayscale, kind 2 = RGB, kind 3 = RGBA
                                const channels = img.kind === 1 ? 1 : img.kind === 3 ? 4 : 3;

                                // For grayscale, expand to RGB
                                let rgbData: Uint8ClampedArray;
                                let effectiveChannels = channels === 1 ? 3 : channels;
                                if (channels === 1) {
                                    rgbData = new Uint8ClampedArray(img.width * img.height * 3);
                                    for (let j = 0; j < img.data.length; j++) {
                                        rgbData[j * 3] = img.data[j];
                                        rgbData[j * 3 + 1] = img.data[j];
                                        rgbData[j * 3 + 2] = img.data[j];
                                    }
                                } else {
                                    rgbData = img.data;
                                }

                                // Downscale large images to prevent worker crashes
                                const scaled = downscalePixels(rgbData, img.width, img.height, effectiveChannels, MAX_OCR_WIDTH);

                                // Convert to BMP for Tesseract
                                const bmpBuffer = rawPixelsToBmp(
                                    scaled.data,
                                    scaled.width,
                                    scaled.height,
                                    effectiveChannels
                                );

                                console.log(`[OCR] Processing image ${imgName}: ${img.width}x${img.height} -> ${scaled.width}x${scaled.height}, bmp=${bmpBuffer.length} bytes`);

                                const { data: ocrResult } = await worker.recognize(bmpBuffer);
                                if (ocrResult.text.trim().length > 10) {
                                    ocrTexts.push(ocrResult.text);
                                    pageOcrDone = true; // One large image per page is usually enough
                                    console.log(`[OCR] Got ${ocrResult.text.trim().length} chars from ${imgName}`);
                                }
                            }
                        } catch (imgErr) {
                            console.log(`[OCR] Failed to process image ${imgName}:`, imgErr);
                        }
                    }
                }
            } catch (opsErr) {
                console.log('[OCR] Operator list extraction failed:', opsErr);
            }
        }

        await worker.terminate();
        return ocrTexts.join('\n');

    } catch (error) {
        console.error('[OCR] extractTextWithOCR failed:', error);
        return '';
    }
}

// ─── Document Verifier ──────────────────────────────────────

export class DocumentVerifier {
    /**
     * Level 1: Validate file basics (exists, size, is valid PDF)
     */
    static async validateFile(filePath: string): Promise<FileValidationResult> {
        const absolutePath = path.join(process.cwd(), 'public', filePath);

        // Check file exists
        try {
            await access(absolutePath);
        } catch {
            return { valid: false, reason: 'File tidak ditemukan' };
        }

        // Read file
        const buffer = await readFile(absolutePath);

        // Check minimum size
        if (buffer.length < MIN_FILE_SIZE) {
            return { valid: false, reason: 'File terlalu kecil (minimal 5KB)' };
        }

        // Check PDF magic bytes
        const header = buffer.subarray(0, 5);
        if (!header.equals(PDF_MAGIC_BYTES)) {
            return { valid: false, reason: 'File bukan PDF yang valid' };
        }

        // Try parsing PDF to check page count
        // Some scanned PDFs fail with pdf-parse, so we try pdfjs-dist as fallback
        let pdfValid = false;
        try {
            const pdf = await pdfParse(buffer);
            if (pdf.numpages && pdf.numpages >= 1) {
                pdfValid = true;
            }
        } catch {
            // pdf-parse failed — try pdfjs-dist as fallback
        }

        if (!pdfValid) {
            try {
                const pdfjsLib = await import('pdfjs-dist/legacy/build/pdf.mjs');
                const pdfData = new Uint8Array(buffer);
                const pdf = await pdfjsLib.getDocument({ data: pdfData }).promise;
                if (pdf.numPages >= 1) {
                    pdfValid = true;
                }
            } catch {
                // Both parsers failed
            }
        }

        if (!pdfValid) {
            return { valid: false, reason: 'PDF tidak dapat dibaca / rusak' };
        }

        return { valid: true };
    }

    /**
     * Level 2 & 3: Extract text from PDF (with OCR fallback) and check for required keywords
     */
    static async verifyDocument(
        filePath: string,
        type: DocumentType
    ): Promise<VerificationResult> {
        const absolutePath = path.join(process.cwd(), 'public', filePath);
        const buffer = await readFile(absolutePath);

        // ─── Step 1: Try pdf-parse text extraction ───
        let text = '';
        let extractionMethod: 'text' | 'ocr' | 'hybrid' = 'text';
        let ocrUsed = false;

        try {
            const pdf = await pdfParse(buffer);
            text = pdf.text || '';
        } catch {
            // pdf-parse failed entirely
            text = '';
        }

        // ─── Step 2: If text is too short, try OCR fallback ───
        const pdfParseText = text.trim();

        if (pdfParseText.length < MIN_TEXT_LENGTH) {
            console.log(`[DocumentVerifier] pdf-parse returned only ${pdfParseText.length} chars. Attempting OCR...`);
            try {
                const ocrText = await extractTextWithOCR(buffer);
                ocrUsed = true;

                if (ocrText.trim().length > 0) {
                    if (pdfParseText.length > 0) {
                        // Some text from pdf-parse + some from OCR = hybrid
                        text = pdfParseText + '\n' + ocrText;
                        extractionMethod = 'hybrid';
                    } else {
                        text = ocrText;
                        extractionMethod = 'ocr';
                    }
                    console.log(`[DocumentVerifier] OCR extracted ${ocrText.trim().length} chars. Method: ${extractionMethod}`);
                } else {
                    console.log('[DocumentVerifier] OCR returned empty text as well.');
                    // text remains whatever pdf-parse got (possibly empty)
                    extractionMethod = 'ocr'; // Mark as OCR attempted
                }
            } catch (ocrError) {
                console.error('[DocumentVerifier] OCR fallback failed:', ocrError);
                ocrUsed = true; // OCR was attempted but failed
                extractionMethod = 'ocr';
            }
        }

        // ─── Step 3: If still no text at all, return failed ───
        if (text.trim().length === 0) {
            return {
                valid: false,
                score: 0,
                matchedKeywords: [],
                missingKeywords: ['(tidak dapat membaca konten PDF — perlu validasi manual)'],
                extractionMethod,
                ocrUsed,
            };
        }

        // ─── Step 4: Keyword matching ───
        const textLower = text.toLowerCase();
        const matched: string[] = [];
        const missing: string[] = [];

        // Check shared keywords
        for (const keyword of SHARED_KEYWORDS) {
            if (textLower.includes(keyword.toLowerCase())) {
                matched.push(keyword);
            } else {
                missing.push(keyword);
            }
        }

        // Check type-specific keywords (each group = any one matches)
        const typeKeywordGroups = TYPE_KEYWORDS[type];
        for (const group of typeKeywordGroups) {
            const groupLabel = group.join('/');
            const found = group.some(kw => textLower.includes(kw.toLowerCase()));
            if (found) {
                matched.push(groupLabel);
            } else {
                missing.push(groupLabel);
            }
        }

        const total = matched.length + missing.length;
        const score = total > 0 ? Math.round((matched.length / total) * 100) : 0;
        const valid = score >= VALIDITY_THRESHOLD * 100;

        return { valid, score, matchedKeywords: matched, missingKeywords: missing, extractionMethod, ocrUsed };
    }

    /**
     * Full verification pipeline: file validation + keyword matching (with OCR fallback)
     */
    static async verify(
        filePath: string,
        type: DocumentType
    ): Promise<{ fileValid: boolean; verification: VerificationResult | null; reason?: string }> {
        // Level 1: File validation
        const fileResult = await this.validateFile(filePath);
        if (!fileResult.valid) {
            return {
                fileValid: false,
                verification: null,
                reason: fileResult.reason,
            };
        }

        // Level 2 & 3: Text extraction (with OCR fallback) + keyword matching
        const verification = await this.verifyDocument(filePath, type);

        return {
            fileValid: true,
            verification,
        };
    }
}

export interface TranslatedError {
    title: string;
    message: string;
}

export function translateError(error: any, defaultMessage: string = 'Terjadi kesalahan sistem'): TranslatedError {
    const rawMessage = error instanceof Error ? error.message : String(error);

    // Default title and message
    let title = 'Gagal';
    let message = rawMessage || defaultMessage;

    // Handle authentication and authorization errors
    if (rawMessage.includes('Unauthorized: Not logged in') || rawMessage.includes('Not logged in')) {
        title = 'Sesi Berakhir';
        message = 'Sesi Anda telah berakhir atau Anda belum login. Silakan login kembali.';
    } else if (rawMessage.includes('Unauthorized: Permission') || rawMessage.includes('Permission')) {
        title = 'Akses Ditolak';
        const match = rawMessage.match(/Permission '(.+?)' required/);
        if (match && match[1]) {
            message = `Anda tidak memiliki hak akses (${match[1]}) untuk melakukan tindakan ini.`;
        } else {
            message = 'Anda tidak memiliki hak akses yang diperlukan untuk melakukan tindakan ini.';
        }
    } else if (rawMessage.includes('Unauthorized: One of')) {
        title = 'Akses Ditolak';
        message = 'Anda tidak memiliki salah satu dari hak akses yang diperlukan untuk melakukan tindakan ini.';
    } else if (rawMessage.includes('UNIQUE constraint failed')) {
        title = 'Data Sudah Ada';
        message = 'Data yang Anda masukkan sudah terdaftar di sistem dan tidak boleh duplikat.';
    } else if (rawMessage.includes('Failed to fetch') || rawMessage.includes('NetworkError')) {
        title = 'Koneksi Terputus';
        message = 'Gagal terhubung ke server. Periksa koneksi internet Anda.';
    } else if (rawMessage.includes('NEXT_REDIRECT')) {
        // Next.js internal redirect error, shouldn't be surfaced as a popup generally, but just in case
        title = 'Memproses...';
        message = 'Mengarahkan halaman...';
    }

    return { title, message };
}

/**
 * Formatter Utilities
 * Centralized formatting functions for dates, times, numbers, and currency
 */

const DEFAULT_TIMEZONE = 'Asia/Jakarta';
const DEFAULT_LOCALE = 'id-ID';

// ==================== DATE & TIME FORMATTERS ====================

/**
 * Format date and time with full details
 * Example: "Rabu, 25 Desember 2025, 22:51:25"
 */
export function formatDateTime(date: Date | string | null | undefined): string {
    if (!date) return '-';
    const d = typeof date === 'string' ? new Date(date) : date;
    return d.toLocaleString(DEFAULT_LOCALE, {
        timeZone: DEFAULT_TIMEZONE,
        weekday: 'long',
        year: 'numeric',
        month: 'long',
        day: 'numeric',
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit',
    });
}

/**
 * Format date only (no time)
 * Example: "25 Desember 2025"
 */
export function formatDate(date: Date | string | null | undefined): string {
    if (!date) return '-';
    const d = typeof date === 'string' ? new Date(date) : date;
    return d.toLocaleDateString(DEFAULT_LOCALE, {
        timeZone: DEFAULT_TIMEZONE,
        year: 'numeric',
        month: 'long',
        day: 'numeric',
    });
}

/**
 * Format date with weekday
 * Example: "Rabu, 25 Desember 2025"
 */
export function formatDateWithDay(date: Date | string | null | undefined): string {
    if (!date) return '-';
    const d = typeof date === 'string' ? new Date(date) : date;
    return d.toLocaleDateString(DEFAULT_LOCALE, {
        timeZone: DEFAULT_TIMEZONE,
        weekday: 'long',
        year: 'numeric',
        month: 'long',
        day: 'numeric',
    });
}

/**
 * Format date short
 * Example: "25/12/2025"
 */
export function formatDateShort(date: Date | string | null | undefined): string {
    if (!date) return '-';
    const d = typeof date === 'string' ? new Date(date) : date;
    return d.toLocaleDateString(DEFAULT_LOCALE, {
        timeZone: DEFAULT_TIMEZONE,
        year: 'numeric',
        month: '2-digit',
        day: '2-digit',
    });
}

/**
 * Format time only
 * Example: "22:51"
 */
export function formatTime(date: Date | string | null | undefined): string {
    if (!date) return '-';
    const d = typeof date === 'string' ? new Date(date) : date;
    return d.toLocaleTimeString(DEFAULT_LOCALE, {
        timeZone: DEFAULT_TIMEZONE,
        hour: '2-digit',
        minute: '2-digit',
    });
}

/**
 * Format time with seconds
 * Example: "22:51:25"
 */
export function formatTimeWithSeconds(date: Date | string | null | undefined): string {
    if (!date) return '-';
    const d = typeof date === 'string' ? new Date(date) : date;
    return d.toLocaleTimeString(DEFAULT_LOCALE, {
        timeZone: DEFAULT_TIMEZONE,
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit',
    });
}

/**
 * Format relative time (e.g., "2 jam yang lalu")
 */
export function formatRelativeTime(date: Date | string | null | undefined): string {
    if (!date) return '-';
    const d = typeof date === 'string' ? new Date(date) : date;
    const now = new Date();
    const diffMs = now.getTime() - d.getTime();
    const diffMins = Math.floor(diffMs / 60000);
    const diffHours = Math.floor(diffMs / 3600000);
    const diffDays = Math.floor(diffMs / 86400000);

    if (diffMins < 1) return 'Baru saja';
    if (diffMins < 60) return `${diffMins} menit yang lalu`;
    if (diffHours < 24) return `${diffHours} jam yang lalu`;
    if (diffDays < 7) return `${diffDays} hari yang lalu`;
    return formatDate(d);
}

/**
 * Get current time formatted
 */
export function getCurrentDateTime(): string {
    return formatDateTime(new Date());
}

// ==================== NUMBER FORMATTERS ====================

/**
 * Format number with thousand separator
 * Example: 1000000 -> "1.000.000"
 */
export function formatNumber(num: number | null | undefined): string {
    if (num === null || num === undefined) return '-';
    return num.toLocaleString(DEFAULT_LOCALE);
}

/**
 * Format currency (Indonesian Rupiah)
 * Example: 1000000 -> "Rp 1.000.000"
 */
export function formatCurrency(amount: number | null | undefined): string {
    if (amount === null || amount === undefined) return '-';
    return new Intl.NumberFormat(DEFAULT_LOCALE, {
        style: 'currency',
        currency: 'IDR',
        minimumFractionDigits: 0,
        maximumFractionDigits: 0,
    }).format(amount);
}

/**
 * Format percentage
 * Example: 0.75 -> "75%"
 */
export function formatPercentage(value: number | null | undefined, decimals = 0): string {
    if (value === null || value === undefined) return '-';
    return `${(value * 100).toFixed(decimals)}%`;
}

// ==================== STRING FORMATTERS ====================

/**
 * Truncate text with ellipsis
 */
export function truncateText(text: string | null | undefined, maxLength: number): string {
    if (!text) return '';
    if (text.length <= maxLength) return text;
    return text.slice(0, maxLength) + '...';
}

/**
 * Capitalize first letter
 */
export function capitalize(text: string | null | undefined): string {
    if (!text) return '';
    return text.charAt(0).toUpperCase() + text.slice(1).toLowerCase();
}

/**
 * Format file size
 * Example: 1024 -> "1 KB"
 */
export function formatFileSize(bytes: number | null | undefined): string {
    if (bytes === null || bytes === undefined) return '-';
    const units = ['B', 'KB', 'MB', 'GB'];
    let unitIndex = 0;
    let size = bytes;

    while (size >= 1024 && unitIndex < units.length - 1) {
        size /= 1024;
        unitIndex++;
    }

    return `${size.toFixed(unitIndex === 0 ? 0 : 1)} ${units[unitIndex]}`;
}

