export function filterMenuByPermissions(session: any, menuItems: MenuItem[]): MenuItem[] {
    return menuItems
        .map((item) => ({ ...item, children: item.children ? [...item.children] : undefined }))
        .filter((item) => {
            let hasAccess = true;

            if (item.permissions && Array.isArray(item.permissions)) {
                hasAccess = hasAnyPermission(session, item.permissions);
            } else if (item.permission) {
                hasAccess = hasPermission(session, item.permission);
            }

            if (!hasAccess) return false;

            if (item.children && Array.isArray(item.children)) {
                item.children = item.children.filter((child) => {
                    if (child.permissions) return hasAnyPermission(session, child.permissions);
                    if (child.permission) return hasPermission(session, child.permission);
                    return true;
                });
                return item.children.length > 0;
            }

            return true;
        });
}

export function hasCustomAdminPermission(session: any): boolean {
    return hasAnyPermission(session, ADMIN_PERMISSIONS);
}

function prefixMenuHrefs(menuItems: MenuItem[], basePath: string): MenuItem[] {
    return menuItems.map((item) => ({
        ...item,
        href: item.href === '#' ? '#' : `${basePath}${item.href}`,
        children: item.children ? prefixMenuHrefs(item.children, basePath) : undefined,
    }));
}

export function getMenuForUser(session: any, defaultMenu: MenuItem[], basePath: string): MenuItem[] {
    const menuItems: MenuItem[] = defaultMenu.map((item) => ({
        ...item,
        children: item.children ? [...item.children] : undefined,
    }));

    if (!hasCustomAdminPermission(session)) {
        return menuItems;
    }

    const prefixedSubmenus = ADMIN_SUBMENU_ITEMS.map((group) => ({
        parentName: group.parentName,
        children: prefixMenuHrefs(group.children, basePath),
    }));
    const prefixedAdminOnly = prefixMenuHrefs(ADMIN_ONLY_MENU_ITEMS, basePath);

    for (const adminGroup of prefixedSubmenus) {
        const existingParent = menuItems.find((m) => m.name === adminGroup.parentName);
        if (!existingParent) continue;

        const allowedChildren = adminGroup.children.filter((child) => {
            if (child.permissions) return hasAnyPermission(session, child.permissions);
            if (child.permission) return hasPermission(session, child.permission);
            return true;
        });

        if (!allowedChildren.length) continue;

        if (!existingParent.children) existingParent.children = [];
        for (const adminChild of allowedChildren) {
            const exists = existingParent.children.some((c) => c.href === adminChild.href);
            if (!exists) existingParent.children.push(adminChild);
        }
    }

    const filteredAdminOnly = filterMenuByPermissions(session, prefixedAdminOnly);
    for (const adminItem of filteredAdminOnly) {
        if (!menuItems.some((m) => m.name === adminItem.name)) {
            menuItems.push(adminItem);
        }
    }

    return menuItems;
}

/**
 * Timezone Utility for LAB UAI
 * 
 * CONVENTION:
 * - Database stores all dates in UTC
 * - Application displays in WIB (Asia/Jakarta, UTC+7)
 * - Use these utilities for consistent timezone handling
 */

// WIB offset in minutes (UTC+7)
const WIB_OFFSET_MINUTES = 7 * 60;

/**
 * Get current time in WIB
 */
export function nowWIB(): Date {
    const now = new Date();
    const utcOffset = now.getTimezoneOffset();
    return new Date(now.getTime() + (WIB_OFFSET_MINUTES + utcOffset) * 60 * 1000);
}

/**
 * Get start of today in WIB, returned as UTC for DB queries
 */
export function startOfTodayWIB(): Date {
    const wibNow = nowWIB();
    const startOfDayWIB = new Date(wibNow.getFullYear(), wibNow.getMonth(), wibNow.getDate());
    // Convert back to UTC for database query
    return new Date(startOfDayWIB.getTime() - WIB_OFFSET_MINUTES * 60 * 1000);
}

/**
 * Get end of today in WIB, returned as UTC for DB queries
 */
export function endOfTodayWIB(): Date {
    const wibNow = nowWIB();
    const endOfDayWIB = new Date(wibNow.getFullYear(), wibNow.getMonth(), wibNow.getDate(), 23, 59, 59, 999);
    // Convert back to UTC for database query
    return new Date(endOfDayWIB.getTime() - WIB_OFFSET_MINUTES * 60 * 1000);
}

/**
 * Convert UTC date to WIB for display
 */
export function toWIB(utcDate: Date | string): Date {
    const date = typeof utcDate === 'string' ? new Date(utcDate) : utcDate;
    const utcOffset = date.getTimezoneOffset();
    return new Date(date.getTime() + (WIB_OFFSET_MINUTES + utcOffset) * 60 * 1000);
}

/**
 * Format date to WIB string (for display)
 */
export function formatWIB(utcDate: Date | string | null, options?: Intl.DateTimeFormatOptions): string {
    if (!utcDate) return '-';

    const defaultOptions: Intl.DateTimeFormatOptions = {
        // mysql2 (without timezone config) reads WIB DATETIME values as UTC-valued JS Dates.
        // Using 'UTC' here displays the raw value, which equals the correct WIB time.
        timeZone: 'UTC',
        hour: '2-digit',
        minute: '2-digit',
        ...options
    };

    const date = typeof utcDate === 'string' ? new Date(utcDate) : utcDate;
    return date.toLocaleString('id-ID', defaultOptions);
}

/**
 * Format date and time to WIB string
 */
export function formatDateTimeWIB(utcDate: Date | string | null): string {
    if (!utcDate) return '-';
    return formatWIB(utcDate, {
        day: '2-digit',
        month: 'short',
        year: 'numeric',
        hour: '2-digit',
        minute: '2-digit'
    });
}

/**
 * Format date only to WIB string
 */
export function formatDateWIB(utcDate: Date | string | null): string {
    if (!utcDate) return '-';
    return formatWIB(utcDate, {
        day: '2-digit',
        month: 'short',
        year: 'numeric',
        hour: undefined,
        minute: undefined
    });
}

/**
 * Format time only to WIB string
 */
export function formatTimeWIB(utcDate: Date | string | null): string {
    if (!utcDate) return '-';
    return formatWIB(utcDate, {
        hour: '2-digit',
        minute: '2-digit'
    });
}

/**
 * Convert a local Date to a "DB-compatible" Date for Drizzle queries.
 * No-op kept for backwards compatibility.
 */
export function toDbDate(date: Date): Date {
    return date;
}

/**
 * Returns WIB midnight of today (or N days ago) as "fake UTC" Date for DB queries.
 * mysql2 serializes this to the correct WIB time string that MySQL stores.
 */
export function startOfDayWIBForDb(daysAgo = 0): Date {
    // Add 7h to get current WIB date, then build midnight in UTC position
    const wibNow = new Date(Date.now() + 7 * 60 * 60 * 1000);
    const year = wibNow.getUTCFullYear();
    const month = wibNow.getUTCMonth();
    const date = wibNow.getUTCDate() - daysAgo;
    return new Date(Date.UTC(year, month, date, 0, 0, 0));
}

/**
 * Get current WIB time as "fake UTC" for DB query parameters.
 */
export function nowAsWIBForDb(): Date {
    return new Date(Date.now() + 7 * 60 * 60 * 1000);
}

/**
 * Get start of today (midnight WIB) as a DB-compatible Date.
 */
export function startOfTodayForDb(): Date {
    return startOfDayWIBForDb(0);
}

import { writeFile, unlink, mkdir } from 'fs/promises';
import path from 'path';

const UPLOAD_DIR = path.join(process.cwd(), 'public', 'uploads');
const MAX_FILE_SIZE = 2 * 1024 * 1024; // 2MB

export async function saveFile(file: File): Promise<string> {
    // Validate file size
    if (file.size > MAX_FILE_SIZE) {
        throw new Error('Ukuran file maksimal 2MB');
    }

    // Generate unique filename
    const timestamp = Date.now();
    const originalName = file.name.replace(/[^a-zA-Z0-9.-]/g, '_');
    const filename = `${timestamp}-${originalName}`;
    const filepath = path.join(UPLOAD_DIR, filename);

    // Convert File to Buffer
    const bytes = await file.arrayBuffer();
    const buffer = Buffer.from(bytes);

    // Save file
    await mkdir(UPLOAD_DIR, { recursive: true });
    await writeFile(filepath, buffer);

    // Return dynamic API URL path instead of static /uploads pattern
    return `/api/file/${filename}`;
}

export async function deleteFile(filePath: string): Promise<void> {
    try {
        // filePath looks like "/api/file/governance/file.pdf" or "/api/file/file.pdf"
        // Strip the leading "/api/file/" prefix and resolve from UPLOAD_DIR
        const relativePath = filePath.replace(/^\/api\/file\//, '');
        const filepath = path.join(UPLOAD_DIR, relativePath);
        await unlink(filepath);
    } catch (error) {
        console.error('Error deleting file:', error);
        // Don't throw - file might already be deleted
    }
}

export function validateFileType(file: File, allowedTypes: string[]): boolean {
    return allowedTypes.some(type => file.type.includes(type));
}

